-- ============================================================================
-- NIS2 + ISO 27001: deutscher Katalogtext
--
-- Ausgangslage, am 15.09.2026 live gemessen: von 4407 Kontrollen tragen 3821
-- deutschen Text. Nur NIS2 (268) und ISO 27001 (318) nicht — in allen 586
-- Zeilen steht in req_de derselbe englische Satz wie in req_en. Die Oberfläche
-- druckt req_de im deutschen Modus wörtlich (ControlRowItem.tsx:113); eine
-- Übersetzungsschicht gibt es nicht. Deutsche Kunden lasen diese beiden
-- Kataloge deshalb vollständig auf Englisch.
--
-- Quelle des Deutschen:
--   * 268 NIS2-Kontrollen aus NIS2-268-Vollstaendige-Kontrollliste-DE.csv.
--     Dieselben 268 IDs wie live (0 Abweichungen); die englische Schwesterdatei
--     stimmt Feld für Feld mit dem Live-Stand überein (einzige Ausnahme
--     REC-METRIC = die noch nicht deployte MTTR-Korrektur). Die Übersetzung
--     gehört also zu genau diesem Katalogstand.
--   * 224 dieser IDs existieren gleichlautend im ISO-27001-Katalog (req_en und
--     alle meta-Texte identisch, dieselbe risk_id) — derselbe deutsche Text.
--   * 94 ISO-eigene Kontrollen: für diesen Seed übersetzt, Hausstil aus der
--     NIS2-CSV abgeleitet, mit Satzscan und Stichprobenlesung geprüft.
--
-- Der englische Katalog bleibt vollständig erhalten: req_en wird nicht
-- angefasst, die deutschen meta-Texte kommen unter eigenen Schlüsseln
-- (description_de, evidence_de, risk_text_de, subgroup_de, topic_label_de)
-- NEBEN die englischen, nicht an deren Stelle.
--
-- Idempotent: alle Anweisungen setzen feste Zielwerte. Ein zweiter Lauf ändert
-- nichts. Eine Transaktion — bricht etwas, bleibt alles beim Alten.
-- ============================================================================
BEGIN;

-- ----------------------------------------------------------------------------
-- 1) Kontrolltexte. 362 Zeilen; sie treffen NIS2 und ISO 27001
--    zugleich, weil 224 IDs in beiden Katalogen stehen und denselben Text tragen.
--    Erwartete Trefferzahl: 586 (268 NIS2 + 318 ISO 27001).
--
--    B2 wird hier mitkorrigiert: meta.topic_label trug in allen 586 Zeilen die
--    UNTERGRUPPE ("S-SCP · Scope and EU representation") statt des Themennamens
--    ("Scope, registration & domain data"). Der Schlüssel heißt topic_label und
--    bekommt jetzt auch den Themennamen. Die Oberfläche liest ihn heute nicht —
--    die Exporte tun es, und ein falsch benanntes Feld wird irgendwann geglaubt.
-- ----------------------------------------------------------------------------
UPDATE public.controls c SET
  req_de = v.titel,
  meta = COALESCE(c.meta,'{}'::jsonb) || jsonb_build_object(
    'description_de',  v.beschreibung,
    'evidence_de',     v.nachweis,
    'risk_text_de',    v.risiko,
    'subgroup_de',     v.untergruppe,
    'topic_label',     v.thema_en,
    'topic_label_de',  v.thema_de,
    'language',        'de+en')
FROM (VALUES
  ('C12.1','Die Anwendbarkeit von NIS2 wird nach relevanten Änderungen erneut bewertet','Die Einrichtung bewertet nach Änderungen ihrer Tätigkeiten, Größe, Eigentumsverhältnisse oder rechtlichen Zuständigkeit, die ihren Status im Anwendungsbereich beeinflussen könnten, erneut, ob und in welcher Weise NIS2 auf sie anwendbar ist.','Beispiele: Aufzeichnungen über relevante Änderungen der Tätigkeiten, Größe, Eigentumsverhältnisse oder rechtlichen Zuständigkeit, verknüpft mit datierten Neubewertungen und den daraus resultierenden Entscheidungen zum Anwendungsbereich. Wenn keine relevante Änderung eingetreten ist, können vorhandene Änderungsinformationen und eine Erläuterung des Auslösers für eine Neubewertung diesen Sachverhalt belegen.','Eine Änderung des Anwendungsbereichs, der Einstufung oder der rechtlichen Zuständigkeit bleibt unbemerkt, sodass Pflichten versäumt werden oder die Einrichtung sich an die falsche zuständige Behörde hält.','S-SCP · Anwendungsbereich und EU-Vertretung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C11.1','Ein EU-Vertreter, der die Voraussetzungen erfüllt, ist wirksam benannt (Gilt nur für Anbieter nach Art. 26(1)(b) ohne Niederlassung in der EU, die Dienste in der EU anbieten.)','Bei den in dieser Kontrolle genannten Anbietern außerhalb der EU ist der benannte Vertreter in einem EU-Mitgliedstaat niedergelassen, in dem der Anbieter Dienste anbietet, und verfügt über ein Mandat, für ihn zu handeln; die bloße Angabe eines EU-Kontakts belegt keine wirksame Benennung.','Soweit anwendbar, können Nachweise eine angenommene Benennung oder ein gleichwertiges Mandat umfassen, aus dem der EU-Vertreter, seine die Voraussetzungen erfüllende Niederlassung in der EU und seine Befugnis, für den Anbieter zu handeln, hervorgehen.','Behördliche Mitteilungen oder erforderliche Folgemaßnahmen verzögern sich, weil kein bevollmächtigter EU-Vertreter für den Anbieter handeln kann.','S-SCP · Anwendungsbereich und EU-Vertretung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C14.1','Die erforderlichen Registrierungsangaben sind vollständig und richtig','Die jeweils erforderlichen Registrierungsangaben sind vollständig und richtig: Name, Anschrift, E-Mail-Adressen, Telefonnummern, IP-Adressbereiche sowie gegebenenfalls Sektor, Teilsektor und Mitgliedstaaten, in denen Dienste erbracht werden. Bei Anbietern, die Art. 27 unterliegen, gehören dazu außerdem die Art der Einrichtung, die Hauptniederlassung und weitere Niederlassungen in der EU sowie die erforderlichen Angaben zum EU-Vertreter.','Beispiele: aktuelle Registrierungsangaben, die mit maßgeblichen Einrichtungs- und Dienstleistungsaufzeichnungen abgeglichen wurden und die erforderlichen Angaben zu Identität, Kontakt und IP-Adressbereichen sowie gegebenenfalls Sektor, Teilsektor und Mitgliedstaaten, in denen Dienste erbracht werden, abdecken. Soweit Art. 27 gilt, sind die Art der Einrichtung, die Niederlassungen in der EU und Angaben zum Vertreter einzubeziehen.','Unvollständige oder unrichtige Daten verhindern die korrekte Identifizierung, die Nachverfolgung des Status im Anwendungsbereich oder die Kontaktaufnahme durch die zuständige Behörde.','S-REG · Registrierung und Änderungen','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C14.2','Die erforderlichen Registrierungsangaben werden fristgerecht übermittelt','Die Einrichtung hat ihren Namen, ihre Anschrift, E-Mail-Adressen, Telefonnummern, IP-Adressbereiche sowie gegebenenfalls Sektor, Teilsektor und Mitgliedstaaten, in denen Dienste erbracht werden, fristgerecht an die zuständige Behörde übermittelt. Soweit Art. 27 gilt, umfasst die Übermittlung außerdem die Art der Einrichtung, Angaben zur Hauptniederlassung und zu weiteren Niederlassungen in der EU sowie die erforderlichen Angaben zum EU-Vertreter.','Beispiele: die übermittelten Registrierungsangaben und der Portalverlauf, eine Empfangsbestätigung oder ein gleichwertiger Übermittlungsnachweis, aus denen die zuständige Behörde und das Übermittlungsdatum hervorgehen, abgeglichen mit der geltenden Frist. Prüfen Sie, ob die Übermittlung alle für die Einrichtung erforderlichen Felder enthält, einschließlich der Angaben nach Art. 27, soweit relevant.','Die zuständige Behörde kann die Einrichtung im vorgeschriebenen Registrierungsverfahren nicht zuverlässig erfassen oder kontaktieren, sodass eine unterlassene oder verspätete Übermittlung korrigierende Folgemaßnahmen auslöst.','S-REG · Registrierung und Änderungen','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C15.2','Änderungen der Registrierungsangaben werden erkannt und innerhalb der geltenden Fristen mitgeteilt','Die Einrichtung erkennt Änderungen ihrer NIS2-Registrierungsangaben und übermittelt die aktualisierten Angaben unverzüglich und innerhalb der geltenden gesetzlichen Frist über den vorgesehenen Meldekanal an die für ihre Registrierung zuständige nationale NIS2-Behörde.','Beispiele: Vorkehrungen zur Erkennung von Änderungen der Registrierungsangaben und datierte Änderungsaufzeichnungen, verknüpft mit den aktualisierten Angaben, der geltenden Frist und der Übermittlung über den vorgesehenen Kanal an die zuständige nationale Behörde. Bewerten Sie neben der Fristeinhaltung auch, ob die verstrichene Zeit eine unangemessene Verzögerung darstellt; wenn keine Änderung eingetreten ist, prüfen Sie die Erkennungsvorkehrungen und den Änderungsverlauf.','Die behördlichen Registerangaben bleiben veraltet, der Kontakt mit der Aufsichtsbehörde wird beeinträchtigt und die Pflicht zur Mitteilung von Änderungen wird nicht erfüllt.','S-REG · Registrierung und Änderungen','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C19.3','Richtlinien zu Domain-Daten und Überprüfungsverfahren sind öffentlich zugänglich (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Das jeweils erfasste Register oder der erfasste Anbieter von Registrierungsdiensten veröffentlicht die Richtlinien und Verfahren, die zur Gewährleistung richtiger und vollständiger Registrierungsdaten eingesetzt werden, einschließlich der Überprüfung; die öffentliche Fassung entspricht dem tatsächlich angewandten Verfahren.','Bei einem erfassten Register oder Anbieter von Registrierungsdiensten umfassen Beispiele öffentlich zugängliche Richtlinien zu Domain-Daten und Überprüfungsverfahren sowie eine datierte Prüfung, dass die veröffentlichten Inhalte zugänglich sind und den angewandten Verfahren entsprechen.','Registranten und andere Nutzende können nicht nachvollziehen oder beanstanden, wie Registrierungsdaten überprüft werden, was zu uneinheitlichen Angaben und vermeidbaren Streitigkeiten führt.','S-DOM · TLD-Namenregister und Domänennamen-Registrierung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C19.1','Die erforderlichen Domain-Registrierungsdaten sind richtig und vollständig (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Prüfen Sie, ob die erforderlichen Felder der Domain-Registrierung ausgefüllt sind und ihre Werte mit den einschlägigen Registrierungs- und Überprüfungsinformationen übereinstimmen. Das bloße Vorhandensein eines Datenbankeintrags belegt weder Richtigkeit noch Vollständigkeit. (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Bei einem erfassten Register oder Anbieter von Registrierungsdiensten umfassen Beispiele die Definition der Pflichtfelder sowie datenschutzgerecht geschützte Stichproben oder beaufsichtigte Datenbankprüfungen, die Vollständigkeit und Richtigkeit im Abgleich mit einschlägigen Registrierungs- und Überprüfungsinformationen belegen.','Fehlerhafte Angaben zu Domain-Inhabern verzögern die Identifizierung und Kontaktaufnahme bei Missbrauchsuntersuchungen oder der Reaktion auf Sicherheitsvorfälle.','S-DOM · TLD-Namenregister und Domänennamen-Registrierung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C19.2','Verfahren zur Überprüfung von Domain-Daten werden tatsächlich angewandt (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Das jeweils erfasste Register oder der erfasste Anbieter von Registrierungsdiensten führt die festgelegten Prüfungen der Registrierungsdaten durch und bearbeitet fehlgeschlagene oder widersprüchliche Ergebnisse; ein veröffentlichtes Verfahren ohne Nachweis seiner Anwendung reicht nicht aus.','Bei einem erfassten Register oder Anbieter von Registrierungsdiensten umfassen Beispiele Überprüfungsverfahren und datenschutzgerecht geschützte Vorgangsaufzeichnungen, die tatsächlich durchgeführte Prüfungen, deren Ergebnisse und die Behandlung von Daten mit fehlgeschlagener Prüfung oder Widersprüchen zeigen.','Falsche Registrantenangaben oder Kontaktdaten, unter denen niemand erreichbar ist, werden als echt akzeptiert, sodass sich missbräuchliche Registrierungen einer verlässlichen Zuordnung und weiteren Verfolgung entziehen.','S-DOM · TLD-Namenregister und Domänennamen-Registrierung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C19.4','Nicht personenbezogene Domain-Registrierungsdaten werden ohne unangemessene Verzögerung veröffentlicht (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Machen Sie die nicht personenbezogenen Registrierungsfelder nach der Registrierung ohne unangemessene Verzögerung öffentlich abrufbar. Prüfen Sie die tatsächlichen Registrierungs- und Veröffentlichungszeitpunkte sowie die ausgewählten Felder; ein Veröffentlichungsplan allein belegt keine rechtzeitige Verfügbarkeit, und personenbezogene Felder dürfen nicht unterschiedslos offengelegt werden. (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Bei einem erfassten Register oder Anbieter von Registrierungsdiensten umfassen Beispiele öffentliche Abfrageergebnisse und Zeitstempel für Registrierung und Veröffentlichung, die die Verfügbarkeit nicht personenbezogener Registrierungsdaten ohne unangemessene Verzögerung belegen. Prüfen Sie die Auswahl der veröffentlichten Felder, ohne unnötige personenbezogene Daten zu kopieren.','R1: Untersuchende und andere Nutzende können erforderliche nicht personenbezogene Domain-Informationen nicht zeitnah erhalten, wodurch sich die Erkennung und weitere Verfolgung von Missbrauch verzögern. R2: Eine Veröffentlichung, die nicht zwischen personenbezogenen und nicht personenbezogenen Feldern unterscheidet, legt personenbezogene Informationen der Registranten gegenüber der Öffentlichkeit offen.','S-DOM · TLD-Namenregister und Domänennamen-Registrierung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C19.8','Richtlinien und Verfahren für den Zugang zu Domain-Daten sind veröffentlicht (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Das jeweils erfasste Register oder der erfasste Anbieter von Registrierungsdiensten veröffentlicht, wie berechtigte Zugangssuchende nicht öffentliche Registrierungsdaten anfordern können, einschließlich des Antragswegs und der zur Beurteilung des Antrags erforderlichen Angaben.','Bei einem erfassten Register oder Anbieter von Registrierungsdiensten umfassen Beispiele die veröffentlichte Zugangsrichtlinie und das Antragsverfahren sowie eine datierte Zugänglichkeitsprüfung, die zeigt, dass Antragstellende den Antragsweg und die Anforderungen finden können.','Berechtigte Antragstellende können den Antragsweg oder die Anforderungen nicht erkennen, sodass Anträge falsch zugeleitet oder verzögert werden.','S-DOM · TLD-Namenregister und Domänennamen-Registrierung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C19.5','Der Zugang zu Domain-Daten ist auf rechtmäßige, begründete Anträge beschränkt (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Bei dem jeweils erfassten Register oder Anbieter von Registrierungsdiensten erhalten berechtigte Zugangssuchende auf rechtmäßige, ordnungsgemäß begründete Anträge hin Zugang zu nicht öffentlichen Registrierungsdaten; beurteilen Sie die Gründe und die zulässige Offenlegung, statt jeden Antrag automatisch als berechtigt zu behandeln.','Bei einem erfassten Register oder Anbieter von Registrierungsdiensten umfassen Beispiele Zugangskriterien und geschwärzte Antragsentscheidungen, aus denen die Rechtsgrundlage, die Begründung, der genehmigte Offenlegungsumfang und gegebenenfalls Ablehnungsgründe hervorgehen. Vergleichen Sie tatsächliche Zugriffe oder Offenlegungen mit diesen Entscheidungen; wenn keine Anträge vorliegen, prüfen Sie den eingerichteten Prozess, statt Fälle zu erfinden.','R1: Unbegründete oder übermäßige Offenlegungen machen nicht öffentliche Registrierungsdaten unbefugten Antragstellenden zugänglich. R2: Rechtmäßige, begründete Anträge werden zu Unrecht abgelehnt, wodurch berechtigte Missbrauchsuntersuchungen behindert werden.','S-DOM · TLD-Namenregister und Domänennamen-Registrierung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C19.6','Anträge auf Zugang zu Domain-Daten werden ohne unangemessene Verzögerung und innerhalb von 72 Stunden beantwortet (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Verfolgen Sie Zugangsanträge vom Eingang bis zur Antwort und antworten Sie ohne unangemessene Verzögerung und innerhalb von 72 Stunden nach Eingang. Eine interne Neuzuweisung setzt die Frist nicht erneut in Gang, und ein Eingangsprotokoll allein belegt nicht, dass eine Antwort versandt wurde. Wenn keine Anträge eingegangen sind, bewerten Sie die Bereitschaft zur Bearbeitung, statt eine nachgewiesene Bearbeitungsleistung zu behaupten. (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Bei einem erfassten Register oder Anbieter von Registrierungsdiensten umfassen Beispiele datenschutzgerecht geschützte Antrags- und Antwortaufzeichnungen, die Eingangszeit, Antwortzeit und etwaige Verzögerungen zeigen. Prüfen Sie sowohl die Antwort ohne unangemessene Verzögerung als auch die Grenze von 72 Stunden; wenn keine Anträge eingegangen sind, prüfen Sie die Bereitschaft zur Bearbeitung, ohne eine nachgewiesene Antwortleistung zu behaupten.','Antworten verzögern sich, Untersuchungen werden behindert und die Frist zur Beantwortung von Zugangsanträgen wird versäumt.','S-DOM · TLD-Namenregister und Domänennamen-Registrierung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C19.9','Die Zusammenarbeit verhindert eine doppelte Erhebung von Domain-Registrierungsdaten (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Die Beteiligten arbeiten zusammen, damit Domain-Namen-Registrierungsdaten nicht doppelt erhoben werden. (Gilt nur für TLD-Namenregister und Anbieter von Domain-Namen-Registrierungsdiensten.)','Bei einem erfassten Register oder Anbieter von Registrierungsdiensten umfassen Beispiele Kooperationsvereinbarungen, Registrierungsdatenflüsse und repräsentative Erhebungsaufzeichnungen, die zeigen, wie die Beteiligten eine doppelte Erhebung derselben Registrierungsdaten vermeiden.','Wiederholte Erhebungen erzeugen widersprüchliche Registrantenaufzeichnungen und unnötige Kopien personenbezogener Daten, verzögern Korrekturen und erhöhen das Offenlegungsrisiko.','S-DOM · TLD-Namenregister und Domänennamen-Registrierung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('C27.1','Verantwortliche Personen verfügen über die Befugnisse zur Sicherstellung der NIS2-Konformität','Personen, die für die Einrichtung verantwortlich sind oder sie rechtlich vertreten und die befugt sind, sie zu vertreten, in ihrem Namen Entscheidungen zu treffen oder sie zu kontrollieren, verfügen über die erforderlichen Befugnisse, um die Einhaltung von NIS2 sicherzustellen.','Beispiele: aktuelle Vertretungs- und Entscheidungsmandate, übertragene Befugnisse oder gleichwertige Governance-Aufzeichnungen, aus denen die verantwortlichen Personen und ihre Befugnisse hervorgehen, Maßnahmen zur Einhaltung der Vorgaben durchzusetzen, soweit verfügbar durch einschlägige Entscheidungen bestätigt.','Eine rechtlich verantwortliche Person kann erforderliche Maßnahmen nicht durchsetzen, sodass Verstöße gegen Compliance-Anforderungen aufgrund fehlender Befugnisse ungelöst bleiben.','A-GOV · Leitungsorganisation','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('C22.1','Das Leitungsorgan genehmigt die aktuellen Risikomanagementmaßnahmen im Bereich der Cybersicherheit','Aus der Genehmigung des Leitungsorgans geht hervor, welche Risikomanagementmaßnahmen im Bereich der Cybersicherheit derzeit gelten, sodass Prüfende eine genehmigte Fassung oder einen genehmigten Umfang von einem Entwurf oder einem nicht genehmigten Vorschlag eines operativen Teams unterscheiden können.','Beispiele: die aktuellen Risikomanagementmaßnahmen im Bereich der Cybersicherheit, verknüpft mit einer datierten Genehmigung des Leitungsorgans, die die genehmigte Fassung oder den genehmigten Umfang bezeichnet, unabhängig davon, ob sie in einem Beschluss, einem Workflow oder einer gleichwertigen Aufzeichnung festgehalten ist.','Sicherheitsmaßnahmen werden angefochten oder umgangen, weil die Leitung ihre Prioritäten und Verbindlichkeit nicht bestätigt hat, wodurch sich die Umsetzung verzögert.','A-GOV · Leitungsorganisation','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('C22.2','Für Sicherheitsaufgaben stehen ausreichend Personal, finanzielle Mittel und Werkzeuge zur Verfügung','Vergleichen Sie die zugewiesenen Sicherheitsaufgaben mit der verfügbaren Personalzeit, den finanziellen Mitteln und den nutzbaren Werkzeugen zu ihrer Durchführung; eine genehmigte Zuständigkeit ist nicht ausreichend mit Ressourcen ausgestattet, wenn wesentliche Aufgaben nicht ausgeführt werden können.','Beispiele: zugewiesene Sicherheitsaufgaben im Vergleich mit verfügbarer Personalzeit, finanziellen Mitteln und nutzbaren Werkzeugen, belegt durch Ressourcenzuweisungen und Betriebsaufzeichnungen. Beziehen Sie gegebenenfalls festgestellte Ressourcenengpässe und deren Behandlung ein.','Genehmigte Maßnahmen funktionieren nicht, weil Personal, Zeit, finanzielle Mittel oder Werkzeuge fehlen, sodass Risiken unbehandelt bleiben.','A-GOV · Leitungsorganisation','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('C27.3','Unvereinbare Aufgaben werden getrennt, soweit dies erforderlich ist','Ermitteln Sie unvereinbare Aufgaben und vergleichen Sie die dafür zugewiesenen Verantwortlichkeiten mit den tatsächlichen Berechtigungen und Abläufen, um die jeweils erforderliche Aufgabentrennung zu überprüfen. Eine schriftliche Trennungsregel reicht nicht aus, wenn eine Person dieselbe Handlung weiterhin einleiten, genehmigen und verbergen kann. Jede alternative Regelung muss im Hinblick auf die geltende Anforderung begründet werden; unabhängige Aufsicht ersetzt nicht automatisch eine vorgeschriebene Aufgabentrennung.','Beispiele: ermittelte unvereinbare Aufgaben, abgeglichen mit tatsächlichen Verantwortlichkeiten, Berechtigungen und stichprobenartig geprüften Vorgängen, die die jeweils erforderliche Trennung zeigen. Wenn eine alternative Regelung herangezogen wird, prüfen Sie deren Begründung und die wirksame unabhängige Kontrolle anhand der geltenden Anforderung.','Eine Person kann eine unzulässige Handlung ohne wirksame unabhängige Kontrolle einleiten, genehmigen und verbergen.','A-GOV · Leitungsorganisation','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('C27.2','Die Sicherheitsberichterstattung erreicht das Leitungsorgan wirksam (Bei Einrichtungen im CIR-Anwendungsbereich berichtet mindestens eine Person unmittelbar an das Leitungsorgan.)','Sicherheitsfeststellungen, Ressourcenbedarfe und Entscheidungen, die einer Aufsicht bedürfen, erreichen das Leitungsorgan über einen funktionierenden Berichtsweg; bei Einrichtungen im CIR-Anwendungsbereich berichtet mindestens eine Person unmittelbar an dieses Organ.','Beispiele: Berichtszuständigkeiten und aktuelle Mitteilungen, die belegen, dass die Sicherheitsberichterstattung das Leitungsorgan erreicht. Benennen Sie bei Einrichtungen im CIR-Anwendungsbereich mindestens eine Person mit einem unmittelbaren Berichtsweg und belegen Sie, dass dieser Weg funktioniert.','Wesentliche Sicherheitsprobleme werden gefiltert oder verzögert, bevor sie die Leitung erreichen, sodass Entscheidungen und Korrekturmaßnahmen zu spät erfolgen.','A-GOV · Leitungsorganisation','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('C23.1','Die Leitung erhält ausreichende Informationen zu Umsetzung und Risiken für ihre Aufsicht','Stellen Sie dem Leitungsorgan aktuelle Informationen zum Umsetzungsstand und zu wesentlichen Risiken einschließlich erheblicher Mängel und Verzögerungen bereit, damit es seine Aufsicht ausüben kann. Vergleichen Sie die tatsächlich eingegangenen Informationen mit bekannten wesentlichen Problemen; ein Bericht, der die Leitung nie erreicht oder diese Probleme auslässt, reicht nicht aus.','Beispiele: dem Leitungsorgan bereitgestellte Informationen zum Umsetzungsstand und zu wesentlichen Risiken, mit Nachweisen ihres Eingangs und einem Abgleich mit bekannten wesentlichen Problemen und dem aktuellen Umsetzungsstand.','Die Leitung stützt sich auf unvollständige oder veraltete Informationen und übersieht schwerwiegende Mängel oder verzögerte Maßnahmen.','A-GOV · Leitungsorganisation','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('C23.2','Die Leitung überwacht die Umsetzung der Cybersicherheitsmaßnahmen','Die Leitung übt die Aufsicht über die Umsetzung tatsächlich aus.','Beispiele: Besprechungen zur Überprüfung durch die Leitung, Entscheidungen, Eingriffe oder Aufzeichnungen über Folgemaßnahmen, verknüpft mit dem Umsetzungsstand, wesentlichen Problemen und dem Fortschritt der von ihr angeforderten Maßnahmen.','Bekannte Mängel bestehen fort, weil die Leitung nicht entscheidet, eingreift oder nachfasst; die Aufsicht wird zu einer bloßen Berichtsformalität.','A-GOV · Leitungsorganisation','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('C27.4','Sicherheitsrollen und personelle Zuweisungen werden überprüft','Sicherheitsrollen und personelle Zuweisungen werden überprüft. Prüfen Sie, ob die zugewiesenen Verantwortlichkeiten, Entscheidungsbefugnisse und das verfügbare Personal weiterhin dem aktuellen Sicherheitsbedarf entsprechen. Halten Sie Entscheidungen fest und aktualisieren Sie Zuweisungen bei Bedarf. Bei Einrichtungen im CIR-Anwendungsbereich sind Rollen in geplanten Abständen und nach erheblichen Sicherheitsvorfällen oder Änderungen sowie personelle Zuweisungen und Personalausstattung mindestens jährlich zu überprüfen.','Beispiele: datierte Überprüfungen von Verantwortlichkeiten, Entscheidungsbefugnissen und Personalausstattung mit geänderten Zuweisungen oder begründeten Entscheidungen, nichts zu ändern. Gleichen Sie bei Einrichtungen im CIR-Anwendungsbereich die Rollenüberprüfungen mit den geplanten Abständen und den Auslösern erheblicher Sicherheitsvorfälle oder Änderungen ab; gleichen Sie die Überprüfungen personeller Zuweisungen und der Personalausstattung mit der Vorgabe einer mindestens jährlichen Überprüfung ab.','Sicherheitsaufgaben werden nach organisatorischen Änderungen versäumt oder verzögert, weil Verantwortlichkeiten und verfügbares Personal nicht mehr dem betrieblichen Bedarf entsprechen.','A-GOV · Leitungsorganisation','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('C25.2','Die Schulung des Leitungsorgans vermittelt die erforderlichen Kenntnisse und Fähigkeiten im Risikomanagement','Die Schulungsinhalte befähigen die Mitglieder des Leitungsorgans, Cybersicherheitsrisiken zu erkennen und Risikomanagementverfahren sowie deren Auswirkungen auf die erbrachten Dienste zu bewerten; die bloße Teilnahme belegt nicht, dass dieser Lernbedarf abgedeckt ist.','Beispiele: Ziele und Inhalte der Schulungen des Leitungsorgans, zugeordnet zu den erforderlichen Kenntnissen und Fähigkeiten im Risikomanagement, gegebenenfalls mit einschlägigen Übungen, Leistungsüberprüfungen oder Gesprächsaufzeichnungen, die diese Übereinstimmung belegen.','Die Leitung beurteilt Prioritäten der Risikobehandlung falsch oder akzeptiert eine Risikoexposition, die sie nicht versteht, weil die Schulung die notwendigen Fähigkeiten im Risikomanagement nicht vermittelt hat.','G-MGT · Schulung der Leitung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('C25.1','Alle von der Schulungspflicht erfassten Mitglieder des Leitungsorgans absolvieren die erforderliche Schulung','Gleichen Sie die von der Pflicht erfassten Mitglieder des Leitungsorgans mit den Nachweisen abgeschlossener Schulungen ab, um noch nicht geschulte Personen zu ermitteln; eine geplante Teilnahme oder der Abschluss allein durch die sicherheitsverantwortliche Person belegt nicht die Abdeckung aller verpflichteten Mitglieder.','Beispiele: die Gesamtheit der von der Pflicht erfassten Mitglieder des Leitungsorgans, abgeglichen mit individuellen Schulungsabschlussnachweisen und etwaigen noch offenen Anforderungen. Teilnahmenachweise, Bestätigungen des Schulungsanbieters oder gleichwertige Aufzeichnungen können den Abschluss belegen, soweit dies geeignet ist.','Ungeschulte Mitglieder des Leitungsorgans treffen Genehmigungs- oder Aufsichtsentscheidungen, ohne wesentliche Auswirkungen auf die Cybersicherheit und auf Abhängigkeiten zwischen Diensten zu erkennen.','G-MGT · Schulung der Leitung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('C29.2','Die Informationssicherheitsleitlinie legt den Sicherheitsansatz und die Verantwortlichkeiten fest','Die Informationssicherheitsleitlinie legt den Sicherheitsansatz und die Verantwortlichkeiten fest. Bestimmen Sie Sicherheitsziele, rechenschaftspflichtige Rollen, Umsetzungsressourcen und Überwachungsvorkehrungen und benennen Sie die unterstützenden themenspezifischen Richtlinien. Die Genehmigung durch die Leitung und die betriebliche Umsetzung müssen nachgewiesen werden; separate Dokumente sind nicht für jedes Thema erforderlich, sofern die Anforderungen erkennbar bleiben.','Beispiele: die aktuelle Informationssicherheitsleitlinie, aus der Ziele, Verantwortlichkeiten, Ressourcen, Überwachungsvorkehrungen und unterstützende themenbezogene Anforderungen hervorgehen, verknüpft mit der Genehmigung durch die Leitung und Stichproben zur betrieblichen Anwendung. Diese Elemente können in einem Dokument oder in einer identifizierbaren Zusammenstellung vorhandener Aufzeichnungen enthalten sein.','Teams treffen unvereinbare Sicherheitsentscheidungen oder umgehen regelmäßig vereinbarte Schutzmaßnahmen, sodass Informationen und Dienste an organisatorischen Schnittstellen ungeschützt bleiben.','A-POL · Sicherheitskonzepte und Dokumente','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C29.5','Sicherheitsdokumente und -aufzeichnungen sind aktuell, verantwortlichen Personen zugewiesen und abrufbar','Für erforderliche Sicherheitsdokumente und -aufzeichnungen sind die aktuellen Fassungen erkennbar, verantwortliche Personen zugewiesen und Aufbewahrungsfristen festgelegt; sie können bei Bedarf abgerufen werden.','Beispiele: Dokumentmetadaten oder gleichwertige Aufzeichnungen, aus denen aktuelle Fassungen, verantwortliche Personen und Aufbewahrungsfristen hervorgehen, ergänzt durch den Abruf stichprobenartig ausgewählter aktueller Anweisungen und aufbewahrter Sicherheitsaufzeichnungen.','R1: Im Betrieb werden veraltete Anweisungen verwendet, was zu fehlerhaften Sicherheitsmaßnahmen führt. R2: Verlorene oder nicht auffindbare Aufzeichnungen verhindern, dass Sicherheitsentscheidungen oder deren Umsetzung rekonstruiert und belegt werden können.','A-POL · Sicherheitskonzepte und Dokumente','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C29.3','Relevante Mitarbeitende und externe Parteien erhalten und befolgen Sicherheitsanweisungen','Relevante Mitarbeitende und externe Parteien erhalten die für ihre Arbeit geltenden Sicherheitsrichtlinien oder -anweisungen und befolgen sie. Empfang und Kenntnisnahme werden nachgewiesen, soweit dies erforderlich ist.','Beispiele: Verteilungs- oder Zugangsaufzeichnungen für relevante Mitarbeitende und externe Parteien, erforderlichenfalls Nachweise über Empfang und Kenntnisnahme sowie Arbeitsstichproben oder Beobachtungen, die die Einhaltung der geltenden Anweisungen belegen.','Mitarbeitende oder externe Parteien gehen unsachgemäß mit Informationen um oder umgehen erforderliche Schutzmaßnahmen, weil die für ihre Arbeit relevanten Anweisungen nicht verstanden oder nicht befolgt werden.','A-POL · Sicherheitskonzepte und Dokumente','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C29.4','Sicherheitsrichtlinien und -verfahren werden gemäß den jeweils geltenden Prüfplänen überprüft','Sicherheitsrichtlinien und -verfahren werden gemäß den jeweils geltenden Prüfplänen überprüft. Führen Sie einen erkennbaren Prüfplan für die übergeordnete Leitlinie und die relevanten themenspezifischen Richtlinien und Verfahren mit Verantwortlichen und den jeweils geltenden Auslösern durch Sicherheitsvorfälle oder Änderungen. Halten Sie die Überprüfung und die daraus resultierenden Aktualisierungen oder eine begründete Entscheidung, nichts zu ändern, fest. Bei Einrichtungen im CIR-Anwendungsbereich überprüft die Leitung die übergeordnete Leitlinie mindestens jährlich; wenden Sie die jeweilige Überprüfungsvorgabe des einzelnen Themas an, statt für alles ein einheitliches jährliches Intervall festzulegen.','Beispiele: ein erkennbarer Prüfplan, der jede relevante Richtlinie oder jedes relevante Verfahren mit den Verantwortlichen, dem Intervall und den Auslösern durch Sicherheitsvorfälle oder Änderungen verknüpft, mit datierten Überprüfungen und Aktualisierungen oder begründeten Entscheidungen, nichts zu ändern. Beziehen Sie bei Einrichtungen im CIR-Anwendungsbereich die mindestens jährliche Überprüfung der übergeordneten Leitlinie durch die Leitung ein und behalten Sie zugleich den jeweils geltenden Prüfplan jedes Themas bei.','Mitarbeitende befolgen veraltete Regeln, die geänderte Systeme oder Arbeitsweisen nicht mehr schützen, sodass zuvor behandelte Gefährdungen erneut auftreten.','A-POL · Sicherheitskonzepte und Dokumente','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C29.1','Die Richtlinie zur Risikoanalyse gibt den Rahmen für die tatsächlich durchgeführten Bewertungen von Cybersicherheitsrisiken vor','Legen Sie fest, wie Cybersicherheitsrisiken identifiziert, analysiert und bewertet werden, und wenden Sie diesen Ansatz in durchgeführten Bewertungen an. Vergleichen Sie die Richtlinie mit den tatsächlich angewandten Methoden und Annahmen; ein Richtliniendokument allein reicht nicht aus, wenn betriebliche Bewertungen einem unbegründeten, uneinheitlichen Ansatz folgen.','Beispiele: die Richtlinie zur Risikoanalyse oder gleichwertige erkennbare Richtlinieninhalte, die Identifizierung, Analyse und Bewertung festlegen, sowie abgeschlossene Bewertungen, die zeigen, dass der festgelegte Ansatz angewandt wird.','Bewertungen lassen relevante Bedrohungen aus oder wenden unvereinbare Annahmen an, sodass Behandlungsentscheidungen wesentliche Gefährdungen unberücksichtigt lassen.','A-RSK · Risikobewertung und Risikobehandlung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C30.4','Risikobewertungsmethoden und Risikoakzeptanzkriterien werden einheitlich angewandt','Eine festgelegte Risikobewertungsmethode und Risikoakzeptanzkriterien werden bei der Einstufung von Risiken und der Entscheidung über ihre Akzeptanz einheitlich angewandt.','Beispiele: die festgelegte Bewertungsmethode und die Akzeptanzkriterien, abgeglichen mit stichprobenartig ausgewählten Risikoeinstufungen und Akzeptanzentscheidungen, einschließlich Erläuterungen für eine wesentlich unterschiedliche Behandlung vergleichbarer Risiken.','Risikoeinstufungen hängen ohne gemeinsame Grundlage von individuellen Einschätzungen ab, wodurch Prioritäten und Akzeptanzentscheidungen verzerrt werden.','A-RSK · Risikobewertung und Risikobehandlung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C30.1','Cybersicherheitsrisiken werden über Dienste, Systeme und Abhängigkeiten hinweg bewertet','Cybersicherheitsrisiken werden über Dienste, Systeme und Abhängigkeiten hinweg bewertet. Nutzen Sie aktuelle Informationen zu Bedrohungen, Schwachstellen, Eintrittswahrscheinlichkeit und Auswirkungen, einschließlich Abhängigkeiten von Dritten und einzelner Ausfallpunkte. Berücksichtigen Sie Vertraulichkeit, Integrität, Authentizität und Verfügbarkeit mit einem gefahrenübergreifenden Ansatz, einschließlich relevanter physischer Ereignisse. Berücksichtigen Sie Auswirkungen auf Diensteempfänger und andere Dienste, nicht nur den eigenen finanziellen Verlust der Einrichtung.','Beispiele: aktuelle Bewertungen, die Dienste, Systeme und Abhängigkeiten von Dritten mit Bedrohungen, Schwachstellen, Eintrittswahrscheinlichkeit und Auswirkungen verknüpfen, einschließlich einzelner Ausfallpunkte und relevanter physischer Gefahren. Prüfen Sie Auswirkungen auf Vertraulichkeit, Integrität, Authentizität und Verfügbarkeit sowie Folgen für Empfänger und andere Dienste.','Erhebliche Risiken werden übersehen oder falsch eingestuft, was zu ungeeigneten Prioritäten und Maßnahmen führt.','A-RSK · Risikobewertung und Risikobehandlung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C30.2','Entscheidungen zur Risikobehandlung sind begründet und mit den bewerteten Risiken verknüpft','Entscheidungen zur Risikobehandlung sind begründet und mit den bewerteten Risiken verknüpft. Halten Sie die ausgewählten Schutzmaßnahmen und deren Begründungen fest und berücksichtigen Sie dabei Risikoexposition, Größe der Einrichtung, Eintrittswahrscheinlichkeit und Schweregrad, gesellschaftliche und wirtschaftliche Folgen, den Stand der Technik und die Umsetzungskosten. Nutzen Sie relevante Erkenntnisse zur Wirksamkeit, den Schutzbedarf der Assets und Kontinuitätsanforderungen. Die Akzeptanz eines Risikos hebt eine geltende gesetzliche Pflicht nicht auf.','Beispiele: Behandlungsentscheidungen, die mit den bewerteten Risiken und ausgewählten Schutzmaßnahmen verknüpft sind und deren Verhältnismäßigkeit anhand von Risikoexposition, Größe, Eintrittswahrscheinlichkeit, Schweregrad, gesellschaftlichen/wirtschaftlichen Auswirkungen, Stand der Technik und Kosten erläutern. Relevante Wirksamkeitsergebnisse, der Schutzbedarf der Assets, Kontinuitätsanforderungen und geltende Pflichten sollten in der Entscheidungsgrundlage nachvollziehbar sein.','Behandlungsentscheidungen lassen sich nicht auf die Risiken und Annahmen zurückführen, auf die sie sich beziehen, sodass bei einer erneuten Prüfung der Entscheidungen ungeeignete Schutzmaßnahmen oder unbehandelte Gefährdungen entstehen.','A-RSK · Risikobewertung und Risikobehandlung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C30.5','Risikobehandlungsmaßnahmen haben Verantwortliche, Zieltermine und eine Fortschrittsverfolgung','Jeder Risikobehandlungsmaßnahme sind eine verantwortliche Person und ein geplanter Umsetzungstermin zugewiesen. Fortschritt, Verzögerungen und Abschluss werden nachverfolgt.','Beispiele: Behandlungsmaßnahmen in bestehenden Plänen oder Aufzeichnungen zur Aufgabenverfolgung, aus denen die verantwortliche Person, der geplante Termin, der Fortschritt, Verzögerungen und Nachweise der tatsächlich abgeschlossenen Umsetzung hervorgehen.','Die Behandlung gerät ins Stocken, Maßnahmen verlieren ihre Verantwortlichen oder ungelöste Risiken bestehen hinter bloßen Abschlussbehauptungen fort.','A-RSK · Risikobewertung und Risikobehandlung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C30.3','Restrisiken werden von rechenschaftspflichtigen Entscheidungsträgern bewertet und akzeptiert','Die nach der Behandlung verbleibenden Risiken werden vom Leitungsorgan oder gegebenenfalls von einem befugten, rechenschaftspflichtigen Risikoverantwortlichen bewertet und akzeptiert, wobei eine angemessene Berichterstattung an das Leitungsorgan erfolgt.','Beispiele: Bewertungen der nach der Behandlung verbleibenden Restrisiken, verknüpft mit deren Akzeptanz durch das Leitungsorgan oder einen befugten, rechenschaftspflichtigen Risikoverantwortlichen, mit Nachweisen einer angemessenen Berichterstattung an das Leitungsorgan, wenn die Akzeptanz delegiert wurde.','Eine verbleibende Risikoexposition wird ohne Befugnis oder Verständnis akzeptiert, oder die Akzeptanz wird fälschlich zur Rechtfertigung von Regelverstößen genutzt.','A-RSK · Risikobewertung und Risikobehandlung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C30.6','Risikobewertungen und Behandlungspläne werden überprüft und aktualisiert','Risikobewertungen und Behandlungspläne werden überprüft und aktualisiert. Führen Sie Überprüfungen in geplanten Abständen und nach erheblichen Sicherheitsvorfällen oder erheblichen Änderungen des Betriebs oder der Risiken durch. Bei Einrichtungen im CIR-Anwendungsbereich erfolgt die regelmäßige Überprüfung mindestens jährlich. Halten Sie das Ergebnis fest und aktualisieren Sie Bewertungsergebnisse, Behandlungsprioritäten und Pläne bei Bedarf.','Beispiele: datierte Überprüfungen und daraus resultierende Aktualisierungen oder bestätigte Bewertungen und Behandlungspläne, abgeglichen mit den geplanten Intervallen sowie den Auslösern erheblicher Sicherheitsvorfälle, betrieblicher Änderungen und Risikoänderungen. Prüfen Sie bei Einrichtungen im CIR-Anwendungsbereich, ob die regelmäßige Überprüfung mindestens jährlich erfolgt.','Veränderungen bei Systemen, Bedrohungen oder Sicherheitsvorfällen machen die Annahmen der Risikobehandlung ungültig, sodass neue oder erhöhte Gefährdungen unbehandelt bleiben.','A-RSK · Risikobewertung und Risikobehandlung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('C42.1','Das Asset-Inventar erfasst Dienste und die sie unterstützenden Assets','Das Asset-Inventar erfasst Dienste und die sie unterstützenden Assets. Führen Sie für den bewerteten Geltungsbereich ein vollständiges, richtiges und konsistentes Inventar, das betriebliche Tätigkeiten und Dienste, ihre Beschreibungen, die unterstützenden Netz- und Informationssysteme sowie zugehörige Assets umfasst. Beziehen Sie relevante Cloud-Abhängigkeiten, Abhängigkeiten von Betriebstechnologie und ausgelagerte Abhängigkeiten ein, statt das Inventar auf eigene Hardware zu beschränken. Erfassen Sie Änderungen nachvollziehbar; C42.4 bewertet den regelmäßigen Abgleich und die Überprüfung.','Beispiele: das aktuelle Inventar mit betrieblichen Tätigkeiten, Diensten, Beschreibungen und unterstützenden Systemen/Assets innerhalb des Geltungsbereichs, einschließlich relevanter Cloud-, OT- und ausgelagerter Abhängigkeiten, mit nachvollziehbaren Änderungen. Vergleichen Sie repräsentative Einträge mit dem tatsächlichen Betrieb, um Vollständigkeit und Richtigkeit zu bewerten.','Nicht erfasste Assets werden bei der Installation von Patches, der Zugriffskontrolle oder der Bestimmung des Vorfallsumfangs übergangen, sodass eine Kompromittierung außerhalb der betrieblichen Aufsicht fortbesteht.','I-AST · Inventar, Verantwortlichkeiten und Informationsklassifizierung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C42.3','Assets im Geltungsbereich haben rechenschaftspflichtige Verantwortliche','Für jedes Asset im Geltungsbereich ist eine Person oder Rolle erkennbar, die für dessen Verwaltung und Schutzentscheidungen rechenschaftspflichtig ist; die technische Betreuung allein begründet diese Rechenschaftspflicht nicht.','Beispiele: Asset- oder Dienstaufzeichnungen, Verantwortungszuweisungen oder gleichwertige Informationen, aus denen für jedes Asset im Geltungsbereich eine rechenschaftspflichtige verantwortliche Person oder Rolle hervorgeht, bestätigt durch die jeweiligen Verantwortlichen.','Schutz- oder Wartungsmaßnahmen für Assets bleiben unerledigt, weil Teams annehmen, andere Verantwortliche würden handeln, wodurch bekannte Gefährdungen oder Dienststörungen länger bestehen bleiben.','I-AST · Inventar, Verantwortlichkeiten und Informationsklassifizierung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C42.2','Die Schutzstufen von Assets berücksichtigen Vertraulichkeit, Integrität, Authentizität und Verfügbarkeit','Die Schutzstufen von Assets berücksichtigen die Anforderungen an Vertraulichkeit, Integrität, Authentizität und Verfügbarkeit. Weisen Sie Systemen und unterstützenden Assets Schutzstufen auf Grundlage ihrer Sensibilität, Kritikalität, Risiken und Dienstabhängigkeiten zu. Stimmen Sie die Verfügbarkeitsanforderungen mit Kontinuitäts- und Wiederherstellungszielen ab. INFO-CLASS bewertet gesondert die Vertraulichkeitskennzeichnungen von Informationen; dies ersetzt nicht die anderen Schutzdimensionen.','Beispiele: zugewiesene Schutzstufen für Assets und Systeme, verknüpft mit Sensibilität, Kritikalität, Risiko und Dienstabhängigkeiten in Bezug auf Vertraulichkeit, Integrität, Authentizität und Verfügbarkeit. Vergleichen Sie die Verfügbarkeitsstufen mit den Kontinuitäts- und Wiederherstellungszielen.','R1: Schutzaufwand wird falsch zugeteilt, weil die Auswirkungen von Assets auf Dienste und ihre Abhängigkeiten unterschätzt werden, sodass prioritäre Betriebsabläufe störungsanfällig bleiben. R2: Unterschätzte Integritätsanforderungen ermöglichen Änderungen kritischer Daten oder Systemkonfigurationen ohne angemessene Schutzmaßnahmen, was zu falschen Geschäftsentscheidungen oder unsicheren Betriebsabläufen führt.','I-AST · Inventar, Verantwortlichkeiten und Informationsklassifizierung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C42.4','Asset-Überprüfungen und Aktualisierungen nach wesentlichen Änderungen werden durchgeführt','Führen Sie die geplanten Asset-Überprüfungen durch und aktualisieren Sie die Inventareinträge bei wesentlichen Änderungen. Bewahren Sie die Prüfergebnisse und nachvollziehbaren Aktualisierungen oder eine begründete Feststellung auf, dass keine Aktualisierung erforderlich war; ein unverändertes Inventar allein belegt nicht, dass eine Überprüfung stattgefunden hat.','Beispiele: abgeschlossene Asset-Überprüfungen, Abgleiche zur Ermittlung fehlender oder veralteter Einträge und nachvollziehbare Inventaraktualisierungen nach wesentlichen Änderungen oder Prüfergebnisse, die bestätigen, dass keine Aktualisierung erforderlich war.','Veraltete Asset-Angaben führen dazu, dass neue oder geänderte Systeme bei Sicherheitsaufgaben übergangen werden und Maßnahmen zur Vorfallsbearbeitung oder Wiederherstellung fehlgeleitet werden.','I-AST · Inventar, Verantwortlichkeiten und Informationsklassifizierung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('INFO-CLASS','Daten und Informationen werden nach Vertraulichkeitsstufe klassifiziert','Weisen Sie Daten und Informationen anhand des Klassifizierungsschemas der Einrichtung und der Folgen einer unbefugten Offenlegung eine Vertraulichkeitsstufe zu; ein Geräteinventar allein zeigt nicht, dass die Informationen der erfassten Geräte klassifiziert wurden.','Beispiele: das Schema zur Vertraulichkeitsklassifizierung und danach klassifizierte repräsentative Informationen mit Erläuterungen, die die zugewiesenen Stufen begründen. Geschwärzte Stichproben oder eine beaufsichtigte Einsichtnahme können die Klassifizierung belegen, ohne sensible Inhalte offenzulegen.','Sensible Informationen werden als öffentlich oder intern behandelt, wodurch unbefugter Zugriff oder unbefugte Offenlegung möglich wird.','I-AST · Inventar, Verantwortlichkeiten und Informationsklassifizierung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('INFO-LABEL','Informationskennzeichnungen entsprechen der zugewiesenen Vertraulichkeitsklasse','Wenden Sie die Kennzeichnungsregeln der Einrichtung so an, dass Nutzende die Vertraulichkeitsklasse erkennen können, die relevanten Informationen oder Datenträgern zugewiesen ist; eine sichtbare Kennzeichnung oder zugehörige Metadaten können verwendet werden, ohne ein einheitliches Format für alle Fälle vorzuschreiben.','Beispiele: repräsentative Dokumente, Dateien oder Datenträger mit Kennzeichnungen, die den zugewiesenen Vertraulichkeitsklassen und den geltenden Kennzeichnungsregeln entsprechen. Nutzen Sie geschwärzte Stichproben oder Beobachtungen; ein bestimmtes Kennzeichnungsformat ist nicht vorgeschrieben.','R1: Nutzende oder automatisierte Verarbeitungsregeln legen vertrauliche Informationen offen, weil die sichtbare Kennzeichnung eine niedrigere Schutzklasse ausweist. R2: Kennzeichnungen oder Asset-Markierungen selbst offenbaren unbefugten Personen sensible Angaben zu Personal, Standorten oder Netzwerken und unterstützen dadurch Auskundschaftung oder gezielte Täuschung.','I-AST · Inventar, Verantwortlichkeiten und Informationsklassifizierung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('INFO-CLASS-REV','Vertraulichkeitsklassifizierungen von Informationen werden überprüft und aktualisiert','Bewerten Sie zugewiesene Vertraulichkeitsstufen regelmäßig und nach relevanten Änderungen erneut und behalten oder korrigieren Sie jede Stufe entsprechend der aktuellen Sensibilität; CIR verlangt ausdrücklich eine regelmäßige Überprüfung, während der Änderungsauslöser in diesem Katalog eine unterstützende Praxis darstellt.','Beispiele: datierte Überprüfungen der Vertraulichkeitsklassifizierungen von Informationen und daraus resultierende Korrekturen oder bestätigte Klassifizierungen, einschließlich einer Neubewertung nach relevanten Änderungen.','Veraltete Vertraulichkeitsstufen lassen sensible Informationen ungeschützt oder führen nach einer Änderung ihrer Sensibilität zu unnötigen Einschränkungen.','I-AST · Inventar, Verantwortlichkeiten und Informationsklassifizierung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C45.2','Die Verarbeitung personenbezogener Daten für NIS2-Zwecke hat eine geeignete Rechtsgrundlage','Bestimmen Sie bei personenbezogenen Daten, die für NIS2-bezogene Tätigkeiten wie Vorfallsuntersuchungen oder Zugriffsüberwachung verwendet werden, den Zweck und die geeignete Rechtsgrundlage dieser Verarbeitung; ein allgemeiner Verweis auf NIS2 rechtfertigt für sich genommen nicht jede Nutzung personenbezogener Daten.','Beispiele: vorhandene Verarbeitungsbeschreibungen und Entscheidungen, die jede Tätigkeit mit personenbezogenen Daten für NIS2-Zwecke mit ihrem Zweck und einer geeigneten Rechtsgrundlage verknüpfen und genügend Kontext zur Begründung dieser Grundlage enthalten. Prüfen Sie Beschreibungen oder geschwärzte Aufzeichnungen statt unnötiger Kopien personenbezogener Daten.','Bei Sicherheitsaktivitäten werden personenbezogene Daten rechtswidrig verarbeitet, wodurch die Einrichtung Beschwerden, Durchsetzungsmaßnahmen und Verarbeitungsbeschränkungen ausgesetzt wird.','I-DATA · Personenbezogene Daten für NIS2-Zwecke','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C45.1','Die Nutzung personenbezogener Daten für NIS2-Zwecke ist auf das Notwendige beschränkt','Beschränken Sie bei NIS2-bezogenen Tätigkeiten die erhobenen, eingesehenen, verwendeten und aufbewahrten personenbezogenen Daten auf das, was der angegebene Sicherheitszweck erfordert; vermeiden Sie die Erhebung zusätzlicher personenbezogener Informationen allein deshalb, weil das System sie bereitstellt.','Beispiele: Entscheidungen zu Zweck und Erforderlichkeit, abgeglichen mit den tatsächlichen personenbezogenen Datenfeldern, Erhebungseinstellungen, Zugriffen/Nutzungen und der Aufbewahrung bei NIS2-bezogenen Tätigkeiten. Geschwärzte Stichproben oder eine beaufsichtigte Einsichtnahme können zeigen, dass nicht erforderliche Daten ausgeschlossen oder entfernt werden.','Übermäßige Überwachung oder Aufbewahrung setzt betroffene Personen unnötigen Risiken aus und vergrößert die Folgen einer Verletzung des Schutzes personenbezogener Daten.','I-DATA · Personenbezogene Daten für NIS2-Zwecke','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C42.5','Regeln für den Umgang mit Assets sind festgelegt und werden angewandt','Legen Sie fest und kommunizieren Sie, wie die relevanten Arten von Assets und Informationen verwendet, aufbewahrt und anderweitig gehandhabt werden dürfen, und prüfen Sie, ob die betriebliche Praxis diesen Regeln entspricht; die praktische Unterweisung der Mitarbeitenden wird gesondert unter TRN-DATA bewertet.','Beispiele: geltende Regeln für den Umgang je Asset- oder Informationsart, Nachweise, dass relevante Nutzende sie erhalten, und Beobachtungen des Umgangs oder betriebliche Stichproben, die ihre Anwendung zeigen.','R1: Unsachgemäßer Umgang führt zur Beschädigung oder zum Verlust von Geräten und Datenträgern, unterbricht die Arbeit oder macht benötigte Informationen unzugänglich. R2: Ein Umgang, der die Sensibilität nicht berücksichtigt, macht Informationen unbefugten Personen zugänglich.','I-INFO-SAFE · Schutz beim Umgang mit Informationen','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C42.6','Die Weitergabe von Assets und Informationen wird entsprechend ihrer Art und Klassifizierung geschützt','Stimmen Sie Schutzmaßnahmen für elektronische, physische und gegebenenfalls mündliche Weitergaben auf die Klassifizierung der Informationen und die Art des Assets ab, damit das gewählte Weitergabeverfahren das Material während des gesamten Austauschs schützt.','Beispiele: Vorkehrungen für die Weitergabe und repräsentative Weitergaben, die Schutzmaßnahmen entsprechend der Asset-/Informationsart und Klassifizierung zeigen und gegebenenfalls den elektronischen, physischen oder mündlichen Austausch abdecken. Vorhandene Kanaleinstellungen, beobachtete Praktiken oder Weitergabeaufzeichnungen können den Schutz belegen.','R1: Informationen werden während der Weitergabe abgefangen oder an einen unbeabsichtigten Empfänger übermittelt. R2: Übertragene Daten werden verändert oder unvollständig, sodass der Empfänger auf Grundlage unrichtiger Informationen handelt.','I-INFO-SAFE · Schutz beim Umgang mit Informationen','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('DATA-OUTFLOW','Unbefugte Übertragungen sensibler Daten werden verhindert oder erkannt','Identifizieren Sie Übertragungswege für sensible Daten und wenden Sie risikobasierte Schutzmaßnahmen an, die eine unbefugte Offenlegung verhindern oder erkennen; beurteilen Sie die erreichte Schutzwirkung und nicht den Kauf eines bestimmten Produkts zur Verhinderung von Datenverlusten.','Beispiele: risikobasierte Auswahl von Schutzmaßnahmen für relevante Übertragungswege sensibler Daten, im Betrieb angewandte Konfigurationen oder Verfahren sowie Aufzeichnungen zur Erkennung oder Verhinderung oder sicher durchgeführte Prüfungen, die zeigen, dass unbefugte Übertragungen verhindert oder erkannt werden.','Sensible Informationen werden über ein autorisiertes Konto oder einen nicht genehmigten Übertragungskanal ausgeschleust; eine verzögerte Erkennung ermöglicht weitere Offenlegungen.','I-INFO-SAFE · Schutz beim Umgang mit Informationen','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('DATA-MASK','Sensible Daten werden maskiert, wenn keine vollständige Sichtbarkeit erforderlich ist (Gilt, wenn sich Zugriffsbedarfe durch eine eingeschränkte Ansicht sensibler Daten erfüllen lassen.)','Wenn eine eingeschränkte Ansicht den Zugriffsbedarf erfüllt, verbergen Sie sensible Werte vor Nutzenden, die nicht den vollständigen Inhalt benötigen, und prüfen Sie, dass die untersuchten Zugriffswege keine unmaskierten Werte offenlegen; dies ist keine Anforderung, jedes Feld zu maskieren.','Wenn eingeschränkte Ansichten den Zugriffsbedarf erfüllen können, umfassen Beispiele Entscheidungen zur Sichtbarkeit, Maskierungseinstellungen und sicher durchgeführte Tests mit synthetischen oder unkenntlich gemachten Daten, die zeigen, dass Nutzende mit eingeschränkten Rechten über die untersuchten Zugriffswege keine vollständigen sensiblen Werte erhalten können.','Personen, die nur begrenzte Informationen benötigen, erhalten vollständige sensible Werte über Anzeigen, Exporte oder eine uneingeschränkte Reidentifizierung.','I-INFO-SAFE · Schutz beim Umgang mit Informationen','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('MEDIA-UNATTENDED','Sensible Papierunterlagen und Datenträger werden bei unbeaufsichtigter Aufbewahrung gesichert (Gilt beim Umgang mit sensiblen Informationen in physischer Form oder Wechseldatenträgern.)','Wenn sensible Papierunterlagen oder Wechseldatenträger gehandhabt werden, bewahren Sie diese bei Abwesenheit geschützt auf oder wenden Sie gleichwertige Schutzmaßnahmen an, damit unberechtigte Personen sie weder lesen noch an sich nehmen können.','Beim Umgang mit sensiblen Papierunterlagen oder Wechseldatenträgern umfassen Beispiele die geltenden Aufbewahrungsregelungen und die Beobachtung, dass unbeaufsichtigte Materialien gesichert sind, ergänzt durch relevante Prüfungen oder behobene Offenlegungsrisiken, soweit verfügbar.','Besuchende oder unbefugte Mitarbeitende lesen, fotografieren oder entwenden unbeaufsichtigt zurückgelassenes sensibles Material.','I-INFO-SAFE · Schutz beim Umgang mit Informationen','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ASSET-OFFSITE','Außerhalb der Einrichtung genutzte Assets sind geschützt (Gilt nur, wenn dienstlich genutzte Assets außerhalb der Räumlichkeiten der Einrichtung verwendet werden.)','Wenn dienstlich genutzte Assets die Räumlichkeiten der Einrichtung verlassen, wenden Sie Handhabungs- und Schutzmaßnahmen an, die zu den enthaltenen Informationen, dem Standort und dem Risiko von Verlust, Diebstahl oder unbefugter Nutzung passen; Standortverfolgung und Fernlöschung sind mögliche Schutzmaßnahmen, keine allgemeinen Anforderungen.','Bei der Nutzung dienstlicher Assets außerhalb der Einrichtung umfassen Beispiele geltende Handhabungsregelungen sowie repräsentative Assets oder Betriebsaufzeichnungen, die dem Standort und der Gefährdung angemessene Schutzmaßnahmen zeigen. Prüfen Sie ausgewählte Schutzmaßnahmen und relevante Aufzeichnungen zum Umgang mit Verlusten, soweit verfügbar; Standortverfolgung und Fernlöschung sind nicht generell vorgeschrieben.','R1: Verlust, Diebstahl oder Beobachtung eines außerhalb der Einrichtung genutzten Assets legt Informationen der Einrichtung offen. R2: Beschädigung oder Verlust eines außerhalb der Einrichtung genutzten Assets unterbricht die Arbeit oder macht lokal gespeicherte Daten unzugänglich.','I-INFO-SAFE · Schutz beim Umgang mit Informationen','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C42.7','Das Anschließen von Wechseldatenträgern wird blockiert, sofern es nicht aus organisatorischen Gründen genehmigt ist','Das Anschließen von Wechseldatenträgern ist technisch untersagt, sofern die Nutzung nicht aus organisatorischen Gründen genehmigt ist.','Beispiele: durchgesetzte Anschlussbeschränkungen für Wechseldatenträger, organisatorische Gründe und Genehmigungen für Ausnahmen sowie sicher durchgeführte Prüfungen zugelassener und blockierter Anschlüsse an repräsentativen Systemen.','R1: Nicht genehmigte Wechseldatenträger bringen Schadcode in angeschlossene Systeme ein. R2: Nutzende kopieren sensible Informationen auf nicht genehmigte Datenträger und entziehen sie der Kontrolle der Einrichtung.','I-INFO-SAFE · Schutz beim Umgang mit Informationen','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C42.8','Wechseldatenträger werden vor der Nutzung geprüft und führen Inhalte nicht automatisch aus','Wechseldatenträger führen Inhalte nicht automatisch aus und werden vor der Nutzung auf Schadcode geprüft.','Beispiele: repräsentative Konfigurationsprüfungen und sicher durchgeführte Demonstrationen, die zeigen, dass Inhalte von Wechseldatenträgern nicht automatisch ausgeführt werden können und dass die Datenträger vor der Nutzung auf Schadcode geprüft werden. Vorhandene Prüfprotokolle können die tatsächliche Anwendung zusätzlich belegen.','R1: Schadcode wird von Wechseldatenträgern ausgeführt und stiehlt Informationen oder Zugangsdaten. R2: Über Datenträger eingebrachte Schadsoftware beschädigt Daten, stört Systeme oder breitet sich auf verbundene Dienste aus.','I-INFO-SAFE · Schutz beim Umgang mit Informationen','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C42.9','Tragbare Speichermedien sind bei Transport und Aufbewahrung geschützt','Wenden Sie bei der Aufbewahrung und beim Transport tragbarer Datenträger mit Daten der Einrichtung geeignete Handhabungs- und Aufbewahrungsschutzmaßnahmen an und setzen Sie Kryptografie ein, soweit angemessen. Prüfen Sie die tatsächlichen Schutzmaßnahmen, nicht nur Ausgabe- oder Verwahrungsaufzeichnungen; die Erfassung der Person, die ein Gerät verwahrt, belegt nicht, dass dessen Daten oder der Datenträger geschützt sind.','Beispiele: beobachtete Handhabung tragbarer Speichermedien sowie Schutzmaßnahmen bei Aufbewahrung und Transport, ergänzt durch kryptografische Einstellungen und sicher durchgeführte Prüfungen, soweit Verschlüsselung angemessen ist. Verwahrungsinformationen oder Übergabeaufzeichnungen können die Bewertung unterstützen, soweit relevant.','R1: Verlorene oder gestohlene tragbare Datenträger legen lesbare sensible Informationen offen. R2: Verlust oder Beschädigung tragbarer Datenträger macht benötigte Informationen unzugänglich, wenn keine nutzbare Kopie vorhanden ist.','I-INFO-SAFE · Schutz beim Umgang mit Informationen','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('TRN-DATA','Mitarbeitende werden im sicheren Umgang mit Daten und Wechseldatenträgern geschult','Mitarbeitende, die Daten oder Wechseldatenträger handhaben, erhalten praktische Unterweisung in die geltenden Regeln für Klassifizierung, Übertragung, Aufbewahrung und Entsorgung, damit sie diese Aufgaben sicher ausführen können; bestehende Schulungen können dies ohne gesonderten Kurs abdecken.','Beispiele: relevante Unterweisungen zur Handhabung von Daten und Wechseldatenträgern sowie Teilnahmeaufzeichnungen, ergänzt durch Erläuterungen der Mitarbeitenden oder praktische Prüfungen der geltenden Handhabungsregeln. Bestehende Einarbeitungsmaßnahmen oder andere Schulungen können diese Nachweise ohne gesonderten Kurs oder Zertifikat liefern.','R1: Mitarbeitende handhaben sensible dienstliche Informationen unsachgemäß, legen sie offen oder eskalieren deren Verlust nicht rechtzeitig. R2: Mitarbeitende bringen durch unsichere Nutzung von Wechseldatenträgern Schadcode ein.','I-DATA-TRN · Schulung zu Daten und Wechselmedien','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('DATA-DELETE','Nicht mehr benötigte Daten werden sicher gelöscht','Wenden Sie die relevanten Aufbewahrungs- und Löschkriterien an, um nicht mehr benötigte Informationen sicher zu entfernen, und berücksichtigen Sie dabei gültige Aufbewahrungspflichten sowie relevante Kopien; dies betrifft den Datenlebenszyklus, nicht nur die Entsorgung von Geräten.','Beispiele: geltende Aufbewahrungs- und Löschkriterien sowie repräsentative Löschergebnisse, die zeigen, dass nicht mehr benötigte Daten sicher entfernt werden, einschließlich Prüfungen relevanter Kopien nach den geltenden Entsorgungsregelungen. Verwenden Sie Metadaten oder kontrollierte Demonstrationen, statt die gelöschten sensiblen Inhalte zu kopieren.','R1: Veraltete sensible Daten werden bei späterem Zugriff, Offenlegung oder Wiederherstellung exponiert, wodurch sich der betroffene Datenbestand und Zeitraum eines Datenlecks vergrößern. R2: Daten werden gelöscht, bevor erforderliche Aufbewahrungs- oder Sicherungsbedarfe enden; dadurch werden Unterlagen vernichtet, die für den Betrieb, Untersuchungen oder die Begründung von Entscheidungen benötigt werden.','I-AST-EXIT · Rückgabe von Werten, Datenlöschung und Geräteentsorgung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C40.12','Anvertraute Assets werden bei Beendigung des Beschäftigungsverhältnisses zurückgegeben, hinterlegt oder gelöscht und verbleibende Zugriffe entzogen','Gleichen Sie die Maßnahmen bei Beendigung des Beschäftigungsverhältnisses mit den von der Person verwahrten Assets ab und überprüfen Sie deren Rückgabe, Hinterlegung oder angemessene Löschung sowie den Entzug verbleibender Zugriffe. Die Rücknahme eines Laptops allein reicht nicht aus, wenn Informationen der Einrichtung oder nutzbare Konten, Token oder Fernzugriffswege außerhalb der autorisierten Kontrolle verbleiben; Fernlöschung ist nicht in jedem Fall erforderlich.','Beispiele: mit den von der Person verwahrten Assets abgeglichene Austrittsaufzeichnungen, die Rückgabe, Hinterlegung oder angemessene Löschung und den Entzug verbleibender Zugriffe zeigen. Empfangsbestätigungen, Systemaufzeichnungen oder beaufsichtigte Prüfungen können das Ergebnis belegen, ohne in jedem Fall eine Fernlöschung zu verlangen.','R1: Ehemalige Mitarbeitende behalten Informationen der Einrichtung und legen sie nach dem Ende ihrer Berechtigung offen. R2: Nicht zurückgegebene Geräte oder fortbestehende Zugriffe ermöglichen die unbefugte Nutzung von Ressourcen der Einrichtung.','I-AST-EXIT · Rückgabe von Werten, Datenlöschung und Geräteentsorgung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C40.4','Informationen werden bei Wiederverwendung und Entsorgung sicher gelöscht','Entfernen Sie vor der Wiederverwendung oder Entsorgung von Geräten oder Datenträgern die darauf enthaltenen Informationen durch ein dem Medium und der Sensibilität angemessenes Lösch- oder Vernichtungsverfahren und überprüfen Sie das Ergebnis; das bloße Löschen eines Dateiverweises ist kein Nachweis einer sicheren Entfernung.','Beispiele: den betreffenden Geräten oder Datenträgern zugeordnete Wiederverwendungs- oder Entsorgungsaufzeichnungen, die das Lösch- oder Vernichtungsverfahren benennen, sowie Prüfungen, die zeigen, dass Informationen vor der Wiederverwendung oder Weitergabe sicher entfernt wurden.','Empfangende wiederverwendeter, verkaufter oder entsorgter Geräte stellen verbliebene sensible Informationen wieder her.','I-AST-EXIT · Rückgabe von Werten, Datenlöschung und Geräteentsorgung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('C40.7','Erforderliche Hintergrundüberprüfungen erfolgen vor der Zuweisung sensibler Rollen','Führen Sie vor der Zuweisung sensibler Aufgaben die durch die Rolle gerechtfertigten und nach geltendem Recht zulässigen Hintergrundüberprüfungen durch; verwenden Sie dabei nur die personenbezogenen Informationen, die zur Feststellung des Ergebnisses erforderlich sind.','Beispiele: erforderliche, rechtmäßige Überprüfungskriterien für sensible Rollen sowie geschützte Ergebnis- und Datumsaufzeichnungen, die den Abschluss vor der Zuweisung zeigen. Prüfen Sie nur die Informationen, die zum Nachweis der Überprüfung erforderlich sind, nicht uneingeschränkt zugängliche Hintergrundberichte.','Eine Person, bei der relevante und rechtmäßig feststellbare Zweifel an der Vertrauenswürdigkeit bestehen, erhält sensiblen Zugriff und missbraucht ihn, um Informationen zu erlangen oder Systeme zu manipulieren.','I-HR · Personalsicherheit','Personalsicherheit','Personnel security'),
  ('C40.6','Mitarbeitende mit sicherheitsrelevanten Aufgaben sind für ihre Rollen qualifiziert','Gleichen Sie die für die zugewiesenen Aufgaben benötigten Sicherheitskenntnisse und Fachkompetenzen mit den Qualifikationen, Erfahrungen oder nachgewiesenen Fähigkeiten der Person ab und beheben Sie relevante Lücken; ein bestimmtes Zertifikat ist nicht automatisch erforderlich.','Beispiele: rollenspezifische Kompetenzbedarfe im Abgleich mit relevanten Qualifikationen, Erfahrungen oder nachgewiesenen Fähigkeiten der eingesetzten Mitarbeitenden, einschließlich des Umgangs mit festgestellten Kompetenzlücken.','Mitarbeitende machen sicherheitsrelevante Konfigurationsfehler oder Fehler bei der Reaktion, weil die zugewiesenen Aufgaben ihre Fähigkeiten übersteigen; dadurch werden Informationen offengelegt oder Dienststörungen verlängert.','I-HR · Personalsicherheit','Personalsicherheit','Personnel security'),
  ('C40.1','Mitarbeitende akzeptieren Sicherheits- und Vertraulichkeitspflichten vor der Zugriffsgewährung','Bevor relevante Zugriffe gewährt werden, verstehen und akzeptieren Mitarbeitende die mit ihrer Arbeit verbundenen Sicherheits- und Vertraulichkeitspflichten; akzeptierte Vertragsbedingungen oder eine gleichwertige dokumentierte Verpflichtung können ohne zusätzliche Vereinbarung ausreichen.','Beispiele: akzeptierte Beschäftigungsbedingungen oder gleichwertige dokumentierte Verpflichtungen zu Sicherheits- und Vertraulichkeitspflichten, mit einem Abgleich der Annahmedaten mit der Gewährung relevanter Zugriffe.','Mitarbeitende legen Informationen offen oder missbrauchen sie, nachdem sie Zugriff erhalten haben, ohne ihre Sicherheits- und Vertraulichkeitspflichten zu verstehen und zu akzeptieren.','I-HR · Personalsicherheit','Personalsicherheit','Personnel security'),
  ('C40.9','Ein rechtmäßiges, kommuniziertes Disziplinarverfahren behandelt Verstöße gegen Sicherheitsrichtlinien','Mitarbeitende werden darüber informiert, wie Verstöße gegen Sicherheitsrichtlinien in einem rechtmäßigen Disziplinarverfahren behandelt werden, und tatsächliche Fälle folgen diesem Verfahren; eine Einrichtung muss keinen Disziplinarfall erfinden, um ihre Handlungsbereitschaft nachzuweisen.','Beispiele: das rechtmäßige Disziplinarverfahren und Nachweise seiner Kommunikation an relevante Mitarbeitende, ergänzt durch anonymisierte Bearbeitungsaufzeichnungen, sofern Verstöße gegen Sicherheitsrichtlinien aufgetreten sind. Das Fehlen eines Disziplinarfalls ist für sich genommen kein Hinweis auf ein Versagen.','Verstöße werden ignoriert oder uneinheitlich behandelt, wodurch wiederholtes unsicheres Verhalten oder ungerechte Behandlung ermöglicht wird.','I-HR · Personalsicherheit','Personalsicherheit','Personnel security'),
  ('C40.8','Fortbestehende Sicherheitspflichten werden nach Beschäftigungsänderungen oder Beendigung festgelegt und durchgesetzt','Legen Sie die nach einem Rollenwechsel oder der Beendigung des Beschäftigungsverhältnisses fortbestehenden Sicherheitspflichten in den geltenden Beschäftigungsbedingungen oder Vereinbarungen fest, teilen Sie sie der betroffenen Person mit und setzen Sie sie durch, soweit anwendbar. Eine allgemeine Vertragsvorlage allein belegt nicht, dass die relevanten fortbestehenden Pflichten vereinbart, kommuniziert und durchgesetzt wurden.','Beispiele: in Beschäftigungsbedingungen oder gleichwertigen Regelungen festgelegte fortbestehende Sicherheitspflichten, deren Kommunikation beim Rollenwechsel oder bei Beendigung des Beschäftigungsverhältnisses sowie relevante Aufzeichnungen zur Durchsetzung, soweit diese Pflichten gelten.','Ehemalige oder in andere Rollen versetzte Mitarbeitende legen Informationen offen oder missbrauchen sie, weil fortbestehende Pflichten unklar sind.','I-HR · Personalsicherheit','Personalsicherheit','Personnel security'),
  ('TRN-07','Der Bedarf an Sicherheitsschulungen wird rollenbezogen festgelegt','Der Bedarf an Sicherheitsschulungen wird rollenbezogen anhand der Sicherheitsverantwortlichkeiten, der genutzten Systeme und der Gefährdung festgelegt. Rollen mit gleichem Schulungsbedarf können zusammengefasst werden; ein gesonderter Schulungsplan für jede Stellenbezeichnung ist nicht erforderlich.','Beispiele: Aufzeichnungen zum Schulungsbedarf, die Rollen oder begründet gebildete Rollengruppen mit Sicherheitsverantwortlichkeiten, genutzten Systemen, Gefährdungen und erforderlichen Lerninhalten verknüpfen.','Rollenspezifische Sicherheitsaufgaben werden fehlerhaft ausgeführt, weil allgemeine Schulungen die tatsächlich verwendeten Werkzeuge, Berechtigungen oder Gefährdungen der Rolle nicht behandeln.','G-AWR · Sensibilisierung und Schulung der Mitarbeitenden','Awareness & Schulung','Awareness & training'),
  ('TRN-04','Hinweise zur Cybersicherheitssensibilisierung sind klar und für Mitarbeitende zugänglich','Klare Hinweise zur Cybersicherheitssensibilisierung werden erstellt und Mitarbeitenden zugänglich gemacht. Sie behandeln die Sicherheitsrichtlinien und Verfahren der Einrichtung, relevante Bedrohungen, eingesetzte Schutzmaßnahmen, sichere Arbeitsweisen sowie Anlaufstellen für Beratung und die Meldung von Bedenken. Jedes zugängliche Format kann verwendet werden, etwa Intranet-Inhalte, Schulungsunterlagen, Videos oder Kurzanleitungen; eine gesonderte Broschüre ist nicht erforderlich.','Beispiele: zugängliche Sensibilisierungshinweise zu aktuellen Richtlinien, Verfahren, relevanten Bedrohungen, Schutzmaßnahmen, sicheren Arbeitsweisen sowie Beratungs- und Meldekontakten, ergänzt durch Prüfungen, dass Mitarbeitende darauf zugreifen können.','Mitarbeitende improvisieren unsichere Vorgehensweisen beim Umgang mit Informationen oder melden Bedenken verspätet, weil nutzbare Hinweise und Kontaktinformationen nicht auffindbar sind.','G-AWR · Sensibilisierung und Schulung der Mitarbeitenden','Awareness & Schulung','Awareness & training'),
  ('TRN-02','Neue Mitarbeitende erhalten Cybersicherheitssensibilisierung innerhalb eines risikogerechten Einarbeitungszeitraums','Führen Sie die Cybersicherheitssensibilisierung im Rahmen der Einarbeitung innerhalb des von der Einrichtung festgelegten, risikogerechten Zeitraums durch. Vergleichen Sie Eintrittsdaten mit Abschlussaufzeichnungen und verfolgen Sie verspätete oder ausgebliebene Teilnahmen nach; die bloße Zuweisung eines Kurses ohne dessen Abschluss belegt nicht, dass neue Mitarbeitende die erforderliche Sensibilisierung rechtzeitig erhalten haben.','Beispiele: der risikogerechte Einarbeitungszeitraum der Einrichtung, Eintrittsdaten und Aufzeichnungen über abgeschlossene Sensibilisierungsmaßnahmen sowie der Umgang mit ausgebliebenen oder verspäteten Abschlüssen.','Neue Mitarbeitende legen Informationen offen oder befolgen betrügerische Anweisungen, bevor sie die wesentlichen Sicherheitspraktiken für ihre Arbeit erlernt haben.','G-AWR · Sensibilisierung und Schulung der Mitarbeitenden','Awareness & Schulung','Awareness & training'),
  ('TRN-03','Geplante Sensibilisierung und rollenbezogene Sicherheitsschulungen werden regelmäßig durchgeführt','Geplante Sensibilisierung und rollenbezogene Sicherheitsschulungen werden regelmäßig durchgeführt. Wiederholen Sie Sensibilisierungsmaßnahmen und führen Sie die unter TRN-07 ermittelten Sicherheitsschulungen in geplanten Abständen durch. Prüfen Sie Durchführungs- und Teilnahmeaufzeichnungen, kümmern Sie sich um versäumte Schulungen und verwenden Sie Nachweise aus den relevanten operativen Themenbereichen wieder, statt doppelte Kurse zu verlangen.','Beispiele: geplante Abstände für Sensibilisierung und rollenbezogene Schulungen im Abgleich mit tatsächlicher Durchführung, Teilnahme und Nachverfolgung versäumter Schulungen, verknüpft mit dem unter TRN-07 ermittelten Bedarf. Verwenden Sie relevante Schulungsaufzeichnungen aus operativen Themenbereichen wieder, ohne doppelte Kurse zu verlangen.','Mitarbeitende wiederholen unsichere Praktiken oder können zugewiesene Sicherheitsaufgaben nicht ausführen, weil geplante Sensibilisierung und rollenbezogene Schulungen nicht durchgeführt oder aufgefrischt werden.','G-AWR · Sensibilisierung und Schulung der Mitarbeitenden','Awareness & Schulung','Awareness & training'),
  ('TRN-09','Versetzte Mitarbeitende werden für neue sicherheitsrelevante Kompetenzanforderungen geschult (Gilt bei einem Wechsel in Rollen, die sicherheitsrelevante Fähigkeiten und Fachkenntnisse erfordern.)','Ermitteln Sie die durch einen Rollenwechsel entstehenden neuen sicherheitsrelevanten Kompetenzanforderungen und führen Sie darauf ausgerichtete Schulungen durch. Vergleichen Sie die veränderten Aufgaben mit Schulungsinhalten und Abschlüssen; frühere allgemeine Sensibilisierung oder Schulungen für die vorherige Rolle sind kein ausreichender Nachweis dafür, dass der neue Bedarf abgedeckt ist. (Gilt bei einem Wechsel in Rollen, die sicherheitsrelevante Fähigkeiten und Fachkenntnisse erfordern.)','Wenn durch eine Versetzung neue sicherheitsrelevante Kompetenzbedarfe entstehen, umfassen Beispiele Informationen zur Versetzung oder Rolle, den geänderten Bedarf und den Abschluss darauf ausgerichteter Schulungen.','Versetzte Mitarbeitende machen bei der Ausführung ungewohnter Aufgaben sicherheitsrelevante Fehler und legen dadurch Informationen offen oder unterbrechen den betroffenen Betrieb.','G-AWR · Sensibilisierung und Schulung der Mitarbeitenden','Awareness & Schulung','Awareness & training'),
  ('TRN-05','Die Wirksamkeit von Schulungen wird über die bloße Teilnahme hinaus beurteilt','Die Wirksamkeit von Schulungen wird beurteilt und nicht aus der Teilnahme abgeleitet. Prüfen Sie, ob Teilnehmende die für ihre Arbeit erforderlichen Sicherheitskenntnisse und Fähigkeiten anwenden können. Beurteilen Sie bei Einrichtungen im CIR-Anwendungsbereich die Wirksamkeit von Schulungen für Rollen, die Sicherheitsfachkenntnisse erfordern; die Prüfung des allgemeinen Sensibilisierungsprogramms ist erforderlich, soweit angemessen. Nutzen Sie verhältnismäßige praktische Prüfungen, Übungen oder andere geeignete Bewertungen und beheben Sie unzureichende Lernergebnisse.','Beispiele: verhältnismäßige praktische Prüfungen, Übungen oder andere Bewertungen, die zeigen, ob Teilnehmende die erforderlichen Sicherheitskompetenzen anwenden können, ausgewertete Ergebnisse und Maßnahmen bei unzureichenden Lernergebnissen. Beziehen Sie bei Einrichtungen im CIR-Anwendungsbereich die Wirksamkeitsbewertung für Rollen mit erforderlichen Sicherheitsfachkenntnissen ein; bewerten Sie die allgemeine Sensibilisierung, soweit angemessen.','Mitarbeitende bleiben außerstande, Bedrohungen zu erkennen oder zugewiesene Sicherheitsaufgaben auszuführen, weil Teilnahme mit wirksamem Lernen verwechselt wird und Defizite nicht behoben werden.','G-AWR · Sensibilisierung und Schulung der Mitarbeitenden','Awareness & Schulung','Awareness & training'),
  ('TRN-06','Sensibilisierungs- und Sicherheitsschulungsprogramme werden aktuell gehalten','Sensibilisierungs- und Sicherheitsschulungsprogramme werden aktuell gehalten. Überprüfen Sie deren Inhalte und Durchführungsregelungen in geplanten Abständen anhand aktueller Richtlinien, Verantwortlichkeiten, Technologien und relevanter Bedrohungen. Aktualisieren Sie bei Änderungen das Programm und den damit verbundenen rollenbezogenen Bedarf. Themenspezifische Kurse verbleiben in ihren operativen Themenbereichen; diese Kontrolle beurteilt die Pflege des Programms.','Beispiele: datierte Überprüfungen von Programminhalten und Durchführung in geplanten Abständen anhand aktueller Richtlinien, Verantwortlichkeiten, Technologien und Bedrohungen sowie daraus resultierende Aktualisierungen der Unterlagen und rollenbezogenen Bedarfe, soweit erforderlich.','Mitarbeitende befolgen veraltete Hinweise zur Cyberhygiene und gehen mit aktuellen Bedrohungen oder veränderten Arbeitsweisen unsachgemäß um.','G-AWR · Sensibilisierung und Schulung der Mitarbeitenden','Awareness & Schulung','Awareness & training'),
  ('C40.2','Zugriffsregeln legen fest, wer welche Ressourcen nutzen darf','Legen Sie Zugriffsregeln fest, die Nutzende oder Rollen den benötigten Ressourcen und zulässigen Aktionen zuordnen und dabei betriebliche Erfordernisse und Schutzbedarfe berücksichtigen; diese Regeln bilden die Grundlage für individuelle Zugriffsentscheidungen.','Beispiele: Zugriffskontrollregeln, die festlegen, welche Nutzenden oder Rollen welche Ressourcen nutzen dürfen, im Abgleich mit repräsentativen Berechtigungen und den zugrunde liegenden betrieblichen Erfordernissen und Schutzbedarfen.','Nutzende erhalten Zugriff über den berechtigten betrieblichen Bedarf hinaus; dadurch werden unbefugte Offenlegung, Änderung oder Löschung von Informationen sowie Störungen des betroffenen Dienstes ermöglicht.','I-ACC · Identitäts- und Zugriffsverwaltung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C40.10','Benutzer- und Systemidentitäten werden über ihren gesamten Lebenszyklus verwaltet','Erstellen, pflegen und legen Sie Identitäten für Personen und Systeme still, sodass ihre Zuordnung und Verantwortlichkeit klar bleiben und nicht mehr benötigte Identitäten deaktiviert werden; der Identitätsdatensatz ist von den zugehörigen Berechtigungen zu unterscheiden.','Beispiele: Benutzer- und Systemidentitätsdatensätze, die von der Erstellung über Änderungen bis zur Stilllegung eine erkennbare Verantwortlichkeit und korrekte Zuordnung zeigen, im Abgleich mit repräsentativen aktiven und stillgelegten Konten.','R1: Verwaiste Benutzer- oder Systemkonten werden für unbefugten Zugriff genutzt, und unklare Verantwortlichkeit verzögert die Eindämmung. R2: Ein Konto wird der falschen Person oder technischen Identität zugeordnet, wodurch die falsche Stelle Zugriff erhält und nachfolgende Aktionen falsch zugerechnet werden.','I-ACC · Identitäts- und Zugriffsverwaltung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C40.3','Zugriffsrechte werden genehmigt, aktualisiert und entzogen','Setzen Sie autorisierte Gewährungen, Änderungen und Entzüge von Zugriffen um, wenn sich Verantwortlichkeiten oder Zugriffsbedarfe ändern, und überprüfen Sie die daraus resultierenden Berechtigungen; geplante Überprüfungen bestehender Rechte werden gesondert unter ACCESS-RECERT beurteilt.','Beispiele: Zugriffsentscheidungen und ihre Genehmigung, verknüpft mit umgesetzten Gewährungen, Aktualisierungen und Entzügen, im Abgleich mit tatsächlichen Rechten und dem aktuellen Bedarf an repräsentativen Ressourcen.','R1: Nicht genehmigte oder veraltete Berechtigungen werden verwendet, um Informationen einzusehen oder zu verändern, nachdem der betriebliche Bedarf entfallen ist. R2: Fehlerhafte Zugriffsänderungen oder ein verfrühter Entzug verhindern, dass berechtigte Mitarbeitende oder Dienstkonten notwendige Aufgaben ausführen, und unterbrechen dadurch den legitimen Betrieb.','I-ACC · Identitäts- und Zugriffsverwaltung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('ACCESS-RECERT','Bestehende Zugriffsrechte werden anhand des aktuellen Bedarfs überprüft','Überprüfen Sie die Zugriffsrechte von Nutzenden und Dienstkonten in geplanten Abständen anhand ihres aktuellen betrieblichen Bedarfs. Passen Sie Rechte nach relevanten organisatorischen Änderungen an. Dokumentieren Sie die Überprüfungsergebnisse und erforderlichen Korrekturen und verifizieren Sie anschließend, dass abgelehnte oder übermäßige Rechte entzogen oder geändert wurden. Die Existenz eines Kontos allein rechtfertigt nicht jede zugewiesene Berechtigung. Verwenden Sie die Überprüfung privilegierter Konten unter C43.1 wieder, soweit sie dieselben Rechte abdeckt; erfassen Sie denselben Mangel nicht doppelt.','Datierte Berechtigungslisten der überprüften Nutzenden und Dienstkonten; geplante Überprüfungsintervalle und zuständige Prüfpersonen; dokumentierte Entscheidungen zum fortbestehenden Bedarf; daraus resultierende Änderungen oder Entzüge sowie die Verifizierung ihrer Wirksamkeit.','R1: Durch frühere Rollen oder Projekte angesammelte Berechtigungen bleiben aktiv und ermöglichen unbefugten Zugriff auf Informationen oder deren Änderung. R2: Eine Überprüfung wird als abgeschlossen gekennzeichnet, obwohl die darin abgelehnten Berechtigungen weiterhin nutzbar sind.','I-ACC · Identitäts- und Zugriffsverwaltung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C40.11','Gemeinsam genutzte Konten sind begründete und genehmigte Ausnahmen','Wenn ein Konto gemeinsam genutzt werden muss, bewahren Sie die konkrete Begründung und Genehmigung auf und wenden Sie Schutzmaßnahmen für eine zurechenbare Nutzung an; Bequemlichkeit allein belegt nicht, dass gemeinsamer Zugriff eine gerechtfertigte Ausnahme ist.','Beispiele: identifizierte gemeinsam genutzte Konten mit konkreten Begründungen und Genehmigungen, im Abgleich mit der tatsächlichen Nutzung und geltenden Maßnahmen zur Sicherstellung der Zurechenbarkeit. Bestehende Kontometadaten oder Entscheidungen können ohne gesondertes Ausnahmenregister ausreichen.','R1: Gemeinsam genutzte Zugänge verschleiern, wer eine Aktion ausgeführt hat, und erschweren die Untersuchung von Missbrauch. R2: Ehemalige oder in andere Rollen versetzte Nutzende behalten gemeinsam genutzte Zugangsdaten und greifen weiterhin auf Ressourcen zu, nachdem ihre individuelle Berechtigung erloschen ist.','I-ACC · Identitäts- und Zugriffsverwaltung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C43.2','Für die Administration werden getrennte, individuell zugewiesene Konten verwendet','Stellen Sie administrierenden Personen individuell zugewiesene Administrationskonten bereit, die von ihren Konten für die gewöhnliche Nutzung getrennt sind, und verwenden Sie diese Identitäten für Administrationsarbeiten, damit Aktionen mit erhöhten Rechten der verantwortlichen Person zugerechnet werden können.','Beispiele: individuell zugewiesene Administrationskonten mit Zuordnung zu ihren Nutzenden und getrennte Konten für die gewöhnliche Nutzung, ergänzt durch sicher durchgeführte Konto- und Nutzungsprüfungen, die zeigen, dass die Administration mit den getrennten Identitäten erfolgt.','R1: Die Kompromittierung eines Kontos für die gewöhnliche Nutzung ermöglicht privilegierte Änderungen oder Zugriff auf geschützte Daten. R2: Administrative Aktionen können keiner Person zuverlässig zugerechnet werden, wodurch Untersuchung und Verantwortungszuordnung beeinträchtigt werden.','I-ACC · Identitäts- und Zugriffsverwaltung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C43.3','Administrationssysteme sind getrennt und geschützt','Trennen und schützen Sie die zur Administration genutzten Systeme so, dass gewöhnliche Benutzeraktivitäten oder unbefugte Verbindungen keinen Zugang zur Verwaltungsumgebung eröffnen; getrennte Kontonamen allein belegen keine Systemtrennung.','Beispiele: Gestaltung und Betriebskonfigurationen der Administrationssysteme, die Trennung und Schutz zeigen, bestätigt durch repräsentative Prüfungen von Zugriff, Isolation und Härtung.','Schadsoftware auf einem Administrationsarbeitsplatz fängt privilegierte Sitzungen oder Zugangsdaten ab und nutzt sie, um verwaltete Systeme zu kompromittieren.','I-ACC · Identitäts- und Zugriffsverwaltung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C43.1','Privilegierte Zugriffe werden regelmäßig anhand des aktuellen Bedarfs überprüft','Prüfen Sie in geplanten Abständen und nach organisatorischen Änderungen, ob administrierende Personen ihre privilegierten Berechtigungen weiterhin benötigen, und setzen Sie die daraus resultierenden Änderungen um; verwenden Sie diese Nachweise in ACCESS-RECERT wieder, statt dieselbe Feststellung doppelt zu erfassen.','Beispiele: datierte Überprüfungen des Bestands privilegierter Konten und Berechtigungen anhand aktueller Verantwortlichkeiten, mit aufbewahrten Entscheidungen und umgesetztem Entzug oder Anpassung unnötiger Rechte.','Veraltete oder übermäßige Administrationsrechte werden missbraucht, um auf sensible Informationen zuzugreifen oder Systeme über die aktuellen Zuständigkeiten der berechtigten Person hinaus zu verändern.','I-ACC · Identitäts- und Zugriffsverwaltung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C40.5','Fernzugriffe verwenden genehmigte, verschlüsselte Verbindungen','Verwenden Sie von der Einrichtung genehmigte Fernzugriffsverfahren, die Verbindungen durch Verschlüsselung schützen und auf autorisierte Zugriffe beschränken; beurteilen Sie die tatsächlichen Verbindungseinstellungen und nicht nur, ob ein Fernzugriffsprodukt installiert ist.','Beispiele: genehmigte Fernzugriffsverfahren im Abgleich mit eingesetzter Verschlüsselung, Zugriffsumfang und repräsentativen Verbindungsprüfungen, die zeigen, dass tatsächliche Fernzugriffe diesen Verfahren entsprechen.','R1: Fernzugriffsverkehr oder Zugangsdaten werden abgefangen, oder Befehle und Daten werden während der Übertragung verändert, wodurch die Vertraulichkeit oder Integrität der Fernzugriffsoperationen beeinträchtigt wird. R2: Nicht genehmigte oder zu weitreichende Fernverbindungen verschaffen Angreifenden Zugang zu internen Systemen.','I-ACC · Identitäts- und Zugriffsverwaltung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('SUP-ACCESS-WINDOW','Verbindungen von Dienstleistern werden genehmigt und zeitlich begrenzt (Gilt, wenn Dienstleister Verbindungen zu den Netz- und Informationssystemen der Einrichtung herstellen.)','Verlangen Sie vor der Freischaltung einer Dienstleisterverbindung einen Genehmigungsantrag. Dokumentieren Sie den genehmigten Zweck, die Systeme oder Ressourcen und den zulässigen Zeitraum. Schließen oder deaktivieren Sie die Verbindung nach Ablauf dieses Zeitraums und genehmigen Sie jede begründete Verlängerung. Verifizieren Sie, dass die Zugriffsdauer im Betrieb kontrolliert wird; eine verschlüsselte Übertragung allein belegt dies nicht. C40.5 beurteilt das sichere Fernzugriffsverfahren und C51.3 die Transparenz über Lieferantenzugriffe; verwenden Sie deren Aufzeichnungen wieder, ohne Feststellungen doppelt zu erfassen. Die ausdrückliche CIR-Anforderung gilt nur innerhalb des CIR-Anwendungsbereichs.','Verbindungsanträge und Genehmigungen für Dienstleister mit Angabe der Ressourcen und zulässigen Dauer; Verbindungseinstellungen und Sitzungsaufzeichnungen mit unkenntlich gemachten sensiblen Angaben; Ablauf- oder Schließungsaufzeichnungen oder sicher durchgeführte Tests; begründete Verlängerungsgenehmigungen. Ein bestimmtes Fernzugriffsprodukt ist nicht erforderlich.','R1: Eine Lieferantenverbindung bleibt nach dem genehmigten Unterstützungszeitraum nutzbar und eröffnet Angreifenden einen unnötigen Zugangsweg. R2: Dienstleisterzugriffe erstrecken sich auf Systeme oder Aktivitäten außerhalb des genehmigten Umfangs und ermöglichen unbefugte Offenlegung oder Änderungen.','I-SUP-ACCESS · Zeitlich begrenzte Verbindungen von Diensteanbietern','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C43.4','Privilegierte Hilfsprogramme werden eingeschränkt und überwacht','Beschränken Sie Werkzeuge, die normale Anwendungs- oder Systemkontrollen umgehen können, auf autorisierte Nutzungen und überwachen Sie ihre Ausführung, damit leistungsfähige Wartungs- oder Diagnoseprogramme keinen unkontrollierten Zugang zu Daten oder Einstellungen eröffnen.','Beispiele: identifizierte privilegierte Hilfsprogramme, deren Zugriffs- und Ausführungsbeschränkungen sowie repräsentative Nutzungs- oder Überwachungsaufzeichnungen, die zeigen, dass die Nutzung auf autorisierte Zwecke beschränkt und überwacht wird.','R1: Privilegierte Hilfsprogramme umgehen Anwendungsschutzmaßnahmen und legen geschützte Daten offen oder verändern sie. R2: Der Missbrauch privilegierter Hilfsprogramme lässt sich nicht rekonstruieren, wodurch Zuordnung und Eindämmung verzögert werden.','I-UTIL · Privilegierte Hilfsprogramme','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C41.1','Die Authentifizierung verwendet eine risikogerechte Stärke','Die Authentifizierung verwendet eine risikogerechte Stärke, einschließlich Multi-Faktor- oder kontinuierlicher Authentifizierung. Wählen und erzwingen Sie die Authentifizierung entsprechend der Klassifizierung der Ressource und dem Zugriffsrisiko. Verwenden Sie Multi-Faktor-Authentifizierung (MFA) oder kontinuierliche Authentifizierung, soweit angemessen, und beurteilen Sie dabei ausdrücklich privilegierte Zugriffe und Fernzugriffe. Erzwingen Sie bei der Verwendung von Passwörtern eine geeignete Stärke und weisen Sie häufig verwendete oder bekanntermaßen kompromittierte Passwörter zurück. Eine Richtlinienaussage allein belegt nicht, dass die Anmeldewege die gewählten Schutzmaßnahmen durchsetzen.','Beispiele: an Ressourcenklassifizierung und Zugriffsrisiko ausgerichtete Authentifizierungsentscheidungen, die privilegierte Zugriffe und Fernzugriffe ausdrücklich berücksichtigen, mit durchgesetzten Einstellungen und sicher durchgeführten Tests auf relevanten Anmeldewegen. Prüfen Sie, soweit anwendbar, MFA oder kontinuierliche Authentifizierung sowie die Zurückweisung schwacher, verbreiteter oder bekanntermaßen kompromittierter Passwörter anhand nicht produktiv genutzter Test-Zugangsdaten, nicht anhand aktiver geheimer Informationen.','Schwache Authentifizierung ermöglicht Angreifenden den Zugriff auf sensible Systeme mit gestohlenen Zugangsdaten.','J-AUTH · Authentisierung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C41.11','Kontoeinrichtung und Kontowiederherstellung umgehen die Sicherheit der Authentifizierung nicht','Bei der Kontoregistrierung, der erstmaligen Bereitstellung von Zugangsdaten und der Wiederherstellung wird die Berechtigung der nutzenden Person geprüft und der erforderliche Authentifizierungsschutz aufrechterhalten, damit Angreifende nicht über einen schwächeren Einrichtungs- oder Zurücksetzungsweg Zugriff erlangen können.','Beispiele: Regelungen für Kontoregistrierung, erstmalige Bereitstellung und Wiederherstellung, ergänzt durch Fallaufzeichnungen mit unkenntlich gemachten sensiblen Angaben oder kontrollierte Demonstrationen mit Testkonten, die zeigen, dass Identitätsprüfungen und Wiederherstellungswege den erforderlichen Authentifizierungsschutz nicht umgehen.','Angreifende erlangen Kontozugriff über schwache Registrierungs-, Erstausgabe- oder Wiederherstellungsprüfungen und umgehen damit einen ansonsten starken Anmeldeschutz.','J-AUTH · Authentisierung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C41.6','Passwörter und andere geheime Authentisierungsinformationen sind geschützt','Schützen Sie geheime Authentisierungsinformationen bei Zuweisung, Speicherung und Übertragung und verbergen Sie Passworteingaben standardmäßig; jede Anzeige im Klartext erfordert eine bewusste Benutzeraktion. Eine reine Anzeigemaskierung schützt keine gespeicherten oder übertragenen geheimen Informationen.','Beispiele: Speicher-, Übertragungs- und Zugriffseinstellungen mit unkenntlich gemachten sensiblen Angaben, die den Schutz geheimer Authentisierungsinformationen belegen, sowie Prüfungen mit synthetischen Eingaben, die zeigen, dass Passworteingaben standardmäßig verborgen bleiben und nur durch eine bewusste Benutzeraktion sichtbar werden. Erheben Sie keine aktiven Passwörter, Token oder anderen geheimen Authentisierungsinformationen.','Offengelegte geheime Authentisierungsinformationen, einschließlich bei der Eingabe beobachteter Passwörter, ermöglichen unbefugten Zugriff.','J-AUTH · Authentisierung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C41.8','Wiederholte fehlgeschlagene Anmeldungen lösen eine Sperrung und das Zurücksetzen der Zugangsdaten aus','Legen Sie den Schwellenwert für fehlgeschlagene Anmeldungen fest und stellen Sie sicher, dass sein Erreichen die Sperrung der nutzenden Person und das Zurücksetzen der Authentisierungsinformationen auslöst; beurteilt wird die konfigurierte Reaktion, ohne eine allgemeingültige Anzahl von Versuchen vorzugeben.','Beispiele: konfigurierte Schwellenwerte für fehlgeschlagene Anmeldungen und Regelungen zur Sperrung und zum Zurücksetzen, ergänzt durch sicher ermittelte Testkontoergebnisse oder Ereignisaufzeichnungen mit unkenntlich gemachten sensiblen Angaben, die zeigen, dass wiederholte Fehlschläge Sperrung und Zurücksetzen der Zugangsdaten auslösen. Verwenden Sie den jeweils gewählten Schwellenwert, ohne eine allgemeingültige Versuchszahl zu erfinden oder aktive Zugangsdaten offenzulegen.','R1: Wiederholtes Raten oder automatisierte Anmeldeversuche ermitteln nutzbare Zugangsdaten und führen zur Kontoübernahme. R2: Angreifende lösen absichtlich kontoweite Sperrungen oder wiederholtes Zurücksetzen aus und verhindern dadurch den Zugriff berechtigter Nutzender auf Dienste oder überlasten den Wiederherstellungsprozess.','J-AUTH · Authentisierung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('DEVICE-LOCK','Unbeaufsichtigte Geräte werden gesperrt und erfordern eine erneute Authentifizierung','Ein unbeaufsichtigtes Gerät verhindert anhand der geltenden Sperrregelungen die weitere Nutzung, bis sich die nutzende Person erneut authentifiziert; eine Gerätesperre ist von der Beendigung der zugrunde liegenden Anwendungssitzung zu unterscheiden.','Beispiele: geltende Gerätesperreinstellungen und sicher durchgeführte Beobachtungen an repräsentativen Geräten, die eine Sperrung bei unbeaufsichtigtem Zustand und eine erneute Authentifizierung vor Wiederaufnahme des Zugriffs zeigen.','Eine unbefugte Person nutzt ein unbeaufsichtigtes, ungesperrtes Gerät, um Informationen einzusehen oder im Konto der berechtigten Person Aktionen auszuführen.','J-AUTH · Authentisierung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C41.9','Inaktive Sitzungen werden automatisch beendet','Konfigurieren Sie einen vorab festgelegten Inaktivitätszeitraum, nach dessen Ablauf die authentifizierte Sitzung beendet wird und keinen Zugriff mehr autorisiert; das Verbergen des Bildschirminhalts ohne Beendigung der Sitzung erfüllt diese Kontrolle nicht.','Beispiele: Einstellungen zur Sitzungsbeendigung bei Inaktivität und sicher durchgeführte Sitzungstests in relevanten Anwendungen, die zeigen, dass abgelaufene Sitzungen keinen authentifizierten Zugriff mehr gewähren.','Eine andere Person verwendet eine inaktive authentifizierte Sitzung weiter, um Informationen zu lesen oder als berechtigte nutzende Person Aktionen auszuführen.','J-AUTH · Authentisierung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C41.7','Zugangsdaten werden bei vermuteter oder bestätigter Kompromittierung ersetzt oder widerrufen','Kompromittierte Authentisierungsinformationen werden ersetzt oder widerrufen. Reagieren Sie auf eine vermutete oder bestätigte Kompromittierung, indem Sie betroffene Passwörter ändern und andere betroffene Zugangsdaten, etwa Token oder Authentifizierungszertifikate, ersetzen oder widerrufen. Stellen Sie sicher, dass die offengelegten Zugangsdaten keinen Zugriff mehr ermöglichen, und beurteilen Sie betroffene Sitzungen im Rahmen der Vorfallreaktion.','Beispiele: Fälle vermuteter oder bestätigter Kompromittierung mit unkenntlich gemachten sensiblen Angaben oder kontrollierte Übungen, die Ersatz oder Widerruf betroffener Zugangsdaten, die Aufhebung ihrer Zugriffswirkung und die Bewertung betroffener Sitzungen im Rahmen der Vorfallreaktion zeigen. Verwenden Sie Test-Zugangsdaten oder Metadaten und erheben Sie keine offengelegten aktiven geheimen Informationen.','Angreifende authentifizieren sich weiterhin mit einem offengelegten Passwort, Token oder anderen Zugangsdaten, nachdem die Einrichtung von der Kompromittierung erfahren hat.','J-AUTH · Authentisierung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C41.10','Authentifizierungsverfahren werden regelmäßig überprüft','Beurteilen Sie in geplanten Abständen, ob die Authentifizierungsverfahren und -technologien weiterhin den aktuellen Risiken und Zugriffsbedarfen angemessen sind, und aktualisieren Sie diese anschließend oder begründen Sie ihre weitere Nutzung; dies ist keine Prüfung periodischer Änderungen von Zugangsdaten.','Beispiele: datierte Überprüfungen der Authentifizierungsverfahren anhand aktueller Bedrohungen, Ressourcen- und Zugriffsbedarfe sowie relevanter Änderungen, mit Schlussfolgerungen und umgesetzten Aktualisierungen oder begründeter weiterer Nutzung. Zeitpunkt und Umfang der Überprüfungen sollten zeigen, dass die Verfahren regelmäßig überprüft werden.','Schwächen der Authentifizierung werden bei veränderten Bedrohungen oder Zugriffsbedarfen ausnutzbar, während die Einrichtung weiterhin auf veraltete Verfahren vertraut.','J-AUTH · Authentisierung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C41.12','Vertrauliche Informationen bleiben bis zur erfolgreichen Authentifizierung verborgen','Verhindern Sie nicht authentifizierten Zugriff auf vertrauliche Inhalte über die relevanten Zugriffswege der Anwendung, einschließlich direkter Anfragen, soweit anwendbar; die Anzeige einer Anmeldeseite reicht nicht aus, wenn geschützte Informationen dahinter weiterhin zugänglich sind.','Beispiele: nicht authentifizierte Tests mit synthetischen geschützten Inhalten über relevante Seiten, direkte URLs, APIs und andere Zugriffswege, die zeigen, dass vertrauliche Informationen bis zur erfolgreichen Authentifizierung nicht verfügbar sind. Bestätigen Sie dies anhand der Einstellungen zur Durchsetzung von Zugriffsbeschränkungen; ein Anmeldebildschirm allein reicht nicht aus.','Eine nicht authentifizierte Person liest geschützte Informationen, indem sie den normalen Anmeldebildschirm umgeht.','J-GUARD · Schutz von Anmeldeinformationen und Passwörtern','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C41.13','Initiale, voreingestellte und temporäre Zugangsdaten werden vor der regulären Nutzung geändert','Initiale, voreingestellte und temporäre Zugangsdaten werden vor der regulären Nutzung geändert. Ersetzen oder ändern Sie initiale und temporäre Passwörter sowie vom Lieferanten bereitgestellte voreingestellte geheime Authentisierungsinformationen durch einen kontrollierten Einrichtungsprozess. Verifizieren Sie, dass Voreinstellungen keinen Zugriff mehr ermöglichen. Dokumentieren Sie für Zugangsdatenarten, die individuell generiert werden und keine gemeinsam genutzten Voreinstellungen sind, das geltende sichere Bereitstellungsverfahren.','Beispiele: sichere Einrichtungs- und Bereitstellungsregelungen sowie Aktivierungsaufzeichnungen mit unkenntlich gemachten sensiblen Angaben oder Testkontoprüfungen, die zeigen, dass initiale, temporäre und vom Lieferanten voreingestellte geheime Informationen vor der regulären Nutzung geändert werden und Voreinstellungen keinen Zugriff mehr erlauben. Prüfen Sie bei individuell generierten Zugangsdatenarten das dokumentierte sichere Bereitstellungsverfahren; erheben Sie keine aktiven geheimen Informationen.','Eine Person, die initiale, temporäre oder vom Lieferanten voreingestellte geheime Informationen kennt, greift nach der Inbetriebnahme auf das Konto oder System zu.','J-GUARD · Schutz von Anmeldeinformationen und Passwörtern','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C41.14','Für dienstliche Passwörter wird ein genehmigter Passwortmanager verwendet','Verwenden Sie für dienstliche Passwörter einen von der Einrichtung genehmigten Passwortmanager und schützen Sie den Zugriff auf dessen Tresor und Wiederherstellungsprozess; die Kontrolle beurteilt die sichere tatsächliche Nutzung, ohne einen Anbieter vorzuschreiben oder die Offenlegung gespeicherter Passwörter zu verlangen.','Beispiele: die genehmigte Auswahl des Passwortmanagers, Nachweise seiner tatsächlichen Nutzung für dienstliche Passwörter und sicher durchgeführte Prüfungen des Tresorzugriffsschutzes und autorisierter Wiederherstellungsregelungen. Verwenden Sie nicht geheime Konfigurationsinformationen oder Demonstrationen, niemals Tresorexporte, geheime Wiederherstellungsinformationen oder dienstliche Passwörter.','R1: Offengelegte oder wiederverwendete dienstliche Passwörter ermöglichen die Kompromittierung von Konten. R2: Schwacher Schutz oder eine schwache Wiederherstellung eines Passworttresors legt Zugangsdaten für mehrere dienstliche Konten zugleich offen. R3: Der Verlust des Zugriffs auf den Passworttresor ohne nutzbaren autorisierten Wiederherstellungsweg verhindert, dass Mitarbeitende die für kritische Arbeiten oder die Wiederherstellung benötigten Zugangsdaten abrufen.','J-GUARD · Schutz von Anmeldeinformationen und Passwörtern','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('AUTH-INTERVAL','Authentisierungsinformationen werden in vorab festgelegten Intervallen geändert. (Gilt nur für Einrichtungen im Anwendungsbereich der Durchführungsverordnung (EU) 2024/2690 der Kommission.)','Legen Sie die Änderungsintervalle für die relevanten Authentisierungsinformationen fest und führen Sie fällige Änderungen durch. Bewahren Sie die Entscheidungen zu den Intervallen sowie Nachweise für deren tatsächliche Einhaltung auf. Die Verordnung legt keine allgemein geltende Anzahl von Tagen fest. Diese Kontrolle bewertet ausschließlich die Intervallanforderung; verwenden Sie C41.13 für Änderungen anfänglicher beziehungsweise voreingestellter Zugangsdaten und C41.7 für Änderungen bei Kompromittierungsverdacht, ohne deren Bewertung zu duplizieren. Wenden Sie diese CIR-spezifische Anforderung nicht automatisch auf Einrichtungen außerhalb des CIR-Anwendungsbereichs an.','Bestätigte CIR-Anwendbarkeit; dokumentierte Änderungsintervalle für Zugangsdaten und zuständige Verantwortliche; technisch durchgesetzte Einstellungen oder kontrollierte Änderungsverfahren; datierte, geschwärzte Aufzeichnungen über fristgerecht durchgeführte Änderungen und die Nachverfolgung versäumter Änderungen. Erheben Sie keine Passwörter oder sonstigen aktuell gültigen geheimen Authentisierungsinformationen als Nachweise.','Unbemerkt offengelegte Zugangsdaten bleiben über ihr festgelegtes Änderungsintervall hinaus nutzbar und ermöglichen dadurch fortgesetzten unbefugten Zugriff.','J-CIR-INTERVAL · Wechselintervalle für Zugangsdaten im CIR-Anwendungsbereich','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('TRN-AUTH','Mitarbeitende werden zur Sicherheit von Passwörtern und Anmeldungen geschult','Mitarbeitende erhalten praktische Unterweisungen zum Schutz geheimer Authentisierungsinformationen, zum Erkennen verdächtiger Anmeldeaktivitäten und zum Befolgen der Reaktionsregeln der Einrichtung, anhand von Beispielen, die zu den von ihnen genutzten Authentisierungsverfahren passen.','Beispiele: Unterweisungen zu Passwörtern und Anmeldungen, einschlägige Teilnahmeaufzeichnungen sowie Erläuterungen von Mitarbeitenden oder sichere Übungen zum Umgang mit geheimen Informationen, zu Anmeldeprüfungen und zur Reaktion auf verdächtige Authentisierungsaktivitäten.','Eine mitarbeitende Person gibt Zugangsdaten preis oder genehmigt die Anmeldung eines Angreifers und setzt dadurch einen ansonsten wirksamen technischen Schutz außer Kraft.','J-AUTH-TRN · Schulung zu Passwörtern und Fernzugriff','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('TRN-REMOTE','Mitarbeitende werden zum sicheren Fernzugriff geschult','Mitarbeitende, die Fernzugriff nutzen, werden in die von der Einrichtung genehmigten Verbindungsverfahren und die erforderlichen Vorsichtsmaßnahmen bei der Arbeit außerhalb ihrer Räumlichkeiten eingewiesen; die Unterweisung orientiert sich an den tatsächlichen Fernzugriffsregelungen, statt eine bestimmte Technologie vorzuschreiben.','Beispiele: Unterweisungen zu den von der Einrichtung genehmigten Fernzugriffsverfahren und Vorsichtsmaßnahmen, einschlägige Teilnahmeaufzeichnungen sowie Erläuterungen von Mitarbeitenden oder praktische Prüfungen der sicheren Verbindungsnutzung.','Mitarbeitende umgehen die geschützte Verbindung, vertrauen einer gefälschten Verbindung oder machen interne Ressourcen über einen nicht autorisierten Zugangsweg zugänglich.','J-AUTH-TRN · Schulung zu Passwörtern und Fernzugriff','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('C38.5','Die Dokumentation der Netzwerkarchitektur ist korrekt und aktuell','Pflegen Sie Architekturunterlagen, die die tatsächlich eingesetzten relevanten Systeme, Zonen, Verbindungen und Abhängigkeiten darstellen. Vergleichen Sie diese mit aktuellen Konfigurationen oder kontrollierten Beobachtungen und machen Sie relevante Änderungen nachvollziehbar; ein datiertes Diagramm belegt keine Korrektheit, wenn das betriebene Netzwerk ohne entsprechende Aktualisierung der Dokumentation verändert wurde.','Beispiele: aktuelle Netzwerkdiagramme oder gleichwertige Architekturunterlagen zu relevanten Systemen, Zonen, Verbindungen und Abhängigkeiten, abgeglichen mit eingesetzten Konfigurationen oder kontrollierten Beobachtungen. Datierte Überarbeitungen oder Verknüpfungen zu Änderungen sollten Korrektheit und Aktualität belegen.','Mit der Reaktion betraute Personen oder Administrierende handeln anhand eines fehlerhaften Netzwerkplans und übersehen dadurch einen Angriffsweg oder beeinträchtigen bei einer Eindämmung oder Änderung eine Abhängigkeit.','G-HYG · Konfiguration, Netzwerkhygiene und Schadsoftwareschutz','Netz- & Systemhygiene','Network & system hygiene'),
  ('C38.3','Sichere Konfigurationen werden angewendet und Abweichungen gesteuert','Sichere Konfigurationen werden angewendet und Abweichungen gesteuert. Vergleichen Sie während des gesamten Betriebs die tatsächlichen Einstellungen mit den genehmigten Sicherheitskonfigurationen, identifizieren Sie Abweichungen und korrigieren Sie diese oder dokumentieren Sie eine begründete, autorisierte Ausnahme mit geeigneten Schutzmaßnahmen.','Beispiele: genehmigte sichere Basiskonfigurationen im Vergleich mit den tatsächlichen Einstellungen während des Betriebs sowie Aufzeichnungen über Abweichungen, die deren Korrektur oder begründete autorisierte Ausnahmen mit wirksamen Schutzmaßnahmen belegen.','R1: Schleichende Konfigurationsabweichungen machen unnötige Dienste oder zu weitreichende Berechtigungen zugänglich, die Angreifer für den Systemzugriff nutzen. R2: Unkontrollierte Konfigurationsabweichungen verursachen Fehlfunktionen von Diensten oder einen inkompatiblen Betrieb.','G-HYG · Konfiguration, Netzwerkhygiene und Schadsoftwareschutz','Netz- & Systemhygiene','Network & system hygiene'),
  ('C38.4','Netzwerke werden nach Risiken und Schutzbedarf segmentiert','Netzwerke werden nach Risiken und Schutzbedarf segmentiert. Ordnen Sie Systeme und Dienste entsprechend ihrer Funktion, Kritikalität und Vertrauensstufe definierten Sicherheitszonen zu und trennen Sie kritische Umgebungen und Umgebungen Dritter, soweit erforderlich. Diese Kontrolle bewertet die übergreifende Konzeption und Umsetzung der Segmentierung; gesonderte Kontrollen bewerten die Trennung drahtloser Netze sowie die Filterung ein- und ausgehenden Verkehrs.','Beispiele: definierte Sicherheitszonen und Zuordnungsentscheidungen auf Grundlage von Funktion, Kritikalität und Vertrauen, mit Konfigurationen und sicheren zonenübergreifenden Prüfungen, die die beabsichtigte Segmentierung belegen, einschließlich kritischer Umgebungen und Umgebungen Dritter, soweit erforderlich.','R1: Ein Angreifer gelangt aus einer Zone mit geringerem Vertrauen oder einer Zone Dritter in sensible Systeme und legt Informationen offen oder verändert sie. R2: Eine Infektion oder ein störendes Ereignis breitet sich über unzureichend getrennte Zonen aus und beeinträchtigt ansonsten nicht zusammenhängende Dienste.','G-HYG · Konfiguration, Netzwerkhygiene und Schadsoftwareschutz','Netz- & Systemhygiene','Network & system hygiene'),
  ('C38.12','Eine demilitarisierte Zone schützt die ein- und ausgehende Netzwerkkommunikation','Eine demilitarisierte Zone schützt Kommunikation, die von den Netzwerken der Einrichtung ausgeht oder an diese gerichtet ist.','Beispiele: DMZ-Architektur und eingesetzte Grenz- beziehungsweise Dienstkonfigurationen, untermauert durch sichere Verbindungsprüfungen, die zeigen, wie der Verkehr zu oder von den Netzwerken der Einrichtung durch die vorgesehene Trennung geschützt wird.','Die Kompromittierung eines von außen erreichbaren Dienstes eröffnet einen direkten Weg in interne Systeme und weitet den Sicherheitsvorfall über den exponierten Dienst hinaus aus.','G-HYG · Konfiguration, Netzwerkhygiene und Schadsoftwareschutz','Netz- & Systemhygiene','Network & system hygiene'),
  ('C38.10','Administrationsnetzwerke und -kanäle sind von anderem Verkehr getrennt','Trennen Sie Administrationsnetzwerke und -kanäle vom operativen und sonstigen Verkehr und überprüfen Sie, dass die vorgesehene Trennung durch die tatsächlichen Zugriffs- und Routingkonfigurationen durchgesetzt wird. Ein lediglich separat benanntes Management-VLAN genügt nicht, wenn gewöhnlicher Verkehr die vorgesehene Grenze umgehen und administrative Schnittstellen erreichen kann; bewerten Sie etwaige kontrollierte Zugriffswege anhand des Trennungskonzepts.','Beispiele: Konzeption der Administrationsnetzwerke und -kanäle sowie tatsächliche Zugriffs- und Routingkonfigurationen, mit sicheren Prüfungen, die die Trennung des Managementverkehrs vom operativen und sonstigen Verkehr belegen.','Ein Angreifer in einem operativen Netzwerk oder einem Netzwerk mit geringerem Vertrauen erreicht Managementschnittstellen und nimmt unbefugte administrative Änderungen vor.','G-HYG · Konfiguration, Netzwerkhygiene und Schadsoftwareschutz','Netz- & Systemhygiene','Network & system hygiene'),
  ('C38.11','Produktionssysteme und Sicherungskopien sind von Entwicklung und Tests getrennt','Verhindern Sie durch die Trennung von Umgebungen und Zugriffsrechten, dass Entwicklungs- oder Testaktivitäten Produktionssysteme oder deren Sicherungskopien kompromittieren; unterschiedliche Umgebungsnamen allein belegen keine wirksame Grenze.','Beispiele: Umgebungs- und Verbindungsunterlagen mit Zugriffs- und Konfigurationsprüfungen, die zeigen, dass Produktionssysteme und deren Sicherungskopien von Entwicklungs- und Testsystemen getrennt sind.','R1: Eine Kompromittierung oder unsichere Aktivität in Entwicklung oder Tests erreicht Produktionssysteme oder Wiederherstellungskopien und legt Produktionsinformationen offen. R2: Testaktivitäten beschädigen Produktionsdaten oder Sicherungskopien, unterbrechen produktive Dienste oder beeinträchtigen die Wiederherstellung.','G-HYG · Konfiguration, Netzwerkhygiene und Schadsoftwareschutz','Netz- & Systemhygiene','Network & system hygiene'),
  ('C38.6','Der Netzwerkzugang ist, soweit angemessen, auf autorisierte Geräte beschränkt','Bestimmen Sie, wo eine Beschränkung des Netzwerkzugangs auf autorisierte Geräte angemessen ist, und setzen Sie diese Beschränkung im gewählten Umfang durch. Prüfen Sie, dass zugelassene Geräte eine Verbindung herstellen können und nicht autorisierte Geräte abgewiesen werden; eine Geräteliste oder eine nicht durchgesetzte Zulassungsregel belegt keinen beschränkten Zugang.','Beispiele: die Entscheidung darüber, wo eine Beschränkung der Gerätezulassung angemessen ist, sowie für diesen Umfang Informationen zu autorisierten Geräten und sichere Prüfungen, die zeigen, dass die Zugangskontrollen zugelassene Geräte akzeptieren und andere abweisen.','Ein nicht autorisiertes oder kompromittiertes Gerät verbindet sich mit dem Netzwerk und greift auf interne Ressourcen zu oder schleust schädlichen Verkehr ein.','G-HYG · Konfiguration, Netzwerkhygiene und Schadsoftwareschutz','Netz- & Systemhygiene','Network & system hygiene'),
  ('C38.9','DNS und Internet-Routing folgen den anwendbaren Sicherheitspraktiken','Wenden Sie die DNS- und Internet-Routing-Sicherheitspraktiken an, die für die Netzwerkrolle und Dienste der Einrichtung relevant sind, und prüfen Sie deren betriebliche Konfiguration; gehen Sie nicht davon aus, dass jede Einrichtung eine eigene DNS- oder Routinginfrastruktur betreibt.','Beispiele: Ermittlung der anwendbaren DNS- und Internet-Routing-Sicherheitspraktiken, entsprechende Dienst- und Routerkonfigurationen sowie betriebliche Prüfungen, die zeigen, dass diese Praktiken entsprechend der Rolle der Einrichtung angewendet werden.','R1: Manipulierte Namensauflösung oder manipuliertes Routing leitet Nutzende und Systeme zu einem vom Angreifer kontrollierten Ziel und legt Zugangsdaten oder ausgetauschte Daten offen. R2: Routing- oder DNS-Ausfälle machen legitime Dienste unerreichbar oder leiten deren Verkehr um.','G-HYG · Konfiguration, Netzwerkhygiene und Schadsoftwareschutz','Netz- & Systemhygiene','Network & system hygiene'),
  ('C38.7','Für Netzwerkschichtprotokolle der neuesten Generation bestehen ein Umstellungsplan und Umsetzungsmaßnahmen','Ein Umsetzungsplan behandelt den Übergang zu Netzwerkschichtprotokollen der neuesten Generation. Für Einrichtungen im CIR-Anwendungsbereich muss der Übergang sicher, angemessen und schrittweise erfolgen, mit Maßnahmen zur Beschleunigung seiner Umsetzung. Ein Plan allein belegt diese Umsetzungsmaßnahmen nicht; die Bestimmung legt weder eine allgemein geltende Protokollversion noch eine allgemeine Umstellungsfrist fest.','Beispiele: ein Umsetzungsplan oder gleichwertige Planungsunterlagen, die den relevanten Übergang zu Netzwerkschichtprotokollen der neuesten Generation, den betroffenen Umfang, Abhängigkeiten und geplante Maßnahmen benennen. Beziehen Sie innerhalb des CIR-Anwendungsbereichs umgesetzte Maßnahmen zur Beschleunigung des sicheren, angemessenen und schrittweisen Übergangs sowie Aufzeichnungen über Fortschritte ein, statt lediglich einen genehmigten Plan vorzulegen.','Ein ungesteuerter Protokollübergang führt ungefilterte Verkehrswege oder inkompatible Verbindungen ein, macht Systeme angreifbar oder stört netzwerkabhängige Dienste.','G-HYG · Konfiguration, Netzwerkhygiene und Schadsoftwareschutz','Netz- & Systemhygiene','Network & system hygiene'),
  ('C28.1','Der Schutz vor schädlicher und nicht autorisierter Software ist wirksam','Der Schutz vor schädlicher und nicht autorisierter Software ist wirksam. Verhindern oder erkennen Sie die nicht genehmigte Installation und Ausführung von Software auf relevanten Systemen, halten Sie Schutzmaßnahmen aktuell und untersuchen Sie Erkennungen im etablierten Sicherheitsprozess.','Beispiele: wirksame Kontrollen gegen schädliche und nicht genehmigte Software, aktueller Schutzstatus und repräsentative Erkennungen von Installationen beziehungsweise Ausführungen oder sichere Tests. Beziehen Sie die Behandlung tatsächlicher Erkennungen im etablierten Sicherheitsprozess ein, soweit solche aufgetreten sind.','R1: Schädliche oder nicht autorisierte Software entwendet Informationen, erfasst Zugangsdaten oder ermöglicht Fernsteuerung. R2: Schadsoftware beschädigt oder verschlüsselt Daten und unterbricht betroffene Dienste.','G-HYG · Konfiguration, Netzwerkhygiene und Schadsoftwareschutz','Netz- & Systemhygiene','Network & system hygiene'),
  ('NET-FILTER','Ein- und ausgehender Netzwerkverkehr ist beschränkt','Ein- und ausgehender Netzwerkverkehr ist beschränkt. Erlauben Sie ausschließlich begründete ein- und ausgehende Verbindungen durch durchgesetzte Regeln für relevante Quellen, Ziele, Dienste und Protokolle. Blockieren Sie nicht benötigte Kommunikation und überprüfen Sie erlaubte und gesperrte Wege in beiden Richtungen. Ein benanntes Firewall-Produkt allein ist kein Nachweis dafür, dass die Beschränkungen wirken.','Beispiele: begründete Regeln für relevante Quellen, Ziele, Dienste und Protokolle im Vergleich mit durchgesetzten Konfigurationen sowie sichere Tests erlaubter und gesperrter Wege sowohl in eingehender als auch in ausgehender Richtung.','R1: Unnötige eingehende Verbindungen setzen interne Dienste unbefugtem Zugriff aus. R2: Unbeschränkte ausgehende Wege ermöglichen Datenabfluss oder Command-and-Control-Verkehr von Angreifern.','G-FLT · Filterung an Netzwerkgrenzen','Netz- & Systemhygiene','Network & system hygiene'),
  ('WIFI-SEG','WLAN-Netze werden entsprechend ihrer Vertrauensstufe getrennt (Gilt nur, wenn die Einrichtung drahtlose Netze betreibt oder bereitstellt, einschließlich verwalteter Netze.)','WLAN-Netze werden entsprechend ihrer Vertrauensstufe getrennt. Isolieren Sie Gastzugänge und andere nicht vertrauenswürdige drahtlose Zugänge von internen Systemen der Einrichtung. Beschränken Sie den internen WLAN-Zugang auf die Zonen und Ressourcen, die durch seine Sicherheitsanforderungen gerechtfertigt sind. Überprüfen Sie die Trennung durch Verbindungstests; unterschiedliche Netzwerknamen allein belegen keine Isolation. (Gilt nur, wenn die Einrichtung drahtlose Netze betreibt oder bereitstellt, einschließlich verwalteter Netze.)','Für betriebene oder bereitgestellte drahtlose Netze zählen zu den Beispielen Konfigurationen von Gastzonen, nicht vertrauenswürdigen Zonen und internen Zonen sowie Verbindungstests, die die Isolation von Gästen und ausschließlich begründeten internen Zugriff auf interne Ressourcen zeigen.','Ein Gastgerät oder ein kompromittiertes drahtloses Gerät mit geringer Vertrauensstufe erreicht Ressourcen der Einrichtung und greift auf Daten zu oder breitet einen Angriff aus.','G-WLAN · Schutz drahtloser Netze','Netz- & Systemhygiene','Network & system hygiene'),
  ('WIFI-AUTH','Drahtloser Zugang nutzt sichere Authentisierung und Verschlüsselung (Gilt nur, wenn die Einrichtung drahtlose Netze betreibt oder bereitstellt, einschließlich verwalteter Netze.)','Drahtloser Zugang nutzt sichere Authentisierung und Verschlüsselung. Schützen Sie drahtlose Verbindungen mit einer ihrem Zweck und Risiko angemessenen Authentisierung und Verschlüsselung. Verlangen Sie für den internen WLAN-Zugang die Authentisierung autorisierter Nutzender oder Geräte, deaktivieren Sie unsichere Verbindungsmodi und überprüfen Sie, dass unbefugter Zugang abgewiesen wird. Halten Sie Gastzugänge außerhalb der internen Zugriffsberechtigungen. (Gilt nur, wenn die Einrichtung drahtlose Netze betreibt oder bereitstellt, einschließlich verwalteter Netze.)','Für betriebene oder bereitgestellte drahtlose Netze zählen zu den Beispielen risikogerechte Authentisierungs- und Verschlüsselungseinstellungen sowie sichere Prüfungen der internen Nutzer- und Geräteautorisierung, der Abweisung unbefugten Zugangs und der Deaktivierung unsicherer Modi. Prüfen Sie, dass Gastzugänge keine internen Berechtigungen erhalten, ohne WLAN-Passwörter oder Schlüssel zu erheben.','R1: Nicht autorisierte Nutzende oder Geräte erhalten durch schwache Authentisierung internen WLAN-Zugang. R2: Ein Angreifer fängt unzureichend geschützten drahtlosen Verkehr ab oder manipuliert ihn und erlangt dadurch sensible Informationen oder bewirkt, dass Systeme veränderte Daten akzeptieren.','G-WLAN · Schutz drahtloser Netze','Netz- & Systemhygiene','Network & system hygiene'),
  ('SYS-CAP','System- und Netzwerkkapazitäten decken den Bedarf der Dienste','System- und Netzwerkkapazitäten decken den Bedarf der Dienste. Bewerten Sie den aktuellen und erwarteten Bedarf an Rechenleistung, Arbeitsspeicher, Datenspeicher und Netzwerkressourcen im Verhältnis zur verfügbaren Kapazität. Definieren Sie Schwellenwerte, erkennen Sie bevorstehende Engpässe und setzen Sie rechtzeitig Anpassungen um, um Dienstunterbrechungen zu vermeiden.','Beispiele: aktueller und prognostizierter Bedarf an Rechenleistung, Arbeitsspeicher, Datenspeicher und Netzwerkressourcen im Vergleich mit verfügbarer Kapazität und definierten Schwellenwerten, mit Aufzeichnungen zu erkannten Engpässen und rechtzeitig umgesetzten Anpassungen, soweit erforderlich.','Der Bedarf übersteigt die Rechen-, Speicher- oder Netzwerkkapazität, beeinträchtigt oder stoppt Dienste und führt möglicherweise dazu, dass wartende Arbeitsaufträge oder Datensätze verworfen werden.','G-CAP · System- und Netzwerkkapazität','Netz- & Systemhygiene','Network & system hygiene'),
  ('C38.13','Netzwerkschutz und Segmentierung werden in geplanten Intervallen und nach relevanten Ereignissen überprüft','Überprüfen Sie die eingesetzten Netzwerkschutzmaßnahmen und die Segmentierung in geplanten Intervallen sowie nach erheblichen Sicherheitsvorfällen oder relevanten Änderungen des Betriebs oder der Risiken und dokumentieren Sie erforderliche Korrekturen oder eine fundierte Entscheidung, dass die Schutzmaßnahmen weiterhin angemessen sind.','Beispiele: geplante Überprüfungsintervalle und relevante ereignisbezogene Auslöser, abgeschlossene Überprüfungen des Netzwerkschutzes und der Segmentierung sowie daraus resultierende Korrekturen oder begründete Entscheidungen gegen Änderungen, gestützt auf relevante technische Prüfungen.','R1: Durch Änderungen bleiben veraltete Netzwerkregeln oder unwirksame Zonengrenzen bestehen, sodass unbefugte Zugangswege unbemerkt fortbestehen. R2: Nach Netzwerkänderungen werden legitime Dienstabhängigkeiten durch veraltete Filter- oder Segmentierungsregeln blockiert; dies unterbricht den Betrieb bis zur Korrektur der Regeln.','G-REVIEW · Überprüfung des Netzwerkschutzes','Netz- & Systemhygiene','Network & system hygiene'),
  ('C39.1','Eine angewendete Kryptografierichtlinie legt die angemessene Nutzung fest','Die Kryptografierichtlinie legt fest, wann und wie kryptografischer Schutz einzusetzen ist, und leitet die tatsächlichen Umsetzungsentscheidungen; eine veröffentlichte, aber nicht befolgte Richtlinie belegt dieses Ergebnis nicht.','Beispiele: die tatsächlich angewendete Kryptografierichtlinie, die die angemessene Nutzung im bewerteten Umfang definiert, im Vergleich mit relevanten Umsetzungsentscheidungen und der Praxis, die ihre Anwendung belegt.','Uneinheitliche kryptografische Entscheidungen lassen sensible Informationen über Systeme und Austauschvorgänge hinweg ungeschützt oder erwecken fälschlich den Eindruck, diese seien geschützt.','H-CRY · Kryptografiekonzept','Kryptografie & sichere Kommunikation','Cryptography & secure communications'),
  ('CRYPTO-INV','Kryptografische Schlüssel und Zertifikate werden inventarisiert','Kryptografische Schlüssel und Zertifikate werden inventarisiert. Führen Sie eindeutig zuordenbare Aufzeichnungen über relevante Schlüssel und digitale Zertifikate, ihre Systeme, ihren Zweck, zuständige Verantwortliche, genehmigte Speicherorte, Gültigkeits- oder Nutzungszeiträume und die Zuständigkeit für Erneuerungen. Gleichen Sie die Aufzeichnungen mit der tatsächlichen Nutzung ab. Erfassen Sie im Inventar Verweise auf sicher verwahrte Schlüssel, nicht das geheime Schlüsselmaterial selbst. Diese Kontrolle legt fest, was verwaltet werden muss; C39.3 bewertet die Maßnahmen im Lebenszyklus.','Inventar oder gleichwertige Systemaufzeichnungen; Zuordnungen zu Verantwortlichen und Diensten; Überwachung von Ablaufdaten oder Nutzungszeiträumen; Abgleich mit eingesetzten Zertifikaten und Schlüsselmanagementsystemen. Extrahieren Sie keine privaten Schlüssel oder sonstiges geheimes Schlüsselmaterial als Auditnachweise.','R1: Nicht erfasste Zertifikate laufen ab, ohne dass eine Zuständigkeit für ihre Erneuerung feststeht, und unterbrechen abhängige Dienste. R2: Kompromittierte oder veraltete Schlüssel bleiben in Gebrauch, weil ihre Speicherorte und abhängigen Systeme für einen Austausch oder Widerruf nicht ermittelt werden können.','H-INV · Kryptografieinventar','Kryptografie & sichere Kommunikation','Cryptography & secure communications'),
  ('C39.2','Erforderliche kryptografische Schutzmaßnahmen werden umgesetzt','Prüfen Sie, dass die für relevante Informationen und Kommunikation ausgewählten kryptografischen Schutzmaßnahmen aktiviert sind und wie vorgesehen funktionieren; die bloße Auflistung einer Anforderung oder die Bereitstellung eines Produkts ohne die erforderliche Konfiguration genügt nicht.','Beispiele: erforderliche kryptografische Schutzmaßnahmen im Vergleich mit eingesetzten Einstellungen und sicheren Prüfungen, die ihre Funktion für relevante Daten und Kommunikation belegen. Verwenden Sie nicht geheime Metadaten oder Testdaten, keine Schlüssel oder sensiblen Klartextdaten.','R1: Eine unbefugte Partei liest sensible gespeicherte oder übertragene Informationen, wenn die erforderliche Verschlüsselung fehlt oder unwirksam ist. R2: Veränderte Kommunikation oder Daten werden als echt akzeptiert, wenn die erforderlichen Integritäts- und Authentizitätsschutzmaßnahmen nicht funktionieren.','H-CRY-IMPL · Kryptografische Umsetzung und Schlüssellebenszyklus','Kryptografie & sichere Kommunikation','Cryptography & secure communications'),
  ('C39.3','Kryptografische Schlüssel werden über ihren gesamten Lebenszyklus verwaltet','Kryptografische Schlüssel werden über ihren gesamten Lebenszyklus verwaltet. Schützen Sie Schlüsselerzeugung, -verteilung, -speicherung und -zugriff. Legen Sie angemessene Nutzungszeiträume fest und setzen Sie diese durch, wechseln Sie Schlüssel bei Fälligkeit und widerrufen oder ersetzen Sie kompromittierte Schlüssel. Sorgen Sie bei Bedarf für sichere Sicherung und Wiederherstellung, erneuern oder widerrufen Sie Zertifikate nach Erfordernis und nehmen Sie Schlüssel sicher außer Betrieb und vernichten Sie diese sicher. Überprüfen Sie, dass die Maßnahmen im Lebenszyklus tatsächlich stattfinden; die Identifizierung von Schlüsseln und Zertifikaten wird gesondert unter CRYPTO-INV bewertet. Protokollieren Sie wesentliche Schlüsselmanagementmaßnahmen und prüfen Sie diese Aufzeichnungen im Rahmen von Audits entsprechend der Schlüsselmanagementrichtlinie.','Beispiele: geschwärzte Aufzeichnungen und Konfigurationen zu Schlüsselerzeugung, -verteilung, -speicherung und -zugriff, Nutzungszeiträumen und fälligen Wechseln, Widerruf beziehungsweise Austausch bei Kompromittierung, Zertifikatserneuerung beziehungsweise -widerruf, erforderlicher Sicherung und Wiederherstellung sowie sicherer Außerbetriebnahme und Vernichtung. Beziehen Sie Protokolle wesentlicher Schlüsselmanagementmaßnahmen und deren Auditierung entsprechend der Richtlinie ein; extrahieren Sie keine privaten Schlüssel oder sonstiges geheimes Schlüsselmaterial.','R1: Offengelegte, schwache oder nicht widerrufene Schlüssel ermöglichen es einem Angreifer, Informationen zu entschlüsseln oder sich als vertrauenswürdige Partei auszugeben. R2: Verlorene oder vorzeitig vernichtete Schlüssel, abgelaufene Zertifikate oder fehlerhafte Widerrufe machen geschützte Daten oder abhängige Dienste unverfügbar.','H-CRY-IMPL · Kryptografische Umsetzung und Schlüssellebenszyklus','Kryptografie & sichere Kommunikation','Cryptography & secure communications'),
  ('C39.4','Kryptografische Richtlinien und Verfahren folgen dem Stand der Technik','Überprüfen Sie kryptografische Richtlinien und Verfahren anhand relevanter technischer Entwicklungen und aktueller Leitlinien, aktualisieren Sie veraltete Entscheidungen oder begründen Sie, warum bestehende Regelungen weiterhin angemessen sind.','Beispiele: datierte Überprüfungen kryptografischer Richtlinien und Verfahren unter Berücksichtigung relevanter aktueller technischer Leitlinien und Entwicklungen, mit daraus resultierenden Aktualisierungen oder fundierten Entscheidungen, dass bestehende Regelungen weiterhin angemessen sind.','Veraltete kryptografische Algorithmen oder Verfahren ermöglichen die Entschlüsselung geschützter Informationen oder die Fälschung vertrauenswürdiger Kommunikation.','H-CRY-IMPL · Kryptografische Umsetzung und Schlüssellebenszyklus','Kryptografie & sichere Kommunikation','Cryptography & secure communications'),
  ('C41.2','Erforderliche reguläre Sprach-, Video- und Textkommunikation wird geschützt','Nutzen Sie, soweit angemessen, gesicherte Sprach-, Video- und Textdienste für die reguläre Kommunikation, mit Schutzmaßnahmen entsprechend ihrem ermittelten Schutzbedarf; die Kontrolle schreibt nicht für jeden Kommunikationskanal dieselbe Lösung vor.','Beispiele: ermittelter Schutzbedarf für reguläre Sprach-, Video- und Textdienste im Vergleich mit tatsächlichen Diensteinstellungen und sicheren Demonstrationen, die zeigen, dass die erforderliche Kommunikation geschützt ist.','R1: Unbefugte Parteien hören oder lesen reguläre Sprach-, Video- oder Textkommunikation mit, die sensible Informationen enthält. R2: Einer gefälschten oder manipulierten Nachricht wird vertraut, wodurch eine fehlerhafte geschäftliche oder sicherheitsbezogene Handlung ausgelöst wird.','J-COM · Sichere Regel- und Notfallkommunikation','Kryptografie & sichere Kommunikation','Cryptography & secure communications'),
  ('C41.5','Systemübergreifende Kommunikationskanäle authentisieren Endpunkte und schützen Daten','Die Kommunikation zwischen Systemen nutzt vertrauenswürdige Kanäle mit authentisierten Endpunkten und geschützten Daten. Überprüfen Sie innerhalb des CIR-Anwendungsbereichs, dass die vertrauenswürdigen Kanäle durch logische, kryptografische oder physische Trennung von anderen Kommunikationskanälen isoliert sind. Diese Isolationsanforderung gilt zusätzlich zur Identifizierung der Endpunkte und zum Schutz vor Datenveränderung oder -offenlegung.','Beispiele: Einstellungen für die Endpunktauthentisierung und vertrauenswürdige Kanäle zwischen Systemen, mit sicheren Verbindungs- und Nachrichtenprüfungen, die die Authentisierung der Gegenstelle und den erforderlichen Schutz der Daten belegen, einschließlich der Abweisung nicht vertrauenswürdiger Gegenstellen, soweit relevant. Beziehen Sie innerhalb des CIR-Anwendungsbereichs Konfigurationen oder sichere Prüfungen ein, die eine logische, kryptografische oder physische Trennung der vertrauenswürdigen Kanäle von anderen Kommunikationskanälen belegen.','R1: Ein System verbindet sich mit einem vorgetäuschten Endpunkt und legt Daten oder Zugangsdaten offen. R2: Nachrichten zwischen Systemen werden verändert oder erneut eingespielt und verursachen unbefugte Transaktionen oder fehlerhafte Verarbeitung.','J-COM · Sichere Regel- und Notfallkommunikation','Kryptografie & sichere Kommunikation','Cryptography & secure communications'),
  ('C41.3','Sichere Notfallkommunikation bleibt bei Bedarf nutzbar','Stellen Sie, soweit angemessen, sichere Notfallkommunikation bereit, die bei den relevanten Störungsszenarien einschließlich des Ausfalls regulärer Kanäle nutzbar bleibt; Kontaktdaten allein belegen keinen verfügbaren Kommunikationsweg.','Beispiele: Regelungen für sichere Notfallkommunikation und kontrollierte Übungen oder Aufzeichnungen tatsächlicher Nutzung, die die Verfügbarkeit bei Bedarf belegen, einschließlich relevanter Störungen der regulären Kanäle.','R1: Der Ausfall von Notfallkommunikationskanälen verzögert die Koordination und schützende Entscheidungen während eines Sicherheitsvorfalls. R2: Mit der Reaktion betraute Personen weichen auf nicht vertrauenswürdige Kanäle aus und legen sensible Vorfallsinformationen offen oder handeln aufgrund von Anweisungen mit vorgetäuschter Identität.','J-COM · Sichere Regel- und Notfallkommunikation','Kryptografie & sichere Kommunikation','Cryptography & secure communications'),
  ('C38.8','Für moderne interoperable E-Mail-Sicherheitsstandards bestehen Einführungspläne und Maßnahmen','Planen Sie die Einführung anwendbarer, interoperabler moderner E-Mail-Sicherheitsstandards und führen Sie nachvollziehbare Umsetzungsmaßnahmen durch; ein Zukunftsplan ohne Fortschritt belegt keine Einführung.','Beispiele: ein Einführungsplan für E-Mail-Sicherheit, der anwendbare moderne interoperable Standards benennt, mit nachvollziehbaren Umsetzungsmaßnahmen und relevanten Konfigurations- oder Interoperabilitätsprüfungen.','R1: Eine uneinheitliche Einführung von E-Mail-Sicherheit führt dazu, dass gefälschten Nachrichten vertraut wird oder sensible E-Mails ohne den vorgesehenen Schutz übertragen werden. R2: Eine inkompatible Einführung von E-Mail-Sicherheit weist legitime Nachrichten zurück oder verzögert sie.','G-EMAIL · Sicherheitsstandards für E-Mail','Kryptografie & sichere Kommunikation','Cryptography & secure communications'),
  ('D04-01','Erforderliche Sicherheitsfunktionen werden vor Beschaffung oder Entwicklung festgelegt','Erforderliche Sicherheitsfunktionen werden vor dem Kauf oder der Entwicklung eines Systems festgelegt. Legen Sie auf Grundlage des vorgesehenen Einsatzzwecks, der Daten, Schnittstellen und Risiken fest, was das System schützen und welche Sicherheitsfunktionen es bereitstellen muss. Nehmen Sie diese Anforderungen in die Beschaffungs- oder Entwicklungsspezifikationen sowie in die anwendbaren Lieferantenanforderungen auf. Legen Sie beispielsweise fest, wer auf Patientenakten zugreifen darf und welche Zugriffsereignisse protokolliert werden müssen.','Beispiele: datierte Beschaffungs- oder Entwicklungsspezifikationen oder gleichwertige Anforderungsunterlagen, die Schutzbedarf und Sicherheitsfunktionen aus dem vorgesehenen Einsatzzweck, den Daten, Schnittstellen und Risiken ableiten, mit Mitteilung der anwendbaren Anforderungen an Lieferanten vor Beschaffung oder Entwicklung.','Ein beschafftes System kann die für seinen vorgesehenen Daten- und Dienstkontext erforderlichen Schutzmaßnahmen nicht bereitstellen, legt Informationen offen oder erzwingt kostspielige Änderungen vor einer sicheren Nutzung.','E-ACQ · Beschaffung und Lebenszyklus','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-02','Vorgeschlagene Systementwürfe werden anhand der Sicherheitsanforderungen geprüft','Der vorgeschlagene Systementwurf wird anhand der Sicherheitsanforderungen geprüft. Prüfen Sie vor der Abnahme des vorgeschlagenen Entwurfs, ob dessen Architektur, Integrationen und geplante Konfiguration die unter D04-01 definierten Anforderungen erfüllen können. Prüfen Sie beispielsweise, dass das vorgeschlagene Zugriffsmodell den Zugriff auf Patientenakten auf autorisierte Nutzende beschränkt und der Entwurf die erforderliche Protokollierung vorsieht. Beheben Sie wesentliche Lücken oder dokumentieren Sie begründete Behandlungsentscheidungen. Bewerten Sie bei einem Standardprodukt die verfügbare Lösung und die Einsatzkonzeption; dies erfordert keinen uneingeschränkten Zugriff auf den internen Entwurf des Lieferanten.','Beispiele: ein Abgleich in der Entwurfsphase mit den Anforderungen aus D04-01 zu Architektur, Integrationen und geplanter Konfiguration, mit Entscheidungen zur Behebung wesentlicher Lücken oder zur Begründung ihrer Behandlung vor der Entwurfsabnahme. Bei Standardprodukten können verfügbare Informationen zur Lösung und Einsatzkonzeption ausreichen.','Ein Entwurf mit unsicheren Vertrauensgrenzen oder inkompatiblen Integrationen wird abgenommen und verankert dadurch eine Schwäche bei Zugriffssicherheit oder Resilienz, deren Behebung nach der Lieferung kostspielig ist.','E-ACQ · Beschaffung und Lebenszyklus','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-10','Komponenteninformationen identifizieren Produkte und Abhängigkeiten bei sicherheitsrelevanten Beschaffungen','Bei sicherheitsrelevanten Beschaffungen beschafft und pflegt die Einrichtung ausreichende Informationen über die Hardware- und Softwarekomponenten, um bei Sicherheitsproblemen betroffene Produkte und Abhängigkeiten identifizieren zu können.','Bei sicherheitsrelevanten Beschaffungen zählen zu den Beispielen gepflegte Komponenten-, Versions- und Abhängigkeitsinformationen, die ausreichen, um bei Sicherheitsproblemen betroffene Produkte zu identifizieren, abgeglichen mit repräsentativen bereits eingesetzten Beschaffungsgegenständen.','Eine verwundbare Komponente oder Abhängigkeit kann dem beschafften Produkt nicht zugeordnet werden, wodurch sich die Identifizierung und Behandlung betroffener Systeme verzögert.','E-ACQ · Beschaffung und Lebenszyklus','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-11','Sicherheitsrelevante Beschaffungen umfassen nutzbare Sicherheits- und Konfigurationsinformationen','Bei sicherheitsrelevanten Beschaffungen beschafft die Einrichtung nutzbare Informationen über Sicherheitsfunktionen und die für den sicheren Betrieb des Produkts oder Dienstes erforderliche Konfiguration.','Bei sicherheitsrelevanten Beschaffungen zählen zu den Beispielen nutzbare Lieferantenunterlagen oder gleichwertige Informationen, die Sicherheitsfunktionen und die für den sicheren Betrieb erforderliche Konfiguration beschreiben und zum beschafften Produkt oder Dienst passen.','Für den Betrieb zuständige Personen setzen ein Produkt mit unsicheren Einstellungen ein oder betreiben es so, weil dessen Sicherheitsfunktionen und Konfigurationsanforderungen nicht verstanden werden.','E-ACQ · Beschaffung und Lebenszyklus','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-12','Zusagen zur Unterstützung mit Sicherheitsupdates und deren Endtermine werden nachverfolgt','Zusagen zur Unterstützung mit Sicherheitsupdates und die Termine für das Ende dieser Unterstützung sind für relevante Produkte und Dienste bekannt und werden nachverfolgt, damit Lücken im unterstützten Betrieb rechtzeitig erkannt werden.','Beispiele: relevante Lieferantenzusagen zu Sicherheitsupdates und Termine für das Supportende in Vereinbarungen, Dienstunterlagen oder gleichwertigen Nachverfolgungsinformationen, mit Prüfungen zur Erkennung bevorstehender oder bestehender Supportlücken.','Die Sicherheitsunterstützung endet unbemerkt und lässt eingesetzte Produkte gegenüber Schwachstellen ungeschützt, für die keine Updates mehr verfügbar sind.','E-ACQ · Beschaffung und Lebenszyklus','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-03','Die Sicherheitsabnahme bestätigt die Anforderungserfüllung gelieferter Systeme','Die Sicherheitsabnahme bestätigt, dass das gelieferte System die Anforderungen erfüllt. Prüfen Sie vor der Produktivsetzung des Systems oder Releases Testergebnisse und andere geeignete Nachweise dafür, dass die erforderlichen Schutzmaßnahmen tatsächlich funktionieren. Überprüfen Sie beispielsweise, dass ein nicht autorisiertes Testkonto keine Patientenakte öffnen kann und das erforderliche Protokoll erzeugt wird. Dokumentieren Sie die Abnahmeentscheidung, die Behandlung wesentlicher Feststellungen und etwaige noch offene Bedingungen. Dies ist die Entscheidung zur Abnahme des gelieferten Systems, nicht die frühere Prüfung seines vorgeschlagenen Entwurfs.','Beispiele: die Abnahmeentscheidung vor der Produktivsetzung, verknüpft mit dem gelieferten System beziehungsweise Release, definierten Anforderungen und Tests oder anderen Nachweisen für die Funktion der erforderlichen Schutzmaßnahmen, einschließlich der Behandlung wesentlicher Feststellungen und noch offener Bedingungen.','Ein geliefertes System geht mit unwirksamen erforderlichen Schutzmaßnahmen in den Produktivbetrieb, weil die Abnahme auf Zusagen statt auf Funktionsnachweisen beruht, und gefährdet dadurch produktive Daten oder Dienste.','E-ACQ · Beschaffung und Lebenszyklus','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-13','Für Produkte kurz vor oder nach dem Supportende sind Lebenszyklusentscheidungen umgesetzt','Für Produkte, deren Sicherheitsunterstützung dem Ende zugeht oder endet, ist eine Lebenszyklusentscheidung umgesetzt, mit einer zuständigen verantwortlichen Person, einem Austausch- oder Migrationszeitplan und begründeten vorläufigen Schutzmaßnahmen, soweit erforderlich.','Beispiele: identifizierte Produkte kurz vor oder nach dem Ende der Sicherheitsunterstützung, mit umgesetzten Lebenszyklusentscheidungen, zuständigen Verantwortlichen, Austausch- oder Migrationszeitplänen und Nachweisen für begründete vorläufige Schutzmaßnahmen, soweit erforderlich.','R1: Nicht mehr unterstützte Systeme bleiben ohne wirksamen vorläufigen Schutz oder einen realisierbaren Migrationsweg in Betrieb und verlängern dadurch die Gefährdung durch ausnutzbare Schwachstellen. R2: Ein überstürzter Austausch nicht mehr unterstützter Technologie stört abhängige Dienste.','E-ACQ · Beschaffung und Lebenszyklus','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-04','Relevante Regeln für sichere Entwicklung werden vor Entwicklungsbeginn festgelegt und angewendet (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Regeln für sichere Entwicklung werden vor Entwicklungsbeginn festgelegt, decken die relevanten Lebenszyklusphasen und verantwortlichen Rollen ab und werden sowohl in internen als auch in ausgelagerten Entwicklungsprojekten angewendet.','Wenn Entwicklung im Anwendungsbereich liegt, zählen zu den Beispielen vor Arbeitsbeginn festgelegte Regeln für sichere Entwicklung, die relevante Lebenszyklusphasen und Rollen abdecken, mit Projektaufzeichnungen, die ihre Anwendung auf interne und ausgelagerte Entwicklung belegen, soweit jeweils zutreffend.','Entwicklungsteams lassen Sicherheitsaktivitäten aus oder wenden uneinheitliche Verfahren an, sodass wiederkehrende Entwurfs- oder Umsetzungsschwächen in Releases gelangen.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-23','Ausgelagerte Entwicklung folgt den Sicherheitsprozessen für Beschaffung und Lieferkette (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Ausgelagerte Entwicklung ist in die Sicherheitsprozesse der Einrichtung für Beschaffung und Lieferkette einbezogen; die anwendbaren Anforderungen und Verantwortlichkeiten werden dem Entwicklungsdienstleister mitgeteilt und mit ihm vereinbart.','Wenn Entwicklung ausgelagert wird, zählen zu den Beispielen vereinbarte Sicherheitsanforderungen und Verantwortlichkeiten in Verträgen oder gleichwertigen Regelungen, mit Nachweisen ihrer Kommunikation und Einbeziehung in Beschaffungs- und Lieferkettenprozesse.','Ein externer Entwicklungsdienstleister lässt erforderliche Schutzmaßnahmen aus oder lässt Verantwortlichkeiten ungeklärt und liefert dadurch Software mit unbehandelten Schwächen oder legt anvertraute Informationen offen.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-14','Die Systemarchitektur verhindert unbefugten Zugriff und begrenzt Angriffe (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Die Systemarchitektur wird so entworfen, dass sie unbefugten Zugriff verhindert und Angriffe begrenzt. Wenden Sie Prinzipien sicherer Systementwicklung an, wenn Sie entscheiden, wie Komponenten miteinander verbunden werden, wo sensible Daten liegen und wie Zugriffe Systemgrenzen überschreiten. Beispielsweise ist eine Datenbank mit Patientenakten nur über autorisierte Anwendungspfade erreichbar, nicht direkt aus dem Internet. Dokumentieren Sie Entwurfsentscheidungen und bewerten und behandeln Sie wesentliche Abweichungen von den Prinzipien. Diese Kontrolle bewertet die Sicherheit der Architektur, nicht die Art, wie einzelne Codefunktionen geschrieben werden.','Wenn Entwicklung im Anwendungsbereich liegt, zählen zu den Beispielen Architekturentscheidungen, die sichere Komponentenverbindungen, die Ablage sensibler Daten und kontrollierte Zugriffe über Vertrauensgrenzen hinweg zeigen, mit Bewertung und Behandlung wesentlicher Abweichungen von Prinzipien sicherer Systementwicklung.','Eine unsichere Systemarchitektur macht sensible Komponenten angreifbar oder erlaubt einem Angreifer, Vertrauensgrenzen zu überschreiten und weitere Funktionen zu kompromittieren.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-16','Änderungen an Entwicklungsrepositories sind autorisiert, nachvollziehbar und geschützt (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Zugriffs- und Änderungsberechtigungen für Entwicklungsrepositories beschränken Codeänderungen auf autorisierte Personen und Prozesse, mit nachvollziehbaren Änderungen und angemessenem Schutz releaserelevanter Branches.','Wenn Entwicklung im Anwendungsbereich liegt, zählen zu den Beispielen Repository-Berechtigungen, Änderungshistorien und der Schutz releaserelevanter Branches, mit Prüfungen, dass nur autorisierte Personen und Prozesse Code ändern können.','Unbefugte Änderungen an Quellcode oder Release-Branches gelangen in ein vertrauenswürdiges Release, führen schädliches Verhalten ein oder deaktivieren Schutzmaßnahmen.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-18','Geheime Informationen für Entwicklung, Build und Bereitstellung werden geschützt (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Zugangsdaten, Tokens und geheime Signierinformationen, die für Entwicklung, Build oder Bereitstellung verwendet werden, werden so gespeichert und zugänglich gemacht, dass nur autorisierte Nutzende und Prozesse Zugriff erhalten; bei Ungültigkeit oder Kompromittierungsverdacht werden sie angemessen behandelt.','Wenn Entwicklung im Anwendungsbereich liegt, zählen zu den Beispielen geschwärzte Einstellungen zu Speicherung, Zugriff und Zugänglichmachung geheimer Informationen für Entwicklung, Build und Bereitstellung sowie Metadaten, die den angemessenen Umgang mit ungültigen oder mutmaßlich kompromittierten geheimen Informationen zeigen. Nutzen Sie synthetische Demonstrationen, soweit hilfreich; erheben Sie niemals aktuell gültige Zugangsdaten, Tokens oder geheime Signierinformationen.','Offengelegte geheime Informationen für Entwicklung, Bereitstellung oder Signierung ermöglichen einem Angreifer, sich als vertrauenswürdige Automatisierung auszugeben, auf Systeme zuzugreifen oder scheinbar authentische schädliche Releases zu verbreiten.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-15','Software wird nach sicheren Programmierpraktiken entwickelt (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Software wird nach sicheren Programmierpraktiken entwickelt. Wenden Sie Programmierregeln an, die relevante Schwachstellen verhindern, beispielsweise die Prüfung von Zugriffsrechten für jede angeforderte Patientenakte und die Verwendung parametrisierter Datenbankabfragen zur Verhinderung von SQL-Injection. Identifizieren Sie Verstöße durch Code-Reviews oder Analysen und beheben Sie wesentliche Schwächen vor der Freigabe; noch offene Feststellungen bedürfen einer begründeten Behandlungs- und Freigabeentscheidung. Diese Kontrolle bewertet, wie Softwarefunktionen implementiert werden, nicht die gesamte Systemarchitektur.','Wenn Entwicklung im Anwendungsbereich liegt, zählen zu den Beispielen anwendbare Programmierregeln, repräsentative Ergebnisse von Code-Reviews oder Analysen und vor der Freigabe behobene wesentliche Schwächen, mit begründeten Behandlungs- und Freigabeentscheidungen zu noch offenen Feststellungen.','R1: Ein Angreifer nutzt Programmierfehler aus, um Daten unbefugt zu lesen oder zu verändern. R2: Softwarefehler verursachen auch ohne Angriff eine fehlerhafte Verarbeitung oder einen Dienstausfall.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-17','Build- und Bereitstellungsprozesse verhindern unbefugte Änderungen (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Build- und Bereitstellungsprozesse verhindern unbefugte Änderungen an Pipeline-Konfiguration, Build-Eingaben und Release-Aktionen, mit den Entwicklungsrisiken angemessenen Berechtigungen und Ausführungsaufzeichnungen.','Wenn Entwicklung im Anwendungsbereich liegt, zählen zu den Beispielen Berechtigungen für Pipelines und Build-Eingaben, Änderungsschutz und Ausführungsaufzeichnungen, die zeigen, dass Konfigurationsänderungen und Release-Aktionen autorisiert sind, im angemessenen Verhältnis zu den Entwicklungsrisiken.','Ein Angreifer verändert Build-Eingaben, Pipeline-Konfigurationen oder Bereitstellungsaktionen, um ein kompromittiertes Release zu verbreiten oder die Produktionsumgebung unbefugt zu verändern.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-20','Die Auswahl von Testdaten berücksichtigt Zweck, Sensibilität und Erforderlichkeit (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Testdatensätze werden für den Testzweck ausgewählt und vor ihrer Verwendung auf Sensibilität und Erforderlichkeit bewertet, wobei die unnötige Verwendung sensibler Echtdaten vermieden wird.','Wenn Entwicklung im Anwendungsbereich liegt, zählen zu den Beispielen vor der Verwendung getroffene Entscheidungen zur Auswahl von Testdatensätzen, die den Zweck mit Sensibilität und Erforderlichkeit verknüpfen und zeigen, warum etwaige sensible Echtdaten benötigt werden. Prüfen Sie Beschreibungen oder geschützte Stichproben, statt Echtdatensätze zu exportieren.','R1: Nicht benötigte sensible Echtdaten werden in Testumgebungen kopiert, wodurch bei unsachgemäßem Zugriff auf die Testumgebung oder deren unsachgemäßer Freigabe mehr Personen und Datensätze gefährdet sind. R2: Nicht repräsentative Testdaten lassen relevante Formate, Beziehungen oder Randbedingungen aus, sodass Fehler, die den tatsächlichen Betrieb beeinträchtigen, die Tests unentdeckt passieren.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-22','Risikogerecht begründete Bereinigung und Anonymisierung von Testdaten werden vor der Verwendung überprüft (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Testdaten werden der durch die Risikobewertung gerechtfertigten Bereinigung und Anonymisierung unterzogen; die resultierenden Daten werden vor der Verwendung geprüft, um den behaupteten Schutz zu bestätigen.','Wenn Entwicklung im Anwendungsbereich liegt, zählen zu den Beispielen die risikobasierte Entscheidung über Bereinigung beziehungsweise Anonymisierung und Validierungsergebnisse vor der Verwendung, die den behaupteten Schutz der resultierenden Testdaten belegen. Verwenden Sie kontrollierte Stichproben und leiten Sie Anonymität nicht allein aus Pseudonymisierung ab.','Als bereinigt oder anonymisiert bezeichnete Daten enthalten weiterhin identifizierbare oder wiederherstellbare sensible Werte, was zu einer Offenlegung führt, wenn sie als sichere Testdaten behandelt werden.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-21','Testdaten werden über ihren gesamten Lebenszyklus geschützt (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Testdaten werden bei Speicherung, Zugriff, Übertragung und Entsorgung durchgehend geschützt, wobei der Zugriff auf die relevanten Testbeteiligten beschränkt und die Aufbewahrung dem Testbedarf angemessen ist.','Wenn Entwicklung im Anwendungsbereich liegt, zählen zu den Beispielen Schutzmaßnahmen für Zugriff, Speicherung, Übertragung und Entsorgung von Testdaten, abgeglichen mit den tatsächlichen Berechtigungen der Beteiligten und dem Testbedarf, mit repräsentativen Aufzeichnungen oder Prüfungen zu Aufbewahrung und Entsorgung.','Nicht autorisierte Testbeteiligte oder spätere Empfänger erhalten sensible Testdaten während der Speicherung oder Übertragung oder nachdem der Testbedarf entfallen ist.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-19','Risikogerechte Sicherheitstests werden während der Entwicklung und vor der Release-Abnahme durchgeführt (Gilt nur für relevante interne oder beauftragte Entwicklungsaktivitäten; der Kauf und die Nutzung eines unveränderten Standardprodukts allein aktivieren diese Gruppe nicht.)','Relevante Sicherheitstests werden während der Entwicklung und vor der Release-Abnahme in einem den Systemrisiken angemessenen Umfang und mit einer entsprechenden Methode durchgeführt; ihre Ergebnisse benennen die getestete Version und die Feststellungen.','Wenn Entwicklung im Anwendungsbereich liegt, zählen zu den Beispielen ein risikogerechter Umfang und risikogerechte Methoden für Sicherheitstests sowie aufbewahrte Ergebnisse aus der Entwicklung und aus Tests vor der Release-Abnahme, die die getestete Version und die Feststellungen benennen.','Sicherheitsmängel bleiben bis nach der Freigabe unentdeckt, weil Tests relevante Angriffswege nicht abdecken oder sich die Feststellungen auf eine andere Version beziehen.','E-DEV · Interne und beauftragte Entwicklung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-06','Geplante Änderungen werden vor der Umsetzung auf ihre Auswirkungen auf Sicherheit und Dienste bewertet','Bevor eine geplante Änderung umgesetzt wird, werden ihre möglichen Auswirkungen auf Sicherheit und Dienste unter Berücksichtigung der relevanten Abhängigkeiten und Risiken bewertet und die erforderlichen Schutzmaßnahmen bestimmt.','Beispiele: vor geplanten Änderungen abgeschlossene Bewertungen, die betroffene Abhängigkeiten, mögliche Auswirkungen auf Sicherheit und Dienste, relevante Risiken und erforderliche Schutzmaßnahmen benennen und der vorgeschlagenen Änderung zugeordnet sind.','Eine Änderung schwächt unerwartet eine Sicherheitsgrenze oder beeinträchtigt einen abhängigen Dienst, weil ihre Auswirkungen nicht bewertet wurden.','E-CHG · Änderungen im Betrieb','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('CHG-ROLLBACK','Für fehlgeschlagene Änderungen ist ein Verfahren zur Rücknahme oder Wiederherstellung festgelegt','Für fehlgeschlagene Änderungen ist ein Verfahren zur Rücknahme oder Wiederherstellung festgelegt. Bestimmen Sie vor der Umsetzung einer Änderung, wie bei einem Fehlschlag der sichere Betrieb wiederhergestellt wird. Benennen Sie die erforderlichen vorherigen Konfigurationen, Sicherungskopien oder sonstigen Wiederherstellungsressourcen, die verantwortlichen Personen und die Bedingungen für den Beginn der Wiederherstellung. Bestätigen Sie, dass die benötigten Ressourcen nutzbar sind und das Verfahren dem Risiko der Änderung angemessen ist. Wenn eine Rücknahme unmöglich ist, legen Sie ein alternatives Wiederherstellungsverfahren fest, statt anzunehmen, dass jede Änderung rückgängig gemacht werden kann.','Änderungsspezifische Anweisungen zur Rücknahme oder alternativen Wiederherstellung; Verantwortlichkeiten und Auslösekriterien; nutzbare Konfigurationskopien oder Sicherungskopien; relevante, dem Risiko angemessene Validierungs- oder Testergebnisse.','Eine fehlgeschlagene Änderung kann weder rückgängig gemacht noch auf andere Weise sicher behoben werden, wodurch die Dienstunterbrechung verlängert wird oder beschädigte Daten und Konfigurationen weiterverwendet werden.','E-CHG · Änderungen im Betrieb','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-07','Geplante betriebliche Änderungen werden vor der Umsetzung risikogerecht getestet','Geplante betriebliche Änderungen werden vor ihrer Umsetzung in einem durch ihre Risiken begründeten Umfang getestet. Die aufgezeichneten Ergebnisse unterstützen die Entscheidung, die Änderung umzusetzen oder zu überarbeiten.','Beispiele: ein durch die Risiken der geplanten Änderung begründeter Testumfang vor der Umsetzung, aufgezeichnete Ergebnisse und die daraus abgeleitete Entscheidung, die Änderung umzusetzen oder zu überarbeiten.','Eine fehlerhafte oder inkompatible betriebliche Änderung gelangt in die Produktion und unterbricht Dienste oder setzt eine erforderliche Schutzmaßnahme außer Kraft.','E-CHG · Änderungen im Betrieb','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('CHG-AUTH','Änderungen werden vor ihrer Umsetzung autorisiert','Änderungen werden vor ihrer Umsetzung autorisiert. Holen Sie vor der Umsetzung einer geplanten betrieblichen Änderung die Genehmigung einer dazu befugten Person ein. Die Genehmigung bezeichnet die Änderung, ihren zulässigen Umfang und die entscheidende Person und berücksichtigt die Folgenabschätzung sowie relevante Testergebnisse. Wenn ein Notfall den regulären Ablauf verhindert, nutzen Sie das festgelegte Verfahren zur Notfallautorisierung und dokumentieren Sie jede ausnahmsweise Abweichung sowie die anschließende Überprüfung.','Änderungsantrag; benannte genehmigungsbefugte Person oder Stelle; Genehmigungszeitpunkt vor der geplanten Umsetzung; Abgleich des genehmigten Umfangs mit den Ausführungsaufzeichnungen; gegebenenfalls Aufzeichnungen zur Notfallautorisierung oder zur Ausnahme und ihrer Überprüfung.','Eine nicht autorisierte Änderung umgeht nachvollziehbar verantwortete Risikoentscheidungen und führt zu einem unsicheren oder störenden Zustand der Produktionsumgebung.','E-CHG · Änderungen im Betrieb','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-05','Sicherheitsrelevante Änderungen und ihre Ergebnisse werden aufgezeichnet','Sicherheitsrelevante Änderungen an Software, Hardware und Konfigurationen werden mit ihrem Umfang, der verantwortlichen Person, dem Zeitpunkt und dem Umsetzungsergebnis aufgezeichnet, damit sich der geänderte Zustand rekonstruieren lässt.','Beispiele: Änderungshistorien für Software, Hardware und Konfigurationen mit Angaben zu Umfang, verantwortlicher Person, Zeitpunkt und Umsetzungsergebnis, die eine Rekonstruktion des geänderten Zustands ermöglichen.','Untersuchende oder Betriebsverantwortliche können einen geänderten Systemzustand nicht rekonstruieren, wodurch Fehlerdiagnose, Ermittlung des Vorfallsumfangs oder Wiederherstellung verzögert werden.','E-CHG · Änderungen im Betrieb','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-24','Aufzeichnungen zu Notfalländerungen erläutern Maßnahmen, Ergebnisse und Verfahrensabweichungen','Wenn ein Notfall die Einhaltung des regulären Änderungsverfahrens verhindert, dokumentiert die Änderungsaufzeichnung, was getan wurde, welches Ergebnis erzielt wurde und warum die regulären Schritte nicht eingehalten werden konnten.','Wenn ein Notfall die regulären Änderungsschritte verhindert, gehören zu den Beispielen Änderungsaufzeichnungen, aus denen die durchgeführten Maßnahmen, ihr Ergebnis und die Gründe hervorgehen, weshalb die regulären Schritte nicht eingehalten werden konnten.','Eine Notfalländerung hinterlässt einen undokumentierten unsicheren Zustand, den spätere Betriebsverantwortliche nicht zuverlässig bewerten oder rückgängig machen können.','E-CHG · Änderungen im Betrieb','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('D04-08','Schwachstellenmeldungen und Sicherheitshinweise werden verfolgt und die Offenlegung bei Bedarf koordiniert','Schwachstellenmeldungen und Sicherheitshinweise werden verfolgt und die Offenlegung wird bei Bedarf koordiniert. Stellen Sie einen nutzbaren Kontakt für Meldungen über Schwachstellen in den Systemen oder Produkten der Einrichtung bereit. Verfolgen Sie aktiv relevante Informationskanäle von Lieferanten und Behörden sowie von Teams für die Reaktion auf IT-Sicherheitsvorfälle (Computer Security Incident Response Team, CSIRT) und überprüfen Sie, ob diese Quellen weiterhin relevant sind. Erfassen Sie eingegangene Meldungen sowie handlungsrelevante Hinweise zu Bedrohungen oder Schwachstellen und leiten Sie diese an eine zuständige Stelle für Bewertung oder Reaktion weiter. Soweit eine koordinierte Offenlegung relevant ist, stimmen Sie die Bearbeitung sowie Zeitpunkt und Inhalt der Offenlegung mit betroffenen Lieferanten, meldenden Personen und weiteren geeigneten Beteiligten ab. Nutzen Sie hierfür ein festgelegtes Verfahren, das mit den anwendbaren Richtlinien zur koordinierten Offenlegung vereinbar ist. Der bloße Eingang von Meldungen erfüllt nicht die Anforderung, Sicherheitshinweise aktiv zu verfolgen; nicht jede Schwachstelle erfordert eine öffentliche Offenlegung.','Funktionsfähiger Meldekontakt; eingegangene Meldungen und Zuordnung der Bearbeitung; relevante Quellen für Sicherheitshinweise und regelmäßige Prüfungen ihrer Relevanz; Nachweise über die aktive Verfolgung und die Weiterleitung handlungsrelevanter Hinweise zur Bewertung oder Reaktion; Korrespondenz und Entscheidungen zur koordinierten Bearbeitung und Offenlegung, soweit relevant. Das bloße Ausbleiben einer öffentlichen Offenlegung ist kein Mangel, wenn eine Offenlegung nicht relevant ist.','R1: Handlungsrelevante Meldungen oder Sicherheitshinweise gelangen nicht zur Bewertung, sodass eine bekannte Schwachstelle vor ihrer Behandlung ausgenutzt werden kann. R2: Eine schlecht koordinierte Offenlegung gefährdet betroffene Nutzende, bevor Schutzmaßnahmen bereitstehen, oder verzögert Informationen, die sie zu ihrem Schutz benötigen.','E-VUL · Schwachstellenmanagement','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('D04-25','Schwachstellenscans und -prüfungen sind risikogerecht und betriebssicher','Zur Identifikation von Schwachstellen werden risikogerechte Scans oder Prüfungen im erforderlichen Systemumfang eingesetzt, gegebenenfalls in geplanten Intervallen und mit aufbewahrten Ergebnissen; die Methoden sind für betriebliche Systeme, OT-Systeme und klinische Systeme sicher.','Beispiele: risikogerechter Umfang von Schwachstellenscans oder -prüfungen, gegebenenfalls geplante Intervalle und aufbewahrte Ergebnisse, die die erforderliche Systemabdeckung belegen, mit Methoden und Vorsichtsmaßnahmen, die für betriebliche, OT- oder klinische Systeme geeignet sind, sofern solche Systeme vorhanden sind.','R1: Unentdeckte Schwachstellen bleiben auf Systemen ausnutzbar, die von Scans und Prüfungen ausgeschlossen oder unzureichend erfasst wurden. R2: Eine unsichere Tätigkeit zur Schwachstellenidentifikation stört ein sensibles betriebliches, klinisches oder OT-System.','E-VUL · Schwachstellenmanagement','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('D04-26','Schwachstellen werden mit den tatsächlichen Produkten, Konfigurationen und der Exposition abgeglichen','Identifizierte oder gemeldete Schwachstellen werden mit den tatsächlichen Produkten, Versionen, Konfigurationen und der Exposition der Einrichtung abgeglichen, damit betroffene und nicht betroffene Systeme begründet unterschieden werden können.','Beispiele: Schwachstellenbewertungen mit Bezug zu den tatsächlichen Produkten, Versionen, Konfigurationen und zur Exposition sowie begründete Entscheidungen für repräsentative Systeme, ob diese betroffen oder nicht betroffen sind.','R1: Ein betroffenes System wird fälschlich als nicht betroffen eingestuft, sodass eine ausnutzbare Schwachstelle unbehandelt bleibt. R2: Ein nicht betroffenes System wird unnötigen, störenden Behebungsmaßnahmen unterzogen, weil Angaben zu Produkt, Version oder Exposition falsch interpretiert werden.','E-VUL · Schwachstellenmanagement','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('D04-27','Prioritäten der Schwachstellenbehandlung berücksichtigen betriebliche Auswirkungen, Exposition und bestehende Schutzmaßnahmen','Die Prioritäten der Schwachstellenbehandlung berücksichtigen die betrieblichen Auswirkungen, die Exposition und die bestehenden Schutzmaßnahmen der Einrichtung. Sie kennzeichnen betriebskritische Schwachstellen, damit diese ohne unangemessene Verzögerung behandelt werden, soweit die CIR gilt.','Beispiele: Behandlungsprioritäten mit Bezug zu betrieblichen Auswirkungen, Exposition und bestehenden Schutzmaßnahmen, die betriebskritische Schwachstellen kennzeichnen und deren Weiterleitung zur Behandlung ohne unangemessene Verzögerung zeigen, soweit die CIR gilt.','Ressourcen werden auf weniger folgenreiche Schwachstellen gelenkt, während exponierte, betrieblich wichtige Schwachstellen für Angreifende weiterhin ausnutzbar bleiben.','E-VUL · Schwachstellenmanagement','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('D04-28','Schwachstellen werden innerhalb angemessener Zeiträume behoben','Schwachstellen werden innerhalb angemessener Zeiträume behoben. Weisen Sie jeder erforderlichen Behebungsmaßnahme eine verantwortliche Person und einen risikobasierten Zieltermin zu. Setzen Sie Patches oder andere Behandlungsmaßnahmen über das festgelegte Änderungsverfahren um und erfassen Sie die betroffenen Systeme sowie das Umsetzungsergebnis. Führen Sie die Behandlung entsprechend der begründeten Priorität und Zeitplanung durch, einschließlich durch die Auswirkungen begründeter Pläne zur Risikominderung und der anwendbaren CIR-Anforderungen an die zügige Behandlung kritischer Schwachstellen und das rechtzeitige Einspielen von Patches. Ein interner Zieltermin setzt eine anwendbare gesetzliche Zeitvorgabe nicht außer Kraft.','Beispiele: erforderliche Behebungsmaßnahmen mit verantwortlichen Personen und begründeten risikobasierten Zielterminen, verknüpft mit Änderungsaufzeichnungen, betroffenen Systemen und tatsächlichen Umsetzungsergebnissen. Vergleichen Sie Priorität und verstrichene Zeit mit den anwendbaren Anforderungen an eine zügige Behandlung und das Einspielen von Patches, einschließlich durch die Auswirkungen begründeter Pläne zur Risikominderung, soweit relevant, sowie des Umgangs mit Verzögerungen.','Angreifende nutzen eine bekannte Schwachstelle aus, während die erforderliche Behebung verzögert, aufgegeben oder lediglich als abgeschlossen dokumentiert wird, ohne tatsächlich umgesetzt worden zu sein.','E-VUL · Schwachstellenmanagement','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('D04-31','Kompensierende Schutzmaßnahmen schützen Systeme mit nicht gepatchten Schwachstellen','Kompensierende Schutzmaßnahmen schützen Systeme mit nicht gepatchten Schwachstellen. Wenn ein Patch nicht verfügbar ist oder nicht eingespielt wird, implementieren und erhalten Sie alternative, für die Schwachstelle geeignete Schutzmaßnahmen, etwa Zugriffsbeschränkungen, die Isolation des betroffenen Systems oder die Deaktivierung der verwundbaren Funktion. Stützen Sie Entscheidungen über Restrisiken auf die tatsächlich im Einsatz befindlichen Schutzmaßnahmen und nicht lediglich auf geplante Maßnahmen; diese Schutzmaßnahmen heben anwendbare Behebungspflichten nicht auf.','Bei nicht gepatchten Schwachstellen gehören zu den Beispielen implementierte alternative Schutzmaßnahmen, die den betroffenen Angriffspfaden zugeordnet sind, mit aktuellen Konfigurations- und Betriebsprüfungen sowie Restrisikoentscheidungen, die auf diesen tatsächlich betriebenen Schutzmaßnahmen beruhen.','Angreifende erreichen eine nicht gepatchte verwundbare Funktion und nutzen sie aus, weil die angenommenen kompensierenden Schutzmaßnahmen den Angriffspfad tatsächlich nicht beschränken.','E-VUL · Schwachstellenmanagement','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('D04-30','Entscheidungen gegen die Behebung von Schwachstellen werden begründet und rechenschaftspflichtigen Verantwortlichen zugeordnet','Entscheidungen, eine Schwachstelle nicht zu beheben oder nicht zu patchen, werden inhaltlich begründet, einer rechenschaftspflichtigen verantwortlichen Person zugeordnet und, soweit erforderlich, durch eine autorisierte Restrisikoakzeptanz gestützt; eine Akzeptanz setzt keine verbindliche Pflicht außer Kraft.','Beispiele: inhaltlich begründete Entscheidungen, nicht zu patchen oder auf andere Weise zu beheben, mit Angabe der betroffenen Schwachstellen, Gründe und rechenschaftspflichtigen Verantwortlichen, gegebenenfalls mit autorisierter Restrisikoakzeptanz und unter Berücksichtigung anwendbarer verbindlicher Pflichten.','Eine Schwachstelle bleibt aufgrund einer unzureichend informierten oder nicht autorisierten Ausnahme exponiert, und ihre Behandlung wird länger aufgeschoben, als es die rechenschaftspflichtigen Verantwortlichen beabsichtigt hatten.','E-VUL · Schwachstellenmanagement','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('D04-32','Schwachstellenausnahmen werden bei Fälligkeit oder veränderten Bedingungen neu bewertet','Schwachstellenausnahmen haben ein begründetes Ablauf- oder Überprüfungsdatum und werden bei Fälligkeit oder bei Änderungen relevanter Bedingungen neu bewertet, einschließlich der Verfügbarkeit von Patches, der Exposition oder der Wirksamkeit vorläufiger Schutzmaßnahmen.','Beispiele: Schwachstellenausnahmen mit begründeten Ablauf- oder Überprüfungsdaten und abgeschlossenen Neubewertungen bei Fälligkeit oder bei Änderungen relevanter Bedingungen, unter Einbeziehung der Patch-Verfügbarkeit, der Exposition und der Wirksamkeit vorläufiger Schutzmaßnahmen.','Eine Ausnahme bleibt bestehen, obwohl ihre Begründung durch veränderte Exposition, Patch-Verfügbarkeit oder Schutzmaßnahmen entfallen ist, sodass ein zunehmend ausnutzbares System unbehandelt bleibt.','E-VUL · Schwachstellenmanagement','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('D04-35','Sicherheitspatches stammen aus verifizierten oder vertrauenswürdigen Quellen','Sicherheitspatches werden über verifizierte Vertriebskanäle des Lieferanten oder andere vertrauenswürdige Vertriebskanäle bezogen. Die Herkunft des Pakets ist vor der Installation nachvollziehbar.','Beispiele: Angaben zu verifizierten Vertriebskanälen des Lieferanten oder anderen vertrauenswürdigen Vertriebskanälen sowie Bezugs- und Herkunftsaufzeichnungen für Patches, aus denen hervorgeht, dass die Paketherkunft vor der Installation nachvollziehbar war.','Ein gefälschtes Update aus einer nicht vertrauenswürdigen Quelle installiert Schadcode mit den Berechtigungen des Aktualisierungsprozesses.','E-PAT · Sicherheitsupdates','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('D04-36','Die Integrität von Sicherheitspatches wird vor der Installation überprüft','Die Integrität von Sicherheitspatches wird vor der Installation mit einem vertrauenswürdigen Prüfmechanismus überprüft. Pakete, deren Prüfung fehlschlägt oder die nicht überprüfbar sind, werden nicht als validierte Updates akzeptiert.','Beispiele: Ergebnisse vertrauenswürdiger Signatur-, Hash- oder gleichwertiger Integritätsprüfungen vor der Installation sowie Aufzeichnungen oder sichere Tests, die zeigen, dass Pakete mit fehlgeschlagener Prüfung oder nicht überprüfbare Pakete nicht als validierte Updates akzeptiert werden.','Ein verändertes oder beschädigtes Update-Paket wird als legitim installiert und führt schädliche Änderungen ein oder beeinträchtigt das Zielsystem.','E-PAT · Sicherheitsupdates','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('D04-34','Sicherheitspatches werden vor dem Einsatz in der Produktion getestet','Sicherheitspatches werden vor der Anwendung in der Produktion mit einer für das betroffene System geeigneten Methode getestet. Die aufgezeichneten Ergebnisse unterstützen die Entscheidung über den Einsatz.','Beispiele: für die betroffenen Systeme geeignete Patch-Testmethoden vor dem Produktionseinsatz, aufbewahrte Ergebnisse und deren Verknüpfung mit der Entscheidung über den Einsatz.','Ein inkompatibler oder fehlerhafter Sicherheitspatch unterbricht die Produktion oder beeinträchtigt eine erforderliche Sicherheitsfunktion.','E-PAT · Sicherheitsupdates','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('MON-RISK','Der Überwachungsbedarf wird durch eine Risikobewertung bestimmt','Der Überwachungsbedarf wird durch eine Risikobewertung bestimmt. Bewerten Sie die Systeme, Dienste, relevanten Bedrohungen, die Exposition und die möglichen Auswirkungen auf Dienste, um den erforderlichen Umfang der Sicherheitsüberwachung zu bestimmen. Halten Sie fest, welche Systeme und Ereignisse überwacht werden müssen, welche Erkennungsabdeckung, Überwachungshäufigkeit und welcher Automatisierungsgrad erforderlich sind und welche Fähigkeiten Werkzeuge oder Dienste bereitstellen müssen. Vorhandene Risikobewertungsaufzeichnungen können verwendet werden, wenn sie diese Überwachungsentscheidungen ausdrücklich stützen; ein gesonderter Risikobericht ist nicht erforderlich. Diese Kontrolle bewertet die begründeten Überwachungsanforderungen, nicht deren Umsetzung.','Risikobewertung mit Benennung relevanter Bedrohungen und Auswirkungen auf Dienste; nachvollziehbare Zuordnung zu überwachten Systemen und Ereignissen, Erkennungsbedarf, Überwachungshäufigkeit sowie Entscheidungen zu Automatisierung und Werkzeugfähigkeiten. Vorhandene Risikoaufzeichnungen sind zulässig, wenn dieser Zusammenhang ausdrücklich erkennbar ist.','Die Überwachungsanforderungen übersehen ein relevantes System oder einen Angriffspfad, sodass eine Kompromittierung in einem nicht überwachten Bereich fortbestehen kann.','B-DET · Betriebliche Überwachung und Erkennung','Protokollierung & Detektion','Logging & detection'),
  ('MON-BASE','Normales Systemverhalten und Alarmschwellen sind festgelegt','Normales Systemverhalten und Alarmschwellen sind festgelegt. Bestimmen Sie für überwachte Systeme relevante normale Betriebsmuster und begründete Alarmkriterien auf Grundlage ihres Zwecks und der bewerteten Risiken. Konfigurieren Sie geeignete Schwellenwerte oder andere Erkennungsbedingungen und berücksichtigen Sie dabei legitime Schwankungen und Änderungen. Dokumentieren Sie, warum eine Abweichung eine Untersuchung rechtfertigt; nicht jede Erkennungsregel erfordert eine statistische Referenzbasis oder einen numerischen Schwellenwert. Diese Kontrolle bewertet die Referenzmuster und Alarmkriterien, nicht die Risikobewertung oder die Prüfung der Erkennungswirksamkeit.','Dokumentierte normale Betriebsmuster und begründete Alarmbedingungen; konfigurierte Schwellenwerte oder Regeln, legitime Ausnahmen und relevante Änderungsaufzeichnungen.','R1: Erkennungskriterien stufen schädliche Abweichungen als normal ein und verzögern dadurch Untersuchungen. R2: Übermäßige oder irreführende Alarme binden die Aufmerksamkeit der Analysierenden und verdecken bedeutsame Ereignisse.','B-DET · Betriebliche Überwachung und Erkennung','Protokollierung & Detektion','Logging & detection'),
  ('D02-01','Die Überwachung wird entsprechend der Risikobewertung umgesetzt','Die Überwachung wird entsprechend der Risikobewertung umgesetzt. Konfigurieren und betreiben Sie die Überwachung so, dass sie die unter MON-RISK festgelegten Anforderungen erfüllt und die ausgewählten Systeme, Ereignisse, Erkennungsbedarfe und Häufigkeiten abdeckt. Weisen Sie nach, dass die gewählten Werkzeuge oder Dienste nutzbare Informationen zur Erkennung und Untersuchung vermuteter Sicherheitsvorfälle liefern. Erfassen und behandeln Sie Lücken zwischen dem bewerteten Bedarf und der tatsächlichen Abdeckung. Weder ein bestimmtes SIEM noch ein anderes namentlich benanntes Produkt ist generell erforderlich; anwendbare CIR-Pflichten, einschließlich der Automatisierung im machbaren Umfang, gelten weiterhin. Diese Kontrolle bewertet den tatsächlichen Betrieb, nicht allein das Vorliegen einer Risikobewertung.','Betriebskonfigurationen, Abdeckungsaufzeichnungen und Überwachungsergebnisse, die die Umsetzung der bewerteten Anforderungen nachweisen; dokumentierte Abdeckungslücken und Maßnahmen. Eine erworbene Lizenz oder ein genehmigter Plan allein belegt keinen Betrieb.','Ein Angriff bleibt unentdeckt, weil die erforderliche Überwachungsabdeckung nicht in Betrieb ist oder keine nutzbaren Informationen liefert.','B-DET · Betriebliche Überwachung und Erkennung','Protokollierung & Detektion','Logging & detection'),
  ('C44.6','Systemuhren werden mit freigegebenen Zeitquellen synchronisiert','Systemuhren werden mit freigegebenen Zeitquellen synchronisiert. Verwenden Sie für relevante Systeme geeignete freigegebene Zeitquellen, prüfen Sie Uhrabweichungen und korrigieren Sie Abweichungen, die die Ereigniskorrelation beeinträchtigen könnten. Beschränken Sie Änderungen an Zeiteinstellungen und überwachen Sie relevante Änderungen der Zeitquellenkonfiguration. Weisen Sie konsistente Ereigniszeitstempel über Systemgrenzen hinweg nach; weder ein bestimmtes Zeitprotokoll noch ein eigener Server ist generell erforderlich.','Freigegebene Zeitquellen, Synchronisierungseinstellungen, Prüfungen auf Uhrabweichungen, geschützte Konfigurationen und Änderungsaufzeichnungen sowie korrelierte Zeitstempel aus relevanten Systemen.','R1: Inkonsistente oder manipulierte Zeitstempel ergeben einen falschen Vorfallsablauf und schwächen dadurch Korrelation, Zuordnung und Zuverlässigkeit der Nachweise. R2: Uhrabweichungen führen dazu, dass zeitabhängige Authentisierungs- oder Zertifikatsprüfungen gültige Zugriffe zurückweisen und damit Dienste unterbrechen, die von diesen Prüfungen abhängen.','B-LOG · Protokollierung und Überwachung','Protokollierung & Detektion','Logging & detection'),
  ('LOG-RET-DEF','Aufbewahrungszeiträume für Sicherheitsprotokolle sind festgelegt und begründet','Aufbewahrungszeiträume für Sicherheitsprotokolle sind festgelegt und begründet. Bestimmen und dokumentieren Sie auf Grundlage des Untersuchungsbedarfs, der bewerteten Risiken und der anwendbaren Anforderungen, wie lange jede relevante Kategorie von Sicherheitsprotokollen aufbewahrt werden muss. Benennen Sie gegebenenfalls unterschiedliche Zeiträume für unmittelbar durchsuchbare und archivierte Aufzeichnungen sowie die verantwortliche Person. Begründen Sie die gewählten Zeiträume, statt eine willkürliche allgemeingültige Dauer zu übernehmen. Diese Kontrolle bewertet die Aufbewahrungsentscheidung, nicht die Speicherkonfiguration oder die tatsächlich aufbewahrten Aufzeichnungen.','Dokumentierte Aufbewahrungszeiträume je relevanter Protokollkategorie; Begründung mit Bezug zum Untersuchungsbedarf, zu Risiken und anwendbaren Anforderungen; verantwortliche Person und etwaige Unterschiede zwischen durchsuchbaren und archivierten Aufzeichnungen.','R1: Ein festgelegter Aufbewahrungszeitraum ist für den Untersuchungsbedarf zu kurz, sodass relevante Nachweise verschwinden, bevor ein Sicherheitsvorfall entdeckt wird. R2: Übermäßige Aufbewahrung setzt unnötige personenbezogene oder sensible Aufzeichnungen einer Gefährdung aus und schafft ungerechtfertigte Risiken bei der Datenverarbeitung.','B-LOG · Protokollierung und Überwachung','Protokollierung & Detektion','Logging & detection'),
  ('C44.1','Erforderliche Sicherheitsprotokollquellen liefern nutzbare Aufzeichnungen','Erforderliche Sicherheitsprotokollquellen liefern tatsächlich nutzbare Aufzeichnungen. Überprüfen Sie die Abdeckung und Aufzeichnungsqualität der erforderlichen Quellen; die Abdeckung privilegierter Aktivitäten und deren Überprüfung werden gesondert unter LOG-PRIV bewertet.','Liste der erforderlichen Quellen, Stichproben tatsächlich eingehender Protokolle, Prüfungen auf Vollständigkeit und Nutzbarkeit sowie Nachverfolgung von Erfassungslücken.','Fehlende oder unbrauchbare Ereignisaufzeichnungen verdecken relevante Aktivitäten und verhindern die Rekonstruktion eines Sicherheitsvorfalls auf den betroffenen Quellsystemen.','B-LOG · Protokollierung und Überwachung','Protokollierung & Detektion','Logging & detection'),
  ('C44.2','Sicherheitsprotokolle sind vor unbefugtem Zugriff und unbefugter Veränderung geschützt','Beschränken Sie, wer Sicherheitsprotokolle lesen oder ändern darf, und schützen Sie diese bei Speicherung und Übertragung vor unbefugter Veränderung, damit sich Untersuchende auf die aufbewahrten Aufzeichnungen verlassen können.','Zugriffsberechtigungen für Protokolle, Einstellungen zur geschützten Speicherung und Übertragung, Schutzmaßnahmen gegen Veränderungen sowie Zugriffs- oder Integritätsprüfungen.','R1: Angreifende verändern oder löschen Protokolle, um Aktivitäten zu verbergen und Untersuchende irrezuführen. R2: Unbefugter Zugriff auf Protokolle legt personenbezogene Daten, interne Infrastrukturdetails oder andere sensible betriebliche Informationen offen.','B-LOG · Protokollierung und Überwachung','Protokollierung & Detektion','Logging & detection'),
  ('C44.3','Sicherheitsprotokolle werden für die festgelegten Zeiträume aufbewahrt','Sicherheitsprotokolle werden für die festgelegten Zeiträume aufbewahrt. Konfigurieren Sie Speicherung, Rotation, Archivierung, Sicherung und Löschung von Protokollen so, dass die unter LOG-RET-DEF festgelegten Zeiträume umgesetzt werden. Sichern Sie Protokolle und überprüfen Sie, dass sich die gesicherten Aufzeichnungen abrufen lassen; redundante Protokollierung allein belegt keine wiederherstellbare Sicherungskopie. Prüfen Sie tatsächlich aufbewahrte Aufzeichnungen und deren Abruf und behandeln Sie vorzeitige Verluste oder eine Aufbewahrung, die nicht mit den festgelegten Zeiträumen und anwendbaren Anforderungen übereinstimmt. Ein dokumentierter Zeitraum allein belegt keine Umsetzung.','Wirksame Einstellungen für Speicherung, Rotation, Archivierung, Sicherung und Löschung; datierte Aufzeichnungen, die die Einhaltung der festgelegten Zeiträume belegen; Abrufprüfungen einschließlich gesicherter Protokolle sowie Aufzeichnungen über Aufbewahrungsfehler oder Korrekturen.','R1: Rotation, Löschung oder Speicherfehler entfernen erforderliche Protokolle vor Ablauf des genehmigten Aufbewahrungszeitraums und verhindern dadurch Untersuchungen oder die Wiedergewinnung von Nachweisen. R2: Protokolle bleiben über ihren begründeten Aufbewahrungszeitraum hinaus zugänglich und setzen personenbezogene oder sensible Informationen unnötig einer Gefährdung aus.','B-LOG · Protokollierung und Überwachung','Protokollierung & Detektion','Logging & detection'),
  ('C44.4','Protokolle können für Untersuchungen abgerufen und korreliert werden','Rufen Sie Aufzeichnungen aus den relevanten Systemen und Zeiträumen ab und führen Sie diese zu einem nutzbaren zeitlichen Ereignisablauf zusammen. Die Speicherung von Protokollen reicht nicht aus, wenn sie sich während einer Untersuchung nicht auffinden, interpretieren oder korrelieren lassen.','Abruf- und Korrelationsprüfungen mit Aufzeichnungen aus relevanten Systemen und Zeiträumen; fallbezogene zeitliche Abläufe, die eine nutzbare Korrelation belegen.','Untersuchende können relevante Aufzeichnungen nicht systemübergreifend abrufen oder miteinander verknüpfen, wodurch sich die Ermittlung des Vorfallsumfangs verzögert und betroffene Vermögenswerte oder Aktivitäten unerkannt bleiben.','B-LOG · Protokollierung und Überwachung','Protokollierung & Detektion','Logging & detection'),
  ('LOG-PRIV','Privilegierte Aktivitäten werden protokolliert und überprüft','Privilegierte Aktivitäten werden protokolliert und überprüft. Erfassen Sie privilegierte Zugriffe und relevante administrative Aktionen mit ausreichenden Angaben, um Konto, Zeitpunkt, betroffenes System und Aktion zu identifizieren. Überprüfen Sie diese Aufzeichnungen auf Missbrauch oder verdächtige Aktivitäten und dokumentieren Sie Untersuchung und Folgemaßnahmen. Erfassen Sie administrative Aktivitäten über die Nutzung privilegierter Hilfsprogramme hinaus; eine automatisierte Überprüfung kann den Prozess unterstützen, aber auf Alarme muss angemessen reagiert werden.','Protokolle administrativer Zugriffe und Aktionen mit Konto, Zeitpunkt, Ziel und Aktion; Überprüfungsaufzeichnungen, untersuchte Ausnahmen und dokumentierte Folgemaßnahmen. Prüfen Sie die Abdeckung privilegierter Aktivitäten getrennt von der allgemeinen Protokollerfassung.','Der Missbrauch administrativer Berechtigungen bleibt unbemerkt und kann nicht zuverlässig zugeordnet werden, sodass unbefugte Änderungen oder Datenzugriffe fortgesetzt werden können.','B-LOG · Protokollierung und Überwachung','Protokollierung & Detektion','Logging & detection'),
  ('C44.5','Protokolle werden regelmäßig überprüft; auf Alarme wird rechtzeitig und fachkundig reagiert','Protokolle werden regelmäßig auf ungewöhnliche Trends überprüft, und auf Alarme wird rechtzeitig und fachkundig reagiert. Bewerten Sie hier den allgemeinen Überprüfungs- und Reaktionsprozess; bewerten Sie die Überprüfung privilegierter Aktivitäten unter LOG-PRIV und vermeiden Sie eine doppelte Erfassung desselben Befunds.','Überprüfungspläne, analysierte Trends, Alarmtickets, Zuweisung fachkundiger Reaktionsverantwortlicher und Reaktionszeitstempel; vermeiden Sie doppelte Befunde zur Überprüfung unter LOG-PRIV.','Bedeutsame Alarme oder ungewöhnliche Muster werden nicht zeitnah untersucht, sodass unbefugte Aktivitäten oder Schäden an Diensten fortbestehen können.','B-LOG · Protokollierung und Überwachung','Protokollierung & Detektion','Logging & detection'),
  ('C44.7','Überwachungs- und Protokollierungssysteme sind redundant ausgelegt','Stellen Sie redundante Überwachungs- und Protokollierungskomponenten oder entsprechende Vorkehrungen bereit, damit der Ausfall einer relevanten Komponente nicht zum Verlust der erforderlichen Überwachungs- und Aufzeichnungsfähigkeit führt; eine einzelne ungetestete Sicherungskopie belegt keine betriebsfähige Redundanz.','Redundante Überwachungs- und Protokollierungsarchitektur, Konfiguration und Ergebnisse von Failover-Tests, die relevante Ausfallszenarien abdecken.','Der Ausfall einer Überwachungs- oder Protokollierungskomponente erzeugt eine Sichtbarkeitslücke und führt zum Verlust von Ereignisaufzeichnungen, während die überwachten Dienste weiter genutzt werden.','B-LOG · Protokollierung und Überwachung','Protokollierung & Detektion','Logging & detection'),
  ('C44.8','Die Verfügbarkeit von Überwachung und Protokollierung wird unabhängig überwacht','Prüfen Sie die Verfügbarkeit von Überwachungs- und Protokollierungsdiensten unabhängig von den Systemen, deren Aktivitäten sie überwachen. Untersuchen Sie Abhängigkeiten und testen Sie die Ausfallerkennung; der normale Eingang von Protokollen allein belegt nicht, dass ein Ausfall des Überwachungs- oder Protokollierungsdienstes zuverlässig erkannt und gemeldet wird.','Unabhängige Verfügbarkeitsprüfungen, Überprüfung der Abhängigkeiten, Ausfallmeldungen und Tests, die die Erkennung bei Ausfall des überwachten Dienstes zeigen.','Der Ausfall des Überwachungs- oder Protokollierungsdienstes bleibt unbemerkt und führt zu einem längeren Zeitraum ohne Erkennung oder verlässliche Ereignisnachweise.','B-LOG · Protokollierung und Überwachung','Protokollierung & Detektion','Logging & detection'),
  ('D02-02','Erkennungsprüfungen identifizieren übersehene Ereignisse und irreführende Alarme','Die Erkennungsvorkehrungen werden anhand relevanter Szenarien mit bekannten Ereignissen und anhand unbedenklicher Aktivitäten überprüft. Ausgebliebene Erkennungen und irreführende Alarme werden untersucht; notwendige Anpassungen werden durch eine Wiederholungsprüfung verifiziert.','Testfälle mit bekannten Ereignissen und unbedenklichen Aktivitäten, Erkennungsergebnisse, ausgebliebene oder irreführende Alarme sowie Ergebnisse erneuter Tests nach der Korrektur.','Unbemerkte Erkennungslücken oder irreführende Regeln bleiben bestehen, weil Prüfungen anhand bekannter Ereignisse sie nicht aufdecken und die Korrekturen nicht verifizieren. Dadurch entsteht ein falsches Vertrauen in die Überwachung.','B-DET-TEST · Prüfung der Erkennungswirksamkeit','Protokollierung & Detektion','Logging & detection'),
  ('D02-12','Die Behandlung von Sicherheitsvorfällen ist festgelegt und genehmigt','Eine genehmigte Richtlinie zur Behandlung von Sicherheitsvorfällen legt den Reaktionslebenszyklus, rechenschaftspflichtige Rollen, Vorkehrungen zur Klassifizierung und Eskalation, die Kommunikation sowie die zu verwendenden Aufzeichnungen und Arbeitsunterlagen fest. Sie ist mit den Vorkehrungen der Einrichtung zur Geschäftskontinuität und Wiederherstellung vereinbar.','Genehmigte Richtlinie zur Behandlung von Sicherheitsvorfällen, Verantwortlichkeiten, Eskalations- und Kommunikationsvorkehrungen, Arbeitsvorlagen und Vereinbarkeit mit Kontinuitätsplänen.','Reaktionsverantwortliche treffen unter Druck widersprüchliche oder verspätete Entscheidungen, wodurch sich der Sicherheitsvorfall verschärft oder unnötige Betriebsunterbrechungen entstehen.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('IR-TIME','Zielzeiten für die Reaktion auf Sicherheitsvorfälle sind festgelegt','Legen Sie risikogerechte Zielzeiten für die Erstbewertung, den Reaktionsbeginn und erforderlichenfalls die Eskalation fest und dokumentieren Sie diese entsprechend der Priorität und den möglichen Auswirkungen des Sicherheitsvorfalls. Bestimmen Sie, wodurch jeder Zielzeitraum beginnt und welche Reaktionsfunktion verantwortlich ist. Dies sind interne Handlungsziele, keine Fristen für Behördenmeldungen oder garantierten Behebungszeiten; sie erlauben weder die Verzögerung dringender Maßnahmen noch das Außerkraftsetzen anwendbarer gesetzlicher Pflichten.','Dokumentierte Zielzeiten nach Priorität und Reaktionsphase, risikobasierte Begründung, festgelegte Startpunkte und verantwortliche Funktionen sowie Nachweise, dass die Zielzeiten den Reaktionsverantwortlichen zugänglich sind.','Dringende Arbeiten an einem Sicherheitsvorfall warten zu lange auf Bewertung, Eskalation oder Eindämmung, wodurch vermeidbare Exposition oder Störungen zunehmen.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-05','Kommunikationskanäle für Sicherheitsvorfälle sind eingerichtet','Richten Sie nutzbare Kommunikationskanäle für die Eskalation von Sicherheitsvorfällen und die Koordination mit den zuständigen Reaktionsverantwortlichen sowie relevanten internen und externen Beteiligten ein. Benennen Sie aktuelle Kontakte und einen Ausweichweg für den Fall, dass der reguläre Kanal oder der primäre Kontakt nicht verfügbar ist.','Festgelegte Kommunikationskanäle, aktuelle Kontaktdaten und Ersatzkontakte sowie ein Test- oder Vorfallsnachweis, der zeigt, dass die zuständigen Reaktionsverantwortlichen und Beteiligten erreicht werden können.','Informationen über Sicherheitsvorfälle erreichen die Personen nicht, die handeln müssen, wodurch die Reaktion verzögert oder fehlgeleitet wird.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-13','Verdächtige Ereignisse können einfach gemeldet werden','Mitarbeitende, Lieferanten sowie Kundinnen und Kunden verfügen über einen einfachen, nutzbaren Weg zur Meldung verdächtiger Ereignisse. Eine eingereichte Meldung erreicht die zuständige Bearbeitungsstelle und kann bis in den Bewertungsprozess nachverfolgt werden.','Zugängliche Meldekanäle für Mitarbeitende, Lieferanten sowie Kundinnen und Kunden; eingereichte Testmeldungen oder tatsächliche Meldungen, deren Eingang bei der Bearbeitungsstelle nachvollziehbar ist.','Beobachtete verdächtige Aktivitäten erreichen das Reaktionsteam nicht, wodurch die Erkennung und Eindämmung eines tatsächlichen Sicherheitsvorfalls verzögert werden.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-14','Mitarbeitende werden in der Meldung von und Reaktion auf Sicherheitsvorfälle geschult','Schulen Sie Mitarbeitende darin, verdächtige Ereignisse zu erkennen und über den verfügbaren Kanal zu melden sowie sichere Erstmaßnahmen zu ergreifen, ohne ihre Befugnisse zu überschreiten. Schulen Sie benannte Reaktionsverantwortliche in den ihnen zugewiesenen Aufgaben der Vorfallsbehandlung. Halten Sie die Unterweisung durch regelmäßige, rollengerechte Schulungen aktuell; informieren Sie Lieferanten sowie Kundinnen und Kunden gegebenenfalls über den Meldemechanismus. Die allgemeine Programmmethodik wird in T06 bewertet; betriebliche Reaktionsübungen werden unter D02-18 bewertet.','Rollengerechte Schulungsinhalte zu Sicherheitsvorfällen und Abschlussnachweise; Wissensprüfungen zu Meldung und sicheren Maßnahmen; Unterweisungsnachweise für Reaktionsverantwortliche sowie zugängliche Meldeinformationen für relevante Lieferanten und die betreffenden Kundinnen und Kunden.','R1: Mitarbeitende melden oder eskalieren einen tatsächlichen Sicherheitsvorfall nicht rechtzeitig. R2: Unvorbereitete Reaktionsverantwortliche ergreifen unsichere Maßnahmen, die Störungen verschärfen oder Nachweise vernichten.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-03','Verdächtige Ereignisse werden bewertet','Verdächtige Ereignisse werden anhand relevanter Fakten, Protokolle und korrelierter Informationen bewertet, um festzustellen, ob ein Sicherheitsvorfall eingetreten ist. Die Entscheidung, einschließlich einer Entscheidung, ein Ereignis als nicht vorfallsrelevant zu verwerfen, wird mit den zugrunde liegenden Gründen dokumentiert.','Bewertungsaufzeichnungen mit unterstützenden Protokollen, Ereignisfakten, Entscheidung, Begründung und prüfender Person; berücksichtigen Sie auch verworfene Ereignisse.','R1: Tatsächliche Sicherheitsvorfälle werden verworfen oder bleiben unerkannt, wodurch sich die Reaktion verzögert. R2: Unbedenkliche Aktivitäten werden fälschlich als Sicherheitsvorfall bestätigt und lösen unnötige Isolation oder Kontosperrungen aus, die den legitimen Betrieb stören.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-04','Sicherheitsvorfälle werden klassifiziert und priorisiert','Bestätigte Sicherheitsvorfälle werden anhand vorab festgelegter Kriterien und der beobachteten oder plausiblen Auswirkungen auf Dienste nach Art und Schwere klassifiziert. Die daraus resultierende Priorität bestimmt, wie dringlich Eindämmung und Beseitigung der Bedrohung erfolgen.','Schweregradkriterien und Vorfallsaufzeichnungen mit Art, bewerteten Auswirkungen, Priorität und Dringlichkeit der Reaktion.','Ein Sicherheitsvorfall mit erheblichen Auswirkungen wird als nachrangig behandelt, wodurch sich seine Eindämmung verzögert, während Reaktionsressourcen für weniger dringende Ereignisse eingesetzt werden.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-15','Vorfallsbewertungen werden bei veränderter Faktenlage aktualisiert','Wenn neue Informationen verfügbar werden oder vorhandene Informationen erneut analysiert werden, werden die Ereignisbewertung und Klassifizierung überprüft und bei entsprechender Sachlage geändert. Die überarbeitete Entscheidung wird dokumentiert und an die Reaktions- und Meldefunktionen weitergegeben, die auf dieser Grundlage handeln müssen.','Versionierte Bewertungs- und Klassifizierungsentscheidungen, Änderungsgründe sowie Nachweise, dass die Reaktions- und Meldefunktionen die Aktualisierungen erhalten haben.','Veraltete Bewertungen führen zu unangemessenen Reaktionen oder versäumten Meldepflichten.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-16','Maßnahmen und Entscheidungen bei Sicherheitsvorfällen werden aufgezeichnet','Vorfallsaufzeichnungen zeigen, wer jede wesentliche Reaktionsmaßnahme durchgeführt hat, wann sie erfolgte, was getan wurde und welches Ergebnis erzielt wurde. Die Aufzeichnungen werden während der Bearbeitung geführt, damit sich die Abfolge von Entscheidungen und Maßnahmen zuverlässig rekonstruieren lässt.','Zeitlicher Vorfallsablauf oder Fallaufzeichnung mit Angaben dazu, wer gehandelt hat, wann dies geschah, was getan wurde und welches Ergebnis erzielt wurde; während der Bearbeitung vorgenommene Einträge.','Maßnahmen lassen sich nicht rekonstruieren, und Reaktionsverantwortliche wiederholen frühere Entscheidungen oder widersprechen ihnen.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-17','Nachweise zu Sicherheitsvorfällen sind nachvollziehbar und geschützt','Für einen Sicherheitsvorfall erhobene Nachweise behalten eine identifizierbare Quelle und einen nachvollziehbaren Erhebungskontext und werden vor unbefugtem Zugriff oder unbefugter Veränderung geschützt. Relevante Übertragungen und Umwandlungen werden aufgezeichnet, damit sich das für Entscheidungen verwendete Material bis zum ursprünglich erhobenen Material zurückverfolgen lässt.','Erhebungsaufzeichnungen mit Angabe von Quelle, Zeitpunkt und Kontext; Zugriffsbeschränkungen, gegebenenfalls Integritätsprüfungen sowie die Historie von Übertragungen oder Umwandlungen.','R1: Nachweise werden verändert, gehen verloren oder lassen sich nicht auf ihre Quelle zurückführen, wodurch Untersuchungen und eine belastbare Nachweisführung beeinträchtigt werden. R2: Die unbefugte Offenlegung von Vorfallsnachweisen legt personenbezogene Informationen, Zugangsdaten oder sensible Einzelheiten der betroffenen Umgebung offen.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-07','Sicherheitsvorfälle werden eingedämmt','Dokumentierte Eindämmungsverfahren werden genutzt, um die Ausbreitung und Auswirkungen eines Sicherheitsvorfalls durch autorisierte, rechtzeitige Maßnahmen zu begrenzen. Die ausgewählten Maßnahmen berücksichtigen kritische Dienstabhängigkeiten und Einschränkungen aufgrund von Anforderungen an den sicheren Betrieb.','Eindämmungsverfahren, Autorisierungs- und Maßnahmenaufzeichnungen; Nachweise über Isolation oder Zugriffsbeschränkungen sowie die Berücksichtigung des sicheren Betriebs und der Dienstabhängigkeiten.','R1: Ein Sicherheitsvorfall breitet sich auf weitere Systeme aus oder gefährdet weiterhin Informationen, bevor er eingedämmt wird. R2: Ungeeignete Eindämmungsmaßnahmen unterbrechen notwendige Dienste oder vernichten flüchtige Nachweise.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-08','Bedrohungen bei Sicherheitsvorfällen werden beseitigt','Dokumentierte Bereinigungsverfahren steuern die Entfernung oder Neutralisierung der Mechanismen, die das Fortbestehen oder Wiederauftreten eines Sicherheitsvorfalls ermöglichen. Die Ergebnisse werden überprüft, statt die Eindämmung allein als Beseitigung der Bedrohung anzusehen.','Bereinigungsverfahren, Aufzeichnungen über entfernte Persistenzmechanismen oder beseitigte kompromittierte Zugriffe sowie Prüfungen, die die Neutralisierung der identifizierten Bedrohungsmechanismen nachweisen.','Angreifende behalten ihren Zugang oder der Sicherheitsvorfall tritt trotz scheinbarer Eindämmung erneut auf.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-09','Dienste werden sicher wieder in Betrieb genommen','Soweit eine Wiederherstellung erforderlich ist, legen dokumentierte Verfahren die vorfallsspezifischen Sicherheitsbedingungen für die Wiederinbetriebnahme betroffener Dienste fest und verifizieren diese. Eine autorisierte Entscheidung dokumentiert, warum die Wiederherstellung oder erneute Anbindung erfolgen kann und welche Schutzmaßnahmen weiterhin bestehen.','Vorfallsspezifische Wiederherstellungskriterien, Ergebnisse der Sicherheitsvalidierung, autorisierte Entscheidung zur Wiederherstellung oder erneuten Anbindung sowie verbleibende Schutzmaßnahmen.','Dienste werden trotz einer nicht behobenen Kompromittierung wiederhergestellt und sind unmittelbar erneut betroffen.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-10','Sicherheitsvorfälle werden zur Gewinnung von Erkenntnissen nachbereitet','Nach der Wiederherstellung werden Sicherheitsvorfälle, soweit angemessen, nachbereitet, um den Ablauf festzustellen, soweit möglich die Grundursachen zu identifizieren und praktische Erkenntnisse festzuhalten. Regelmäßige Prüfungen bestätigen, dass keine Sicherheitsvorfälle übersehen wurden, die eine Nachbereitung erfordern.','Kriterien für Nachbereitungen und abgeschlossene Nachbereitungen von Sicherheitsvorfällen mit zeitlichem Ablauf, Grundursachen, soweit möglich, und gewonnenen Erkenntnissen; Prüfungen auf unterlassene Nachbereitungen.','Unerkannte Grundursachen oder Schwächen der Reaktion treten bei späteren Sicherheitsvorfällen erneut auf und verursachen vermeidbare wiederholte Störungen oder Kompromittierungen.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-11','Verbesserungen aus der Nachbereitung von Sicherheitsvorfällen werden umgesetzt','Für vereinbarte Verbesserungen aus der Nachbereitung von Sicherheitsvorfällen und aus Übungen sind Verantwortliche und Zieltermine festgelegt. Die Verbesserungen werden in den betroffenen Regelungen zur Risikobehandlung, Erkennung oder Reaktion umgesetzt. Der Abschluss wird durch Nachweise gestützt, dass die beabsichtigte Korrektur wirksam ist.','Maßnahmenregister mit Verknüpfung zu Nachbereitungen oder Übungen, Verantwortlichen, Zielterminen, umgesetzten Änderungen und nachweisgestützten Abschlussprüfungen.','Erkannte Schwachstellen bleiben ungelöst, und dieselben Fehler treten erneut auf.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-18','Die Reaktion auf Sicherheitsvorfälle wird durch Übungen getestet','Die Verfahren zur Reaktion auf Sicherheitsvorfälle und die relevanten Rollen werden in geplanten Übungen getestet, die plausible Szenarien und die erforderlichen Übergaben abdecken. Weitere Tests berücksichtigen erhebliche Sicherheitsvorfälle oder wesentliche Änderungen des Betriebs oder der Risiken, soweit die anwendbaren Anforderungen dies vorsehen. Beobachtete Ergebnisse und Fehler werden dokumentiert.','Übungsplan, plausible Szenarien, Aufzeichnungen zu Teilnehmenden und Übergaben, beobachtete Ergebnisse und festgestellte Fehler; anwendbare, durch Änderungen ausgelöste Tests.','Ungetestete Reaktionsverfahren versagen bei einem tatsächlichen Sicherheitsvorfall, und Übergaben funktionieren nicht.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('D02-19','Verfahren zur Reaktion auf Sicherheitsvorfälle werden aktuell gehalten','Überprüfen Sie operative Verfahren zur Reaktion auf Sicherheitsvorfälle, Ablaufanweisungen und Kontakt- oder Eskalationsregelungen in geplanten Abständen sowie nach erheblichen Sicherheitsvorfällen oder wesentlichen Änderungen des Betriebs oder der Risiken. Aktualisieren und verteilen Sie diese bei Bedarf; dokumentieren Sie gegebenenfalls begründet, dass keine Änderung erforderlich ist. Diese Kontrolle bewertet aktuelle operative Anweisungen, nicht die Genehmigung von Richtlinien oder allgemeine Rollenzuweisungen. Sie bleibt auch dann relevant, wenn kein Sicherheitsvorfall eingetreten ist.','Datierte planmäßige und ereignisbezogene Überprüfungen operativer Verfahren, Ablaufanweisungen und Kontaktregelungen; Versionsänderungen oder begründete Entscheidungen, keine Änderung vorzunehmen; Nachweise, dass aktuelle Anweisungen die Nutzenden erreichen. Feststellungen zu Richtlinien oder allgemeinen Rollenzuweisungen nicht doppelt erfassen.','Die mit der Reaktion betrauten Personen befolgen veraltete Anweisungen oder kontaktieren die falschen Personen, wodurch die Behandlung des Sicherheitsvorfalls verzögert oder fehlgeleitet wird.','B-IR · Bewältigung von Sicherheitsvorfällen','Vorfallbehandlung','Incident response'),
  ('C54.1','Die Einrichtung erkennt Sicherheitsvorfälle, die dem CSIRT oder der zuständigen Behörde gemeldet werden müssen','Bewerten Sie, ob ein Sicherheitsvorfall eine schwerwiegende Betriebsstörung der Dienste oder finanzielle Verluste für die Einrichtung oder erhebliche materielle oder immaterielle Schäden für andere verursacht hat oder verursachen kann. Wenden Sie relevante allgemeine und dienstspezifische CIR-Kriterien für die Erheblichkeit ausschließlich innerhalb ihres Anwendungsbereichs an. Dokumentieren Sie, ob der Sicherheitsvorfall dem CSIRT oder der zuständigen Behörde gemeldet werden muss; setzen Sie interne Prioritätskennzeichnungen nicht mit der rechtlichen Erheblichkeit gleich.','Anwendbare Erheblichkeitskriterien, Folgenabschätzung und dokumentierte Entscheidungen zur Meldepflicht oder Nichtmeldepflicht mit Begründung.','Ein erheblicher Sicherheitsvorfall wird fälschlich als nicht meldepflichtig eingestuft. Dadurch werden die Kenntnisnahme und Koordination durch die Behörde verzögert, und die anwendbare Meldepflicht bleibt unerfüllt.','B-REP-READY · Behördliche Meldewege und Meldeentscheidungen','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C54.2','Die Einrichtung trifft und eskaliert Entscheidungen zur Meldung von Sicherheitsvorfällen ohne Verzögerung','Legen Sie fest, wer entscheidet, ob ein Sicherheitsvorfall dem CSIRT oder der zuständigen Behörde gemeldet werden muss, und wer die Meldungen übermittelt. Stellen Sie sicher, dass diese Personen auf der Grundlage aktueller Informationen handeln können, auch außerhalb der Arbeitszeiten, und dass Eskalationen oder interne Freigaben eine gesetzlich erforderliche Meldung nicht verzögern. Bewertet wird die Entscheidungsfindung, nicht der Portalzugang oder die Kriterien selbst.','Entscheidungsbefugnisse, Stellvertretungen, Eskalationsregelungen und dokumentierte zeitliche Entscheidungsabläufe aus Sicherheitsvorfällen oder Übungen.','Interne Unklarheiten oder Engpässe bei Freigaben verhindern eine fristgerechte gesetzliche Meldung.','B-REP-READY · Behördliche Meldewege und Meldeentscheidungen','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C67.1','Erhebliche Sicherheitsvorfälle können dem CSIRT oder der zuständigen Behörde jederzeit gemeldet werden','Autorisierte Mitarbeitende und ihre benannten Stellvertretungen können Meldungen erheblicher Sicherheitsvorfälle über den offiziellen Meldeweg an das zuständige Computer-Notfallteam (Computer Security Incident Response Team, CSIRT) oder gegebenenfalls an die zuständige NIS2-Behörde übermitteln. Halten Sie Zugangsdaten, Berechtigungen und Kontaktdaten nutzbar und testen Sie den Meldeweg während und außerhalb der Arbeitszeiten mit einem vereinbarten Testverfahren, statt eine falsche Vorfallsmeldung abzugeben. Bewertet wird die Einsatzbereitschaft, nicht der Nachweis, dass eine bestimmte erforderliche Meldung tatsächlich übermittelt wurde.','Benannte meldende Personen und Stellvertretungen, Angaben zu Meldeweg und Empfänger, Zugangsprüfungen und Aufzeichnungen durchgängiger Tests einschließlich der Verfügbarkeit außerhalb der Arbeitszeiten.','Ein erheblicher Sicherheitsvorfall kann bei Bedarf nicht über den offiziellen Meldeweg gemeldet werden. Dies verzögert die behördliche Koordination und setzt die Einrichtung dem Risiko eines Verstoßes gegen Meldepflichten aus.','B-REP-READY · Behördliche Meldewege und Meldeentscheidungen','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C57.1','Die Einrichtung bewertet wiederkehrende Sicherheitsvorfälle auf ihre gemeinsame Erheblichkeit für die Meldepflicht (Gilt nur für Einrichtungen im CIR-Anwendungsbereich.)','Prüfen Sie vierteljährlich, ob für sich genommen nicht erhebliche Sicherheitsvorfälle innerhalb von sechs Monaten mindestens zweimal aufgetreten sind, dieselbe augenscheinliche Ursache haben und zusammengenommen das CIR-Kriterium für finanzielle Verluste erfüllen: tatsächliche oder mögliche direkte finanzielle Verluste von mehr als 500.000 EUR oder 5 % des Umsatzes der Einrichtung im vorangegangenen Geschäftsjahr, je nachdem, welcher Betrag niedriger ist. Wenn alle Bedingungen erfüllt sind, behandeln Sie sie für die Meldung an das CSIRT oder die zuständige Behörde als einen erheblichen Sicherheitsvorfall. Die vierteljährliche Prüfung erlaubt keine Verzögerung der Meldung, sobald die Erheblichkeit bekannt ist. (Gilt nur für Einrichtungen im CIR-Anwendungsbereich.)','Vierteljährliche Überprüfungen, Aufzeichnungen zusammenhängender Sicherheitsvorfälle, Verknüpfungen ihrer Ursachen, Verlustberechnungen und daraus resultierende Meldeentscheidungen.','Wiederkehrende Sicherheitsvorfälle werden nur einzeln bewertet, sodass ihre gemeinsamen Auswirkungen nicht gemeldet werden, obwohl der anwendbare Meldeschwellenwert erreicht ist.','B-REP-CIR · Wiederkehrende Vorfälle im CIR-Anwendungsbereich','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C58.1','Die Einrichtung übermittelt dem CSIRT oder der zuständigen Behörde innerhalb von 24 Stunden eine Frühwarnung','Übermitteln Sie die Frühwarnung über den vorgesehenen offiziellen Meldeweg unverzüglich und spätestens 24 Stunden nach Kenntniserlangung von dem erheblichen Sicherheitsvorfall. Lassen Sie die Frist nicht erst mit der Freigabe durch die Leitung beginnen und warten Sie nicht auf den Abschluss einer Untersuchung. Geben Sie gegebenenfalls vermutete rechtswidrige oder böswillige Handlungen und mögliche grenzüberschreitende Auswirkungen an; unterscheiden Sie bekannte Tatsachen von Unsicherheiten.','Kopie der Frühwarnung, korrekter Empfänger und offizieller Meldeweg, Zeitstempel der Kenntniserlangung und Übermittlung, Berechnung der verstrichenen Zeit, Gründe für etwaige Verzögerungen sowie unterstützende Informationen zur vermuteten Ursache und zu grenzüberschreitenden Auswirkungen.','Eine unterlassene, verspätete oder in wesentlichen Punkten unvollständige Frühwarnung verhindert eine rechtzeitige behördliche Bewertung und Koordination.','B-REP-STAGES · Frühwarnung, Vorfallmeldung und Folgeberichte','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C60.1','Die Einrichtung übermittelt dem CSIRT oder der zuständigen Behörde innerhalb von 72 Stunden eine Meldung des Sicherheitsvorfalls','Übermitteln Sie die auf die Frühwarnung folgende Meldung des Sicherheitsvorfalls unverzüglich und innerhalb von 72 Stunden nach Kenntniserlangung von dem erheblichen Sicherheitsvorfall, nicht nach Übermittlung der Frühwarnung. Für einen Vertrauensdiensteanbieter gilt stattdessen eine Frist von 24 Stunden, wenn der erhebliche Sicherheitsvorfall die Erbringung seiner Vertrauensdienste betrifft. Übermitteln Sie die Meldung über den offiziellen Meldeweg und verknüpfen Sie sie mit der Frühwarnung. Die erste Bewertung und die weiteren erforderlichen Inhalte werden unter C60.4 bewertet.','Kopie der Meldung des Sicherheitsvorfalls und Nachweise der offiziellen Übermittlung; Zeitpunkte der Kenntniserlangung und Übermittlung; Berechnung der verstrichenen Zeit; anwendbare Einstufung des Anbieters bzw. Dienstes; Gründe für etwaige Verzögerungen.','Die auf die Frühwarnung folgende Meldung wird unterlassen oder verspätet übermittelt, oder es wird die falsche Frist angewendet. Dadurch wird eine rechtzeitige Koordination verhindert.','B-REP-STAGES · Frühwarnung, Vorfallmeldung und Folgeberichte','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C60.4','Die Einrichtung nimmt die erforderliche Bewertung in ihre Meldung des Sicherheitsvorfalls auf','Aktualisieren Sie in der Meldung des Sicherheitsvorfalls an das CSIRT oder die zuständige Behörde gegebenenfalls die Angaben der Frühwarnung und geben Sie eine erste Bewertung des Schweregrads und der Auswirkungen ab. Nehmen Sie verfügbare Kompromittierungsindikatoren, beispielsweise bösartige Adressen oder Datei-Hashwerte, sowie Informationen auf, die eine Bewertung grenzüberschreitender Auswirkungen ermöglichen. Kennzeichnen Sie vorläufige oder nicht verfügbare Informationen deutlich.','Kopie der Meldung, erste Bewertung des Schweregrads und der Auswirkungen, gegebenenfalls erforderliche Aktualisierungen und verfügbare technische Indikatoren.','Unvollständige oder unzuverlässige Meldeinhalte vermitteln der Behörde ein falsches Bild von Schweregrad, Ausbreitung oder technischem Kontext des Sicherheitsvorfalls und verzögern koordinierte Folgemaßnahmen oder lenken sie in die falsche Richtung.','B-REP-STAGES · Frühwarnung, Vorfallmeldung und Folgeberichte','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C61.1','Die Einrichtung übermittelt auf Ersuchen des CSIRT oder der zuständigen Behörde Zwischenberichte zum Sicherheitsvorfall (Gilt, wenn ein solches Ersuchen vorliegt.)','Wenn das CSIRT oder die zuständige Behörde einen Zwischenbericht anfordert, übermitteln Sie der anfordernden Stelle die relevanten Aktualisierungen zum Stand des Sicherheitsvorfalls und gehen Sie auf die angeforderten Informationen sowie die anwendbaren Vorgaben für die Antwort ein. Ohne ein solches Ersuchen wird kein routinemäßiger Zeitplan für Zwischenberichte eingeführt. (Gilt, wenn ein solches Ersuchen vorliegt.)','Tatsächliches Ersuchen, benannte verantwortliche Person für die Antwort, übermittelte Statusaktualisierung und Übermittlungsnachweise.','Eine angeforderte Statusaktualisierung wird nicht bereitgestellt, sodass die Behörde Folgemaßnahmen auf der Grundlage veralteter Informationen über den Sicherheitsvorfall koordinieren muss.','B-REP-STAGES · Frühwarnung, Vorfallmeldung und Folgeberichte','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C62.1','Die Einrichtung übermittelt dem CSIRT oder der zuständigen Behörde innerhalb eines Monats den Abschlussbericht zum Sicherheitsvorfall','Übermitteln Sie dem CSIRT oder der zuständigen Behörde den Abschlussbericht spätestens einen Monat nach Übermittlung der Meldung des Sicherheitsvorfalls. Dauert der Sicherheitsvorfall zu diesem Zeitpunkt noch an, legen Sie stattdessen einen Fortschrittsbericht vor und übermitteln Sie den Abschlussbericht innerhalb eines Monats nach der Bewältigung des Sicherheitsvorfalls. Dokumentieren Sie, welches Vorgehen anzuwenden ist; ein Monat entspricht nicht automatisch 30 Tagen.','Datum der Meldung des Sicherheitsvorfalls, Status des Sicherheitsvorfalls, gegebenenfalls Datum seiner Bewältigung, Fristberechnung und Übermittlung des Abschlussberichts. Bewahren Sie Nachweise zu den unterschiedlichen Fristbeginnzeitpunkten auf; ein Monat entspricht nicht automatisch 30 Tagen.','Eine verspätete oder unterlassene Abschlussberichterstattung verhindert die rechtzeitige behördliche Prüfung des Ergebnisses der Vorfallsbehandlung und lässt den vorgeschriebenen Meldezyklus unvollständig.','B-REP-STAGES · Frühwarnung, Vorfallmeldung und Folgeberichte','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C62.2','Die Einrichtung nimmt Erkenntnisse zum Sicherheitsvorfall und Abhilfemaßnahmen in den Abschlussbericht auf','Beschreiben Sie im Abschlussbericht an das CSIRT oder die zuständige Behörde den Sicherheitsvorfall einschließlich seines Schweregrads und seiner Auswirkungen, die wahrscheinliche Art der Bedrohung oder Ursache, bereits ergriffene und noch laufende Maßnahmen sowie gegebenenfalls grenzüberschreitende Auswirkungen. Trennen Sie gesicherte Schlussfolgerungen von verbleibenden Unsicherheiten.','Abschlussbericht und unterstützende Untersuchungsergebnisse, Aufzeichnungen zu Abhilfemaßnahmen sowie gegebenenfalls die Bewertung grenzüberschreitender Auswirkungen.','Eine unvollständige oder unbelegte abschließende Darstellung vermittelt der Behörde ein falsches Bild von Ursachen, Auswirkungen oder Abhilfemaßnahmen und beeinträchtigt Folgemaßnahmen sowie das gemeinsame Lernen.','B-REP-STAGES · Frühwarnung, Vorfallmeldung und Folgeberichte','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C63.1','Die Einrichtung übermittelt einen Fortschrittsbericht, wenn der Sicherheitsvorfall bei Fälligkeit des Abschlussberichts noch andauert (Gilt für Sicherheitsvorfälle, die zu diesem Berichtszeitpunkt noch andauern.)','Dauert der Sicherheitsvorfall noch an, wenn der Abschlussbericht andernfalls fällig wäre, übermitteln Sie dem CSIRT oder der zuständigen Behörde zu diesem Zeitpunkt einen Fortschrittsbericht. Erläutern Sie den aktuellen Stand und behalten Sie die Verantwortung für den späteren Abschlussbericht bei; erklären Sie den Sicherheitsvorfall nicht fälschlich für abgeschlossen. (Gilt für Sicherheitsvorfälle, die zu diesem Berichtszeitpunkt noch andauern.)','Nachweise, dass der Sicherheitsvorfall noch andauert, Fortschrittsbericht, Übermittlungsdatum und nachverfolgte Verpflichtung zum späteren Abschlussbericht.','Ein andauernder Sicherheitsvorfall wird als abgeschlossen dargestellt oder es erfolgt keine Fortschrittsmeldung. Dadurch erhält die Behörde ein unzutreffendes Bild, und angemessene Folgemaßnahmen werden verhindert.','B-REP-STAGES · Frühwarnung, Vorfallmeldung und Folgeberichte','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C64.1','Die Einrichtung übermittelt relevanten Empfängern ihrer Dienste Vorfallsinformationen und Hinweise zum Schutz vor Bedrohungen','Informieren Sie gegebenenfalls die Empfänger der Dienste unverzüglich über erhebliche Sicherheitsvorfälle, die sich voraussichtlich nachteilig auf die ihnen erbrachten Dienste auswirken. Übermitteln Sie, soweit anwendbar, potenziell betroffenen Empfängern der Dienste umgehend die Maßnahmen oder Abhilfemöglichkeiten, die sie gegen eine erhebliche Cyberbedrohung ergreifen können; erläutern Sie gegebenenfalls auch die Bedrohung selbst. Bewerten Sie jeden Auslöser gesondert: Schutzhinweise können bereits vor Eintritt eines Sicherheitsvorfalls erforderlich sein. Diese Mitteilungen richten sich an die Empfänger der Dienste und ersetzen keine Meldung an das CSIRT oder die zuständige Behörde.','Bewertung des Sicherheitsvorfalls oder der Bedrohung mit Ermittlung der relevanten Empfänger und anwendbaren Kommunikationspflichten; versandte Vorfallsmitteilungen oder umsetzbare Schutzhinweise, relevante Erläuterungen zur Bedrohung, Empfängerlisten, Versandzeitpunkte und begründete Entscheidungen über die Nichtanwendbarkeit.','Den Empfängern der Dienste fehlen rechtzeitige Informationen oder praktische Handlungshinweise, wodurch sie vermeidbare Störungen oder Schäden erleiden.','B-REP-RECIP · Unterrichtung von Diensteempfängern und Öffentlichkeit','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C64.4','Die Einrichtung veröffentlicht Informationen zu Sicherheitsvorfällen, wenn das CSIRT oder die zuständige Behörde dies verlangt (Gilt, wenn die Einrichtung zur Information der Öffentlichkeit aufgefordert wird.)','Wenn das CSIRT oder die zuständige Behörde die Einrichtung gemäß Art. 23(7) auffordert, die Öffentlichkeit über einen erheblichen Sicherheitsvorfall zu informieren, veröffentlichen Sie die verlangte Mitteilung gemäß der anwendbaren Vorgabe. Dies betrifft die Information der Öffentlichkeit, die erforderlich ist, um den Sicherheitsvorfall zu verhindern oder zu bewältigen, oder eine Offenlegung, die anderweitig im öffentlichen Interesse liegt. Es handelt sich nicht um eine routinemäßige Veröffentlichungspflicht für jeden Sicherheitsvorfall. (Gilt, wenn die Einrichtung zur Information der Öffentlichkeit aufgefordert wird.)','Aufforderung der Behörde oder des CSIRT, Einzelheiten der Kommunikation, zu denen eine Konsultation stattgefunden hat oder die vereinbart wurden, und Veröffentlichungsnachweise.','R1: Erforderliche Informationen für die Öffentlichkeit werden zurückgehalten, sodass Menschen nicht angemessen auf den Sicherheitsvorfall reagieren können. R2: Eine öffentliche Vorfallsmitteilung legt unnötig personenbezogene Daten oder sensible Einzelheiten der Reaktion offen. Dies führt zu weiteren Offenlegungen oder hilft Angreifenden, ihr Vorgehen anzupassen.','B-REP-RECIP · Unterrichtung von Diensteempfängern und Öffentlichkeit','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C21.1','Die Einrichtung benachrichtigt die NIS2-Behörde bei Beitritt zu oder Austritt aus einer Vereinbarung über den Informationsaustausch (Gilt nur für wesentliche und wichtige Einrichtungen, die solchen Vereinbarungen beitreten oder aus ihnen austreten.)','Benachrichtigen Sie die zuständige NIS2-Behörde, wenn die Einrichtung einer Vereinbarung über den Austausch von Cybersicherheitsinformationen beitritt, sowie bei einem Austritt, sobald dieser wirksam wird. Diese Benachrichtigung betrifft die Teilnahme an der Vereinbarung, nicht die Meldung eines einzelnen Sicherheitsvorfalls. (Gilt nur für wesentliche und wichtige Einrichtungen, die solchen Vereinbarungen beitreten oder aus ihnen austreten.)','Aufzeichnung über die Teilnahme oder den Austritt, Datum des Wirksamwerdens und an die zuständige NIS2-Behörde übermittelte Benachrichtigung.','Die zuständige Behörde handelt auf der Grundlage eines unzutreffenden Bildes der Teilnahme der Einrichtung an einer Vereinbarung über den Informationsaustausch. Dies beeinträchtigt die erforderliche Aufsicht und Folgemaßnahmen.','B-SHR · Freiwillige Vereinbarungen zum Informationsaustausch','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('C21.2','Wenn die Einrichtung an einer Vereinbarung über den Informationsaustausch teilnimmt, gibt sie Cybersicherheitsinformationen sicher weiter','Wenn die Einrichtung an einer freiwilligen Vereinbarung über den Austausch von Cybersicherheitsinformationen teilnimmt, hält sie die vereinbarten Regeln für den Umgang mit Informationen ein, schützt sensible Informationen und übermittelt Informationen nur an autorisierte Teilnehmende. Der Beitritt ist freiwillig. Ohne eine entsprechende Teilnahme ist diese Kontrolle nicht anwendbar; sie betrifft den Austausch zwischen Teilnehmenden, nicht die gesetzliche Meldung von Sicherheitsvorfällen.','Regeln der Vereinbarung, Empfängerberechtigungen, Beschränkungen für den Umgang mit Informationen und geeignete Beispiele ausgetauschter Informationen.','Durch den freiwilligen Austausch werden sensible Informationen offengelegt oder über den Kreis der berechtigten Teilnehmenden hinaus verbreitet.','B-SHR · Freiwillige Vereinbarungen zum Informationsaustausch','Meldepflichten & Informationsaustausch','Reporting duties & information sharing'),
  ('BC-BIA','Eine Analyse der Betriebsauswirkungen (Business Impact Analysis, BIA) wird durchgeführt, und Anforderungen an die Betriebsfortführung werden festgelegt','Bewerten Sie, wie sich die Unterbrechung relevanter Dienste und Tätigkeiten im Zeitverlauf auf den Betrieb auswirkt, einschließlich der Abhängigkeiten von Systemen, Daten, Mitarbeitenden und Lieferanten. Berücksichtigen Sie betriebliche, finanzielle, rechtliche und sicherheitsbezogene Folgen. Bestimmen Sie die Wiederherstellungsprioritäten und den Zeitpunkt, ab dem eine Unterbrechung untragbar wird, und drücken Sie diesen, soweit zweckmäßig, als maximal tolerierbare Unterbrechungsdauer (Maximum Tolerable Period of Disruption, MTPD) aus. Dokumentieren Sie die daraus folgenden Anforderungen an die Betriebsfortführung. Bewertet werden die Folgen einer Unterbrechung, nicht nur die Wahrscheinlichkeit von Bedrohungen.','Dokumentierte Auswirkungsanalyse für Dienste und Tätigkeiten mit Zeithorizonten, Abhängigkeiten und Beiträgen der interessierten Parteien; begründete Schwellen für untragbare Auswirkungen, Wiederherstellungsprioritäten und daraus folgende Anforderungen an die Betriebsfortführung.','Kritische Abhängigkeiten und die Folgen länger andauernder Unterbrechungen werden falsch eingeschätzt, sodass Wiederherstellungsprioritäten und Vorkehrungen zur Betriebsfortführung die wichtigsten Dienste nicht schützen.','C-IMPACT · Geschäftsauswirkungen und Wiederherstellungsziele','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('BC-RTO','Wiederherstellungszeitziele (Recovery Time Objectives, RTO) sind für prioritäre Dienste festgelegt','Legen Sie auf der Grundlage der Erkenntnisse zu den Betriebsauswirkungen fest, innerhalb welcher Zielzeit jeder prioritäre Dienst auf einem definierten nutzbaren Niveau wiederhergestellt werden soll. Definieren Sie, wann die Zeitmessung beginnt und was als Wiederherstellung gilt; berücksichtigen Sie Abhängigkeiten von Systemen und Lieferanten. Setzen Sie die Ziele so früh an, dass untragbare Unterbrechungen vermieden werden, und lassen Sie bei Bedarf Zeit für die anschließende Wiederherstellung der Geschäftsabläufe. Beispielsweise verlangt ein RTO von zwei Stunden, dass die festgelegte Leistungsfähigkeit des Dienstes innerhalb von zwei Stunden wiederhergestellt ist. Die Dauer eines Datensicherungsauftrags ist kein RTO eines Dienstes.','Dienstspezifisches RTO-Register oder gleichwertige Planeinträge; Begründung anhand der Betriebsauswirkungen; definierte Start- und Endkriterien sowie das Dienstleistungsniveau; Abstimmung mit Abhängigkeiten und Bestätigung durch die fachlich Verantwortlichen.','Wiederherstellungsteams arbeiten auf willkürliche oder widersprüchliche Fristen hin, sodass Dienste länger ausfallen, als es die betrieblichen Toleranzen zulassen.','C-IMPACT · Geschäftsauswirkungen und Wiederherstellungsziele','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C32.1','Pläne zur Betriebsfortführung sind festgelegt','Legen Sie anhand der Erkenntnisse zu den Betriebsauswirkungen und der Wiederherstellungsziele fest, wie prioritäre Dienste fortgeführt werden, während reguläre Systeme oder Räumlichkeiten nicht verfügbar sind. Bestimmen Sie Aktivierungsbedingungen, Ersatzverfahren, Verantwortlichkeiten und Ressourcen. Geben Sie das mindestens akzeptable Dienstleistungsniveau im vorübergehenden Betrieb an und verwenden Sie, soweit zweckmäßig, ein Ziel für die Diensterbringung (Service Delivery Objective, SDO), beispielsweise welche wesentlichen Transaktionen weiterhin möglich sein müssen. Dies ist der operative Plan zur Betriebsfortführung, nicht die BIA selbst oder eine Zusage unterbrechungsfreier Dienste.','Aktuelle Pläne zur Betriebsfortführung mit Verknüpfung zu BIA-Prioritäten und Wiederherstellungszielen; Mindestniveaus der Diensterbringung im vorübergehenden Betrieb, Aktivierungsbedingungen, Ersatzverfahren, Verantwortliche und Ressourcenbedarf.','Prioritäre Dienste fallen während einer Unterbrechung aus oder werden unterhalb eines akzeptablen Niveaus betrieben, weil die geplanten Vorkehrungen zur Betriebsfortführung nicht umsetzbar sind.','C-PREP · Vorkehrungen für Kontinuität, Wiederherstellung und Krisen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C32.3','Verfahren zur Wiederherstellung nach Notfällen sind festgelegt','Definieren Sie die Schritte, die Reihenfolge und die verantwortlichen Teams für die Wiederherstellung ausgefallener Systeme und Dienste. Berücksichtigen Sie Abhängigkeiten, den Zugang zu Wiederherstellungsressourcen, die Validierung wiederhergestellter Systeme und die Rückkehr vom vorübergehenden zum regulären Betrieb. Verwenden Sie die unter BC-RTO und BC-RPO festgelegten RTO- und RPO-Werte zur Ausgestaltung der Verfahren; legen Sie hier keine widersprüchlichen Ziele neu fest. Bewerten Sie, ob Mitarbeitende ausführbare Anweisungen haben, nicht nur eine Aussage, dass eine Wiederherstellung erfolgen wird.','Aktuelle Wiederherstellungsanweisungen, eine an Abhängigkeiten ausgerichtete Wiederherstellungsreihenfolge, verantwortliche Teams, Regelungen zu Ressourcen und Zugängen sowie Abnahmeprüfungen; Rückverfolgbarkeit zu den festgelegten RTO-/RPO-Werten.','Wiederherstellungsteams verfügen über keine ausführbaren Anweisungen oder stellen voneinander abhängige Komponenten in der falschen Reihenfolge wieder her. Dies verhindert die rechtzeitige und zuverlässige Wiederherstellung der Dienste.','C-PREP · Vorkehrungen für Kontinuität, Wiederherstellung und Krisen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C32.4','Krisenpläne legen fest, wann eskaliert wird und wer entscheidet','Definieren Sie, wann eine Unterbrechung eine Koordination auf Krisenebene erfordert, die über die routinemäßige Vorfallsbehandlung hinausgeht, wer den Krisenstab aktiviert und wer dringende Entscheidungen zu Diensten und Ressourcen treffen darf. Legen Sie interne und externe Kommunikationsregelungen sowie Stellvertretungen fest und bestimmen Sie, wie Pläne und Kontakte zugänglich bleiben, wenn die regulären Systeme ausfallen. Nicht jeder Sicherheitsvorfall erfordert die Aktivierung des Krisenstabs; die gesetzliche Meldung wird in T14 bewertet.','Kriterien zur Aktivierung und Beendigung des Krisenmodus, Entscheidungsbefugnisse und Stellvertretungen, Kommunikationsregelungen, zugängliche Kopien von Plänen und Kontakten sowie Schnittstellen zu den Plänen zur Betriebsfortführung.','Bei einer Unterbrechung, die die Kapazität der routinemäßigen Vorfallsbehandlung übersteigt, trifft die Leitung widersprüchliche oder verspätete Entscheidungen. Dadurch verlängert sich die Dienstunterbrechung, und interessierte Parteien werden verunsichert.','C-PREP · Vorkehrungen für Kontinuität, Wiederherstellung und Krisen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C32.6','Die in den Plänen zur Betriebsfortführung benötigten Ressourcen sind verfügbar','Stellen Sie die in den Betriebsfortführungs- und Wiederherstellungsplänen vorgesehenen alternativen Systeme, Räumlichkeiten, Mitarbeitenden und Kommunikationsressourcen innerhalb der erforderlichen Zeit bereit. Prüfen Sie ihre Kapazität, Zugangsregelungen und Abhängigkeiten anhand des geplanten Dienstleistungsniveaus, einschließlich der von Lieferanten bereitgestellten Ressourcen. Ein Lieferantenname oder eine geplante Anschaffung allein weist keine Verfügbarkeit nach; nicht jeder Dienst benötigt einen zweiten Standort.','Zuordnung der Plananforderungen zu Ressourcen, Kapazitäts- und Zugangsprüfungen, personelle Vertretungsregelungen, Lieferantenzusagen und Nachweise der Ressourcenverfügbarkeit innerhalb der erforderlichen Zeit.','Dokumentierte Ersatzverfahren oder Wiederherstellungsschritte können nicht ausgeführt werden, weil Ersatzressourcen nicht verfügbar, nicht zugänglich oder zu knapp bemessen sind.','C-READY · Vorbereitung alternativer Ressourcen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('BC-RPO','Wiederherstellungspunktziele (Recovery Point Objectives, RPO) sind für die Datenwiederherstellung festgelegt','Bestimmen Sie anhand der betrieblichen Auswirkungen des Verlusts von Datensätzen oder Transaktionen, bis zu welchem zurückliegenden Zeitpunkt Daten wiederhergestellt werden dürfen, ohne dass ein untragbarer Verlust entsteht. Legen Sie für relevante Datenbestände und Dienste das akzeptable Datenverlustfenster fest und nutzen Sie es anschließend zur Auswahl der Datensicherungshäufigkeit und weiterer Wiederherstellungsvorkehrungen. Beispielsweise erlaubt ein RPO von 15 Minuten den Verlust von Aktualisierungen aus höchstens 15 Minuten. Das RPO ist weder die Dauer der Datenwiederherstellung noch eine Aufbewahrungsfrist für Sicherungskopien.','Dokumentierte RPO-Werte für relevante Daten und Dienste; Begründung des akzeptablen Verlusts durch die fachlich Verantwortlichen; Zuordnung zur Ausgestaltung der Datensicherung oder anderer Wiederherstellungsverfahren; konsistente Annahmen zu Replikation, zeitlichen Abläufen und Datenabhängigkeiten.','Die Wiederherstellungsvorkehrungen stellen zu alte Daten wieder her und verursachen dadurch einen untragbaren Verlust von Transaktionen oder Datensätzen, selbst wenn der Dienst schnell wiederhergestellt wird.','C-BACKUP · Datenwiederherstellungsziele und geschützte Datensicherungen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C32.2','Datensicherungsverfahren werden umgesetzt und getestet','Führen Sie Datensicherungen für die zur Wiederherstellung benötigten Daten, Software und Konfigurationen einschließlich relevanter in der Cloud gehosteter Inhalte nach festgelegten Zeitplänen und Aufbewahrungsfristen durch. Testen Sie, ob das Datensicherungsverfahren die erforderlichen Quellen einbezieht, die vorgesehenen Kopien erstellt und fehlgeschlagene oder ausgelassene Aufträge erkennt; beheben Sie Fehler und testen Sie die betroffenen Schritte erneut. Diese Kontrolle bewertet die zuverlässige Erstellung von Sicherungskopien, während C32.5 die Integrität gespeicherter Kopien prüft und C33.1 die tatsächliche Wiederherstellung testet. Replikation oder ein Cloud-Abonnement allein reicht nicht aus.','An Wiederherstellungsanforderungen ausgerichteter Datensicherungsumfang und entsprechende Zeitpläne; Aufbewahrungseinstellungen; Aufzeichnungen zu Aufträgen und Ausnahmen; dokumentierte Tests der Quellenabdeckung, Kopienerstellung und Fehlererkennung; behobene Fehler und Ergebnisse erneuter Tests.','Das Datensicherungsverfahren lässt erforderliche Informationen unbemerkt aus oder erstellt keine aktuellen Wiederherstellungskopien. Dadurch verfügen Dienste über keine brauchbare Wiederherstellungsquelle.','C-BACKUP · Datenwiederherstellungsziele und geschützte Datensicherungen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C33.2','Sicherungskopien sind vor einer Kompromittierung der Produktivsysteme geschützt','Schützen Sie Sicherungskopien und ihre Administration vor einer Kompromittierung der Produktivsysteme sowie vor unbefugtem Zugriff, unbefugter Änderung und Löschung. Berücksichtigen Sie gemeinsame Abhängigkeiten und Schäden auf Standortebene. Einrichtungen im CIR-Anwendungsbereich müssen Kopien außerhalb des Netzwerks des Produktivsystems und in ausreichender Entfernung vom Hauptstandort vorhalten, damit sie nicht von derselben Katastrophe betroffen sind, und angemessene Zugriffskontrollen anwenden. Sowohl Online- als auch Offline-Kopien sind möglich; weder eine ausschließlich auf Offline-Kopien ausgerichtete Gestaltung noch ein bestimmtes Produkt ist allgemeingültig vorgeschrieben.','Netzwerk- und Administrationsarchitektur der Datensicherung, Bewertung des Standorts und gemeinsamer Katastrophenrisiken, Zugriffsbeschränkungen, Schutzmaßnahmen gegen Löschung und Änderung sowie getestete Kompromittierungsszenarien. Prüfen Sie im CIR-Anwendungsbereich die netzwerkbezogene und geografische Trennung, statt eine unbegründete Kennzeichnung als ''sichere Datensicherung'' zu akzeptieren.','R1: Eine Kompromittierung oder ein gemeinsamer Ausfall zerstört oder beschädigt sowohl die Produktivdaten als auch die zu ihrer Wiederherstellung benötigten Kopien. R2: Ein Angreifer erlangt sensible Informationen aus Wiederherstellungskopien, die innerhalb derselben kompromittierten Vertrauensgrenze wie die Produktivsysteme liegen.','C-BACKUP · Datenwiederherstellungsziele und geschützte Datensicherungen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C32.7','Sicherheitsmaßnahmen bleiben während des Notbetriebs wirksam','Wenden Sie angemessene Sicherheitsmaßnahmen an, wenn Vorkehrungen zur Betriebsfortführung vorübergehende Systeme, manuelle Aufzeichnungen, Notfallzugänge oder alternative Räumlichkeiten nutzen. Steuern Sie, wer auf Informationen zugreifen kann, schützen Sie vorübergehende Aufzeichnungen und bewerten Sie Schutzmaßnahmen bei veränderten Bedingungen erneut. Entziehen Sie bei Wiederaufnahme des regulären Betriebs vorübergehende Zugriffsrechte und behandeln Sie vorübergehende Aufzeichnungen sicher; wenn keine Unterbrechung eingetreten ist, bewerten Sie die vorbereiteten Schutzmaßnahmen und Übungsnachweise.','Sicherheitsvorkehrungen für den Notbetrieb, Kontrollen für vorübergehende Zugriffe und den Umgang mit Aufzeichnungen, Nachweise aus Sicherheitsvorfällen oder Übungen, Risikoentscheidungen und Prüfungen bei der Rückkehr zum regulären Betrieb.','R1: Ersatzverfahren für den Notbetrieb legen während des gestörten Betriebs Informationen offen oder ermöglichen unbefugten Zugriff. R2: Vorübergehende Notfallberechtigungen oder unsichere Konfigurationen bleiben nach der Wiederherstellung bestehen und werden später missbraucht.','C-OPERATE · Sicherheit bei Störungen und Rückkehr zum Normalbetrieb','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('TRN-BCDR','Mitarbeitende werden für ihre Aufgaben bei der Betriebsfortführung und Wiederherstellung nach Notfällen geschult','Schulen Sie Mitarbeitende für die ihnen zugewiesenen Aufgaben bei der Betriebsfortführung und Wiederherstellung: Mitarbeitende erlernen die relevanten vorübergehenden Arbeitsabläufe, Wiederherstellungsteams die Wiederherstellungsverfahren und Krisenkoordinierende die Aufgaben zur Aktivierung und Kommunikation. Aktualisieren Sie die Unterweisung, wenn sich relevante Aufgaben oder Pläne ändern, und prüfen Sie, ob die Teilnehmenden das Gelernte anwenden können. Ein gesonderter Kurs oder ein Zertifikat ist nicht erforderlich; auch eine Übung kann als Schulungsnachweis dienen, wenn Lernen und Verständnis nachgewiesen werden. T06 bewertet das allgemeine Schulungsprogramm, nicht diese themenspezifische Durchführung.','Schulungsabdeckung der rollenbezogenen Aufgaben; aktuelle Anweisungen und Schulungsaufzeichnungen; praktische Demonstrationen oder Wissensprüfungen; Nachverfolgung festgestellter Lernlücken.','Mitarbeitende wissen nicht, wie prioritäre Dienste aufrechterhalten oder zugewiesene Wiederherstellungsaufgaben ausgeführt werden. Dadurch versagen ansonsten angemessene Pläne während einer Unterbrechung.','C-VERIFY · Wiederherstellungsnachweis, Schulung und Planübungen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C32.5','Sicherungskopien werden auf Beschädigung und Unvollständigkeit geprüft','Überprüfen Sie regelmäßig mit geeigneten Prüfverfahren die Integrität und Vollständigkeit gespeicherter Sicherungskopien und untersuchen Sie Fehler. Bestätigen Sie, dass betroffene Kopien bei Bedarf repariert oder ersetzt werden. Geprüft wird das gespeicherte Material; dies ersetzt keinen Wiederherstellungstest und belegt nicht, dass ein Dienst mit den wiederhergestellten Daten betrieben werden kann.','Integritäts- und Vollständigkeitsprüfungen, festgestellte Fehler, Aufzeichnungen zu betroffenen Kopien und Nachweise einer erfolgreichen Korrektur oder Ersetzung.','Beschädigte oder unvollständige Sicherungsinhalte werden als nutzbar angesehen, können aber die zur Wiederherstellung benötigten Daten, Konfigurationen oder Metadaten nicht bereitstellen.','C-VERIFY · Wiederherstellungsnachweis, Schulung und Planübungen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C33.1','Die Wiederherstellung aus Sicherungskopien wird anhand der Wiederherstellungspunktziele (Recovery Point Objectives, RPO) getestet','Stellen Sie in geplanten, risikogerechten Abständen ausgewählte Daten und Systeme aus Sicherungskopien wieder her und überprüfen Sie Nutzbarkeit, Vollständigkeit und den wiederhergestellten Datenstand anhand des festgelegten Wiederherstellungspunktziels (Recovery Point Objective, RPO). Dokumentieren Sie die verstrichene Wiederherstellungszeit als Eingangsgröße für die Validierung des RTO auf Dienstebene sowie Fehler und Korrekturmaßnahmen. Ein erfolgreicher Datensicherungsauftrag belegt keine erfolgreiche Wiederherstellung, und ein isolierter Wiederherstellungstest weist für sich allein nicht nach, dass der gesamte Dienst sein RTO einhält.','Wiederherstellungsszenarien und Abnahmekriterien; Zeitstempel der wiederhergestellten Datenstände und Vergleiche mit dem RPO; Prüfungen der Nutzbarkeit und Vollständigkeit; gemessene Wiederherstellungsdauern; Fehler, Korrekturmaßnahmen und Ergebnisse erneuter Tests.','Eine Wiederherstellung kann keine vollständigen, nutzbaren Daten zum erforderlichen Wiederherstellungspunkt rekonstruieren. Dadurch entstehen Datenverluste über das vereinbarte RPO hinaus.','C-VERIFY · Wiederherstellungsnachweis, Schulung und Planübungen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C33.4','Failover-Tests bestätigen, dass redundante Ressourcen übernehmen können','Testen Sie die geplante Umschaltung von primären Ressourcen auf ihre redundanten Alternativen unter realistischen Ausfallbedingungen. Prüfen Sie, ob Kapazität, Konnektivität und abhängige Dienste weiterhin ausreichend sind, und dokumentieren und beheben Sie fehlgeschlagene Umschaltungen. Bewertet wird die Übernahme der Diensterbringung, nicht der Wiederaufbau eines Systems aus einer Sicherungskopie. Wenden Sie diese Kontrolle auf die Redundanz an, die das Konzept zur Betriebsfortführung erfordert.','Failover-Szenarien, Umschaltprotokolle, Prüfungen der Dienste und Abhängigkeiten beim Betrieb mit den alternativen Ressourcen, Kapazitätsergebnisse und Behebung von Fehlern.','Bereitschaftsressourcen sind vorhanden, übernehmen jedoch nicht oder können den Dienst nicht tragen, wenn die primären Ressourcen nicht verfügbar sind.','C-VERIFY · Wiederherstellungsnachweis, Schulung und Planübungen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C33.3','Übungen zur Betriebsfortführung und Wiederherstellung testen die Wiederherstellungszeitziele der Dienste (RTO)','Üben Sie eine realistische Unterbrechung von der Aktivierung der Betriebsfortführung über die Wiederherstellung bis zur Rückkehr zum regulären Betrieb. Überprüfen Sie das vorübergehende Dienstleistungsniveau und messen Sie die durchgängige Wiederherstellung des Dienstes anhand des festgelegten Wiederherstellungszeitziels (Recovery Time Objective, RTO), einschließlich der Abhängigkeiten von Mitarbeitenden, Lieferanten und Systemen. Ziehen Sie bei einer Wiederherstellung mit Datenverlust auch die Nachweise zur RPO-Überprüfung heran. Überprüfen Sie Pläne in geplanten Abständen und nach erheblichen Sicherheitsvorfällen oder relevanten wesentlichen Änderungen; arbeiten Sie gewonnene Erkenntnisse ein und verifizieren Sie Korrekturmaßnahmen.','Durchgängige Übungsszenarien und Teilnahmeaufzeichnungen; gemessene Wiederherstellungszeiten der Dienste im Vergleich zum RTO; Ergebnisse zum vorübergehenden Dienstleistungsniveau; relevante RPO-Nachweise; überarbeitete Pläne und verifizierte Korrekturmaßnahmen.','Die durchgängige Wiederherstellung überschreitet das RTO des Dienstes, weil Abhängigkeiten, Übergaben oder das Zusammenspiel der Wiederherstellungsschritte trotz Tests einzelner Komponenten nicht funktionieren.','C-VERIFY · Wiederherstellungsnachweis, Schulung und Planübungen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C32.8','Krisenübungen testen Führungsentscheidungen und Kommunikation','Testen Sie anhand realistischer Krisenszenarien die Aktivierung, Entscheidungsbefugnisse, Koordination und Kommunikation, wenn reguläre Abläufe unter Druck stehen. Überprüfen und aktualisieren Sie den Krisenplan gemäß den anwendbaren Anforderungen an regelmäßige oder durch Sicherheitsvorfälle bzw. Änderungen ausgelöste Überprüfungen. Bewerten Sie hier die Krisenführung, ohne technische Wiederherstellungstests doppelt zu erfassen; eine gemeinsame Übung kann Nachweise für beide unterschiedlichen Ergebnisse liefern.','Krisenszenarien, Beteiligung der Leitung, Entscheidungs- und Kommunikationsaufzeichnungen, Überprüfungsergebnisse, aktualisierte Regelungen und Nachverfolgung von Schwachstellen.','Die Leitung kann während einer schwerwiegenden Unterbrechung dringende Entscheidungen nicht koordinieren oder nicht wirksam kommunizieren, obwohl ein schriftlicher Krisenplan vorliegt.','C-VERIFY · Wiederherstellungsnachweis, Schulung und Planübungen','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('REC-METRIC','Tatsächliche Wiederherstellungszeiten werden gemessen und überprüft','Erfassen Sie die Zeit von der Unterbrechung eines Dienstes bis zu seiner verifizierten Wiederherstellung nach einheitlichen Regeln für Beginn und Ende. Berechnen Sie für vergleichbare tatsächliche Ereignisse die mittlere Wiederherstellungszeit (mean time to recovery), indem Sie die gesamte Wiederherstellungszeit durch die Anzahl der Ereignisse mit abgeschlossener Wiederherstellung teilen; betrachten Sie Dienste und Szenarien mit wesentlich unterschiedlichen Wiederherstellungserwartungen getrennt. Prüfen Sie neben dem Durchschnitt auch jedes Ereignis anhand seines RTO, untersuchen Sie Überschreitungen und verfolgen Sie Verbesserungen nach. Halten Sie Übungsergebnisse von Statistiken tatsächlicher Ereignisse getrennt. Wenn keine tatsächlichen Ereignisse vorliegen, bewerten Sie die Messbereitschaft und die bei Tests erfassten Zeiten; verlangen Sie keinen erfundenen Durchschnitt und weisen Sie keine mittlere Wiederherstellungszeit von null aus. Das Handbuch verwendet die Abkürzung MTTR ausschließlich für „mean time to remediate“; die Wiederherstellungsgröße wird deshalb hier ausgeschrieben statt abgekürzt.','Definierte Grenzen der Zeitmessung und Abgrenzung vergleichbarer Ereignisse; Ereigniszeitstempel und Abnahmeaufzeichnungen; reproduzierbare Berechnung der mittleren Wiederherstellungszeit mit Stichprobengröße; einzelne RTO-Vergleiche; Untersuchungs- und Verbesserungsaufzeichnungen. Wenn keine Ereignisse eingetreten sind: vorbereitete Messmethode und gesondert gekennzeichnete Übungsergebnisse.','Wiederkehrende Wiederherstellungsverzögerungen oder dienstspezifische RTO-Überschreitungen bleiben durch unvollständige Messungen oder irreführende Durchschnittswerte verborgen, sodass Verbesserungsmaßnahmen die tatsächlichen Engpässe verfehlen.','C-MEASURE · Messung und Verbesserung der Wiederherstellungsleistung','Business Continuity & Wiederherstellung','Business continuity & recovery'),
  ('C51.5','Die Einrichtung legt fest, wie die Lieferantensicherheit gesteuert wird','Legen Sie fest, wer für die Lieferantensicherheit verantwortlich ist, wie Lieferanten bewertet, vertraglich eingebunden und überwacht werden und wie Lieferantenbeziehungen geordnet beendet werden. Wenden Sie diese Regeln entsprechend den Risiken der gelieferten Produkte und erbrachten Dienste an.','Richtlinie zur Sicherheit der Lieferkette, benannte Verantwortliche und Aufzeichnungen, die die Anwendung der Regeln in tatsächlichen Lieferantenbeziehungen zeigen.','Zwischen Beschaffung, Dienstverantwortlichen und Sicherheitsteams entstehen Zuständigkeitslücken bei der Lieferantensicherheit, sodass während der gesamten Beziehung erhebliche Risiken fortbestehen.','D-REL · Lieferanten, Verantwortlichkeiten und Abhängigkeiten','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C51.1','Die Einrichtung führt ein aktuelles Lieferanten- und Diensteregister','Erfassen Sie relevante direkte Lieferanten, ihre Kontaktdaten sowie die von ihnen bereitgestellten ICT-Produkte, -Dienste oder -Prozesse. Stellen Sie fest, welche betrieblichen Dienste von jedem Lieferanten abhängen, und aktualisieren Sie das Register bei Änderungen der Beziehung.','Lieferantenregister mit Kontaktdaten, gelieferten Produkten bzw. erbrachten Diensten, Verknüpfungen zu betrieblichen Diensten und Abgleich mit Beschaffungsaufzeichnungen.','Ein nicht erfasster Lieferant oder eine nicht erfasste Dienstabhängigkeit wird bei der Vorfallskoordination und Sicherheitsüberwachung übersehen. Dadurch verzögern sich Maßnahmen, wenn dieser Lieferant ausfällt oder kompromittiert wird.','D-REL · Lieferanten, Verantwortlichkeiten und Abhängigkeiten','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('SUP-RESP','Sicherheitsverantwortlichkeiten sind zwischen der Einrichtung und dem Lieferanten vereinbart (Gilt, wenn Sicherheitsverantwortlichkeiten mit einem Lieferanten geteilt werden.)','Vereinbaren Sie für Dienste mit geteilten Sicherheitsaufgaben, welche Partei jede relevante Aufgabe übernimmt, etwa das Einspielen von Patches, Datensicherungen, Zugriffsverwaltung, Protokollierung und Reaktion auf Sicherheitsvorfälle. Definieren Sie Übergaben und überprüfen Sie, dass keine notwendige Aufgabe ohne Zuständigkeit bleibt. (Gilt, wenn Sicherheitsverantwortlichkeiten mit einem Lieferanten geteilt werden.)','Dienstspezifische Verantwortlichkeitsmatrix oder gleichwertige vereinbarte Aufgabenverteilung, Bestätigung durch den Lieferanten und Aufzeichnungen, die die Zuständigkeit bei operativen Übergaben bestätigen.','R1: Jede Partei geht davon aus, dass die andere eine notwendige Sicherheitsaufgabe erfüllt. Dadurch bleiben Systeme ungepatcht, unüberwacht oder ohne nutzbare Sicherungskopien. R2: Unklare Übergaben verzögern die Eindämmung oder Wiederherstellung, während Einrichtung und Lieferant darüber streiten, wer handeln muss.','D-REL · Lieferanten, Verantwortlichkeiten und Abhängigkeiten','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C51.2','Die Einrichtung bestimmt, welche Lieferanten für ihre Dienste kritisch sind','Bewerten Sie für jeden relevanten Lieferanten, welche Folgen dessen Ausfall oder Kompromittierung für den Betrieb, die Informationen und die Wiederherstellung hätte. Entscheiden Sie anhand des Ergebnisses, wie eingehend der Lieferant bewertet und überwacht werden muss.','Bewertungen der Lieferantenkritikalität mit Auswirkungen auf Dienste, Wiederherstellungsabhängigkeiten und daraus folgenden Überwachungsanforderungen.','Der Ausfall oder die Kompromittierung eines Lieferanten beeinträchtigt einen prioritären Dienst stärker als erwartet, weil seine betrieblichen Abhängigkeiten und Wiederherstellungsabhängigkeiten unterschätzt wurden.','D-REL · Lieferanten, Verantwortlichkeiten und Abhängigkeiten','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C51.3','Die Einrichtung prüft, auf welche Systeme und Daten Lieferanten zugreifen können','Ermitteln Sie Lieferantenkonten, Fernverbindungen, Berechtigungen und zugängliche Informationen. Vergleichen Sie die erfassten Zugriffsmöglichkeiten mit den tatsächlichen Berechtigungen und leiten Sie unnötige oder ungeklärte Zugriffe zur Korrektur an die Zugriffsverwaltung weiter.','Aufzeichnungen zu Lieferantenzugriffen, tatsächliche Konto- und Verbindungslisten sowie Nachweise, dass Abweichungen behoben wurden.','R1: Unbekannte oder übermäßige Lieferantenzugriffe werden genutzt, um Informationen der Einrichtung zu erlangen. R2: Ein kompromittiertes Lieferantenkonto oder eine kompromittierte Verbindung ermöglicht unbefugte Änderungen an internen Systemen.','D-REL · Lieferanten, Verantwortlichkeiten und Abhängigkeiten','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C51.4','Die Einrichtung bewertet die Abhängigkeit von einzelnen Lieferanten und gemeinsam genutzten Plattformen','Ermitteln Sie Dienste, die gemeinsam ausfallen könnten, weil sie von einem einzigen Lieferanten oder einer einzigen Plattform abhängen. Bewerten Sie Hindernisse für einen Lieferantenwechsel, etwa inkompatible Datenformate oder fehlendes Fachwissen, und entscheiden Sie, wie untragbare Abhängigkeiten verringert werden sollen.','Analyse gemeinsamer Abhängigkeiten, Einschränkungen bei Wechsel oder Ausstieg und dokumentierte Behandlungsentscheidungen; mehrere Lieferanten sind nicht automatisch erforderlich.','R1: Der Ausfall eines Lieferanten oder einer gemeinsam genutzten Plattform unterbricht mehrere abhängige Dienste gleichzeitig. R2: Anbieterbindung oder der Verlust internen Wissens verhindert einen rechtzeitigen Lieferantenwechsel und verlängert die Unterbrechung.','D-REL · Lieferanten, Verantwortlichkeiten und Abhängigkeiten','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C49.4','Die Einrichtung wendet bei der Lieferantenauswahl Sicherheitskriterien an','Vergleichen Sie potenzielle Lieferanten vor der Auswahl anhand festgelegter Sicherheits- und Resilienzanforderungen. Dokumentieren Sie, warum der ausgewählte Lieferant geeignet ist und wie mit gegebenenfalls akzeptierten Lücken umgegangen wird.','Sicherheitsbezogene Auswahlkriterien, bewertete Lieferantenangebote, Freigabe der Auswahl und begründeter Umgang mit Lücken.','Ein Lieferant wird ausgewählt, der begründete Cybersicherheits- oder Resilienzanforderungen nicht erfüllen kann. Dadurch ist die Einrichtung vermeidbaren Risiken ausgesetzt oder muss einen kostspieligen Lieferantenwechsel unter eingeschränkten Bedingungen vornehmen.','D-ASSESS · Lieferantenbewertung und Auswahl geeigneter Dienste','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C50.1','Die Einrichtung nutzt relevante Erkenntnisse aus EU-Risikobewertungen der Lieferketten (Gilt, wenn eine relevante Bewertung nach NIS2 Art. 22(1) vorliegt.)','Prüfen Sie, ob koordinierte EU-Bewertungen Risiken aufzeigen, die für die Lieferanten, Produkte oder Dienste der Einrichtung relevant sind. Beziehen Sie anwendbare Erkenntnisse in Entscheidungen zur Lieferantensicherheit ein und dokumentieren Sie, warum Erkenntnisse anwendbar oder nicht anwendbar sind. (Gilt, wenn eine relevante Bewertung nach NIS2 Art. 22(1) vorliegt.)','Relevanzprüfung, anwendbare Erkenntnisse aus EU-Bewertungen und Nachweise der daraus folgenden Lieferanten- und Sicherheitsentscheidungen.','Eine Lieferantenentscheidung beruht auf veralteten Annahmen und lässt ein erhebliches Lieferkettenrisiko unbehandelt, obwohl eine relevante koordinierte EU-Bewertung dieses aufgezeigt hat.','D-ASSESS · Lieferantenbewertung und Auswahl geeigneter Dienste','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C49.2','Die Einrichtung bewertet die Sicherheitspraktiken der Lieferanten und die Zuverlässigkeit ihrer Produkte','Bewerten Sie, ob die Sicherheitspraktiken des Lieferanten sowie die Qualität und Resilienz seiner Produkte oder Dienste den Anforderungen der Einrichtung entsprechen. Beziehen Sie, soweit relevant, ein, wie der Lieferant Software sicher entwickelt und pflegt; wenden Sie dies auch auf beschaffte Software an, nicht nur auf ausgelagerte Entwicklungsprojekte.','Lieferantenbewertung, relevante Nachweise zur Vertrauenswürdigkeit sowie zu Produkten und Diensten und gegebenenfalls eine Bewertung der Praktiken zur sicheren Entwicklung.','R1: Ein Lieferantenprodukt oder eine Betriebspraxis setzt anvertraute Informationen unbefugtem Zugriff aus. R2: Ein ungeeigneter Lieferantendienst bietet nicht die von der Einrichtung benötigte Verfügbarkeit oder Wiederherstellbarkeit. R3: Schwache Entwicklungspraktiken des Lieferanten bringen ausnutzbare Fehler oder kompromittierte Komponenten in beschaffte oder gewartete Systeme ein.','D-ASSESS · Lieferantenbewertung und Auswahl geeigneter Dienste','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('SUP-LOC','Lieferantenstandorte werden auf Sicherheits- und Betriebsfortführungsrisiken bewertet (Gilt, wenn Betriebs- oder Informationsverarbeitungsstandorte von Lieferanten die Sicherheit oder Betriebsfortführung wesentlich beeinflussen können.)','Ermitteln Sie die Länder oder Regionen, in denen relevante Lieferantendienste betrieben und Informationen der Einrichtung verarbeitet oder gespeichert werden, einschließlich der Wiederherstellungsstandorte. Bewerten Sie, ob regionale Ausfälle, unterbrochene Verbindungen, Instabilität oder gemeinsame Standortabhängigkeiten den Dienst unterbrechen oder Informationen kompromittieren könnten. Vereinbaren Sie eine Vorabbenachrichtigung über wesentliche Standortänderungen, damit deren Auswirkungen vor der Verlagerung bewertet werden können. Dies ist keine pauschale Anforderung, Informationen in der EU zu halten. (Gilt, wenn Betriebs- oder Informationsverarbeitungsstandorte von Lieferanten die Sicherheit oder Betriebsfortführung wesentlich beeinflussen können.)','Aufzeichnungen zu relevanten Standorten für Diensterbringung, Verarbeitung, Speicherung und Wiederherstellung; Bewertung standortspezifischer und gemeinsamer Abhängigkeiten; vereinbarte Bedingungen zur Vorabbenachrichtigung; Bewertungen tatsächlicher wesentlicher Standortänderungen.','R1: Eine regionale Strom-, Kommunikations- oder sonstige Störung beeinträchtigt sowohl den primären Dienst als auch seine Wiederherstellungsvorkehrungen, weil die gemeinsame Standortabhängigkeit nicht erkannt wurde. R2: Ein Lieferant verlagert die Diensterbringung oder Informationsverarbeitung ohne vorherige Bewertung. Dadurch werden Sicherheitsannahmen ungültig oder vereinbarte Wiederherstellungsvorkehrungen unwirksam.','D-ASSESS · Lieferantenbewertung und Auswahl geeigneter Dienste','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C49.1','Die Einrichtung behandelt bei ihren Lieferanten festgestellte Sicherheitsschwächen','Bewerten Sie, wie sich festgestellte Schwächen eines Lieferanten, seiner Produkte oder Dienstleistungen auf die Einrichtung auswirken könnten. Entscheiden Sie über notwendige Schutz- oder Korrekturmaßnahmen und verfolgen Sie diese nach; verlangen Sie beispielsweise stärkere Schutzmaßnahmen, bevor Sie einem Fernwartungsanbieter privilegierten Zugriff gewähren. Das technische Einspielen von Patches bleibt Bestandteil des Schwachstellenmanagements.','Lieferantenspezifische Feststellungen, Folgenabschätzung, erforderliche Schutzmaßnahmen oder vertragliche Bedingungen, zugewiesene Maßnahmen und deren Nachverfolgung.','Eine festgestellte lieferantenspezifische Sicherheitsschwäche bleibt bei Akzeptanz- oder Korrekturentscheidungen unbehandelt und ermöglicht unbefugten Zugriff, Änderungen an den Systemen der Einrichtung oder eine Störung ihrer Dienstleistungen.','D-ASSESS · Lieferantenbewertung und Auswahl geeigneter Dienste','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C52.1','Lieferantenverträge regeln Sicherheit, Vorfallbenachrichtigung und Schwachstellenbehandlung','Die Einrichtung vereinbart mit Lieferanten durchsetzbare, risikogerechte Sicherheitsanforderungen. Nehmen Sie die Pflicht auf, die Einrichtung ohne unangemessene Verzögerung über Vorfälle zu benachrichtigen, die ihre Systeme bedrohen, sowie die Verantwortlichkeiten für die Behandlung relevanter Schwachstellen. Legen Sie Ansprechpersonen und die erforderlichen Informationen fest; diese Regelungen unterstützen die eigenen Reaktionsmaßnahmen und gesetzlichen Meldepflichten der Einrichtung, ersetzen sie jedoch nicht.','Unterzeichnete Sicherheitsklauseln und Service-Level-Vereinbarungen, die erforderliche Schutzmaßnahmen, Ansprechpersonen und Benachrichtigungspflichten bei Vorfällen sowie Verantwortlichkeiten und Eskalationsregelungen für die Schwachstellenbehandlung festlegen.','R1: Ein Lieferant bestreitet oder unterlässt notwendige Sicherheitsarbeiten, weil verbindliche Verantwortlichkeiten und Leistungserwartungen unklar sind, sodass die Einrichtung Schutz oder Korrekturen nicht rechtzeitig erwirken kann. R2: Ein Lieferant verzögert relevante Vorfallinformationen oder hält sie zurück, wodurch sich die Reaktion der Einrichtung verzögert oder sie eine anwendbare gesetzliche Meldefrist versäumt. R3: Eine die Einrichtung betreffende Schwachstelle bleibt ausnutzbar, während Lieferant und Kunde über Zuständigkeiten, Benachrichtigungen oder Erwartungen an die Behebung streiten.','D-CON · Vereinbarung und Prüfung von Sicherheitsanforderungen','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C52.3','Die Einrichtung sichert sich Rechte zur Prüfung von Lieferanten oder zum Erhalt von Prüfberichten','Vereinbaren Sie einen praktikablen Weg, um durch Prüfungsrechte oder relevante Prüfberichte Nachweise zur Sicherheit der bezogenen Dienstleistung zu erhalten. Eine Vor-Ort-Prüfung jedes Lieferanten ist nicht erforderlich; der vereinbarte Zugang muss eine aussagekräftige Überprüfung ermöglichen.','Vertragliche Prüfungsrechte oder Rechte auf Berichterhalt, aus denen die erfasste Dienstleistung, die zugänglichen Nachweise und die relevanten Zugangsbedingungen hervorgehen.','Die Einrichtung kann keine für den Geltungsbereich relevanten Nachweise zur Sicherheitsbeurteilung erhalten, sodass wesentliche Schwächen des Lieferanten unentdeckt oder ungelöst bleiben.','D-CON · Vereinbarung und Prüfung von Sicherheitsanforderungen','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C52.7','Die Einrichtung legt Sicherheitsbedingungen für die Untervergabe durch Lieferanten fest','Legen Sie fest, ob und unter welchen Bedingungen Lieferanten Arbeiten an Unterauftragnehmer vergeben dürfen. Ist eine Untervergabe zulässig, verlangen Sie, dass relevante Sicherheitsverpflichtungen auch für Unterauftragnehmer gelten, und beschaffen Sie Nachweise dafür, dass diese Bedingungen erfüllt werden.','Genehmigungen und Beschränkungen für die Untervergabe, relevante Unterlagen zu Unterauftragnehmern und Nachweise der geltenden Sicherheitsverpflichtungen.','R1: Ein Unterauftragnehmer erhält oder verarbeitet Informationen der Einrichtung ohne die Schutzmaßnahmen, die vom direkten Lieferanten erwartet werden. R2: Eine nicht offengelegte oder unzureichend kontrollierte Abhängigkeit von einem Unterauftragnehmer unterbricht die vertraglich vereinbarte Dienstleistung. R3: Ein Unterauftragnehmer bringt schädliche oder kompromittierte Komponenten in das gelieferte Produkt oder die Dienstleistung ein und ermöglicht dadurch eine Kompromittierung der Systeme der Einrichtung.','D-CON · Vereinbarung und Prüfung von Sicherheitsanforderungen','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C52.5','Die Einrichtung überprüft erforderliche Hintergrundüberprüfungen des Lieferantenpersonals (Gilt, soweit die Rolle und das anwendbare Recht Hintergrundüberprüfungen rechtfertigen.)','Vereinbaren Sie für sensible Rollen beim Lieferanten, welche rechtmäßigen Hintergrundüberprüfungen erforderlich sind, und bestätigen Sie deren Abschluss vor dem Einsatz. Holen Sie verhältnismäßige Bestätigungen ein, statt unnötige personenbezogene Unterlagen anzufordern. (Gilt, soweit die Rolle und das anwendbare Recht Hintergrundüberprüfungen rechtfertigen.)','Rollenbezogene Anforderungen an Hintergrundüberprüfungen und rechtmäßig eingeholte Abschlussbestätigungen für das in den betreffenden Rollen eingesetzte Personal.','R1: Einer Person, bei der relevante und rechtmäßig feststellbare Bedenken hinsichtlich ihrer Vertrauenswürdigkeit bestehen, werden sensible Aufgaben beim Lieferanten übertragen, und sie missbraucht den dadurch gewährten Zugang. R2: Durch unverhältnismäßige Hintergrundüberprüfungen werden unnötige personenbezogene Informationen über das Lieferantenpersonal erhoben oder offengelegt.','D-CON · Vereinbarung und Prüfung von Sicherheitsanforderungen','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C52.4','Die Einrichtung überprüft, ob das Lieferantenpersonal über die erforderlichen Sicherheitskompetenzen verfügt','Definieren Sie die Sicherheitskompetenzen und rollenspezifischen Schulungen, die das an der Dienstleistung mitwirkende Lieferantenpersonal benötigt. Beschaffen Sie verhältnismäßige Nachweise dafür, dass es diese Anforderungen erfüllt; verlangen Sie Zertifikate nur, wenn dies gerechtfertigt ist.','Vereinbarte Rollen- und Kompetenzanforderungen sowie verhältnismäßige Qualifikations- oder Schulungsnachweise für das eingesetzte Lieferantenpersonal.','Das Lieferantenpersonal macht sicherheitsrelevante Fehler im Betrieb oder reagiert nicht angemessen, weil ihm die für seine zugewiesenen Aufgaben erforderlichen Kompetenzen fehlen.','D-CON · Vereinbarung und Prüfung von Sicherheitsanforderungen','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('SUP-AUTH','Die Einrichtung überprüft die Authentizität und Integrität kritischer ICT-Lieferungen','Überprüfen Sie vor der Nutzung kritischer beschaffter Hardware oder Software, dass diese aus einer vertrauenswürdigen Quelle stammt und keine Hinweise auf Austausch oder Manipulation aufweist. Wählen Sie die Prüfungen entsprechend dem Produktrisiko aus, beispielsweise die Bestätigung einer autorisierten Bezugsquelle, eine Herstellerprüfung, digitale Signaturen oder die physische Prüfung der Lieferung. Damit werden Herkunft und Integrität des gelieferten Produkts geprüft, nicht die Funktionsfähigkeit seiner Sicherheitsfunktionen oder die Authentizität späterer Patches.','Risikobasierte Abnahmekriterien, Unterlagen zu vertrauenswürdigen Bezugsquellen und produktgerechte Authentizitäts- und Integritätsprüfungen mit Aufzeichnungen zu zurückgewiesenen oder verdächtigen Lieferungen und deren weiterer Behandlung.','R1: Gefälschte, ausgetauschte oder böswillig veränderte Hardware oder Software wird in betrieblich genutzte Systeme übernommen und ermöglicht unbefugten Zugriff oder Manipulation. R2: Eine unzuverlässige gefälschte Komponente fällt im Betrieb aus und stört eine kritische Dienstleistung.','D-DELIVERY · Prüfung von ICT-Lieferungen vor dem Betriebseinsatz','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('TRN-12','Die Einrichtung stellt sicher, dass relevante Lieferanten ihre Sicherheits- und Melderegeln verstehen','Vermitteln Sie die für die bezogene Dienstleistung relevanten Cybersicherheitsrisiken, Praktiken der Cyberhygiene und Meldewege. Prüfen Sie, ob der Lieferant diese versteht und anwendet, und bieten Sie bei Bedarf geeignete Sensibilisierungsmaßnahmen an. Dies betrifft gemeinsame Arbeitsregeln, nicht fachliche Spezialqualifikationen.','Hinweise für Lieferanten und Kommunikationsaufzeichnungen, gegebenenfalls Teilnahme an Sensibilisierungsmaßnahmen sowie Nachweise des Verständnisses und der Anwendung.','Mitarbeitende des Lieferanten missachten die Erwartungen der Einrichtung an Cyberhygiene oder Meldungen, wodurch gemeinsam genutzte Informationen gefährdet werden oder die Eskalation verdächtiger Aktivitäten verzögert wird.','D-MON · Vermittlung von Regeln und Überwachung der Zusammenarbeit','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C53.1','Die Einrichtung prüft Zertifikate und Prüfberichte von Lieferanten, bevor sie sich darauf stützt','Überprüfen Sie, ob die Nachweise zur Sicherheitsbeurteilung die tatsächlich bezogene Lieferantenleistung und einen relevanten Zeitraum abdecken. Prüfen Sie Ausschlüsse und offene Feststellungen und entscheiden Sie anschließend, ob weitere Nachweise oder Korrekturmaßnahmen erforderlich sind; ein Zertifikat allein reicht nicht aus.','Dokumentierte Prüfungen von Geltungsbereich, Datumsangaben, Feststellungen und Ausschlüssen der Berichte oder Zertifikate sowie Entscheidungen über Folgemaßnahmen.','Ein Zertifikat oder Bericht, der sich auf die falsche Dienstleistung, den falschen Zeitraum oder den falschen Geltungsbereich bezieht, vermittelt falsche Sicherheit, sodass tatsächliche Schwächen des Lieferanten weiterhin akzeptiert und unbehandelt bleiben.','D-MON · Vermittlung von Regeln und Überwachung der Zusammenarbeit','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C53.2','Die Einrichtung bewertet Lieferanten bei Änderungen ihrer Sicherheitsleistung oder der Rahmenbedingungen erneut','Überprüfen Sie die Sicherheitsleistung der Lieferanten in geplanten, risikogerechten Abständen und nach wesentlichen Änderungen oder relevanten Vorfällen. Wenn Service-Level-Vereinbarungen bestehen, prüfen Sie die Berichte zu deren Umsetzung und die damit verbundenen Vorfälle, nicht nur aktuelle Zertifikate. Halten Sie fest, ob eine außerplanmäßige Überprüfung erforderlich ist, bewerten Sie veränderte Risiken und verfolgen Sie notwendige Schutz- oder Korrekturmaßnahmen nach.','Regelmäßige und ereignisgesteuerte Überprüfungen, Leistungs- und Sicherheitsberichte, Änderungs- oder Vorfallmitteilungen und nachverfolgte Korrekturmaßnahmen.','Eine Verschlechterung der Schutzmaßnahmen des Lieferanten oder veränderte Leistungsabhängigkeiten bleiben unbemerkt, sodass die Gefährdung durch Kompromittierung oder Unterbrechung über die ursprünglich akzeptierten Bedingungen hinaus zunimmt.','D-MON · Vermittlung von Regeln und Überwachung der Zusammenarbeit','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('SUP-EXIT-TEST','Die Einrichtung testet, ob kritische ausgelagerte Dienstleistungen übertragen werden können (Gilt für kritische ausgelagerte Dienstleistungen, bei denen die Beendigung der Lieferantenbeziehung eine Übertragung von Dienstleistungen oder Informationen erfordert.)','Testen Sie, bevor eine Beendigung der Lieferantenbeziehung notwendig wird, ob eine kritische ausgelagerte Dienstleistung tatsächlich an einen anderen Anbieter oder in eine interne Umgebung übertragen werden kann. Überprüfen Sie durch eine risikogerechte Übung oder einen technischen Test, ob die erforderlichen Informationen, Konfigurationen und Dokumentationen beschafft und genutzt werden können und ob wesentliche Betriebsabläufe fortgeführt werden können. Beseitigen Sie wesentliche Hindernisse und wiederholen Sie den Test, wenn Änderungen dies rechtfertigen. Eine Exportfunktion oder eine Ausstiegsklausel allein ist kein Nachweis dafür, dass die Übertragung funktioniert. (Gilt für kritische ausgelagerte Dienstleistungen, bei denen die Beendigung der Lieferantenbeziehung eine Übertragung von Dienstleistungen oder Informationen erfordert.)','Umfang und Szenario des Ausstiegstests, nutzbare Daten- und Konfigurationsexporte, gegebenenfalls Ergebnisse des Imports oder der Verarbeitung in einer alternativen Umgebung, Ergebnisse von Kontinuitätsübungen, festgestellte Hindernisse und Aufzeichnungen zu Korrekturmaßnahmen.','R1: Der Ausfall eines Lieferanten oder die Vertragsbeendigung führt dazu, dass die Einrichtung exportierte Informationen nicht nutzen oder die Dienstleistung nicht anderweitig wiederherstellen kann, weil die Übertragbarkeit nie nachgewiesen wurde. R2: Unerkannte Abhängigkeiten von Konfigurationen, Lizenzen, Fachkenntnissen oder Integrationen verlängern den Lieferantenwechsel über die für die Dienstleistung tolerierbare Unterbrechungsdauer hinaus.','D-EXIT · Sichere Beendigung der Zusammenarbeit','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('C52.8','Die Einrichtung erhält ihre Informationen zurück und beendet den Lieferantenzugang bei Vertragsende','Vereinbaren und überprüfen Sie die Rückgabe oder sichere Entsorgung der beim ausscheidenden Lieferanten vorhandenen Informationen entsprechend dem Vertrag und den anwendbaren Anforderungen. Entziehen Sie nicht mehr benötigte Zugänge und bestätigen Sie eine gegebenenfalls erforderliche Dienstleistungsübergabe, damit die Beendigung der Beziehung keine Daten gefährdet oder den Betrieb unterbricht.','Ausstiegsbedingungen, abgeschlossene Übergabe, Bestätigungen über die Rückgabe oder Löschung von Informationen und überprüfte Entfernung von Konten, Zugangsdaten und Verbindungen.','R1: Ein ehemaliger Lieferant behält nutzbare Zugänge oder Informationen und greift später unbefugt auf Daten der Einrichtung zu, verändert sie oder legt sie offen. R2: Eine unvollständige Dienstleistungsübergabe führt dazu, dass Informationen oder eine abhängige Dienstleistung während des Lieferantenausstiegs nicht verfügbar sind.','D-EXIT · Sichere Beendigung der Zusammenarbeit','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('ENV-RISK','Physische und umgebungsbedingte Risiken werden bewertet','Bewerten Sie aktuelle und vernünftigerweise vorhersehbare physische und umgebungsbedingte Bedrohungen für relevante ICT-Systeme, deren Standorte und unterstützende Versorgungseinrichtungen. Stellen Sie fest, ob der Klimawandel für die Informationssicherheit und Kontinuität relevant ist, und berücksichtigen Sie dabei lokale Hochwassergefährdung, extreme Hitze, Stürme und damit verbundene Störungen der Stromversorgung oder Kühlung. Nutzen Sie standortspezifische Informationen und relevante Anforderungen interessierter Parteien; dokumentieren Sie die Begründung, wenn der Klimawandel nicht relevant ist. Verknüpfen Sie festgestellte Risiken mit dem bestehenden Risikoregister sowie Schutz- und Wiederherstellungsentscheidungen und aktualisieren Sie die Bewertung bei wesentlichen Änderungen der Bedingungen. Dies ist keine Bewertung von Emissionen oder allgemeinen Umweltauswirkungen.','Dokumentierte Schlussfolgerung zur Klimarelevanz; standortspezifische Hochwasser- und Gefahreninformationen sowie relevante Projektionen, Bewertung der Abhängigkeiten von Versorgungseinrichtungen und Kühlung, Verknüpfungen zum Risikoregister, gegebenenfalls Anforderungen interessierter Parteien sowie Überprüfungs- und Behandlungsentscheidungen. Nutzen Sie den Bewertungsprozess aus T03 erneut, statt einen gesonderten Bericht zu verlangen.','R1: Veränderungen der Hochwasser-, Hitze- oder Sturmgefährdung werden übersehen und bestehende Schutzmaßnahmen reichen nicht mehr aus, was zu ICT-Schäden, Informationsverlust oder Dienstleistungsunterbrechungen führt. R2: Physische und umgebungsbedingte Risiken für die unterstützende Stromversorgung, Kühlung oder Wiederherstellungsstandorte werden unterschätzt, sodass Primär- und Wiederherstellungsfähigkeit gleichzeitig ausfallen. R3: Gefährdungen durch physischen Zugang, Diebstahl oder Manipulation an einem ICT-Standort werden übersehen, sodass sensible Informationen und Geräte nicht angemessen vor unbefugten Eingriffen geschützt sind.','I-PHY-RISK · Bewertung physischer und umweltbedingter Risiken','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('PHY-ZONE','Server- und Netzwerkräume verfügen über geschützte physische Begrenzungen (Gilt, wenn die Einrichtung Serverräume, Netzwerkräume oder vergleichbare geschützte Gerätebereiche betreibt.)','Definieren Sie die Begrenzung jedes geschützten Server- oder Netzwerkbereichs und untersuchen Sie Türen, Wände, Fenster sowie zugängliche Wege über Decken und Böden auf Möglichkeiten zur Umgehung der Zutrittskontrollen. Sorgen Sie für eine risikogerechte Trennung von öffentlichen, gemeinsam genutzten oder Anlieferungsbereichen. Hier wird die physische Begrenzung geprüft, nicht die individuelle Zutrittsberechtigung. (Gilt, wenn die Einrichtung Serverräume, Netzwerkräume oder vergleichbare geschützte Gerätebereiche betreibt.)','Plan der geschützten Bereiche, Prüfung der Bereichsgrenzen und Aufzeichnungen über beseitigte Umgehungsmöglichkeiten.','R1: Eine eindringende Person umgeht die kontrollierte Tür über eine unzureichend geschützte Bereichsbegrenzung und erlangt Zugang zu Geräten oder Informationen. R2: Ein gemeinsam genutzter Bereich oder Anlieferungsbereich bietet einen unkontrollierten Zugang zu kritischen Gerätebereichen.','I-PHY-AREA · Geschützte Bereiche, Zutritt und sicheres Arbeiten','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('C46.1','Der physische Zutritt zu geschützten Bereichen ist beschränkt','Gestatten Sie den Zutritt zu Serverräumen, Netzwerkräumen und anderen geschützten Bereichen nur für einen autorisierten Zweck. Verwalten Sie Schlüssel und Karten, überprüfen Sie Zutrittsrechte regelmäßig und entziehen Sie diese, sobald sie nicht mehr benötigt werden. Autorisieren Sie Besuchende und Auftragnehmer und beaufsichtigen Sie sie risikogerecht; verhindern Sie den Zutritt durch unbeaufsichtigte Türen oder unkontrollierte Anlieferungswege.','Zutrittsgenehmigungen und deren Überprüfungen, Schlüssel- und Kartenverzeichnis, Besuchsgenehmigungen, beobachtete Türkontrollen und Aufzeichnungen über entzogene Zutrittsrechte. Die Vollständigkeit der Ein- und Austrittsaufzeichnungen wird unter PHY-ENTRY-LOG bewertet.','R1: Eine unbefugte Person betritt einen geschützten Bereich und stiehlt, beobachtet oder kopiert sensible Informationen. R2: Physische Manipulationen an Systemen oder Geräten unterbrechen Dienstleistungen oder verändern deren Betrieb.','I-PHY-AREA · Geschützte Bereiche, Zutritt und sicheres Arbeiten','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('PHY-ENTRY-LOG','Der Zutritt zu Serverräumen wird protokolliert und, soweit gerechtfertigt, durch Videoaufzeichnungen ergänzt (Gilt, wenn die Einrichtung Serverräume, Netzwerkräume oder vergleichbare geschützte Gerätebereiche betreibt.)','Erfassen Sie den Ein- und Austritt jeder Person in geschützte Geräteräume bzw. aus diesen, einschließlich Besuchender und Auftragnehmer, mit Identität, Raum und hinreichend verlässlichen Zeitangaben. Verwenden Sie individuelle Zutrittsmittel oder ein gleichwertiges kontrolliertes Verzeichnis. Soweit Kameraüberwachung gerechtfertigt ist, sorgen Sie für eine nutzbare Erfassung relevanter Zutrittspunkte oder Gerätebereiche, prüfen Sie die Bildqualität und überprüfen Sie den Abruf aufgezeichneter Aufnahmen. Schützen Sie Protokolle und Aufnahmen vor unbefugtem Zugriff oder Änderungen, legen Sie begründete Aufbewahrungs- und Löschregelungen fest und untersuchen Sie unvollständige oder unerklärte Aufzeichnungen. Beschränken Sie die Kameraerfassung auf notwendige Bereiche. Die Zutrittsprotokollierung bleibt auch dann anwendbar, wenn Kameras nicht gerechtfertigt sind; Aufnahmen ersetzen weder die verlässliche Nachvollziehbarkeit von Person, Raum und Zeit noch die unmittelbare Reaktion auf unbefugtes Eindringen nach C46.4. (Gilt, wenn die Einrichtung Serverräume, Netzwerkräume oder vergleichbare geschützte Gerätebereiche betreibt.)','Ein- und Austritts- sowie Besuchsaufzeichnungen mit Person, Raum und Zeit; Prüfungen der Zeitstempel und Vollständigkeit; soweit Kameras gerechtfertigt sind, Begründung des Erfassungsbereichs sowie Bildqualitäts- und Abruftests; abgesicherte Zugriffs- und Exportberechtigungen, begründete Aufbewahrungs- und Löschregelungen und untersuchte Abweichungen.','R1: Unbefugter oder unerklärter Zutritt lässt sich keiner Person oder Zeit zuordnen, weil Ein- und Austrittsaufzeichnungen für Serverräume fehlen, unvollständig sind oder nur auf gemeinsam genutzten Zutrittsmitteln beruhen. R2: Veränderte, vorzeitig gelöschte oder nicht zugängliche Zutrittsaufzeichnungen verhindern eine verlässliche Untersuchung physischer Eingriffe und die Rekonstruktion von Ereignissen. R3: Nicht erfasste Bereiche, Kameraausfälle oder unbrauchbare Bilder verhindern die Rekonstruktion unbefugten Zutritts oder physischer Eingriffe, wenn auf visuelle Nachweise vertraut wird. R4: Eine übermäßige Kameraerfassung oder unbefugter Zugriff auf Aufnahmen legt sensible Informationen oder identifizierbare Personen unnötig offen.','I-PHY-AREA · Geschützte Bereiche, Zutritt und sicheres Arbeiten','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('C46.4','Räumlichkeiten werden auf unbefugten physischen Zutritt überwacht','Betreiben Sie eine risikogerechte Überwachung auf unbefugtes physisches Eindringen für relevante Räumlichkeiten, einschließlich der Zutrittspunkte zu Serverräumen. Leiten Sie erkannte Ereignisse an eine handlungsfähige zuständige Person weiter und überprüfen Sie die Reaktionsregelungen, auch außerhalb der Arbeitszeiten. Wachdienste, Einbruchmeldeanlagen oder andere geeignete Vorkehrungen können eingesetzt werden; Kameras an jedem Ort sind nicht erforderlich.','Überwachungsumfang, Alarmweiterleitung und Reaktionsaufzeichnungen, Zugang zu Überwachungssystemen sowie Erkennungs- und Reaktionstests.','Eine eindringende Person bleibt lange genug unentdeckt, um Informationen zu stehlen oder Systeme zu manipulieren, bevor das zuständige Personal reagieren kann.','I-PHY-AREA · Geschützte Bereiche, Zutritt und sicheres Arbeiten','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('PHY-WORK','Regeln für sicheres Arbeiten in Server- und Netzwerkräumen sind festgelegt und werden eingehalten (Gilt, wenn Personal oder Auftragnehmer in geschützten Gerätebereichen arbeiten.)','Definieren Sie Regeln für Arbeiten innerhalb geschützter Geräteräume und setzen Sie sie durch: Sicherheitstüren geschlossen halten, Auftragnehmer soweit erforderlich beaufsichtigen, Fotografieren und Aufzeichnen auf autorisierte Zwecke beschränken, Speisen, Getränke und sachfremde Lagerung untersagen, Kühlungs- und Fluchtwege freihalten und den Raum nach Abschluss der Arbeiten sichern. Diese Regeln betreffen das Verhalten im Raum; Zutrittsautorisierung und Personalschulung werden gesondert bewertet. (Gilt, wenn Personal oder Auftragnehmer in geschützten Gerätebereichen arbeiten.)','Freigegebene Arbeitsanweisungen, Aufzeichnungen zur Beaufsichtigung von Auftragnehmern, Rauminspektionen und beobachtete Einhaltung der Regeln.','R1: Eine autorisierte Arbeitskraft legt Informationen offen oder ermöglicht unbefugten Zutritt, indem sie Arbeitsregeln für geschützte Bereiche missachtet. R2: Unsichere Arbeiten oder im Raum zurückgelassene Materialien behindern die Kühlung oder beschädigen Geräte im laufenden Betrieb und unterbrechen Dienstleistungen.','I-PHY-AREA · Geschützte Bereiche, Zutritt und sicheres Arbeiten','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('TRN-PHY','Relevantes Personal wird zur physischen Sicherheit geschult (Gilt für Personal, dessen Aufgaben geschützte Gerätebereiche betreffen.)','Unterweisen Sie Mitarbeitende und Auftragnehmer vor entsprechenden Arbeiten über die geltenden Zutritts-, Arbeits- und Notfallregeln, einschließlich der Stellen, die bei unbefugtem Eindringen, Rauch, Leckagen oder ausgefallener Kühlung zu alarmieren sind, und der Maßnahmen, zu denen sie befugt sind. Frischen Sie die Unterweisung bei Bedarf auf und überprüfen Sie das Verständnis. Die allgemeine Steuerung von Schulungen verbleibt in T06. (Gilt für Personal, dessen Aufgaben geschützte Gerätebereiche betreffen.)','Rollengerechte Anweisungen, Aufzeichnungen zu Erst- und Auffrischungsunterweisungen sowie praktische Überprüfungen oder Übungen, die zeigen, dass Meldewege und Handlungsbefugnisse verstanden wurden.','R1: Personal meldet ein physisches oder umgebungsbedingtes Warnzeichen nicht unverzüglich, wodurch Schäden oder Unterbrechungen eskalieren können. R2: Ungeschultes Personal handelt außerhalb seiner Kompetenz oder umgeht Schutzmaßnahmen des Raums und verursacht dadurch vermeidbare Gefährdungen oder Ausfälle.','I-PHY-AREA · Geschützte Bereiche, Zutritt und sicheres Arbeiten','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('PHY-ACCESS-TEST','Physische Zutrittskontrollen werden auf ihre Wirksamkeit getestet (Gilt für physische Zutrittskontrollen, die von der Einrichtung betrieben werden.)','Testen Sie physische Zutrittskontrollen in geplanten Abständen und nach relevanten wesentlichen Vorfällen oder Änderungen. Überprüfen Sie anhand autorisierter, risikogerechter Szenarien, dass unberechtigte oder widerrufene Zutrittsmittel zurückgewiesen werden und dass Umgehungswege oder das Hinterhergehen hinter einer berechtigten Person wie vorgesehen verhindert oder erkannt werden. Dokumentieren Sie Mängel und überprüfen Sie Korrekturmaßnahmen. Die Überprüfung von Zutrittsrechten allein zeigt nicht, dass Zutrittskontrollen funktionieren. Stimmen Sie Tests so ab, dass Menschen und die Dienstleistungsverfügbarkeit geschützt werden; verdeckte Penetrationstests sind nicht allgemeingültig vorgeschrieben. (Gilt für physische Zutrittskontrollen, die von der Einrichtung betrieben werden.)','Freigegebener Testumfang und Testszenarien, Ergebnisse von Tests zur Zutrittsverweigerung und Umgehung, festgestellte Mängel, zugewiesene Korrekturmaßnahmen und Nachweise erneuter Tests.','R1: Fehlerhafte Zutrittskontrollen ermöglichen einer unbefugten Person den Zugang zu geschützten Systemen, obwohl die Zutrittsberechtigungen scheinbar korrekt sind. R2: Ungeprüfte Änderungen lassen Umgehungswege unentdeckt, wodurch Geräte oder Informationen Diebstahl oder Eingriffen ausgesetzt sind.','I-PHY-AREA · Geschützte Bereiche, Zutritt und sicheres Arbeiten','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('PHY-SITING','Server und Netzwerkgeräte sind sicher aufgestellt und geschützt (Gilt, wenn die Einrichtung die physische Installation von ICT-Geräten kontrolliert.)','Platzieren und sichern Sie Geräte und Racks so, dass unbeabsichtigte Schäden, unbefugte Handhabung und blockierte Luftströme verhindert werden. Berücksichtigen Sie örtliche Leckagequellen, herabfallende Gegenstände und den Zugang zu Konsolen oder entnehmbaren Komponenten; schützen Sie bei Bedarf gemeinsam genutzte Racks. Hier werden die Aufstellung und der Schutz der Geräte geprüft, nicht die allgemeinen Brand- oder Einbruchschutzmaßnahmen des Raums. (Gilt, wenn die Einrichtung die physische Installation von ICT-Geräten kontrolliert.)','Aufstellungsplan für Geräte und Racks, physische Inspektion, Installationsanforderungen und behobene Mängel bei Aufstellung oder Schutz.','R1: Eine ungünstige Geräteaufstellung oder ein behinderter Luftstrom verursacht Überhitzung, Schäden oder einen Dienstleistungsausfall. R2: Frei zugängliche Konsolen, Komponenten oder ungesicherte Geräte ermöglichen unbefugte Einsichtnahme, Entnahme oder Manipulation.','I-PHY-EQUIP · Geräteschutz und Manipulationskontrollen','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('PHY-TAMPER-CHECK','Gefährdete ICT-Geräte werden auf physische Manipulationen überprüft (Gilt, wenn die Einrichtung Geräte kontrolliert, die einem wesentlichen Risiko physischer Manipulation ausgesetzt sind.)','Identifizieren Sie Geräte mit einer wesentlichen Gefährdung durch physische Manipulation und legen Sie risikobasierte Prüfintervalle und Prüfanlässe fest. Untersuchen Sie relevante Gehäuse, Komponenten und Verbindungen auf unerklärte Änderungen oder Anzeichen von Eingriffen und nutzen Sie gegebenenfalls Siegel oder dokumentierte Referenzzustände. Dokumentieren Sie die Ergebnisse und bearbeiten Sie Manipulationsverdachtsfälle im Rahmen der Vorfallreaktion unter Sicherung relevanter Nachweise. Hier werden Geräte während des Betriebs geprüft, nicht nur nach Wartungsarbeiten; eine routinemäßige Prüfung jedes Geräts ist nicht erforderlich. (Gilt, wenn die Einrichtung Geräte kontrolliert, die einem wesentlichen Risiko physischer Manipulation ausgesetzt sind.)','Risikobasiert festgelegter Geräteumfang, Prüfintervalle und Prüfanlässe, Aufzeichnungen zu Referenzzuständen oder Siegeln, soweit verwendet, abgeschlossene Prüfaufzeichnungen und untersuchte Abweichungen.','R1: Eine unbefugte physische Veränderung bleibt unbemerkt und ermöglicht Informationsdiebstahl oder Änderungen am Systembetrieb. R2: Unerklärte Änderungen an Komponenten oder Verbindungen bleiben unentdeckt, bis sie eine kritische Dienstleistung stören.','I-PHY-EQUIP · Geräteschutz und Manipulationskontrollen','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('C46.2','Schutzmaßnahmen begegnen physischen und umgebungsbedingten Gefahren','Nutzen Sie die dokumentierte Bewertung physischer und umgebungsbedingter Risiken (ENV-RISK), um Server- und Netzwerkräume angemessen zu schützen, beispielsweise durch Branderkennung und geeignete Löschmaßnahmen, Leckageschutz und die Vermeidung gefährlicher Lagerung, soweit die Bewertung dies erfordert. Die reguläre Regelung von Temperatur und Luftfeuchtigkeit wird unter PHY-CLIMATE bewertet. Weder eine bestimmte Löschtechnik noch eine bestimmte Gebäudegestaltung ist allgemeingültig vorgeschrieben. Überprüfen und testen Sie relevante Maßnahmen regelmäßig und nach wesentlichen Vorfällen oder Änderungen.','Bewertung der Standortgefahren, umgesetzter Brand- und Wasserschutz, Inspektions- und Testaufzeichnungen sowie Korrekturmaßnahmen.','R1: Feuer, Wasser, Hitze oder eine andere wesentliche standortspezifische Gefahr beschädigt Geräte oder Datenträger und unterbricht die unterstützten Dienstleistungen. R2: Eine standortspezifische Gefahr zerstört gespeicherte Informationen oder beschädigt sie unwiederbringlich, sodass erforderliche Aufzeichnungen auch nach der Wiederherstellung von Systemen und Räumlichkeiten nicht verfügbar sind. R3: Feuer oder extreme Umgebungsbedingungen verletzen Personal oder machen den Aufenthalt in den Räumlichkeiten unsicher, sodass ein sicherer Betrieb oder eine sichere Vorfallreaktion nicht möglich ist.','I-PHY-ENV · Gefahrenschutz und unterstützende Infrastruktur','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('C46.3','Unterstützende Versorgungseinrichtungen erfüllen die Resilienzanforderungen der Dienstleistungen','Stellen Sie Stromversorgungs- und Konnektivitätsvorkehrungen bereit, die die erforderliche Resilienz der Dienstleistungen gewährleisten können, und bewerten Sie Kontinuitätsvorkehrungen für die Kühlung. Die tatsächliche Regelung von Temperatur und Luftfeuchtigkeit wird unter PHY-CLIMATE bewertet. Leiten Sie den Bedarf und die erforderlichen Kapazitäten für unterbrechungsfreie Stromversorgungen (UPS), alternative Stromversorgung, Kühlungsredundanz und Notfallbrennstoff oder Notfallunterstützung aus den bewerteten Unterbrechungstoleranzen ab; nicht jeder Raum benötigt einen Generator.','Bewertung der Abhängigkeiten von Versorgungseinrichtungen und ihrer Kapazitäten, installierte Schutzmaßnahmen und Überbrückungszeitberechnungen sowie erforderlichenfalls Notversorgungsregelungen.','R1: Der Ausfall von Stromversorgung, Kühlung oder Kommunikation setzt abhängige Systeme oder Räumlichkeiten länger außer Betrieb, als die Dienstleistung tolerieren kann. R2: Ein abrupter Stromausfall beschädigt laufende Schreibvorgänge oder führt zum Verlust noch nicht festgeschriebener Daten, sodass auch bei schneller Wiederaufnahme der Dienstleistung eine Datenrekonstruktion erforderlich wird.','I-PHY-ENV · Gefahrenschutz und unterstützende Infrastruktur','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('PHY-CLIMATE','In Server- und Netzwerkräumen werden geeignete Temperatur- und Luftfeuchtigkeitsbedingungen aufrechterhalten (Gilt, wenn die Einrichtung Serverräume, Netzwerkräume oder vergleichbare Geräteumgebungen betreibt.)','Halten Sie Geräte mithilfe angemessen dimensionierter Kühlung, Belüftung oder anderer geeigneter Umgebungsregelungen innerhalb begründeter Betriebstemperatur- und Luftfeuchtigkeitsbereiche. Berücksichtigen Sie Wärmelast, Luftstrom und vorhersehbare Hitzeperioden; überprüfen Sie die tatsächlichen Bedingungen an repräsentativen Gerätestandorten. Bewerten Sie Kühlungsausfälle und Redundanzbedarf im Rahmen der Resilienz der Versorgungseinrichtungen (C46.3); die Alarmeskalation verbleibt unter C46.5 und die Wartung unter C46.6. Eine eigene Klimaanlage ist nicht verpflichtend, wenn eine andere wirksame Methode die erforderlichen Bedingungen aufrechterhält. (Gilt, wenn die Einrichtung Serverräume, Netzwerkräume oder vergleichbare Geräteumgebungen betreibt.)','Umgebungsanforderungen der Geräte, begründete Betriebsbereiche, Bewertung von Wärmelast und Kühlleistung sowie repräsentative Temperatur- und Luftfeuchtigkeitsmessungen, die eine wirksame Regelung der Umgebungsbedingungen nachweisen.','R1: Unzureichende Kühlung oder Luftströmung führt zu Überhitzung, Leistungsdrosselung von Geräten, Schäden oder zur Abschaltung der Dienstleistung. R2: Ungeeignete Luftfeuchtigkeit ermöglicht Kondensation oder elektrostatische Effekte, die Geräte beschädigen und den zuverlässigen Betrieb beeinträchtigen.','I-PHY-ENV · Gefahrenschutz und unterstützende Infrastruktur','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('C46.7','Stromversorgungs- und Telekommunikationsinfrastruktur ist geschützt','Schützen Sie relevante Strom- und Kommunikationsleitungen, Verteilerpunkte und Patchfelder vor Beschädigung oder unbefugten Eingriffen. Begegnen Sie dem Abhören von Kommunikation und elektrischen Störungen durch geeignete Leitungsführung, Trennung, Gehäuse und Zugangsbeschränkungen; kennzeichnen Sie Kabel ausreichend, um sichere Arbeiten zu ermöglichen.','Leitungsführungs- und Verteilerpläne, Inspektionen der Schutzmaßnahmen, Kennzeichnung und kontrollierter Zugang zu Verteilerpunkten.','R1: Beschädigungen oder Manipulationen der Stromversorgungs- oder Telekommunikationsinfrastruktur unterbrechen abhängige Dienstleistungen. R2: Durch Abhören ungeschützter Telekommunikationsinfrastruktur werden sensible Kommunikationsinhalte offengelegt.','I-PHY-ENV · Gefahrenschutz und unterstützende Infrastruktur','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('C46.6','Unterstützende Versorgungseinrichtungen und Notversorgungen werden gewartet und getestet','Warten und testen Sie die für die Dienstleistung erforderlichen Stromversorgungs-, Kühlungs-, Kommunikations- und Notfallvorkehrungen. Prüfen Sie relevante UPS-Batterien, Umschaltvorkehrungen und andere installierte Schutzmaßnahmen unter kontrollierten Bedingungen und beheben Sie Fehler. Unterscheiden Sie diese Arbeiten an der unterstützenden Infrastruktur von der Wartung der Server- und Netzwerkhardware.','Wartungspläne, Wartungsberichte, gegebenenfalls kontrollierte Last- und Failover-Tests sowie behobene Mängel.','Eine beeinträchtigte Schutzvorkehrung der Versorgungseinrichtungen oder eine Notversorgung versagt im Bedarfsfall und verursacht trotz nominell vorhandener Reservekapazität einen vermeidbaren Ausfall.','I-PHY-MAINT · Wartung und Wiederinbetriebnahme','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('PHY-MAINT','Server- und Netzwerkhardware wird durch autorisiertes Personal gewartet','Planen Sie risikogerechte Hardwarewartungen anhand der Herstellerhinweise und betrieblichen Erfordernisse und führen Sie diese durch. Autorisieren Sie das technische Personal und dokumentieren Sie die Arbeiten und Mängel. Wenden Sie bestehende Änderungs- und Zugangskontrollen auf Arbeiten mit möglichen Betriebsbeeinträchtigungen oder auf Fernarbeiten an. Dies betrifft die Wartung der Hardware, nicht das Einspielen von Softwarepatches oder die Wartung der Versorgungseinrichtungen des Gebäudes.','Hardwarewartungsplan, Autorisierungen des technischen Personals, Wartungsberichte und den relevanten Assets zugeordnete Nachverfolgung von Mängeln.','R1: Nicht gewartete Hardware verschlechtert sich oder fällt aus und unterbricht die unterstützte Dienstleistung. R2: Nicht autorisierte oder unkontrollierte Wartungsarbeiten legen Informationen offen oder verändern kritische Geräte.','I-PHY-MAINT · Wartung und Wiederinbetriebnahme','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('PHY-RETURN','Gewartete oder reparierte Geräte werden vor der Wiederinbetriebnahme überprüft','Überprüfen Sie nach Hardwarewartungen oder Reparaturen die korrekte Funktion und stellen Sie vor der Freigabe der Geräte für den Betrieb sicher, dass relevante Sicherheitseinstellungen und physische Schutzmaßnahmen weiterhin wirksam sind. Prüfen Sie auf unerwartete Änderungen und entfernen Sie gegebenenfalls verwendete temporäre Wartungszugänge. Hier wird das Ergebnis nach der Wartung geprüft, nicht die Wartungstätigkeit selbst oder die erstmalige Abnahme bei der Beschaffung.','Prüfungen nach der Wartung, Vergleich relevanter Einstellungen und Komponenten, Beendigung temporärer Zugänge und Freigabeaufzeichnung.','R1: Geräte werden mit veränderten Sicherheitseinstellungen oder verbliebenen Wartungszugängen wieder in Betrieb genommen und ermöglichen dadurch unbefugte Nutzung. R2: Ein unentdeckter Reparaturmangel verursacht nach der Freigabe einen erneuten Ausfall oder unzuverlässigen Betrieb.','I-PHY-MAINT · Wartung und Wiederinbetriebnahme','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('C46.5','Abweichungen bei Umgebungsbedingungen und Versorgungseinrichtungen lösen Warnungen an zuständiges Personal aus','Definieren Sie begründete Schwellenwerte für relevante Bedingungen wie Temperatur, Luftfeuchtigkeit und Stromversorgungsstatus. Überwachen Sie diese und leiten Sie Abweichungen an handlungsfähiges Personal weiter, auch außerhalb der Arbeitszeiten. Testen Sie, ob die Warnung die empfangende Person erreicht; eine Sensoranzeige ohne wirksame Eskalation reicht nicht aus.','Freigegebene Schwellenwerte, Sensor- und Alarmkonfiguration, Überwachungsverlauf sowie Tests der Warnungszustellung und Reaktion.','Eine Abweichung bei Umgebungsbedingungen oder Versorgungseinrichtungen bleibt unbemerkt oder erreicht keine handlungsfähige zuständige Person und eskaliert zu Geräteschäden oder einer Dienstleistungsunterbrechung.','I-PHY-ALERT · Alarmierung bei Umwelt- und Versorgungsstörungen','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('C37.1','Für Wirksamkeitsbewertungen sind Umfang, Methoden, Zeitpunkte und Zuständigkeiten festgelegt','Für Wirksamkeitsbewertungen sind Umfang, Methoden, Zeitpunkte und Zuständigkeiten festgelegt. Bestimmen Sie, welche Maßnahmen bewertet werden, wie valide Ergebnisse erzielt werden, wann Bewertung und Analyse stattfinden und wer sie durchführt. Richten Sie das Programm an bewerteten Risiken und relevanten Erfahrungen aus Vorfällen aus und dokumentieren Sie anwendbare Kriterien zur Interpretation der Ergebnisse.','Beispiele: ein Bewertungsprogramm oder gleichwertige Aufzeichnungen, die erfasste Maßnahmen, Methoden zur Erzielung valider Ergebnisse, Zeitpunkte für Bewertung und Analyse, verantwortliche Personen und Interpretationskriterien benennen und mit bewerteten Risiken sowie relevanten Erfahrungen aus Vorfällen verknüpft sind.','Bewertungen messen Tätigkeiten statt Schutzwirkungen oder verwenden uneinheitliche Kriterien, wodurch falsche Sicherheit entsteht und Verbesserungsprioritäten fehlgeleitet werden.','F-ASSESS · Wirksamkeitsbewertung und Nachweisführung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C37.5','Betrieblich genutzte Systeme werden risikobasierten technischen Sicherheitstests unterzogen','Betrieblich genutzte Systeme werden risikobasierten technischen Sicherheitstests unterzogen. Testen Sie die technische Sicherheit bereits eingesetzter Systeme, einschließlich beschaffter Anwendungen und Infrastruktur, im Hinblick auf relevante Angriffspfade wie unbefugten Zugriff, Rechteausweitung oder Bewegungen zwischen Netzwerksegmenten. Legen Sie Umfang, Methoden und Häufigkeit risikogerecht fest; autorisieren Sie Tests und schützen Sie die Dienstleistungsverfügbarkeit und Daten. Dokumentieren Sie Feststellungen und verfolgen Sie deren Behebung nach. Dies unterscheidet sich von Entwicklungstests vor der Freigabe, Prüfungen der Überwachung und Erkennung sowie physischen Zutrittstests; vorhandene Ergebnisse können erneut genutzt werden, soweit sie die erforderliche Abdeckung des laufenden Betriebs nachweisen.','Risikobasierter Testumfang und Testplan; Autorisierung und Vorkehrungen zur Betriebssicherheit; Berichte mit Angaben zu getesteten Systemen, Methoden und Feststellungen; Aufzeichnungen zur Behebung. Tests erfordern weder die unkontrollierte Ausnutzung von Schwachstellen in produktiven Systemen noch ein bestimmtes kommerzielles Testprodukt.','R1: Nicht getestete Angriffspfade im laufenden Betrieb bleiben ausnutzbar und werden fälschlich als abgesichert angesehen. R2: Unzureichend kontrollierte Sicherheitstests stören betriebliche Dienstleistungen oder beschädigen Daten.','F-ASSESS · Wirksamkeitsbewertung und Nachweisführung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C37.2','Bewertungen der Sicherheitswirksamkeit werden durchgeführt und überprüft','Führen Sie die geplanten Wirksamkeitsbewertungen durch und prüfen Sie die zugrunde liegenden Ergebnisse anhand der beabsichtigten Schutzwirkungen. Eine abgeschlossene Testaufzeichnung ohne Prüfung und Interpretation ihrer Ergebnisse belegt nicht, dass die Einrichtung bewertet hat, ob die Sicherheitsmaßnahmen tatsächlich funktionieren.','Beispiele: abgeschlossene Wirksamkeitsbewertungen mit den zugrunde liegenden Ergebnissen und Nachweisen ihrer Prüfung und Interpretation anhand der beabsichtigten Schutzwirkungen.','Auf unwirksame Schutzmaßnahmen wird weiterhin vertraut, weil ihre Funktionsweise und Ergebnisse nicht geprüft werden, sodass bekannte Arten von Vorfällen erneut auftreten können.','F-ASSESS · Wirksamkeitsbewertung und Nachweisführung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C37.3','Die Einhaltung von Sicherheitsvorgaben wird überwacht und dem Leitungsorgan berichtet','Überwachen Sie die tatsächliche Einhaltung anwendbarer Sicherheitsrichtlinien, Regeln und Standards und berichten Sie dem Leitungsorgan über die Feststellungen und relevanten Abweichungen. Bewahren Sie die Nachvollziehbarkeit zwischen Überwachungsergebnissen und berichteten Informationen; eine nicht durch Überwachung belegte Managementzusammenfassung oder Feststellungen, über die nie berichtet wird, weisen den vollständigen Prozess nicht nach.','Beispiele: Ergebnisse der Überwachung anhand anwendbarer interner Sicherheitsrichtlinien, Regeln und Standards mit Nachweisen, dass die Feststellungen und relevanten Abweichungen dem Leitungsorgan berichtet wurden.','Regelmäßige Abweichungen von Sicherheitsregeln bleiben bestehen, ohne dass die Leitung davon Kenntnis erhält, sodass unsichere Praktiken nicht korrigiert werden.','F-ASSESS · Wirksamkeitsbewertung und Nachweisführung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C37.4','Fachkundige, unparteiische Überprüfungen bewerten das Sicherheitsmanagement und seine Umsetzung','Fachkundige, unparteiische Überprüfungen bewerten das Sicherheitsmanagement und seine Umsetzung. Überprüfen Sie Menschen, Prozesse und Technik in geplanten Abständen und nach erheblichen Vorfällen oder wesentlichen Änderungen des Betriebs oder der Risiken, soweit CIR anwendbar ist. Stellen Sie angemessene Prüfungskompetenz und Unabhängigkeit vom geprüften Bereich sicher oder dokumentierte alternative Vorkehrungen zur Unparteilichkeit, wenn die Größe eine Trennung verhindert. Berichten Sie der Leitung über die Ergebnisse und führen Sie Feststellungen einer Korrektur oder autorisierten Risikobehandlung zu.','Beispiele: abgeschlossene Überprüfungen von Menschen, Prozessen und Technik des Sicherheitsmanagements mit geplanten oder ereignisgesteuerten Zeitpunkten, Kompetenz und Unabhängigkeit der Prüfenden oder dokumentierten alternativen Vorkehrungen zur Unparteilichkeit, wenn die Größe eine Trennung verhindert. Beziehen Sie die Berichterstattung an die Leitung und die Weiterleitung von Feststellungen zur Korrektur oder autorisierten Behandlung ein und prüfen Sie, soweit CIR anwendbar ist, die Auslöser durch erhebliche Vorfälle oder wesentliche Änderungen.','Eine voreingenommene oder unqualifizierte Überprüfung übersieht Schwächen oder berichtet einen unzutreffenden Sicherheitszustand, was zu unangemessenen Korrekturentscheidungen führt.','F-ASSESS · Wirksamkeitsbewertung und Nachweisführung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C47.1','Mängel an Sicherheitsmaßnahmen werden ohne unangemessene Verzögerung korrigiert','Ergreifen Sie ohne unangemessene Verzögerung geeignete Korrekturmaßnahmen für festgestellte Mängel an Sicherheitsmaßnahmen, wobei Termine und Fortschritt auf die festgestellte Schwäche zurückführbar sein müssen. Prüfen Sie die tatsächlichen Maßnahmen und die Begründung fortbestehender Verzögerungen im Licht des Risikos; das bloße Eröffnen eines Tickets oder Auflisten einer künftigen Maßnahme belegt keine rechtzeitige Korrektur.','Beispiele: festgestellte Mängel an Maßnahmen, verknüpft mit Korrekturentscheidungen und tatsächlichen Maßnahmen, mit Datumsangaben, Fortschritt und Verzögerungsbegründungen, die ausreichen, um zu beurteilen, ob eine geeignete Korrektur ohne unangemessene Verzögerung erfolgt ist.','Eine festgestellte Schutzschwäche bleibt bestehen, während sich die Korrektur verzögert, sodass derselbe Fehler oder Angriffspfad erneut wirksam werden kann.','F-FIX · Korrekturmaßnahmen','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C47.2','Abschluss und Wirksamkeit von Korrekturmaßnahmen werden überprüft','Überprüfen Sie vor dem Abschluss einer Korrekturmaßnahme sowohl, dass die vereinbarte Änderung umgesetzt wurde, als auch, dass sie die festgestellte Schwäche beseitigt hat; eine abgeschlossene Aufgabe oder ein abgeschlossenes Ticket allein belegt keine Wirksamkeit.','Beispiele: Überprüfung abgeschlossener Korrekturmaßnahmen und relevante Ergebnisse der Nachprüfung, die zeigen, ob die festgestellte Schwäche beseitigt wurde, gegebenenfalls mit Entscheidungen zum Abschluss oder zu weiteren Maßnahmen.','Eine Korrekturmaßnahme wird abgeschlossen, obwohl sie die zugrunde liegende Schwäche nicht beseitigt hat, wodurch falsche Sicherheit entsteht und eine Wiederholung möglich bleibt.','F-FIX · Korrekturmaßnahmen','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C28.2','Anwendbare Anforderungen an die europäische Cybersicherheitszertifizierung werden erfüllt (Gilt nur, wenn eine wirksame rechtliche Anforderung nach NIS2 Art. 24 eine solche Zertifizierung verlangt; dies ist keine allgemeingültige Pflicht zu einem ISO 27001-Zertifikat oder einem generischen NIS2-Zertifikat.)','Anwendbare Anforderungen an die europäische Cybersicherheitszertifizierung werden erfüllt. Überprüfen Sie das vorgeschriebene Schema, den zertifizierten Geltungsbereich, die Gültigkeit und die Vertrauenswürdigkeitsstufe für die relevanten Produkte, Dienstleistungen, Prozesse oder die Einrichtung. (Gilt nur, wenn eine wirksame rechtliche Anforderung nach NIS2 Art. 24 eine solche Zertifizierung verlangt; dies ist keine allgemeingültige Pflicht zu einem ISO 27001-Zertifikat oder einem generischen NIS2-Zertifikat.)','Soweit eine wirksame Zertifizierungsanforderung gilt, gehören zu den Beispielen die Entscheidung über die Anwendbarkeit und Zertifizierungsnachweise, aus denen das vorgeschriebene europäische Schema, das erfasste Produkt, die Dienstleistung, der Prozess oder die Einrichtung, die Gültigkeit und die Vertrauenswürdigkeitsstufe hervorgehen. Gilt keine wirksame Anforderung, begründen Sie diese Schlussfolgerung zum Geltungsbereich, statt ein Zertifikat zu verlangen.','Auf ein Produkt, eine Dienstleistung, einen Prozess oder eine Einrichtung wird vertraut, ohne dass eine wirksame Zertifizierungsanforderung erfüllt ist, was zur Beanstandung der Regelkonformität und zu einem möglicherweise betriebsbeeinträchtigenden Austausch oder einer eingeschränkten Nutzung führt.','F-CERT · Anwendbare Zertifizierungsanforderungen','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C69.1','Der zuständigen Behörde werden angeforderte Umsetzungsnachweise korrekt bereitgestellt','Fordert die zuständige Behörde Umsetzungsnachweise an, übermitteln Sie eine korrekte und ausreichende Antwort für den angeforderten Umfang, die auf zugrunde liegende Aufzeichnungen und die tatsächliche Übermittlung zurückgeführt werden kann. Eine unbelegte Behauptung der Regelkonformität ersetzt die angeforderten Nachweise nicht. Gab es keine Anfrage, halten Sie diesen Umstand fest, statt eine Einreichung zu erfinden. (Gilt, wenn eine solche Anfrage gestellt wurde.)','Wenn Umsetzungsnachweise angefordert wurden, gehören zu den Beispielen die Anfrage der zuständigen Behörde und die eingereichte Antwort, die zur Darlegung ihrer Richtigkeit und Hinlänglichkeit den zugrunde liegenden Aufzeichnungen und dem angeforderten Umfang zugeordnet sind, einschließlich Übermittlungsnachweisen. Gab es keine Anfrage, halten Sie diesen Umstand fest, statt eine Einreichung zu erfinden.','Unvollständige oder unzutreffende Nachweise verhindern eine verlässliche Bewertung der Umsetzung durch die Behörde und führen zu zusätzlichen Nachfragen oder korrigierenden Aufsichtsmaßnahmen.','O-EVD · Nachweise und Zusammenarbeit mit Aufsichtsbehörden','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C69.2','Rechtmäßige aufsichtsrechtliche Inspektionen und Anfragen werden unterstützt (Gilt, wenn eine zuständige Behörde Aufsicht ausübt oder eine rechtmäßige Anfrage stellt.)','Gewähren Sie die für rechtmäßige aufsichtsrechtliche Inspektionen, Audits, Sicherheitsscans und Informations- oder Dokumentenanforderungen erforderliche Zusammenarbeit und den erforderlichen Zugang, gegebenenfalls einschließlich der Zusammenarbeit mit einer bestellten Überwachungsperson. Bewerten Sie die tatsächlich gestellte Anfrage und die Reaktion der Einrichtung. Die vollständige Behinderung einer angeforderten rechtmäßigen Aufsichtsmaßnahme stützt die Standardbewertung Absent Major; ein einzelnes administratives Versäumnis bei wirksamer Zusammenarbeit ist nicht derselbe Mangel. Liegt keine anwendbare Aufsichtsmaßnahme oder Anfrage vor, bedeutet dies nicht anwendbar, nicht automatisch bestanden. Unbekannte Anwendbarkeit erfordert eine Prüfung des Geltungsbereichs, keine Minor-Feststellung.','Wenn rechtmäßige Aufsicht stattfindet, gehören zu den Beispielen die Inspektion, das Audit, der Scan oder die Informations- bzw. Zugangsanfrage sowie Abstimmungs- oder Zugangsaufzeichnungen, die zeigen, dass die Einrichtung die autorisierte Tätigkeit innerhalb ihres Umfangs unterstützt hat. Hat keine solche Tätigkeit stattgefunden, prüfen Sie relevante Vorkehrungen, ohne eine nachgewiesene Zusammenarbeit bei einem nicht stattgefundenen Ereignis zu behaupten.','Die Behinderung eines rechtmäßigen aufsichtsrechtlichen Zugangs verzögert die Feststellung oder Überprüfung von Schwächen und setzt die Einrichtung einer Verschärfung der Durchsetzungsmaßnahmen aus.','O-EVD · Nachweise und Zusammenarbeit mit Aufsichtsbehörden','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C69.3','Ergebnisse gezielter Sicherheitsaudits stehen der zuständigen Behörde zur Verfügung (Gilt, wenn ein solches aufsichtsrechtliches Audit durchgeführt wird.)','Ergebnisse gezielter Sicherheitsaudits werden der zuständigen Behörde zur Verfügung gestellt. Wird im Rahmen der NIS2-Aufsichtsbefugnisse durch die zuständige Behörde oder eine unabhängige Stelle ein gezieltes Sicherheitsaudit durchgeführt, stellen Sie sicher, dass dessen Ergebnisse dieser Behörde zugänglich gemacht werden. Ein solches Audit konzentriert sich auf Risiken, die durch Bewertungen der Behörde oder der Einrichtung oder anhand anderer verfügbarer Risikoinformationen festgestellt wurden. Diese Kontrolle prüft die Verfügbarkeit der Auditergebnisse, nicht die allgemeine Zusammenarbeit beim Audit oder ein routinemäßiges internes Audit. (Gilt, wenn ein solches aufsichtsrechtliches Audit durchgeführt wird.)','Dokumentation zur Identifizierung des aufsichtsrechtlichen Audits und seines Umfangs; der daraus resultierende Auditbericht; Übermittlung, Empfangsbestätigung oder andere Nachweise dafür, dass die zuständige Behörde Zugang zu den Ergebnissen hat. Führt die Behörde das Audit selbst durch, verlangen Sie keine redundante Einreichung eines Berichts, der ihr bereits vorliegt.','Die Behörde kann die Feststellungen gezielter Audits nicht bewerten oder festgestellte Schwächen nicht nachverfolgen, weil ihr die Auditergebnisse nicht wie vorgeschrieben zur Verfügung gestellt werden.','O-EVD · Nachweise und Zusammenarbeit mit Aufsichtsbehörden','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C72.1','Verbindliche aufsichtsrechtliche Anweisungen werden innerhalb ihres Umfangs und ihrer Fristen erfüllt (Gilt, wenn der Einrichtung eine wirksame verbindliche Anweisung erteilt wurde.)','Identifizieren Sie die wirksame Anweisung, die erforderliche Maßnahme, den Umfang und die Frist. Setzen Sie die erforderliche Maßnahme um und bewahren Sie Nachweise über den Abschluss sowie über erforderliche Mitteilungen an die zuständige Behörde auf. Die Standardbewertung Absent Major betrifft die vollständige Nichterfüllung einer anwendbaren Anweisung bei Fälligkeit. Ein geringfügiges administratives Versäumnis trotz wirksamer Schutzmaßnahmen wird nach seinem tatsächlichen Ausmaß bewertet; Partial kann dennoch eine Hochstufung rechtfertigen. Liegt keine Anweisung vor, kennzeichnen Sie die Kontrolle als nicht anwendbar. Bewerten Sie vor Ablauf einer Frist die Einhaltung bereits fälliger Pflichten, statt einen künftigen Abschluss als überfällig zu behandeln. Durchsetzungsmaßnahmen nach Art. 32(5) unterliegen eigenen Voraussetzungen und sind weder eine automatische Folge noch eine automatische ISO-Auditbewertung.','Wenn verbindliche Anweisungen vorliegen, gehören zu den Beispielen die Anweisung und ihr geltender Umfang sowie ihre Fristen, verglichen mit datierten Umsetzungsaufzeichnungen und belegenden Ergebnissen. Liegen keine Anweisungen vor, begründen Sie diesen Umstand, statt eine Anordnung zu erfinden oder ihn als Nachweis der Erfüllung anderer Kontrollen zu behandeln.','Eine verbindliche aufsichtsrechtliche Anweisung wird nicht im geforderten Umfang oder nicht fristgerecht erfüllt, wodurch der festgestellte Verstoß fortbesteht und weitere Durchsetzungsmaßnahmen in Betracht gezogen werden.','O-ORD · Verbindliche aufsichtsbehördliche Anordnungen','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('C72.2','Die angeordnete öffentliche Bekanntmachung von Verstößen erfolgt in der vorgeschriebenen Weise','Hat die zuständige Behörde die öffentliche Bekanntmachung eines Verstoßes angeordnet, veröffentlichen Sie die erforderlichen Informationen in der in dieser Anordnung festgelegten Weise und innerhalb etwaiger darin bestimmter Fristen; ohne eine solche Anordnung verlangt diese Kontrolle keine Veröffentlichung.','Wenn eine öffentliche Bekanntmachung angeordnet wurde, gehören zu den Beispielen die Anordnung und eine datierte öffentliche Veröffentlichung oder gleichwertige Nachweise dafür, dass der vorgegebene Inhalt, die Art und Weise und die anwendbaren Fristen eingehalten wurden. Wurde keine Bekanntmachung angeordnet, stellen Sie diesen Umstand fest, statt eine Veröffentlichung zu verlangen.','Eine vorgeschriebene öffentliche Bekanntmachung eines Verstoßes ist unvollständig oder verspätet, sodass betroffene Parteien uninformiert bleiben und weitere aufsichtsrechtliche Folgemaßnahmen ausgelöst werden.','O-ORD · Verbindliche aufsichtsbehördliche Anordnungen','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-ACCESS-COORDINATION','Relevante Regelungen zur Zugangssteuerung sind aufeinander abgestimmt','Ermitteln Sie die sicherheitsrelevanten Abhängigkeiten zwischen den Regelungen zum physischen Zutritt, zum Systemzugang und zu Informationsberechtigungen, die im bewerteten Anwendungsbereich bestehen. Legen Sie Verantwortlichkeiten sowie Entscheidungs- und Kommunikationsschnittstellen fest, damit die zugehörigen Zugangsregeln und deren Änderungen die geschäftlichen und die informationssicherheitsbezogenen Anforderungen ohne unbeabsichtigte Lücken oder widersprüchliche Entscheidungen unterstützen. Prüfen Sie repräsentative Fälle über die relevanten Schnittstellen hinweg, einschließlich Änderungen von Rollen oder von Lieferantenzugängen, soweit zutreffend, und beseitigen Sie nicht begründete Widersprüche. Unterschiedliche Berechtigungen können beabsichtigt und begründet sein; die Abstimmung verlangt weder identische Rechte noch den gleichzeitigen Entzug sachlich unabhängiger Rechte oder eine einzige zusammengefasste Richtlinie. Nutzen Sie Nachweise aus C40.2, C40.3, C46.1, ACCESS-RECERT und aus den ISMS-Prozessen erneut, soweit diese dasselbe Abstimmungsergebnis bereits belegen; bewerten Sie nur die verbleibende Lücke.','Verknüpfte Zugangsregeln, Workflow-Definitionen oder gleichwertige Aufzeichnungen, welche die relevanten Abhängigkeiten, Verantwortlichkeiten und begründeten Unterschiede benennen. Repräsentative Fälle verfolgen die beabsichtigte Zugangsentscheidung oder Zugangsänderung über die relevanten Schnittstellen bis zu den tatsächlichen Berechtigungen, mit Aufzeichnungen zu festgestellten Widersprüchen und zu deren Behebung. Vorhandene Genehmigungen, Rechteüberprüfungen und Prozessaufzeichnungen für denselben Anwendungsbereich und Zeitraum werden erneut genutzt. Ist keine relevante Änderung eingetreten, werden die umgesetzten Regelungen begutachtet und ein gefahrloses Szenario verwendet, statt ein Ereignis zu erfinden. Ein bestimmtes Matrixformat, ein zusammengefasstes Dokument oder eine zusätzliche Kopie vorhandener Nachweise ist nicht erforderlich.','R1: Eine sicherheitsrelevante Zugangsänderung wird an einer abhängigen Schnittstelle nicht mitgeteilt oder nicht umgesetzt, sodass ein unbeabsichtigter Weg zu geschützten Informationen oder Werten (Assets) offen bleibt. R2: Widersprüchliche Zugangsentscheidungen zwischen den relevanten Regelungen lassen nicht begründeten Zugang zu oder verhindern zu Unrecht autorisierte Arbeit.','ISO-spezifische Anforderung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('ISO-ANNEX-COMPARISON','Die erforderlichen Maßnahmen werden mit allen Maßnahmen aus Annex A abgeglichen','Gleichen Sie die über die Risikobehandlung bestimmten Maßnahmen mit allen 93 Referenzmaßnahmen aus Annex A ab, um Auslassungen festzustellen. Beziehen Sie erforderliche organisationsspezifische Maßnahmen ein; Annex A ist eine Referenz zur Vollständigkeitsprüfung und keine allgemeingültige Produktcheckliste.','Vollständiger Abgleich mit Annex A, festgestellte Auslassungen und die daraus folgenden Entscheidungen zur Maßnahmenauswahl, verknüpft mit der Risikobehandlung.','Eine erforderliche Schutzmaßnahme fehlt, weil die Auswahl nie gegen den vollständigen Referenzsatz geprüft wurde.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-ASSET-CHANGE','Nach einer Rollen- oder Vertragsänderung nicht mehr autorisierte Werte (Assets) werden zurückgegeben','Wenn sich ein Beschäftigungsverhältnis, eine Rolle, ein Vertrag oder eine Vereinbarung ändert, ohne beendet zu werden, gleichen Sie die überlassenen Assets und Informationen mit dem neuen berechtigten Bedarf ab. Ziehen Sie nicht mehr autorisierte Gegenstände ein und halten Sie jede begründete fortbestehende Zuweisung fest. Nutzen Sie dieselben Bestands- und Zugangsänderungsaufzeichnungen erneut; der Rückerhalt bei Beendigung bleibt Gegenstand von C40.12 und C52.8. Eine Rollenänderung erfordert nicht die Herausgabe von Ausstattung, die für die neue Tätigkeit weiterhin ordnungsgemäß zugewiesen ist.','Änderungsaufzeichnungen, die den zugewiesenen physischen und informationsbezogenen Assets zugeordnet sind, bestätigte Rückgaben oder Übergaben der Obhut sowie dokumentierte fortbestehende Zuweisungen. Zugangsänderungen werden verknüpft, ohne sie ein zweites Mal zu bewerten. Ist im Zeitraum keine relevante Änderung eingetreten, werden die festgelegten Abgleichs- und Rückgaberegelungen, die zugewiesenen Verantwortlichkeiten sowie ein angemessener Durchgang oder ein gefahrloses Szenario auf Grundlage der vorhandenen Assetaufzeichnungen bewertet. Das Fehlen einer Ausführungsstichprobe wird festgehalten; eine Änderung darf nicht erfunden und die Rückgabe weiterhin ordnungsgemäß zugewiesener Assets darf nicht verlangt werden.','Eine auf eine andere Aufgabe versetzte Person oder ein gewechselter Dienstleister behält Informationen oder Ausstattung, die nicht mehr benötigt werden, und kann sie außerhalb der neuen berechtigten Rolle nutzen oder offenlegen.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-AUDIT-EXECUTION','Die geplanten internen ISMS-Audits werden durchgeführt','Führen Sie die geplanten Audits durch, um die Konformität des ISMS sowie dessen wirksame Umsetzung und Aufrechterhaltung festzustellen. Nutzen Sie vorhandene unabhängige Überprüfungen nur dann erneut, wenn der geforderte Auditumfang und die geforderten Auditkriterien des ISMS nachweislich abgedeckt sind.','Abgeschlossene Auditaufzeichnungen mit Bezug zum Auditprogramm, die geprüften Nachweise und die Schlussfolgerungen im Hinblick auf die festgelegten Kriterien.','Das Auditprogramm besteht nur auf dem Papier, während wesentliche Mängel des ISMS nie untersucht werden.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-AUDIT-PLAN','Ein internes ISMS-Auditprogramm legt Abdeckung und Prioritäten fest','Planen Sie interne Audits der ISMS-Anforderungen der Organisation und der ISO 27001. Legen Sie Häufigkeit, Methoden, Verantwortlichkeiten, Kriterien und Umfang fest und berücksichtigen Sie dabei die Bedeutung der Prozesse sowie die Ergebnisse vorangegangener Audits; eine willkürlich gesetzte jährliche Häufigkeit wird nicht vorgeschrieben.','Auditprogramm, Begründung nach Risiko bzw. Bedeutung, Terminplan sowie festgelegte Auditkriterien und Auditumfänge.','Wichtige ISMS-Prozesse oder ISMS-Anforderungen werden systematisch nicht von der internen Auditabdeckung erfasst.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-AUDIT-REPORTING','Die Ergebnisse interner ISMS-Audits werden berichtet und aufbewahrt','Berichten Sie die Auditergebnisse an die zuständige Leitung und bewahren Sie Nachweise zum Auditprogramm und zu den Ergebnissen auf. Halten Sie so viele Einzelheiten fest, dass die Feststellungen und deren Nachverfolgung belegt sind; allgemeine Ausgaben technischer Tests genügen allein nicht.','Auditberichte, Empfängerangaben oder Kenntnisnahme durch die Leitung, aufbewahrte Aufzeichnungen zum Auditprogramm und nachvollziehbare Feststellungen.','Die Leitung kann auf Auditfeststellungen nicht reagieren und nicht belegen, was tatsächlich auditiert wurde.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-AUDITOR-SELECTION','Interne ISMS-Auditoren sind kompetent und unparteiisch','Wählen Sie Auditoren aus, die über die für ihre Aufträge erforderliche Kompetenz verfügen, und stellen Sie die Objektivität und die Unparteilichkeit des Auditprozesses sicher. Nutzen Sie vorhandene Kompetenzaufzeichnungen erneut; bewerten Sie Interessenkonflikte bezogen auf die tatsächlich erteilten Aufträge.','Nachweise zur Kompetenz der Auditoren, Entscheidungen zur Auftragszuweisung sowie Vorkehrungen zur Unabhängigkeit und zum Umgang mit Interessenkonflikten.','Auditfeststellungen sind unzuverlässig, weil den Auditoren die Kompetenz fehlt oder weil sie Arbeitsergebnisse ohne ausreichende Unparteilichkeit bewerten.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-AUTHORITY-CONTACTS','Relevante Behördenkontakte und Regelungen zur Kontaktaufnahme werden gepflegt','Pflegen Sie die relevanten Behördenkontakte sowie die Umstände, in denen Kontakt aufzunehmen ist, einschließlich Sicherheitsvorfällen und weiterer geltender Pflichten. Nutzen Sie den NIS2-Meldeweg erneut, sofern dies angemessen ist; diese Maßnahme verlangt weder einen routinemäßigen Austausch von Lageinformationen noch den Kontakt zu jeder Behörde.','Kontaktverzeichnis; Verantwortlichkeiten und Auslöser für die Kontaktaufnahme; Aktualitätsprüfungen und einschlägige Aufzeichnungen der Kommunikation.','Die Organisation kann im Bedarfsfall keine behördliche Unterstützung erhalten oder den zuständigen Empfänger nicht erreichen.','ISO-spezifische Anforderung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('ISO-CLIMATE','Die Relevanz des Klimawandels für das ISMS wird bestimmt','Bestimmen Sie, ob der Klimawandel die beabsichtigten Ergebnisse des ISMS beeinflusst, und berücksichtigen Sie die relevanten Anforderungen interessierter Parteien. Nutzen Sie Standort- und Lieferantenbewertungen erneut, betrachten Sie darüber hinaus aber auch Veränderungen im Betrieb, bei den Abhängigkeiten und bei den vertraglichen Erwartungen. Halten Sie eine begründete Schlussfolgerung fest, einschließlich einer begründeten Nichtrelevanz; es handelt sich nicht um ein Programm zur Minderung von Treibhausgasemissionen.','Schlussfolgerung zur Klimarelevanz und deren Begründung; relevante Anforderungen interessierter Parteien; Verknüpfungen zu ENV-RISK und zu den Lieferantenbewertungen.','Klimabedingte Veränderungen setzen die Annahmen zur Sicherheit oder zur Betriebsfortführung außer Kraft, und relevante Anforderungen werden übersehen.','ISO-spezifische Anforderung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('ISO-CLOUD-LIFECYCLE','Die Cloud-Nutzung folgt festgelegten Regelungen zur Sicherheitssteuerung','Legen Sie Steuerungsregelungen für die Cloud-Nutzung fest und wenden Sie diese an; sie umfassen die Einführung, die zulässige Nutzung, die Verwaltung und die Entscheidungen zum Ausstieg. Verknüpfen Sie vorhandene Maßnahmen zur Lieferantenabsicherung, zur Verantwortungszuordnung und zum Ausstieg; bewerten Sie diese hier nicht erneut. Dies gilt für Cloud-Kunden einschließlich der Nutzer von SaaS und nicht nur für Anbieter.','Regelungen zur Cloud-Nutzung; Verzeichnis der genehmigten Dienste und Mandanten (Tenants); Entscheidungen zur geteilten Verantwortung; Aufzeichnungen zu Einführung, Änderung und Ausstieg, verknüpft mit den vorhandenen Lieferantenmaßnahmen.','Der Kunde nimmt an, dass der Anbieter eine nicht zugewiesene Verantwortung abdeckt, oder er verliert den sicheren Zugang und die Datenübertragbarkeit, wenn sich der Cloud-Dienst ändert oder endet.','ISO-spezifische Anforderung','Lieferkette & Dienstleister','Supply chain & suppliers'),
  ('ISO-COMMUNICATION','Die interne und externe ISMS-Kommunikation ist festgelegt','Bestimmen Sie, welche ISMS-Informationen wann, an wen und auf welche Weise kommuniziert werden müssen. Ordnen Sie die Verantwortung über bestehende Rollen zu. Verknüpfen Sie die Regelungen mit der Kommunikation bei Vorfällen und gegenüber Behörden, statt parallele Meldewege einzurichten.','Kommunikationsregelungen; Zielgruppen, Zeitpunkte und Methoden; beispielhafte Mitteilungen und die verantwortlichen Rollen.','Sicherheitsbezogene Entscheidungen, Pflichten oder Änderungen erreichen die Personen nicht, die handeln müssen.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-COMPETENCE-ACTIONS','Kompetenzmaßnahmen außerhalb von Schulungen sind nachweislich wirksam','Werden Kompetenzlücken durch Mentoring, Umsetzung auf eine andere Aufgabe, Neueinstellung oder eine andere Maßnahme außerhalb von Schulungen geschlossen, bewerten Sie, ob die erforderliche Fähigkeit erreicht wurde, und bewahren Sie die Nachweise auf. Die Prüfung von Qualifikation und Lücke verbleibt bei C40.6, die Bewertung der Schulungswirksamkeit verbleibt bei TRN-05.','Entscheidungen zu Kompetenzlücken außerhalb von Schulungen sowie Aufzeichnungen zu Mentoring, Umsetzung oder Neueinstellung, mit der nachgewiesenen Fähigkeit nach der Maßnahme und mit aufbewahrten Nachweisen zu Qualifikation oder Erfahrung. Für die zugrunde liegende Kompetenzbewertung wird C40.6 erneut genutzt, für die Schulungswirksamkeit TRN-05.','Eine Kompetenzlücke besteht nach Mentoring, Umsetzung oder Neueinstellung fort, weil der Abschluss der Maßnahme mit der nachgewiesenen Fähigkeit verwechselt wird.','ISO-spezifische Anforderung','Personalsicherheit','Personnel security'),
  ('ISO-CONTEXT','Interne und externe Themen mit Auswirkung auf das ISMS sind bestimmt','Ermitteln Sie die organisatorischen, geschäftlichen, rechtlichen, technologischen und externen Rahmenbedingungen, die das Management der Informationssicherheit beeinflussen können. Halten Sie die Bewertung auch bei veränderten Umständen nutzbar; ein benanntes Rahmenwerk oder ein eigenes SWOT-Dokument ist nicht erforderlich.','Kontextbewertung; relevante Änderungen; Verknüpfungen zum Anwendungsbereich und zu Planungsentscheidungen.','Wesentliche geschäftliche oder externe Rahmenbedingungen werden übersehen, sodass das ISMS die falschen Prioritäten schützt.','ISO-spezifische Anforderung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('ISO-CONTINUAL-IMPROVEMENT','Das ISMS wird über die Behebung einzelner Mängel hinaus fortlaufend verbessert','Nutzen Sie Informationen aus Leistungsbewertung, Risikobetrachtung, Bewertungen und Betrieb, um Eignung, Angemessenheit und Wirksamkeit des ISMS zu verbessern. Weisen Sie umgesetzte Verbesserungen nach; eine willkürlich festgelegte jährliche Anzahl von Verbesserungsprojekten ist nicht zu fordern.','Verbesserungsentscheidungen und umgesetzte Änderungen; Nachweise über den erzielten Nutzen oder dessen Bewertung.','Das ISMS bleibt statisch und verliert seine Wirksamkeit, während sich Betrieb und Bedrohungen verändern.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-DISPLAY-CLEARING','Sensible Informationen werden von gemeinsam genutzten physischen Anzeigeflächen entfernt','Entfernen oder verdecken Sie sensible Informationen auf gemeinsam genutzten Whiteboards und anderen nicht gerätegebundenen Anzeigeflächen sicher, sobald sie nicht mehr benötigt werden oder Unbefugte sie einsehen könnten. Für Papierunterlagen und Datenträger greift MEDIA-UNATTENDED, für elektronische Geräte DEVICE-LOCK; diese Maßnahme behandelt die verbleibende Offenlegung über Anzeigeflächen.','Geltende Regeln zum Freiräumen von Anzeigeflächen sowie Beobachtungen nach Besprechungen oder Arbeitstätigkeiten, ergänzt um die Erläuterung der Mitarbeitenden, wie Informationen verdeckt oder entfernt werden.','Sensible Besprechungs- oder Betriebsinformationen bleiben für Besucher oder spätere Raumnutzer sichtbar, nachdem die berechtigte Tätigkeit beendet ist.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-DOCUMENT-NEEDS','Die erforderliche dokumentierte Information des ISMS ist ermittelt','Ermitteln Sie die dokumentierte Information, die die Norm fordert und die die Organisation für ein wirksames ISMS benötigt. Nutzen Sie vorhandene Dokumente und Aufzeichnungen; für jede einzelne Anforderung ist keine eigene Richtlinie oder Vorlage zu verlangen.','Verzeichnis der dokumentierten Information oder ein gleichwertiger Abdeckungsnachweis, verknüpft mit den ISMS-Anforderungen und den betrieblichen Erfordernissen.','Wesentliche Vorgaben oder Nachweise fehlen, weil der Dokumentationsbedarf nie bestimmt wurde.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-DOCUMENT-RELEASE','ISMS-Dokumente werden angemessen gekennzeichnet, bewertet und genehmigt','Verwenden Sie beim Erstellen und Aktualisieren von ISMS-Dokumenten eine angemessene Kennzeichnung und ein angemessenes Format und prüfen und genehmigen Sie die Eignung vor der Freigabe. Die übergreifende Dokumentenverwaltung und die Versionskontrolle bleiben durch C29.5 abgedeckt.','Stichproben freigegebener Dokumente mit angemessener Kennzeichnung, angemessenem Format, Prüfung und Genehmigung, einschließlich geänderter Fassungen.','Ungeeignete oder nicht genehmigte Dokumente werden als verbindliche Vorgaben herausgegeben.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-EMERGENCY-AUTHORISATION','Ausnahmsweise privilegierter Zugriff hat einen genehmigten Umfang und eine Befristung','Legen Sie dort, wo ausnahmsweise privilegierter Zugriff benötigt wird, den Genehmigungsweg, den zulässigen Umfang und die Befristung fest und wenden Sie diese an. Greifen Sie auf die bestehenden Maßnahmen zur Vergabe und zum Entzug von Zugriffsrechten zurück; geprüft wird die Entscheidung über den Ausnahmezugriff, nicht der Einsatz eines bestimmten Break-Glass-Produkts.','Verfahren für Ausnahmezugriffe und Einzelfallgenehmigungen mit Angabe von Umfang, genehmigender Stelle und Befristung, verknüpft mit den Zugriffsaufzeichnungen. Wird ausnahmsweise privilegierter Zugriff zwar benötigt, war aber bislang nicht im Einsatz, so sind der festgelegte Genehmigungsweg, der genehmigte Umfang und die Befristungsregelungen über einen angemessenen Durchgang (Walkthrough) oder einen gefahrlosen Test zu beurteilen. Halten Sie fest, dass keine Stichprobe einer tatsächlichen Nutzung vorliegt; ein herbeigeführter Notfall oder ein bestimmtes Produkt ist nicht zu fordern.','Notfallberechtigungen werden zu einem unbeschränkten Zugang zu sensiblen Systemen.','ISO-spezifische Anforderung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('ISO-EMERGENCY-REVIEW','Ausnahmsweise privilegierte Sitzungen werden nach der Nutzung überprüft','Überprüfen Sie die ausnahmsweise privilegierte Nutzung im Nachgang anhand des genehmigten Zwecks und klären Sie unberechtigte Aktivitäten oder offen gebliebene Zugriffe. Für die zugrunde liegenden Aktivitätsaufzeichnungen greift LOG-PRIV, für den Entzug von Zugriffsrechten C40.3. Wird ausnahmsweise privilegierter Zugriff zwar benötigt, war aber bislang nicht im Einsatz, beurteilen Sie die Bereitschaft zur nachgelagerten Überprüfung, ohne ein Szenario als Überprüfung einer tatsächlichen Sitzung darzustellen.','Nachgelagerte Überprüfung von Ausnahmesitzungen, zugehörige Aktivitätsaufzeichnungen, Abweichungen und die bestätigte Schließung temporärer Zugriffe. Bei benötigtem, aber bislang nicht genutztem Ausnahmezugriff sind die festgelegte prüfende Stelle, die Prüfkriterien, die Verfügbarkeit geeigneter Aktivitätsaufzeichnungen und die Regelungen zur Schließung temporärer Zugriffe über einen angemessenen Durchgang (Walkthrough) oder einen gefahrlosen Test zu prüfen. Unterscheiden Sie diese Bereitschaftsnachweise von der Überprüfung einer tatsächlichen Nutzung.','Missbrauch während eines Ausnahmezugriffs bleibt unentdeckt, weil die Genehmigung mit einer Gewähr für die ordnungsgemäße Nutzung verwechselt wird.','ISO-spezifische Anforderung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('ISO-EMPLOYER-DUTIES','Die Arbeitsbedingungen benennen die Sicherheitsverantwortung der Organisation','Prüfen Sie, ob die einschlägigen Arbeitsverträge neben den bereits unter C40.1 beurteilten Pflichten der Beschäftigten auch die Verantwortung der Organisation für die Informationssicherheit benennen. Vorhandene Vertragsklauseln können beide Maßnahmen erfüllen; ergänzt wird die Arbeitgeberseite der Vereinbarung, nicht eine zweite Bestätigung durch die Beschäftigten.','Einschlägige Arbeitsbedingungen oder einbezogene Vertragsklauseln, die die Verantwortung der Organisation und der Beschäftigten ausweisen; Prüfungen über die relevanten Beschäftigungsgruppen hinweg, ohne unnötige personenbezogene Angaben zu übernehmen.','Den Beschäftigten werden Sicherheitsanforderungen auferlegt, ohne dass die Organisation ihre eigene Verantwortung festlegt. Dadurch entstehen Unklarheiten bei beschäftigungsbezogenen Sicherheitsentscheidungen.','ISO-spezifische Anforderung','Personalsicherheit','Personnel security'),
  ('ISO-EXTERNAL-DOCUMENTS','Erforderliche externe Dokumente sind ermittelt und werden gelenkt','Ermitteln Sie die externen Dokumente, die für Planung und Betrieb des ISMS erforderlich sind, etwa vertragliche Anforderungen, Normen und Vorgaben von Lieferanten. Lenken Sie Aktualität und Zugriff so, dass überholte oder nicht verfügbare externe Vorgaben keine Entscheidungen bestimmen.','Verzeichnis externer Dokumente oder gleichwertige Verweise; Versionsprüfungen; gelenkter Zugriff und festgelegte Zuständigkeit für Aktualisierungen.','Überholte externe Anforderungen oder Vorgaben führen zu falschen Sicherheits- oder Konformitätsentscheidungen.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-INFORMATION-IA','Die Informationsklassifizierung umfasst den Bedarf an Integrität und Verfügbarkeit','Bestimmen Sie neben der bereits unter INFO-CLASS beurteilten Vertraulichkeitsklassifizierung die Folgen unbefugter Veränderung und fehlender Verfügbarkeit auf Ebene der Information und berücksichtigen Sie dabei die einschlägigen Anforderungen interessierter Parteien. Greifen Sie auf Schutzniveaus von Werten (Assets) nur dort zurück, wo diese die betroffene Information ausdrücklich abdecken; eine zweite Vertraulichkeitsklassifizierung ist nicht anzulegen.','Aufzeichnungen zur Informationsklassifizierung mit dem Bedarf an Integrität und Verfügbarkeit samt Begründung, verknüpft mit den einschlägigen Anforderungen und den vorhandenen Aufzeichnungen zur Vertraulichkeit oder zum Schutz von Assets.','R1: Informationen sind gegen Offenlegung geschützt, können jedoch ohne ausreichende Sicherungen verändert werden. R2: Eine für eine kritische Entscheidung benötigte Information ist nicht verfügbar, weil ihr Verfügbarkeitsbedarf nie klassifiziert wurde.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-INFORMATION-INVENTORY','Das Verzeichnis erfasst Informationen und zugehörige Werte (Assets) außerhalb der IKT','Ermitteln Sie die Informationsbestände und die relevanten Assets außerhalb der IKT im Anwendungsbereich des ISMS einschließlich der verantwortlichen Eigentümer und pflegen Sie deren Verzeichnis bei Änderungen fort. Greifen Sie auf das Verzeichnis der Dienste und Systeme zurück; ergänzen Sie nur Informationen oder Assets, die dort nicht abgebildet sind, etwa ein Papierarchiv oder einen fachlichen Informationsbestand, der sich über mehrere Systeme erstreckt.','Einträge im Verzeichnis der Informationsbestände und zugehörigen Assets mit Eigentümerschaft und Aktualisierungen; Abgleich mit den Aufzeichnungen zu Diensten und Systemen sowie mit stichprobenweise betrachteten Geschäftstätigkeiten oder physischen Beständen.','Geschäftsinformationen oder Assets außerhalb der IKT bleiben von Schutzentscheidungen ausgenommen, weil das Verzeichnis nur Dienste, Systeme und Geräte aufführt.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-IP-DISPOSAL','Lizenzierte Software wird vor Entsorgung oder Weiterverwendung von Geräten entfernt','Weisen Sie vor der Entsorgung oder Weiterverwendung der betreffenden Geräte nach, dass lizenzierte Software entfernt oder sicher überschrieben wurde. Greifen Sie auf die vorhandene Entsorgungsaufzeichnung zurück; die Entfernung sensibler Daten wird weiterhin durch C40.4 beurteilt.','Aufzeichnungen zu Entsorgung und Weiterverwendung, die die Entfernung oder das Überschreiben lizenzierter Software belegen, verknüpft mit den vorhandenen Nachweisen zur sicheren Datenlöschung.','Geräte verlassen die berechtigte Nutzung mit weiterhin installierter lizenzierter Software, was eine unbefugte Nutzung oder Weitergabe ermöglicht.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-IP-ENTITLEMENTS','Rechte zur Nutzung von Software und geschütztem Material sind festgelegt','Legen Sie die geltenden Bedingungen zum geistigen Eigentum und zur Lizenzierung für beschaffte Software und sonstiges geschütztes Material fest, einschließlich der Eigentumsverhältnisse und der Nutzungsgrenzen, soweit diese einschlägig sind. Nutzen Sie dafür vorhandene Vertrags- und Beschaffungsnachweise.','Lizenzansprüche (Entitlements), Rechte an geschütztem Material sowie einschlägige Beschaffungs- und Eigentumsbedingungen.','Die Organisation setzt Software oder Material ein, ohne über ein gültiges Nutzungsrecht zu verfügen.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-IP-USAGE','Die tatsächliche Nutzung von Software und Material entspricht den eingeräumten Rechten','Gleichen Sie die tatsächlichen Installationen sowie die tatsächliche Nutzung und Vervielfältigung mit den festgelegten Rechten und Grenzen ab und beheben Sie unbefugte Nutzung. Eine Software-Freigabe und eine Aufzeichnung der Lizenzansprüche belegen nicht, dass die tatsächliche Nutzung lizenziert ist.','Abgleich der Nutzung oder der Installationen mit den Lizenzansprüchen, Ausnahmen und Aufzeichnungen zur Behebung.','Die tatsächliche Nutzung überschreitet die Lizenzrechte und führt zu rechtlichen Risiken oder zum Verlust des Zugriffs auf kritische Software.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-ISMS-ACTION-EFFECTIVENESS','Maßnahmen zu ISMS-Risiken und -Chancen werden bewertet','Bewerten Sie, ob die für ISMS-Risiken und -Chancen ergriffenen Maßnahmen die beabsichtigte Wirkung erzielt haben. Nutzen Sie vorhandene Nachweise aus der Leistungsbewertung oder aus Überprüfungen und reagieren Sie dort, wo eine Maßnahme nicht gewirkt hat.','Maßnahmenbezogene Bewertungskriterien, Ergebnisse und Folgeentscheidungen mit Bezug zum ursprünglichen Planungsanliegen.','Abgeschlossene Planungsmaßnahmen gelten als wirksam, während die ursprüngliche Schwäche des Managementsystems fortbesteht.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-ISMS-ACTIONS','Maßnahmen zu ISMS-Risiken und -Chancen sind geplant und eingebunden','Planen Sie Maßnahmen für die ermittelten ISMS-Risiken und -Chancen und binden Sie diese in die Prozesse ein, die sie umsetzen. Bestimmen Sie verantwortliche Umsetzungsregelungen; dies ist keine Wiederholung einzelner technischer Maßnahmen der Risikobehandlung.','Maßnahmenentscheidungen, verantwortliche Prozesseigentümer und die Einbindung in Betriebspläne oder Arbeitsabläufe.','Bekannte Schwächen des ISMS bleiben unbearbeitet, weil Planungsentscheidungen nie in die operative Arbeit gelangen.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-ISMS-AWARENESS','Mitarbeitende verstehen ihren Beitrag zum ISMS','Personen, die unter der Kontrolle der Organisation tätig sind, verstehen die Informationssicherheitsleitlinie, den Beitrag ihrer Arbeit zur Wirksamkeit des ISMS und zur Verbesserung der Sicherheitsleistung sowie die Folgen einer Nichterfüllung der ISMS-Anforderungen. Nutzen Sie die allgemeinen und die rollenspezifischen Sensibilisierungsaktivitäten; geprüft wird das Verständnis, nicht die Durchführung einer zusätzlichen Pflichtschulung.','Vorhandene Sensibilisierungsunterlagen, die diese Punkte abdecken, ergänzt um angemessene Interviews oder praktische Beispiele, die das Verständnis der Mitarbeitenden belegen; Verknüpfung mit vorhandenen Teilnahme- und Bewertungsaufzeichnungen.','Mitarbeitende kennen einzelne technische Regeln, missachten aber die übergreifenden Sicherheitsverantwortlichkeiten oder Konsequenzen, die das Managementsystem erst wirksam machen.','ISO-spezifische Anforderung','Awareness & Schulung','Awareness & training'),
  ('ISO-ISMS-CHANGE-PLAN','Änderungen am ISMS werden vor der Umsetzung geplant','Planen Sie Änderungen am Anwendungsbereich, an den Verantwortlichkeiten, an den Methoden oder an den Prozessen des ISMS, bevor Sie diese umsetzen. Bestimmen Sie die Auswirkungen und die Umsetzungsregelungen; technische Systemänderungen verbleiben in den bestehenden Maßnahmen zur Änderungssteuerung.','Entscheidungen über Änderungen am ISMS, Betrachtungen der Auswirkungen sowie Übergangsregelungen mit Verantwortlichen und Genehmigung.','Eine Änderung der Governance oder des Anwendungsbereichs führt zu nicht zugewiesenen Verantwortlichkeiten oder zu uneinheitlichen ISMS-Prozessen.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-ISMS-MEASUREMENT-DESIGN','Messungen der ISMS-Prozesse haben festgelegte Methoden, Zeitpunkte und Verantwortlichkeiten','Bestimmen Sie, welche ISMS-Prozesse und Leistungsergebnisse überwacht oder gemessen werden müssen, mit welchen Methoden gültige Ergebnisse erzielt werden, wann Überwachung und Analyse stattfinden und wer sie jeweils durchführt. Legen Sie brauchbare Bewertungskriterien fest und bewahren Sie diese Festlegungen auf. Nutzen Sie C37.1 für die Gestaltung der Bewertung von Sicherheitsmaßnahmen und ergänzen Sie nur die dort noch nicht abgedeckten Prozesse des Managementsystems. Ein festes Dashboard, ein Zahlenziel für jeden Prozess oder ein einheitlicher Kennzahlensatz sind nicht erforderlich.','Festlegungen zu Messung und Bewertung auf Prozessebene mit Anwendungsbereich, Methoden, Zeitpunkten für Überwachung und Analyse, verantwortlichen Rollen und Kriterien, verknüpft mit dem bestehenden Programm zur Bewertung der Sicherheitsmaßnahmen.','Die Organisation beurteilt ihr ISMS anhand technischer Testergebnisse, während ungemessene Fehler in der Governance oder in den Betriebsprozessen die beabsichtigten Ergebnisse verhindern.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-ISMS-PERFORMANCE','Die Informationssicherheitsleistung und die Wirksamkeit des ISMS werden bewertet','Nutzen Sie die unter ISO-ISMS-MEASUREMENT-DESIGN und C37.1 festgelegten Methoden, Zeitpunkte, Verantwortlichkeiten und Kriterien, um die Informationssicherheitsleistung und das ISMS insgesamt zu bewerten. Bewahren Sie die Analysen und die Schlussfolgerungen zu den beabsichtigten Ergebnissen auf; einzelne technische Testergebnisse genügen für sich allein nicht.','Leistungsanalyse zu den ISMS-Prozessen und -Zielen, zugrunde liegende Messergebnisse und dokumentierte Schlussfolgerungen; Verknüpfungen zum bestehenden Bewertungsprogramm und zur Managementbewertung.','Einzelne Schutzmaßnahmen erscheinen wirksam, während Fehler des Managementsystems die Organisation daran hindern, ihre Sicherheitsziele zu erreichen.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-ISMS-RISKS-OPPORTUNITIES','Risiken und Chancen mit Auswirkung auf die Ergebnisse des ISMS sind bestimmt','Bestimmen Sie anhand des Kontextes der Organisation und der Anforderungen interessierter Parteien die Risiken und Chancen, die sich auf die beabsichtigten Ergebnisse des ISMS auswirken. Behandeln Sie dabei die Themen des Managementsystems und nicht eine zweite Kopie des technischen Risikoregisters.','Planungsbewertung des ISMS, die den Kontext und die Anforderungen mit Risiken, Chancen und beabsichtigten Ergebnissen verknüpft.','Schwächen des Managementsystems oder Chancen zur Verbesserung werden trotz technischer Risikobeurteilungen übersehen.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-ISMS-UNINTENDED-CHANGE','Unbeabsichtigte Änderungen am ISMS werden überprüft und nachteilige Auswirkungen behandelt','Überprüfen Sie unbeabsichtigte Änderungen, die sich auf den Betrieb des ISMS auswirken, und ergreifen Sie erforderlichenfalls Maßnahmen, um nachteilige Auswirkungen abzumildern. Nutzen Sie dafür tatsächliche Änderungsaufzeichnungen oder ein angemessenes Szenario, wenn keine solche Änderung aufgetreten ist.','Überprüfung unbeabsichtigter Änderungen und Entscheidungen zur Minderung, verknüpft mit den betroffenen ISMS-Prozessen und der Nachverfolgung.','Unerwartete organisatorische Änderungen beeinträchtigen das ISMS, ohne dass ihre Folgen behandelt werden.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-LEADERSHIP-ALIGNMENT','Die oberste Leitung stimmt Sicherheitsleitlinie und Sicherheitsziele auf die Strategie ab','Die oberste Leitung stellt sicher, dass die Sicherheitsleitlinie und die Sicherheitsziele mit der strategischen Ausrichtung der Organisation vereinbar sind. Nutzen Sie die vorhandenen Aufzeichnungen zu Leitlinie und Zielen; geprüft wird die strategische Abstimmung, nicht eine zweite Genehmigung der Leitlinie.','Entscheidungen der Leitung, die Strategie, Leitlinie und Sicherheitsziele miteinander verknüpfen, einschließlich der Auflösung widersprüchlicher Prioritäten.','Sicherheitsziele stehen im Widerspruch zur Geschäftsstrategie und werden bei wesentlichen Entscheidungen übergangen.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-LEADERSHIP-SUPPORT','Die oberste Leitung kommuniziert und unterstützt den wirksamen Betrieb des ISMS','Die oberste Leitung vermittelt die Bedeutung einer wirksamen Informationssicherheit und der Erfüllung der ISMS-Anforderungen und unterstützt die Beschäftigten sowie die zuständigen Führungskräfte dabei, zu den beabsichtigten Ergebnissen und zur Verbesserung beizutragen. Die Angemessenheit der Ressourcen bleibt Gegenstand von C22.2.','Kommunikation der Leitung sowie nachweisbare Unterstützung der verantwortlichen Führungskräfte, Hemmnisse und Entscheidungen zur Verbesserung.','Formale Rollen sind vorhanden, doch ohne aktive Unterstützung der Leitung können die Beschäftigten das ISMS nicht umsetzen.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-LEGAL-COMPLIANCE','Die Umsetzung der anwendbaren Sicherheitspflichten wird geprüft','Prüfen Sie, ob die Organisation die ermittelten Sicherheitspflichten tatsächlich erfüllt, und beheben Sie Lücken. Nutzen Sie die Bewertungen der zugrunde liegenden Maßnahmen erneut; hier wird die Abdeckung der Pflichten bewertet und keine zweite Antwort zur Umsetzung verlangt.','Abgleich der Pflichten mit den Nachweisen, festgestellte Lücken und Korrekturentscheidungen auf Basis vorhandener Bewertungsergebnisse.','Ein vollständiges Rechtsregister erzeugt eine trügerische Sicherheit, obwohl die darin aufgeführten Pflichten nicht umgesetzt sind.','ISO-spezifische Anforderung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('ISO-LEGAL-REQUIREMENTS','Anwendbare Pflichten zur Informationssicherheit werden ermittelt und aktuell gehalten','Führen Sie die anwendbaren rechtlichen, regulatorischen, gesetzlichen und vertraglichen Pflichten zur Informationssicherheit samt verantwortlichen Eigentümern und der Art ihrer Erfüllung. Erfassen Sie relevante Empfänger und Fristen; nutzen Sie bestehende NIS2-Maßnahmen erneut, statt doppelte Meldepflichten zu schaffen.','Aktuelles Anforderungsregister mit Anwendbarkeit, Quellen, Eigentümern, soweit einschlägig Empfängern und Fristen sowie Verknüpfungen zu den Maßnahmen.','Eine verbindliche oder vertragliche Pflicht wird übersehen, ist veraltet oder wird auf den falschen Anwendungsbereich bezogen.','ISO-spezifische Anforderung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('ISO-LOGIN-ATTEMPTS','Wiederholte fehlgeschlagene Anmeldeversuche werden begrenzt','Legen Sie risikoangemessene Grenzwerte oder andere wirksame Schutzmaßnahmen gegen wiederholte fehlgeschlagene Authentifizierungsversuche auf den relevanten Anmeldewegen fest und setzen Sie diese durch. Überprüfen Sie die konfigurierte Reaktion, etwa Verzögerung (Throttling), vorübergehende Sperrung oder zusätzliche Verifizierung, durch sichere Tests. Eine allgemein gültige Anzahl zulässiger Fehlversuche oder ein automatisches Zurücksetzen der Anmeldedaten wird hier nicht vorgeschrieben. C41.8 behält das davon getrennte CIR-Ergebnis zu Sperrung und Zurücksetzen. Nutzen Sie dessen Nachweise erneut, sofern sie diesen Schutz für denselben Anwendungsbereich und Zeitraum belegen; bewerten Sie verbleibende ISO-Anmeldewege gesondert.','Dokumentierte Schutzmaßnahmen gegen Anmeldemissbrauch und deren Risikobegründung; einschlägige Einstellungen des Identitätsanbieters und der Anwendungen; Ergebnisse sicherer Tests mit Testkonten, die die Reaktion auf wiederholte Fehlversuche zeigen; verknüpfte Aufzeichnungen zu erkanntem Missbrauch, soweit vorhanden. Erheben Sie keine produktiv genutzten Passwörter. Nutzen Sie die Testnachweise aus C41.8 erneut, sofern sie dieses Ergebnis belegen.','R1: Ein Angreifer errät wiederholt Anmeldedaten oder verwendet abgeflossene Anmeldedaten erneut, ohne dass eine wirksame Beschränkung greift, und erlangt so unberechtigten Zugriff. R2: Ein schlecht gewähltes Sperrverhalten ermöglicht es einem Angreifer, berechtigten Nutzenden den Zugang zu entziehen, indem er Sperrungen gezielt auslöst.','ISO-spezifische Anforderung','Identitäten, Zugriff & Authentisierung','Identity, access & authentication'),
  ('ISO-MALWARE-COVERAGE','Der Schutz vor Schadsoftware deckt die relevanten Eintrittspunkte und Kanäle ab','Ermitteln Sie, auf welchen Wegen Schadcode in die Systeme im Anwendungsbereich gelangen oder sich darin bewegen kann, einschließlich der relevanten Wege über E-Mail, Web, Wechseldatenträger, Dateifreigaben und Systemübertragungen. Bestätigen Sie, dass für jeden Weg ein risikoangemessener Schutz besteht. Legen Sie fest, wie verschlüsselter Datenverkehr und Archive behandelt werden, durch Inspektion oder durch begründete alternative Schutzmaßnahmen, wenn eine Inspektion nicht geeignet ist. Bewerten Sie Abdeckungslücken, statt den bereits unter C28.1 bewerteten Betrieb des Schutzes erneut zu beurteilen. Ein bestimmtes Produkt, eine bestimmte Anzahl von Sicherheitsprodukten oder eine generelle Entschlüsselung des Datenverkehrs wird nicht gefordert.','Verzeichnis der Eintrittspunkte und Kanäle mit Verknüpfung zu den Schutzmaßnahmen; repräsentative Konfigurationen und Ergebnisse sicherer Tests, die die abgedeckten Wege belegen; dokumentierte Behandlung verschlüsselter Inhalte und von Archiven; begründete Alternativen und festgehaltene Behandlung von Abdeckungslücken. Nutzen Sie vorhandene Nachweise zu Schadsoftwareschutz, Web-Filterung und Wechseldatenträgern durch Verweis erneut.','R1: Schadcode gelangt über eine ungeschützte Dateifreigabe, einen ungeschützten Übertragungsweg oder einen Wechseldatenträger herein, obwohl der Schutz an anderer Stelle wirkt. R2: Verschlüsselte oder archivierte Inhalte umgehen die gewählten Schutzmaßnahmen, weil weder eine geeignete Inspektion noch eine wirksame Alternative umgesetzt wurde.','ISO-spezifische Anforderung','Netz- & Systemhygiene','Network & system hygiene'),
  ('ISO-MR-CONDUCT','Die oberste Leitung bewertet das ISMS in geplanten Abständen','Die oberste Leitung bewertet das ISMS in geplanten Abständen, um dessen fortdauernde Eignung, Angemessenheit und Wirksamkeit festzustellen. Bestehende Governance-Sitzungen können diesem Zweck dienen, sofern die Bewertung des ISMS darin erkennbar ist.','Zeitpunkte der Bewertung, Teilnahme der obersten Leitung und eine erkennbare Bewertung des ISMS; die erforderlichen Eingaben und Ergebnisse werden in gesonderten Maßnahmen bewertet.','Die oberste Leitung prüft nicht regelmäßig, ob das Managementsystem seinen Zweck weiterhin erfüllt.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-MR-DECISIONS','Die Managementbewertung hält Entscheidungen zu Verbesserungen und Änderungen am ISMS fest','Bewahren Sie dokumentierte Ergebnisse der Bewertung auf, einschließlich der Entscheidungen zu Verbesserungsmöglichkeiten und zu einem etwaigen Änderungsbedarf am ISMS. Halten Sie, wo angemessen, auch begründete Entscheidungen fest, das bisherige Vorgehen beizubehalten; ein Sitzungstermin oder eine Foliensammlung allein ist kein Ergebnis.','Festgehaltene Schlussfolgerungen und Entscheidungen der Bewertung, einschließlich erforderlicher Verbesserungen oder Änderungen, mit ausreichender Nachvollziehbarkeit zu den behandelten Themen.','Die Managementbewertung führt zu Diskussionen, aber zu keiner festgehaltenen Vorgabe für Verbesserungen oder notwendige Änderungen.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-MR-FOLLOW-UP','Maßnahmen aus der Managementbewertung werden kommuniziert und nachverfolgt','Teilen Sie die vereinbarten Maßnahmen aus der Bewertung den verantwortlichen Eigentümern mit und verfolgen Sie die Umsetzung oder eine begründet geänderte Entscheidung. Nutzen Sie vorhandene Änderungs- und Verbesserungsaufzeichnungen erneut; legen Sie keine doppelten Maßnahmentickets an.','Eigentümer der Maßnahmen aus der Bewertung, Nachweise zu Kommunikation, Fortschritt und Abschluss sowie der offene Bearbeitungsstand, der der nächsten Bewertung zur Verfügung steht.','Entscheidungen bleiben im Protokoll stehen und bekannte Schwächen des ISMS bestehen trotz Zustimmung der Leitung fort.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-MR-INPUTS','Die Managementbewertung berücksichtigt die geforderten Eingaben zum ISMS','Berücksichtigen Sie Maßnahmen aus vorangegangenen Bewertungen; Änderungen des Kontexts und der Erfordernisse der relevanten interessierten Parteien; Entwicklungen der Sicherheitsleistung einschließlich Nichtkonformitäten, Korrekturmaßnahmen, Messungen, Audits und Zielerreichung; Rückmeldungen der interessierten Parteien; den Stand von Risikobeurteilung und Risikobehandlung; sowie Verbesserungsmöglichkeiten.','Unterlagensammlung der Eingaben zur Bewertung und Aufzeichnung der Erörterung, die die Berücksichtigung jeder relevanten Eingabe belegt, einschließlich früherer Maßnahmen sowie aktueller Risiko- und Leistungsinformationen.','Die Leitung gelangt zu einer scheinbar fundierten Schlussfolgerung, lässt dabei aber wesentliche Änderungen, Leistungsmängel oder ungelöste Risiken außer Acht.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-NC-CAUSE','Die Ursachen von Nichtkonformitäten des ISMS werden ermittelt','Prüfen Sie jede Nichtkonformität und ermitteln Sie deren Ursachen, um angemessene Entscheidungen zur Verhinderung eines erneuten Auftretens zu ermöglichen. Halten Sie Art und Ursache fest; eine bestimmte Methode der Ursachenanalyse ist nicht vorgeschrieben. Die Ursachenanalyse von Vorfällen verbleibt in der Vorfallsbehandlung.','Aufzeichnungen zu Nichtkonformitäten, die den Mangel, die Ursachenanalyse und die Nachweise für die Ursachenfeststellung ausweisen.','Der sichtbare Mangel wird behoben, ohne dass festgestellt wird, warum er aufgetreten ist, sodass derselbe Fehler erneut auftritt.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-NC-CORRECTION','Nichtkonformitäten in ISMS-Prozessen werden beherrscht und ihre Folgen bearbeitet','Reagieren Sie auf Nichtkonformitäten des Managementsystems, indem Sie diese, soweit zutreffend, beherrschen und korrigieren und ihre Folgen bearbeiten. Halten Sie den Mangel und die tatsächlich ergriffene Reaktion fest; das Anlegen einer Aufgabe ist keine Korrektur. Erfasst sind Prozessfehler wie eine unterbliebene Managementbewertung oder nicht gelenkte erforderliche Aufzeichnungen, über die bereits unter C47.1 bewerteten Mängel an Sicherheitsmaßnahmen hinaus. Die Beseitigung der Ursache verbleibt bei ISO-NC-RECURRENCE.','Aufzeichnungen zu Nichtkonformitäten in ISMS-Prozessen, die die Anforderung, den festgestellten Mangel, die Eindämmung oder Korrektur, die Folgen und die tatsächlich ergriffene Reaktion benennen. Verknüpfen Sie vorhandene Aufzeichnungen zu Korrekturmaßnahmen für jeden gemeinsam betroffenen Mangel. Ist keine einschlägige Nichtkonformität in einem Prozess aufgetreten, bewerten Sie die Reaktionsbereitschaft anhand der festgelegten Verantwortlichkeiten und Regelungen für Beherrschung, Korrektur und Bearbeitung der Folgen, mittels einer angemessenen Durchsprache oder eines sicheren Szenarios. Erfinden Sie keinen Mangel; halten Sie die Abdeckung von Abschnitt 10.2 weiterhin unter Beobachtung.','Ein Fehler des Managementsystems besteht fort oder seine Folgen wirken weiter, während die Organisation lediglich die Absicht einer künftigen Korrekturmaßnahme festhält.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-NC-EFFECTIVENESS','Korrekturmaßnahmen in ISMS-Prozessen werden auf ihre Wirksamkeit überprüft','Überprüfen Sie bei Korrekturmaßnahmen zu Nichtkonformitäten in Prozessen des Managementsystems die Umsetzung und beurteilen Sie, ob die Maßnahme die Ursache beseitigt oder das beabsichtigte erneute Auftreten verhindert hat. Bewahren Sie die Ergebnisse auf und nehmen Sie unwirksame Maßnahmen wieder auf. Bewerten Sie erst, nachdem eine angemessene Gelegenheit zur Beobachtung des Ergebnisses bestand; eine abgeschlossene Aufgabe oder das Ausbleiben einer Wiederholung, bevor der Prozess erneut durchlaufen wurde, ist kein ausreichender Nachweis. Nutzen Sie C47.2 erneut, sofern dort dieselbe Maßnahme und derselbe Anwendungsbereich bereits geprüft werden.','An der Ursache ausgerichtete Wirksamkeitskriterien, Nachweise der Umsetzung, Aufzeichnungen zur Nachverfolgung des Prozesses sowie dokumentierte Entscheidungen über Abschluss oder weitere Maßnahmen. Erfundene Fälle oder eine allgemein festgelegte Wartezeit sind nicht erforderlich. Besteht keine einschlägige Maßnahme, prüfen Sie die Regelungen zur Festlegung und Beurteilung der Wirksamkeit und halten Sie fest, dass kein tatsächliches Wirksamkeitsergebnis vorliegt. Besteht eine Maßnahme, ohne dass bereits eine angemessene Gelegenheit zur Beobachtung bestand, bewahren Sie die geplante Überprüfung und deren Status als ausstehend auf; behandeln Sie sie nicht als wirksam bestätigt und schließen Sie Abschnitt 10.2 nicht aus.','Eine Korrekturmaßnahme des Managementsystems wird für erfolgreich erklärt, ohne ihre Wirkung zu prüfen, sodass derselbe Prozessfehler erneut auftreten kann.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-NC-EXTENT','Ähnliche oder mögliche Nichtkonformitäten des ISMS werden bewertet','Stellen Sie fest, ob die festgestellte Nichtkonformität auch an anderer Stelle besteht oder auftreten könnte, und halten Sie den daraus folgenden Handlungsbedarf fest. Nutzen Sie dieselbe Aufzeichnung zur Nichtkonformität. Für Korrektur und Wirksamkeit verwenden Sie C47.1/C47.2 für die Grundgesamtheit der Mängel an Sicherheitsmaßnahmen und ISO-NC-CORRECTION/ISO-NC-EFFECTIVENESS für die übrigen Fälle in ISMS-Prozessen; nutzen Sie eine vorhandene Bewertung erneut, sofern sie dasselbe Ergebnis, denselben Anwendungsbereich und denselben Zeitraum bereits belegt.','Bewertung der Reichweite des Mangels über die relevanten Prozesse, Systeme oder Standorte hinweg sowie verknüpfte Maßnahmen zur Verhinderung eines erneuten Auftretens.','Ein Mangel wird lokal behoben, während derselbe zugrunde liegende Fehler in anderen Teilen der Organisation fortbesteht.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-NC-RECURRENCE','Ermittelte ISMS-Ursachen werden mit angemessenen Maßnahmen gegen ein erneutes Auftreten behandelt','Setzen Sie die als notwendig bestimmte Maßnahme um, um die Ursache zu beseitigen und ein erneutes Auftreten zu verhindern, einschließlich der erforderlichen Änderungen am ISMS. Nutzen Sie C47.1 erneut für Maßnahmen, die Mängel an Sicherheitsmaßnahmen bereits abdecken; hier kommt die Behandlung der Ursache im Managementsystem über die unmittelbare Korrektur hinaus hinzu. ISO-NC-CORRECTION deckt die unmittelbare Reaktion ab; C47.2 und ISO-NC-EFFECTIVENESS liefern die Wirksamkeitsprüfungen für die jeweils betrachtete Grundgesamtheit.','Entscheidungen zur Zuordnung von Ursache und Maßnahme, abgeschlossene Änderungen am Managementsystem und aufbewahrte Ergebnisse, verknüpft mit den vorhandenen Aufzeichnungen zu Korrekturmaßnahmen und zu deren Wirksamkeit.','Die Ursache ist dokumentiert, doch es wird nur der unmittelbare Mangel korrigiert, sodass derselbe Fehler im ISMS erneut auftreten kann.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-NDA-COVERAGE','Die erforderlichen Vertraulichkeitsvereinbarungen erfassen die relevanten Parteien','Überprüfen Sie, ob die erforderlichen Vertraulichkeitsvereinbarungen oder die einbezogenen Vertragsklauseln für die relevanten Parteien dokumentiert und unterzeichnet sind. Nutzen Sie C40.1 und die Ergebnisse aus den Lieferantenverträgen für bereits abgedeckte Grundgesamtheiten erneut; bewerten Sie nur die verbleibenden Abdeckungslücken.','Abgleich der relevanten Parteien mit unterzeichneten Vereinbarungen oder angenommenen Vertragsbedingungen, mit Verknüpfungen zu den vorhandenen Nachweisen aus Personal- und Lieferantenunterlagen.','Geeignete Vertraulichkeitsklauseln bestehen, doch eine Partei, die geschützte Informationen erhält, ist nicht an sie gebunden.','ISO-spezifische Anforderung','Personalsicherheit','Personnel security'),
  ('ISO-NDA-TERMS','Die Vertraulichkeitsklauseln passen zu den Informationen und zur Geschäftsbeziehung','Bestimmen und überprüfen Sie Vertraulichkeitsklauseln, die den geschützten Informationen und der jeweiligen Geschäftsbeziehung angemessen sind, einschließlich der Laufzeit sowie der Rückgabe- oder Vernichtungspflichten, soweit diese erforderlich sind. Vorhandene Klauseln in Arbeits- oder Lieferantenverträgen können ausreichen.','Vertraulichkeitsanforderungen, aktuelle Klauseln und Überprüfungsentscheidungen bei Änderungen der Informationen oder der Geschäftsbeziehungen.','Unterzeichnete Vereinbarungen schützen die tatsächlich betroffenen Informationen nicht oder gelten mit unpassenden Klauseln fort.','ISO-spezifische Anforderung','Personalsicherheit','Personnel security'),
  ('ISO-NETWORK-SERVICE-ASSURANCE','Netzdienste erfüllen die für sie festgelegten Sicherheitsanforderungen','Überprüfen und überwachen Sie die Erfüllung der festgelegten Sicherheitsvereinbarungen für die Netzdienste. Nutzen Sie Lieferantenbewertungen, Netztests und Kapazitätsnachweise erneut; bewerten Sie die Abdeckung interner Dienste oder Anforderungen, die dort noch nicht nachgewiesen ist.','Abgleich der Anforderungen mit Nachweisen zur tatsächlichen Erbringung der Netzdienste, Test- oder Dienstergebnisse sowie Entscheidungen über Korrekturmaßnahmen.','Für einen Netzdienst sind Schutzmaßnahmen auf dem Papier vereinbart, im Betrieb werden sie jedoch nicht erbracht.','ISO-spezifische Anforderung','Netz- & Systemhygiene','Network & system hygiene'),
  ('ISO-NETWORK-SERVICE-REQUIREMENTS','Sicherheits- und Dienstgüteanforderungen an Netzdienste sind festgelegt','Legen Sie die Sicherheitsmechanismen, die Dienstgüten (Service Level) und die Managementanforderungen für die Netzdienste im Anwendungsbereich fest, einschließlich der intern betriebenen Dienste. Nutzen Sie Lieferantenvereinbarungen erneut, soweit diese die Anforderungen bereits festlegen.','Anforderungen an die Netzdienste und die jeweils verantwortlichen Eigentümer, mit den geltenden Vereinbarungen oder den internen Dienstspezifikationen.','Abhängige Systeme verlassen sich auf Schutzmaßnahmen oder Unterstützungsleistungen von Netzdiensten, die nie vereinbart wurden.','ISO-spezifische Anforderung','Netz- & Systemhygiene','Network & system hygiene'),
  ('ISO-OBJECTIVE-PLANS','Für die Sicherheitsziele liegen Umsetzungspläne mit zugewiesenen Ressourcen vor','Bestimmen Sie für jedes Ziel die Maßnahmen, die erforderlichen Ressourcen, die verantwortlichen Eigentümer, den Zeitpunkt der Fertigstellung und die Art, wie die Ergebnisse bewertet werden. Nutzen Sie vorhandene Umsetzungspläne erneut, sofern diese Elemente darin erkennbar sind.','Pläne, die die Ziele mit Maßnahmen verknüpfen, samt Ressourcen, Verantwortlichen, Terminen und Regelungen zur Bewertung.','Die Sicherheitsziele bleiben bloße Absichtserklärungen, weil niemand über einen umsetzbaren Plan zu ihrer Erreichung verfügt.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-OBJECTIVE-REVIEW','Die Sicherheitsziele werden überwacht und aktualisiert','Überwachen Sie den Fortschritt und die Ergebnisse im Hinblick auf die Ziele und aktualisieren Sie die Ziele, wenn dies angemessen ist. Geprüft wird die Leistung auf Zielebene und nicht, ob einzelne technische Schutzmaßnahmen ihre Tests bestehen.','Fortschritt und Ergebnisse zu den Zielen, Bewertung anhand des beabsichtigten Ergebnisses sowie begründete Entscheidungen über Aktualisierungen.','Verfehlte oder überholte Ziele bestimmen weiterhin die Entscheidungen, ohne dass die Leitung die Lücke erkennt.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-OBJECTIVES-DEFINED','Informationssicherheitsziele sind festgelegt und kommuniziert','Legen Sie dokumentierte Informationssicherheitsziele für die relevanten Funktionen und Ebenen fest, die mit der Leitlinie sowie mit den relevanten Anforderungen und Risikoergebnissen im Einklang stehen. Machen Sie die Ziele messbar, soweit dies praktikabel ist, und kommunizieren Sie sie an diejenigen, die danach handeln müssen.','Aktuelle Ziele, ihre Verknüpfung mit Leitlinie und Risiken sowie die Begründung der Messbarkeit, mit den zugehörigen Kommunikationsaufzeichnungen.','Der Organisation fehlt eine klare und gemeinsam getragene Festlegung der Sicherheitsergebnisse, die sie erreichen will.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-OPERATING-PROCEDURES','Die notwendigen Betriebsanweisungen sind dokumentiert und zugänglich','Stellen Sie nutzbare Anweisungen für den Betrieb der Informationsverarbeitung bereit, wo eine einheitliche Ausführung notwendig ist. Erfassen Sie dabei die relevanten Routineaufgaben, die Abhängigkeiten, die Behandlung von Ausnahmen und die Eskalation. Nutzen Sie vorhandene Handbücher zu Datensicherung, Vorfällen, Änderungen und weiteren Themen erneut; erstellen Sie nicht grundsätzlich ein zusätzliches Dokument je System.','Relevante Betriebsanweisungen; aktuelle Zuständigkeit und Zugriffsmöglichkeit; Stichproben aus dem Betrieb, die zeigen, dass die Mitarbeitenden die Anweisungen anwenden können.','Der Routinebetrieb hängt vom Gedächtnis Einzelner ab, und eine uneinheitliche Ausführung schädigt Informationen oder unterbricht Dienste.','ISO-spezifische Anforderung','Netz- & Systemhygiene','Network & system hygiene'),
  ('ISO-OTHER-AREA-PERIMETERS','Weitere sensible Bereiche verfügen über festgelegte und wirksame Sicherheitsgrenzen','Legen Sie Grenzen für die sensiblen Bereiche außerhalb der unter PHY-ZONE bewerteten Technikräume fest und setzen Sie diese um, etwa für Archive oder für Bereiche mit vertraulicher Arbeit. Prüfen Sie, ob Wege über öffentliche oder gemeinsam genutzte Flächen die gewählte Grenze umgehen können; einzelne Zutrittsberechtigungen bleiben Gegenstand von C46.1.','Pläne, welche die zusätzlichen sensiblen Bereiche und die gewählten Grenzen ausweisen, beobachtete Prüfungen auf Umgehungsmöglichkeiten sowie Korrekturen dort, wo Lücken festgestellt wurden; verknüpfen Sie die gemeinsam genutzten Gebäudemaßnahmen, statt Begehungen doppelt durchzuführen.','Personen gelangen über eine ungeschützte Büro- oder Archivgrenze an sensible Informationen, obwohl der Serverraum wirksam geschützt ist.','ISO-spezifische Anforderung','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('ISO-OTHER-EQUIPMENT-PROTECTION','Weitere informationsbezogene Betriebsmittel sind sicher aufgestellt und geschützt','Bewerten Sie die relevanten informationsbezogenen Betriebsmittel, die nicht von PHY-SITING erfasst sind, einschließlich der zugehörigen Betriebsmittel außerhalb der IKT, soweit solche vorhanden sind. Stellen Sie diese so auf und schützen Sie sie so, dass Beschädigungen, unbefugte Handhabung und die Preisgabe von Informationen während der Nutzung verhindert werden; nutzen Sie Schutzmaßnahmen erneut, die für dieselben Betriebsmittel bereits nachgewiesen sind.','Ermittlung der zusätzlichen Betriebsmittel, Entscheidungen zu Aufstellung und Schutz sowie eine Begehung, die den Schutz vor den relevanten Beschädigungen oder vor der Preisgabe von Informationen belegt.','Betriebsmittel außerhalb des Installationsbereichs der IKT werden beschädigt oder geben Informationen preis, weil ihre Aufstellung und ihr Schutz nicht bewertet wurden.','ISO-spezifische Anforderung','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('ISO-OTHER-FACILITY-EXPOSURE','Vertrauliche Arbeit in weiteren Räumlichkeiten ist vor Beobachtung von außen geschützt','Verhindern Sie in den relevanten Büros oder Räumlichkeiten ohne Technikausstattung, dass vertrauliche Arbeit unbefugt gesehen oder gehört wird. Nutzen Sie die Maßnahmen zum Gebäudezutritt und zu den Bereichsgrenzen erneut; geprüft wird hier die Preisgabe während der befugten Arbeit und nicht die Zutrittsberechtigung.','Raumaufteilung und Beobachtungsprüfungen, die den Schutz vor dem relevanten Einblick oder Mithören von außen belegen.','Vertrauliche Informationen werden mitgehört oder eingesehen, ohne dass jemand den geschützten Raum betritt.','ISO-spezifische Anforderung','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('ISO-OTHER-FACILITY-HAZARDS','Weitere ISMS-Räumlichkeiten sind gegen bewertete physische Gefahren geschützt','Wenden Sie geeignete Schutzmaßnahmen auf relevante Büros, Archive und weitere Räumlichkeiten ohne Technikausstattung an, um bewerteten physischen oder umweltbedingten Schäden vorzubeugen. Greifen Sie dabei auf ENV-RISK sowie auf die vorhandenen Brand- und Wasserschutzmaßnahmen zurück; ergänzen Sie nur diejenigen Bereiche, die nicht bereits durch C46.2 abgedeckt sind.','Abdeckung der zusätzlichen Räumlichkeiten, risikobezogene Schutzmaßnahmen sowie Inspektions- oder Prüfergebnisse für ausgewählte Schutzvorkehrungen.','Informationen in Büros oder Archiven werden beschädigt, weil sich der Schutz ausschließlich auf Technikräume konzentriert.','ISO-spezifische Anforderung','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('ISO-OTHER-SECURE-AREA-WORK','Das Arbeiten in weiteren Sicherheitsbereichen folgt festgelegten Schutzregeln','Legen Sie Arbeitsregeln für Sicherheitsbereiche außerhalb der von PHY-WORK abgedeckten Technikräume fest und wenden Sie diese an. Regeln Sie, wer dort tätig werden darf, wo eine Beaufsichtigung erforderlich ist und wie unbefugtes Aufzeichnen oder Entfernen von Informationen verhindert wird. Passen Sie die Regeln an den tatsächlichen Bereich an, statt die Ordnungsvorgaben für Serverräume zu übernehmen.','Regeln für die zusätzlichen Sicherheitsbereiche, Kommunikation an die betroffenen Beschäftigten oder Auftragnehmer sowie Beobachtungen oder Arbeitsaufzeichnungen, die deren Anwendung belegen.','Ein berechtigter Zutritt wird als Erlaubnis missverstanden, geschützte Informationen während der Arbeit im Sicherheitsbereich aufzuzeichnen, offenzulegen oder zu beeinträchtigen.','ISO-spezifische Anforderung','Physische & umgebungsbezogene Sicherheit','Physical & environmental security'),
  ('ISO-PARTIES-ID','Die für das ISMS relevanten interessierten Parteien sind ermittelt','Ermitteln Sie die Parteien, deren Bedürfnisse oder Verpflichtungen sich auf das ISMS auswirken können, einschließlich der relevanten internen und externen Parteien. Begründen Sie deren Relevanz; die Entscheidung, welche Anforderungen das ISMS behandelt, wird gesondert bewertet.','Verzeichnis der interessierten Parteien mit Relevanz und Anwendungsbereich; Abgleich mit den wesentlichen Geschäftsbeziehungen und den internen Verantwortlichkeiten.','Eine relevante Partei wird übersehen, sodass ihre Erwartungen an die Informationssicherheit nie in die ISMS-Planung einfließen.','ISO-spezifische Anforderung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('ISO-PARTIES-REQUIREMENTS','Für die relevanten Anforderungen der interessierten Parteien liegt eine ISMS-Behandlungsentscheidung vor','Bestimmen Sie die relevanten Anforderungen der ermittelten Parteien und legen Sie fest, welche davon das ISMS behandelt. Verknüpfen Sie verbindliche rechtliche und vertragliche Verpflichtungen mit dem bestehenden Anforderungsverzeichnis; behandeln Sie nicht jeden Wunsch als verbindlich.','Zuordnungen von Parteien zu Anforderungen und dokumentierte Behandlungsentscheidungen, einschließlich der anwendbaren Verpflichtungen und der Begründung für die Festlegung des Anwendungsbereichs.','Die ermittelten interessierten Parteien bleiben eine bloße Namensliste, während verbindliche oder wichtige Anforderungen im ISMS unberücksichtigt bleiben.','ISO-spezifische Anforderung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('ISO-POLICY-COMMITMENTS','Die Informationssicherheitsleitlinie enthält die geforderten ISMS-Verpflichtungen','Prüfen Sie, ob die Leitlinie zur Organisation passt, die Festlegung von Informationssicherheitszielen unterstützt und eine Verpflichtung auf die anwendbaren Informationssicherheitsanforderungen sowie auf die fortlaufende Verbesserung des ISMS enthält. Nutzen Sie die vorhandene Leitlinie sowie die bestehenden Genehmigungs- und Kommunikationsaufzeichnungen, statt eine zweite Leitlinie herauszugeben.','Die aktuelle Leitlinie mit erkennbaren Verpflichtungen und Regelungen zur Zielfestlegung, abgeglichen mit dem Zweck der Organisation und den anwendbaren Verpflichtungen; vorhandene Genehmigungs- und Verteilungsaufzeichnungen.','Der Leitlinie fehlen die Verpflichtungen, die Rechtskonformität und Verbesserung steuern, sodass Sicherheitsentscheidungen ohne klaren Auftrag der Leitung getroffen werden.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-PRIVACY-IMPLEMENTATION','Anwendbare Datenschutzmaßnahmen decken die Verarbeitung im gesamten ISMS ab','Setzen Sie die anwendbaren Anforderungen an den Datenschutz und an personenbezogene Daten (personally identifiable information, PII) für die Verarbeitung im Anwendungsbereich des ISMS um. Greifen Sie auf das Rechtsverzeichnis und die gemeinsam genutzten Schutzmaßnahmen zurück; C45.1/C45.2 decken die Verarbeitung zu NIS2-Zwecken ab, nicht jede Verarbeitung im Beschäftigungs- oder Kundenkontext.','Umfang der Verarbeitung und anwendbare Datenschutzpflichten, verknüpft mit den umgesetzten Schutzmaßnahmen, einschließlich Protokollierungs- und Auditaufzeichnungen, soweit einschlägig.','Personenbezogene Daten außerhalb der sicherheitsbezogenen Verarbeitung nach NIS2 werden entgegen den anwendbaren Datenschutzanforderungen verarbeitet.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-PRIVACY-RESPONSIBILITIES','Die beteiligten Parteien kennen ihre Verantwortlichkeiten im Datenschutz','Kommunizieren Sie die anwendbaren Datenschutzverantwortlichkeiten an die Parteien, die an der betreffenden Verarbeitung beteiligt sind. Greifen Sie auf vertragliche Pflichten und Schulungsnachweise zurück; hieraus entsteht keine neue Pflicht, jede interessierte Partei über jeden Verarbeitungsvorgang zu unterrichten.','Zuweisung der Verantwortlichkeiten und deren Kommunikation an die betroffenen Beschäftigten oder Dienstleister, gestützt auf Nachweise, dass die Vorgaben verstanden wurden.','Datenschutzmaßnahmen sind festgelegt, aber die Parteien, welche die Verarbeitung durchführen, kennen ihre Verantwortlichkeiten nicht.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-PROCESS-DESIGN','Die ISMS-Prozesse und ihre Durchführungskriterien sind festgelegt','Legen Sie die zusammenwirkenden ISMS-Prozesse, deren Verantwortliche, Schnittstellen und die Kriterien fest, die zum Erreichen der geplanten Sicherheitsergebnisse erforderlich sind. Regeln Sie dabei auch, wie relevante extern bereitgestellte Prozesse gesteuert werden, und nutzen Sie die vorhandenen Lieferantenaufzeichnungen.','Prozessbeschreibungen oder gleichwertige Ablaufdefinitionen, Schnittstellen, Verantwortliche und Durchführungskriterien; Verknüpfungen zu den Maßnahmen für Lieferanten.','Für die ISMS-Tätigkeiten fehlen vereinbarte Durchführungskriterien, und die Verantwortlichkeiten brechen an den Prozessschnittstellen ab.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-PROCESS-OPERATION','Die ISMS-Prozesse laufen wie geplant innerhalb der Geschäftstätigkeiten ab','Weisen Sie die tatsächliche Durchführung der festgelegten ISMS-Prozesse in den relevanten Geschäftstätigkeiten nach. Bewahren Sie so viele Aufzeichnungen auf, dass die planmäßige Ausführung und die Steuerung relevanter extern bereitgestellter Prozesse belegt sind; nutzen Sie vorhandene Lieferantenbewertungen, statt sie zu wiederholen.','Aktuelle Aufzeichnungen zur Prozessdurchführung und Geschäftsentscheidungen im Abgleich mit den festgelegten Kriterien; vorhandene Aufzeichnungen zur Überwachung ausgelagerter Leistungen.','Das ISMS verfügt über dokumentierte Verfahren, die im tatsächlichen Geschäftsbetrieb jedoch umgangen werden.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-PROJECT-REQUIREMENTS','Projekte außerhalb der Entwicklung setzen ihre Sicherheitsanforderungen um','Ermitteln Sie für diese geschäftlichen oder organisatorischen Projekte die anwendbaren Sicherheitsanforderungen, weisen Sie die Verantwortung für deren Umsetzung zu und prüfen Sie die Erfüllung vor der jeweiligen Abnahmeentscheidung. Greifen Sie auf das Rechtsverzeichnis und die zugrunde liegenden Nachweise zu den Schutzmaßnahmen zurück.','Projektanforderungen, zuständige Verantwortliche und Nachweise der sicherheitsbezogenen Abnahme, verknüpft mit den ermittelten Risiken und Verpflichtungen.','Projektrisiken werden bewertet, die erforderlichen Schutzmaßnahmen sind jedoch nicht umgesetzt, bevor die geschäftliche Veränderung wirksam wird.','ISO-spezifische Anforderung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('ISO-PROJECT-RISKS','Projekte außerhalb der Entwicklung bewerten die Informationssicherheitsrisiken bis zur Fertigstellung','Bewerten Sie die Informationssicherheitsrisiken in den relevanten geschäftlichen oder organisatorischen Projekten von der Initiierung bis zur Fertigstellung und überprüfen Sie diese Bewertung erneut. Wenden Sie dies nur auf diejenigen Projekte an, die nicht bereits durch die gemeinsamen Maßnahmen für Entwicklung und Beschaffung bewertet werden.','Verzeichnis der relevanten Projekte, Risikobewertungen über den Lebenszyklus und Behandlungsentscheidungen, verknüpft mit den Änderungen aus den Geschäftsprojekten.','Ein Geschäftsprojekt führt zu einer nicht bewerteten Offenlegung von Informationen, weil sich die Sicherheitsprüfungen ausschließlich auf die IT-Entwicklung konzentrieren.','ISO-spezifische Anforderung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('ISO-RECORD-READABILITY','Aufbewahrte Geschäftsaufzeichnungen bleiben über Technologiewechsel hinweg lesbar','Erhalten Sie die Aufzeichnungen über den geforderten Zeitraum lesbar und abrufbar, auch wenn sich Formate, Software oder Speicherplattformen ändern. Prüfen Sie den Abruf nach den jeweiligen Migrationen; die bloße Aufbewahrung einer Datei belegt noch keine Lesbarkeit.','Prüfungen zu Abruf und Lesbarkeit, einschlägige Migrationsvorkehrungen und deren Ergebnisse für die aufbewahrten Formate und Aufzeichnungskategorien.','Aufbewahrte Aufzeichnungen werden unbrauchbar, weil die zum Lesen erforderliche Software oder das erforderliche Format nicht mehr verfügbar ist.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-RECORD-RETENTION','Anforderungen an Aufbewahrung und Erhaltung von Geschäftsaufzeichnungen sind festgelegt','Legen Sie für die relevanten Kategorien von Geschäftsaufzeichnungen die Anforderungen an Aufbewahrung und Erhaltung fest, einschließlich geltender rechtlicher oder vertraglicher Erfordernisse. Greifen Sie auf die bereits festgelegten Fristen für Sicherheitsdokumente und Protokolle zurück; erfinden Sie keine einheitliche Aufbewahrungsfrist für alle Fälle.','Regeln zu Aufbewahrung und Erhaltung je Aufzeichnungskategorie mit ihren Begründungen und den verantwortlichen Eigentümern.','Erforderliche Geschäftsaufzeichnungen werden zu früh vernichtet oder ohne begründeten Bedarf weiter aufbewahrt.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-RECORD-SAFEGUARDS','Geschäftsaufzeichnungen sind über die gesamte erforderliche Aufbewahrungsdauer geschützt','Schützen Sie aufbewahrte Geschäftsaufzeichnungen vor Verlust, Zerstörung, Verfälschung und unbefugter Offenlegung. Greifen Sie auf die bestehenden Schutzmaßnahmen für Zugriff und Speicherung zurück und prüfen Sie nur diejenigen Bestände an Aufzeichnungen, die durch diese Maßnahmen noch nicht nachgewiesen sind.','Regelungen zum Schutz von Aufzeichnungen sowie beobachtete Schutzmaßnahmen für Zugriff, Integrität und Wiederherstellung, verknüpft mit den Nachweisen bestehender gemeinsam genutzter Maßnahmen.','Aufzeichnungen sind über den erforderlichen Zeitraum zwar vorhanden, werden aber verändert, gehen verloren oder werden offengelegt und können ihren vorgesehenen Zweck nicht mehr erfüllen.','ISO-spezifische Anforderung','Assets, Klassifizierung & Informationsschutz','Assets, classification & information handling'),
  ('ISO-RESIDUAL-ACCEPTANCE','Risikoeigentümer akzeptieren die Restrisiken der Informationssicherheit','Holen Sie für die ermittelten Restrisiken die Akzeptanz der jeweiligen Risikoeigentümer ein. Greifen Sie auf C30.3 zurück, wenn das freigebende Mitglied der Leitung zugleich Risikoeigentümer ist; eine allgemeine Freigabe durch die Leitung begründet diese Befugnis nicht automatisch.','Entscheidungen zu Restrisiken, die das Risiko, die Annahmen der Risikobehandlung und den akzeptierenden Risikoeigentümer benennen; die vorhandene kombinierte Freigabeaufzeichnung kann dafür ausreichen.','Die verbleibende Gefährdung wird von einer Person akzeptiert, die nicht Eigentümer des Risikos ist oder über die Höhe des Restrisikos nicht informiert ist.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-REVIEW-CHANGE','Wesentliche Änderungen werden unabhängig sicherheitsseitig überprüft','Holen Sie bei wesentlichen Änderungen eine unabhängige Überprüfung des betroffenen Ansatzes für die Informationssicherheit und seiner Umsetzung ein. Richten Sie den Umfang der Überprüfung an der Änderung aus und bewahren Sie Schlussfolgerungen und Nachverfolgung auf. Greifen Sie auf Überprüfungen nach C37.4 und auf Nachweise des internen Audits zurück, wenn diese das Ereignis bereits abdecken; ein unveränderter jährlicher Überprüfungstermin allein belegt nicht, dass die geänderten Regelungen überprüft wurden. Dies ergibt sich aus der Auswahl der ISO-Maßnahmen und nicht allein aus dem Anwendungsbereich des CIR.','Aufzeichnungen zu wesentlichen Änderungen, verknüpft mit dem Umfang der unabhängigen Überprüfung, der Unparteilichkeit der prüfenden Person, den Schlussfolgerungen und der Nachverfolgung. Soweit C37.4 dieselbe Änderung bereits abdeckt, verweisen Sie auf die dortige Bewertung und deren Nachweise, statt die Überprüfung zu wiederholen. Ist keine wesentliche Änderung eingetreten, bewerten Sie die festgelegten Auslöser für eine Überprüfung, die Verantwortung für das Erkennen und Weiterleiten von Änderungen sowie die Regelungen für eine unparteiische Überprüfung anhand eines angemessenen Durchgangs (Walkthrough) oder eines gefahrlosen Szenarios. Damit wird die Bereitschaft belegt, nicht eine abgeschlossene ereignisbezogene Überprüfung.','Eine wesentliche Änderung setzt die bestehenden Sicherheitsregelungen außer Kraft, während die unabhängige Überprüfung weiterhin das frühere Betriebsmodell bewertet.','ISO-spezifische Anforderung','Wirksamkeit, Verbesserung & Aufsicht','Effectiveness, improvement & supervision'),
  ('ISO-RISK-OWNER','Risiken der Informationssicherheit haben verantwortliche Eigentümer','Weisen Sie jedes bewertete Risiko der Informationssicherheit einer Person zu, die befugt ist, dieses Risiko zu steuern. Unterscheiden Sie die Eigentümerschaft am Risiko von der Eigentümerschaft an einem Wert (Asset) und von der Zuständigkeit für die Durchführung einer einzelnen Behandlungsmaßnahme.','Risikoregister mit namentlich benannten oder eindeutig zugeordneten Risikoeigentümern; Bestätigung der übernommenen Eigentümerschaft und Eskalationswege.','Niemand mit entsprechender Verantwortung entscheidet darüber, wie ein wesentliches Risiko behandelt oder akzeptiert wird.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-RISK-PRIORITY','Bewertete Risiken haben begründete Prioritäten für die Risikobehandlung','Nutzen Sie die bereits unter C30.4 bewerteten Risikoeinschätzungen, um die relativen Prioritäten für die Behandlung der Risiken zu bestimmen. Halten Sie fest, warum bestimmte Risiken vor anderen behandelt werden müssen, und erläutern Sie begründete Ausnahmen. Greifen Sie auf das Risikoregister zurück; wiederholen Sie weder die Prüfung der Risikobewertung und Risikoakzeptanz noch die unter C30.5 bewertete Zuordnung von Maßnahmenverantwortung und Terminen.','Prioritäten der Risikobehandlung, verknüpft mit den bewerteten Risiken und ihrer Bedeutung, samt Begründung für Ausnahmen; das vorhandene Risikoregister oder der Risikobehandlungsplan genügt.','Risiken mit hoher Auswirkung werden zurückgestellt, während Maßnahmen geringerer Priorität Ressourcen binden, weil aus den Risikobewertungen keine einheitlichen Behandlungsprioritäten abgeleitet wurden.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-ROLES','Die Verantwortung für die Konformität des ISMS und die Berichterstattung über seine Leistung ist zugewiesen','Weisen Sie Verantwortung und Befugnis für die Konformität des ISMS sowie für die Berichterstattung über die ISMS-Leistung an die oberste Leitung zu und kommunizieren Sie diese. Greifen Sie auf bestehende Sicherheitsrollen zurück, soweit diese die genannten Pflichten abdecken; eine neue Stellenbezeichnung oder ein gesondertes Organigramm ist nicht erforderlich.','Rollenzuweisungen und Befugnisse; Aufzeichnungen zur Kommunikation; Berichte zur ISMS-Leistung.','Anforderungen an das ISMS und Lücken in seiner Leistung bleiben ohne verantwortliche Person oder werden nicht eskaliert.','ISO-spezifische Anforderung','Governance & Management-Verantwortung','Governance & management responsibility'),
  ('ISO-SCOPE','Der Anwendungsbereich des ISMS und seine Grenzen sind dokumentiert','Legen Sie fest, welche Organisationseinheiten, Tätigkeiten, Standorte, Informationen, Schnittstellen und externen Abhängigkeiten zum ISMS gehören. Berücksichtigen Sie dabei den Kontext und die Anforderungen interessierter Parteien. Grenzen Sie diesen Anwendungsbereich von der rechtlichen Einrichtungsgrenze nach NIS2 ab und weisen Sie jeden Unterschied ausdrücklich aus.','Genehmigte Beschreibung des Anwendungsbereichs; Aufzeichnungen zu Schnittstellen und Abhängigkeiten; Abgleich mit dem NIS2-Anwendungsbereich, sofern beide Rahmenwerke gelten.','Relevante Informationen oder Schnittstellen liegen außerhalb des Sicherheitsmanagements, während nach außen eine umfassendere Zertifizierung behauptet wird.','ISO-spezifische Anforderung','Geltungsbereich, Registrierung & Domänendaten','Scope, registration & domain data'),
  ('ISO-SCREENING-ENTRY','Eine angemessene Überprüfung beim Eintritt erfasst den relevanten Personenkreis','Legen Sie eine rechtmäßige und ethisch vertretbare Überprüfung des Hintergrunds fest und führen Sie diese durch, bevor relevantes Personal seine Tätigkeit aufnimmt. Greifen Sie für sensible Rollen auf C40.7 zurück und behandeln Sie den übrigen Personenkreis angemessen zu betrieblichen Erfordernissen, Informationsklassifizierung und Risiko; Führungszeugnisse oder Bonitätsauskünfte sind nicht für jede Person erforderlich.','Abdeckung und angemessene Kriterien der Überprüfung mit geschützt aufbewahrten Aufzeichnungen über den Abschluss; Verknüpfungen zu den bestehenden Prüfungen für sensible Rollen.','Relevantes Personal nimmt Tätigkeiten in einer Vertrauensstellung auf, ohne dass die für die Rolle gerechtfertigte Überprüfung des Hintergrunds erfolgt ist.','ISO-spezifische Anforderung','Personalsicherheit','Personnel security'),
  ('ISO-SCREENING-ONGOING','Die laufende Überprüfung reagiert auf relevante Änderungen der Vertrauensstellung und der Rolle','Legen Sie eine begründete laufende Überprüfung des Hintergrunds fest und führen Sie diese durch, wenn sich Beschäftigung, Zugriffsrechte oder andere relevante Umstände ändern. Halten Sie die rechtmäßigen Gründe fest, erneut zu prüfen oder auf eine erneute Prüfung zu verzichten; die Überprüfung bei der Einstellung allein deckt fortbestehende Vertrauensanforderungen nicht ab.','Kriterien und Auslöser der laufenden Überprüfung, angemessene Prüfentscheidungen und zugriffsbeschränkte Aufzeichnungen der begründeten Prüfungen.','Änderungen, die die Vertrauenswürdigkeit betreffen, bleiben nach der Erstüberprüfung unbetrachtet.','ISO-spezifische Anforderung','Personalsicherheit','Personnel security'),
  ('ISO-SECURITY-FORUMS','Kontakte zu relevanten Sicherheitsforen und Fachstellen werden gepflegt','Pflegen Sie nützliche Kontakte zu einschlägigen Fachgruppen, Foren oder Berufsverbänden im Bereich Sicherheit. Wählen Sie die für die Organisation passenden Kanäle; eine kostenpflichtige Mitgliedschaft oder der Beitritt zu einer gesetzlich vorgesehenen freiwilligen Vereinbarung zum Informationsaustausch ist nicht in jedem Fall erforderlich.','Ausgewählte Kontakte oder Kanäle; verantwortliche Teilnehmende; Beispiele für erhaltene oder ausgetauschte relevante Informationen.','Einschlägiges Fachwissen und sicherheitsrelevante Entwicklungen werden nicht wahrgenommen, wodurch sich fundierte Sicherheitsentscheidungen verzögern.','ISO-spezifische Anforderung','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('ISO-SOA-EXCLUSIONS','Ausgeschlossene Maßnahmen aus Annex A sind belastbar begründet','Begründen Sie jede ausgeschlossene Maßnahme aus Annex A anhand des bewerteten Anwendungsbereichs des ISMS, der Risiken und der geltenden Verpflichtungen. Schließen Sie die Kapitel 4 bis 10 nicht über die Erklärung zur Anwendbarkeit (SoA) aus und setzen Sie eine fehlende Umsetzung nicht mit Nichtanwendbarkeit gleich.','Ausschlussentscheidungen, die durch Nachweise zu Anwendungsbereich und Risiken gestützt sind; Prüfungen auf entgegenstehende geltende Verpflichtungen.','Notwendige Maßnahmen bleiben hinter nicht belegten Entscheidungen zur Nichtanwendbarkeit verborgen.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-SOA-INCLUSIONS','Die Erklärung zur Anwendbarkeit (SoA) benennt die erforderlichen Maßnahmen und die Gründe für ihre Aufnahme','Führen Sie eine Erklärung zur Anwendbarkeit (SoA), in der die erforderlichen Maßnahmen und der Grund für die Aufnahme jeder einzelnen Maßnahme benannt sind. Verknüpfen Sie diese mit Risiken oder anderen anwendbaren Anforderungen und nehmen Sie auch erforderliche Maßnahmen außerhalb von Annex A auf.','SoA-Einträge mit den IDs der erforderlichen Maßnahmen und den Begründungen für deren Aufnahme, abgeglichen mit der Risikobehandlung und den anwendbaren Verpflichtungen.','Die Organisation kann ihre ausgewählten Schutzmaßnahmen nicht begründen und nicht nachweisen, dass erforderliche Maßnahmen außerhalb von Annex A berücksichtigt wurden.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-SOA-STATUS','Der Umsetzungsstatus in der Erklärung zur Anwendbarkeit (SoA) stimmt mit den Aufzeichnungen zu den Maßnahmen überein','Halten Sie fest, ob die erforderlichen Maßnahmen umgesetzt sind, und gleichen Sie die SoA mit den aktuellen Umsetzungsnachweisen ab. Verweisen Sie auf die gemeinsam genutzten Aufzeichnungen zu den Maßnahmen, statt eine zweite Angabe zur Umsetzung zu pflegen.','SoA-Status, verknüpft mit den aktuellen Bewertungsaufzeichnungen, samt untersuchten und korrigierten Abweichungen.','Die Leitung oder die Auditoren verlassen sich auf eine SoA, die eine Umsetzung ausweist, welche die zugrunde liegenden Nachweise nicht belegen.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-SOURCE-READ','Der lesende Zugriff auf Quellcode und Entwicklungsressourcen ist eingeschränkt','Beschränken Sie das Lesen und das Extrahieren von Quellcode, Bibliotheken und Entwicklungsressourcen auf autorisierte Bedarfe. Überprüfen Sie die betreffenden Zugriffsrechte und die externe Freigabe. Für den Schutz vor Änderungen und für den Schutz von Release-Branches nutzen Sie D04-16 erneut; ein Schreibschutz allein schützt vertraulichen Quellcode nicht.','Leseberechtigungen in Repositorys und Entwicklungswerkzeugen; Einstellungen zur externen Freigabe; Genehmigungen der Eigentümer und Aufzeichnungen der Überprüfungen.','Unbefugte Leserinnen und Leser erlangen vertraulichen Code oder Entwicklungswissen, obwohl sie diesen nicht verändern können.','ISO-spezifische Anforderung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('ISO-TEST-PROTECTION','Testinformationen außerhalb der Entwicklung sind bis zu ihrer sicheren Entfernung geschützt','Schützen Sie Informationen, die in Tests außerhalb der Entwicklung verwendet werden, beim Kopieren, Speichern, Zugreifen, Übertragen und Entsorgen. Wenden Sie die für den jeweiligen Datenbestand begründete Bereinigung (Sanitisierung) oder Maskierung an und überprüfen Sie sie, beschränken Sie die Nutzung auf autorisierte Testbeteiligte und entfernen Sie nicht benötigte Kopien, sobald der genehmigte Bedarf endet. Nutzen Sie vorhandene Nachweise zu Zugriff, Maskierung und Löschung erneut. Identische Berechtigungen in Test und Produktion sind nicht erforderlich. Für Datenbestände der Entwicklung gelten weiterhin D04-21 und D04-22.','Schutzvorkehrungen für Zugriff und Speicherung der Datenbestände außerhalb der Entwicklung, Überprüfungen der gewählten Maskierung oder Bereinigung, Aufzeichnungen zur genehmigten Aufbewahrung und Entfernung sowie Nachweise zu übertragenen Kopien. Verwenden Sie synthetische oder geschwärzte Stichproben.','Unbefugte erlangen sensible Testinformationen durch übermäßige Zugriffsrechte, durch eine unwirksame Bereinigung oder durch Kopien, die nach dem Ende eines betrieblichen Tests aufbewahrt bleiben.','ISO-spezifische Anforderung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('ISO-TEST-SELECTION','Testinformationen außerhalb der Entwicklung werden zweckbezogen ausgewählt und genehmigt','Wählen Sie für Tests außerhalb der eigenen oder der beauftragten Entwicklung Informationen aus, die zum Testzweck passen, und bewerten Sie vor der Nutzung deren Sensibilität und Erforderlichkeit. Holen Sie für die Verwendung von Produktivdaten (Live-Daten) oder sensiblen Informationen eine angemessene Genehmigung ein und bevorzugen Sie geeignete synthetische oder bereinigte Daten, sofern diese den Bedarf decken. Beispiele sind der Test einer beschafften Anwendung, einer Konfigurationsänderung oder eines Wiederherstellungsverfahrens. Für die Auswahl von Testdaten in der Entwicklung bleibt D04-20 die maßgebliche Bewertung; verlangen Sie für diese Grundgesamtheit keine zweite Angabe.','Testpläne außerhalb der Entwicklung, Entscheidungen zur Auswahl der Datenbestände und zu deren Sensibilität, Genehmigung für Produktivdaten, soweit erforderlich, sowie Nachvollziehbarkeit zum getesteten System und zum Testzweck. Verwenden Sie Beschreibungen oder geschützte Vorführungen, statt Produktivdatenbestände zu kopieren.','R1: Sensible Produktivinformationen werden im betrieblichen Test unnötig offengelegt. R2: Ungeeignete Testinformationen bilden wichtige Betriebsbedingungen nicht ab, sodass eine fehlerhafte Änderung oder ein fehlerhaftes Wiederherstellungsverfahren als erfolgreich erscheint.','ISO-spezifische Anforderung','Beschaffung, Entwicklung & Änderungen','Acquisition, development & change'),
  ('ISO-THREAT-ANALYSIS','Bedrohungsinformationen werden analysiert und als verwertbare Erkenntnisse bereitgestellt','Analysieren Sie die erhobenen Bedrohungsinformationen im Kontext der Organisation und stellen Sie verwertbare Schlussfolgerungen den zuständigen Verantwortlichen für Risiko, Überwachung oder Reaktion bereit. Ein Feed-Abonnement oder eine weitergeleitete Sicherheitsmeldung allein ist keine Analyse.','Datierte Bedrohungsbewertungen mit Bezug zum Betrieb und zu den Werten (Assets), bereitgestellte Schlussfolgerungen sowie die daraus folgenden Entscheidungen oder begründeten Entscheidungen, keine Maßnahme zu ergreifen.','Relevante Bedrohungsinformationen werden zwar erhoben, fließen aber nie in Schutz- oder Reaktionsentscheidungen ein.','ISO-spezifische Anforderung','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('ISO-THREAT-SOURCES','Quellen für Bedrohungsinformationen werden nach ihrer Relevanz für die Organisation ausgewählt','Wählen und überprüfen Sie interne und externe Quellen, die für die Bedrohungen und den Betrieb der Organisation relevant sind, einschließlich des weiteren Angreiferverhaltens, soweit dieses relevant ist. Nutzen Sie vorhandene Feeds mit Schwachstellenmeldungen erneut; geprüft wird die Eignung der Quellen, nicht der Umfang der Abonnements.','Begründung der Quellenauswahl, Zuständigkeiten für die Erhebung sowie Überprüfungen der Relevanz und der Zuverlässigkeit der Quellen.','Die Bedrohungsanalyse stützt sich auf unpassende oder unzuverlässige Quellen und übersieht die Bedrohungen, von denen die Organisation betroffen ist.','ISO-spezifische Anforderung','Schwachstellen- & Patch-Management','Vulnerability & patch management'),
  ('ISO-TREATMENT-PLAN-APPROVAL','Die Risikoeigentümer genehmigen den Risikobehandlungsplan','Holen Sie die Genehmigung des Behandlungsplans und der darin ausgewählten Maßnahmen durch die zuständigen Risikoeigentümer ein. Kennzeichnen Sie die genehmigte Version; diese Entscheidung ist von der Akzeptanz der nach der Behandlung verbleibenden Risiken zu unterscheiden.','Behandlungsplan und Genehmigung durch die benannten Risikoeigentümer, verknüpft mit der vereinbarten Version und den Behandlungsentscheidungen.','Die Behandlung wird umgesetzt, ohne dass der verantwortliche Risikoeigentümer der geplanten Reaktion zugestimmt hat.','ISO-spezifische Anforderung','Risikomanagement & Sicherheitsrichtlinien','Risk management & security policies'),
  ('ISO-WEB-ENFORCEMENT','Die Schutzvorkehrungen für den Webzugriff setzen die festgelegten Einschränkungen durch','Setzen Sie die festgelegten Schutzvorkehrungen gegen schädliche Webinhalte um und überprüfen Sie sie. Prüfen Sie das jeweilige Sperr- bzw. Freigabeverhalten und die genehmigten Ausnahmen auf gefahrlose Weise; das Regelwerk allein belegt die Durchsetzung nicht.','Durchgesetzte Einstellungen für den Webzugriff, gefahrlose funktionale Prüfungen sowie die Korrektur von Umgehungen oder unbeabsichtigten Ausnahmen.','Nutzende gelangen trotz dokumentierter Einschränkungen des Webzugriffs an schädliche Inhalte.','ISO-spezifische Anforderung','Netz- & Systemhygiene','Network & system hygiene'),
  ('ISO-WEB-RULES','Die Einschränkungen des Webzugriffs werden aus dem Sicherheitsrisiko abgeleitet','Bestimmen Sie die Einschränkungen des Webzugriffs, die erforderlich sind, um die Exposition gegenüber schädlichen Inhalten zu verringern, einschließlich begründeter Ausnahmen. Wählen Sie Regeln oder Kategorien, die zur Organisation passen; eine allgemeine Freigabeliste oder die Untersuchung jeder verschlüsselten Verbindung ist nicht vorgeschrieben.','Risikobegründung für den Webzugriff, festgelegte Einschränkungen bzw. Kategorien sowie Regelungen zur Genehmigung von Ausnahmen.','Die Regeln zum Schutz des Webzugriffs sind willkürlich oder lassen die Exposition außer Acht, welche die Organisation verringern muss.','ISO-spezifische Anforderung','Netz- & Systemhygiene','Network & system hygiene')
) AS v(id,titel,beschreibung,nachweis,risiko,untergruppe,thema_de,thema_en)
WHERE c.framework IN ('NIS2','ISO27001') AND c.id = v.id;

-- ----------------------------------------------------------------------------
-- 2) Risikotexte. 362 Risiken (R6-*). Anders als bei den Kontrollen
--    gibt es hier eine echte Sprachtrennung: risks.text_de / risks.text_en
--    werden getrennt gelesen (useRiskAnalysis.ts:435, riskEngine.ts:526). Live
--    steht in beiden Spalten derselbe englische Satz — in allen 362 Zeilen.
--    Nur text_de wird gesetzt; text_en bleibt unberührt.
-- ----------------------------------------------------------------------------
UPDATE public.risks r SET
  text_de = v.txt,
  meta = COALESCE(r.meta,'{}'::jsonb) || jsonb_build_object('language','de+en')
FROM (VALUES
  ('R6-C12.1','Eine Änderung des Anwendungsbereichs, der Einstufung oder der rechtlichen Zuständigkeit bleibt unbemerkt, sodass Pflichten versäumt werden oder die Einrichtung sich an die falsche zuständige Behörde hält.'),
  ('R6-C11.1','Behördliche Mitteilungen oder erforderliche Folgemaßnahmen verzögern sich, weil kein bevollmächtigter EU-Vertreter für den Anbieter handeln kann.'),
  ('R6-C14.1','Unvollständige oder unrichtige Daten verhindern die korrekte Identifizierung, die Nachverfolgung des Status im Anwendungsbereich oder die Kontaktaufnahme durch die zuständige Behörde.'),
  ('R6-C14.2','Die zuständige Behörde kann die Einrichtung im vorgeschriebenen Registrierungsverfahren nicht zuverlässig erfassen oder kontaktieren, sodass eine unterlassene oder verspätete Übermittlung korrigierende Folgemaßnahmen auslöst.'),
  ('R6-C15.2','Die behördlichen Registerangaben bleiben veraltet, der Kontakt mit der Aufsichtsbehörde wird beeinträchtigt und die Pflicht zur Mitteilung von Änderungen wird nicht erfüllt.'),
  ('R6-C19.3','Registranten und andere Nutzende können nicht nachvollziehen oder beanstanden, wie Registrierungsdaten überprüft werden, was zu uneinheitlichen Angaben und vermeidbaren Streitigkeiten führt.'),
  ('R6-C19.1','Fehlerhafte Angaben zu Domain-Inhabern verzögern die Identifizierung und Kontaktaufnahme bei Missbrauchsuntersuchungen oder der Reaktion auf Sicherheitsvorfälle.'),
  ('R6-C19.2','Falsche Registrantenangaben oder Kontaktdaten, unter denen niemand erreichbar ist, werden als echt akzeptiert, sodass sich missbräuchliche Registrierungen einer verlässlichen Zuordnung und weiteren Verfolgung entziehen.'),
  ('R6-C19.4','R1: Untersuchende und andere Nutzende können erforderliche nicht personenbezogene Domain-Informationen nicht zeitnah erhalten, wodurch sich die Erkennung und weitere Verfolgung von Missbrauch verzögern. R2: Eine Veröffentlichung, die nicht zwischen personenbezogenen und nicht personenbezogenen Feldern unterscheidet, legt personenbezogene Informationen der Registranten gegenüber der Öffentlichkeit offen.'),
  ('R6-C19.8','Berechtigte Antragstellende können den Antragsweg oder die Anforderungen nicht erkennen, sodass Anträge falsch zugeleitet oder verzögert werden.'),
  ('R6-C19.5','R1: Unbegründete oder übermäßige Offenlegungen machen nicht öffentliche Registrierungsdaten unbefugten Antragstellenden zugänglich. R2: Rechtmäßige, begründete Anträge werden zu Unrecht abgelehnt, wodurch berechtigte Missbrauchsuntersuchungen behindert werden.'),
  ('R6-C19.6','Antworten verzögern sich, Untersuchungen werden behindert und die Frist zur Beantwortung von Zugangsanträgen wird versäumt.'),
  ('R6-C19.9','Wiederholte Erhebungen erzeugen widersprüchliche Registrantenaufzeichnungen und unnötige Kopien personenbezogener Daten, verzögern Korrekturen und erhöhen das Offenlegungsrisiko.'),
  ('R6-C27.1','Eine rechtlich verantwortliche Person kann erforderliche Maßnahmen nicht durchsetzen, sodass Verstöße gegen Compliance-Anforderungen aufgrund fehlender Befugnisse ungelöst bleiben.'),
  ('R6-C22.1','Sicherheitsmaßnahmen werden angefochten oder umgangen, weil die Leitung ihre Prioritäten und Verbindlichkeit nicht bestätigt hat, wodurch sich die Umsetzung verzögert.'),
  ('R6-C22.2','Genehmigte Maßnahmen funktionieren nicht, weil Personal, Zeit, finanzielle Mittel oder Werkzeuge fehlen, sodass Risiken unbehandelt bleiben.'),
  ('R6-C27.3','Eine Person kann eine unzulässige Handlung ohne wirksame unabhängige Kontrolle einleiten, genehmigen und verbergen.'),
  ('R6-C27.2','Wesentliche Sicherheitsprobleme werden gefiltert oder verzögert, bevor sie die Leitung erreichen, sodass Entscheidungen und Korrekturmaßnahmen zu spät erfolgen.'),
  ('R6-C23.1','Die Leitung stützt sich auf unvollständige oder veraltete Informationen und übersieht schwerwiegende Mängel oder verzögerte Maßnahmen.'),
  ('R6-C23.2','Bekannte Mängel bestehen fort, weil die Leitung nicht entscheidet, eingreift oder nachfasst; die Aufsicht wird zu einer bloßen Berichtsformalität.'),
  ('R6-C27.4','Sicherheitsaufgaben werden nach organisatorischen Änderungen versäumt oder verzögert, weil Verantwortlichkeiten und verfügbares Personal nicht mehr dem betrieblichen Bedarf entsprechen.'),
  ('R6-C25.2','Die Leitung beurteilt Prioritäten der Risikobehandlung falsch oder akzeptiert eine Risikoexposition, die sie nicht versteht, weil die Schulung die notwendigen Fähigkeiten im Risikomanagement nicht vermittelt hat.'),
  ('R6-C25.1','Ungeschulte Mitglieder des Leitungsorgans treffen Genehmigungs- oder Aufsichtsentscheidungen, ohne wesentliche Auswirkungen auf die Cybersicherheit und auf Abhängigkeiten zwischen Diensten zu erkennen.'),
  ('R6-C29.2','Teams treffen unvereinbare Sicherheitsentscheidungen oder umgehen regelmäßig vereinbarte Schutzmaßnahmen, sodass Informationen und Dienste an organisatorischen Schnittstellen ungeschützt bleiben.'),
  ('R6-C29.5','R1: Im Betrieb werden veraltete Anweisungen verwendet, was zu fehlerhaften Sicherheitsmaßnahmen führt. R2: Verlorene oder nicht auffindbare Aufzeichnungen verhindern, dass Sicherheitsentscheidungen oder deren Umsetzung rekonstruiert und belegt werden können.'),
  ('R6-C29.3','Mitarbeitende oder externe Parteien gehen unsachgemäß mit Informationen um oder umgehen erforderliche Schutzmaßnahmen, weil die für ihre Arbeit relevanten Anweisungen nicht verstanden oder nicht befolgt werden.'),
  ('R6-C29.4','Mitarbeitende befolgen veraltete Regeln, die geänderte Systeme oder Arbeitsweisen nicht mehr schützen, sodass zuvor behandelte Gefährdungen erneut auftreten.'),
  ('R6-C29.1','Bewertungen lassen relevante Bedrohungen aus oder wenden unvereinbare Annahmen an, sodass Behandlungsentscheidungen wesentliche Gefährdungen unberücksichtigt lassen.'),
  ('R6-C30.4','Risikoeinstufungen hängen ohne gemeinsame Grundlage von individuellen Einschätzungen ab, wodurch Prioritäten und Akzeptanzentscheidungen verzerrt werden.'),
  ('R6-C30.1','Erhebliche Risiken werden übersehen oder falsch eingestuft, was zu ungeeigneten Prioritäten und Maßnahmen führt.'),
  ('R6-C30.2','Behandlungsentscheidungen lassen sich nicht auf die Risiken und Annahmen zurückführen, auf die sie sich beziehen, sodass bei einer erneuten Prüfung der Entscheidungen ungeeignete Schutzmaßnahmen oder unbehandelte Gefährdungen entstehen.'),
  ('R6-C30.5','Die Behandlung gerät ins Stocken, Maßnahmen verlieren ihre Verantwortlichen oder ungelöste Risiken bestehen hinter bloßen Abschlussbehauptungen fort.'),
  ('R6-C30.3','Eine verbleibende Risikoexposition wird ohne Befugnis oder Verständnis akzeptiert, oder die Akzeptanz wird fälschlich zur Rechtfertigung von Regelverstößen genutzt.'),
  ('R6-C30.6','Veränderungen bei Systemen, Bedrohungen oder Sicherheitsvorfällen machen die Annahmen der Risikobehandlung ungültig, sodass neue oder erhöhte Gefährdungen unbehandelt bleiben.'),
  ('R6-C42.1','Nicht erfasste Assets werden bei der Installation von Patches, der Zugriffskontrolle oder der Bestimmung des Vorfallsumfangs übergangen, sodass eine Kompromittierung außerhalb der betrieblichen Aufsicht fortbesteht.'),
  ('R6-C42.3','Schutz- oder Wartungsmaßnahmen für Assets bleiben unerledigt, weil Teams annehmen, andere Verantwortliche würden handeln, wodurch bekannte Gefährdungen oder Dienststörungen länger bestehen bleiben.'),
  ('R6-C42.2','R1: Schutzaufwand wird falsch zugeteilt, weil die Auswirkungen von Assets auf Dienste und ihre Abhängigkeiten unterschätzt werden, sodass prioritäre Betriebsabläufe störungsanfällig bleiben. R2: Unterschätzte Integritätsanforderungen ermöglichen Änderungen kritischer Daten oder Systemkonfigurationen ohne angemessene Schutzmaßnahmen, was zu falschen Geschäftsentscheidungen oder unsicheren Betriebsabläufen führt.'),
  ('R6-C42.4','Veraltete Asset-Angaben führen dazu, dass neue oder geänderte Systeme bei Sicherheitsaufgaben übergangen werden und Maßnahmen zur Vorfallsbearbeitung oder Wiederherstellung fehlgeleitet werden.'),
  ('R6-INFO-CLASS','Sensible Informationen werden als öffentlich oder intern behandelt, wodurch unbefugter Zugriff oder unbefugte Offenlegung möglich wird.'),
  ('R6-INFO-LABEL','R1: Nutzende oder automatisierte Verarbeitungsregeln legen vertrauliche Informationen offen, weil die sichtbare Kennzeichnung eine niedrigere Schutzklasse ausweist. R2: Kennzeichnungen oder Asset-Markierungen selbst offenbaren unbefugten Personen sensible Angaben zu Personal, Standorten oder Netzwerken und unterstützen dadurch Auskundschaftung oder gezielte Täuschung.'),
  ('R6-INFO-CLASS-REV','Veraltete Vertraulichkeitsstufen lassen sensible Informationen ungeschützt oder führen nach einer Änderung ihrer Sensibilität zu unnötigen Einschränkungen.'),
  ('R6-C45.2','Bei Sicherheitsaktivitäten werden personenbezogene Daten rechtswidrig verarbeitet, wodurch die Einrichtung Beschwerden, Durchsetzungsmaßnahmen und Verarbeitungsbeschränkungen ausgesetzt wird.'),
  ('R6-C45.1','Übermäßige Überwachung oder Aufbewahrung setzt betroffene Personen unnötigen Risiken aus und vergrößert die Folgen einer Verletzung des Schutzes personenbezogener Daten.'),
  ('R6-C42.5','R1: Unsachgemäßer Umgang führt zur Beschädigung oder zum Verlust von Geräten und Datenträgern, unterbricht die Arbeit oder macht benötigte Informationen unzugänglich. R2: Ein Umgang, der die Sensibilität nicht berücksichtigt, macht Informationen unbefugten Personen zugänglich.'),
  ('R6-C42.6','R1: Informationen werden während der Weitergabe abgefangen oder an einen unbeabsichtigten Empfänger übermittelt. R2: Übertragene Daten werden verändert oder unvollständig, sodass der Empfänger auf Grundlage unrichtiger Informationen handelt.'),
  ('R6-DATA-OUTFLOW','Sensible Informationen werden über ein autorisiertes Konto oder einen nicht genehmigten Übertragungskanal ausgeschleust; eine verzögerte Erkennung ermöglicht weitere Offenlegungen.'),
  ('R6-DATA-MASK','Personen, die nur begrenzte Informationen benötigen, erhalten vollständige sensible Werte über Anzeigen, Exporte oder eine uneingeschränkte Reidentifizierung.'),
  ('R6-MEDIA-UNATTENDED','Besuchende oder unbefugte Mitarbeitende lesen, fotografieren oder entwenden unbeaufsichtigt zurückgelassenes sensibles Material.'),
  ('R6-ASSET-OFFSITE','R1: Verlust, Diebstahl oder Beobachtung eines außerhalb der Einrichtung genutzten Assets legt Informationen der Einrichtung offen. R2: Beschädigung oder Verlust eines außerhalb der Einrichtung genutzten Assets unterbricht die Arbeit oder macht lokal gespeicherte Daten unzugänglich.'),
  ('R6-C42.7','R1: Nicht genehmigte Wechseldatenträger bringen Schadcode in angeschlossene Systeme ein. R2: Nutzende kopieren sensible Informationen auf nicht genehmigte Datenträger und entziehen sie der Kontrolle der Einrichtung.'),
  ('R6-C42.8','R1: Schadcode wird von Wechseldatenträgern ausgeführt und stiehlt Informationen oder Zugangsdaten. R2: Über Datenträger eingebrachte Schadsoftware beschädigt Daten, stört Systeme oder breitet sich auf verbundene Dienste aus.'),
  ('R6-C42.9','R1: Verlorene oder gestohlene tragbare Datenträger legen lesbare sensible Informationen offen. R2: Verlust oder Beschädigung tragbarer Datenträger macht benötigte Informationen unzugänglich, wenn keine nutzbare Kopie vorhanden ist.'),
  ('R6-TRN-DATA','R1: Mitarbeitende handhaben sensible dienstliche Informationen unsachgemäß, legen sie offen oder eskalieren deren Verlust nicht rechtzeitig. R2: Mitarbeitende bringen durch unsichere Nutzung von Wechseldatenträgern Schadcode ein.'),
  ('R6-DATA-DELETE','R1: Veraltete sensible Daten werden bei späterem Zugriff, Offenlegung oder Wiederherstellung exponiert, wodurch sich der betroffene Datenbestand und Zeitraum eines Datenlecks vergrößern. R2: Daten werden gelöscht, bevor erforderliche Aufbewahrungs- oder Sicherungsbedarfe enden; dadurch werden Unterlagen vernichtet, die für den Betrieb, Untersuchungen oder die Begründung von Entscheidungen benötigt werden.'),
  ('R6-C40.12','R1: Ehemalige Mitarbeitende behalten Informationen der Einrichtung und legen sie nach dem Ende ihrer Berechtigung offen. R2: Nicht zurückgegebene Geräte oder fortbestehende Zugriffe ermöglichen die unbefugte Nutzung von Ressourcen der Einrichtung.'),
  ('R6-C40.4','Empfangende wiederverwendeter, verkaufter oder entsorgter Geräte stellen verbliebene sensible Informationen wieder her.'),
  ('R6-C40.7','Eine Person, bei der relevante und rechtmäßig feststellbare Zweifel an der Vertrauenswürdigkeit bestehen, erhält sensiblen Zugriff und missbraucht ihn, um Informationen zu erlangen oder Systeme zu manipulieren.'),
  ('R6-C40.6','Mitarbeitende machen sicherheitsrelevante Konfigurationsfehler oder Fehler bei der Reaktion, weil die zugewiesenen Aufgaben ihre Fähigkeiten übersteigen; dadurch werden Informationen offengelegt oder Dienststörungen verlängert.'),
  ('R6-C40.1','Mitarbeitende legen Informationen offen oder missbrauchen sie, nachdem sie Zugriff erhalten haben, ohne ihre Sicherheits- und Vertraulichkeitspflichten zu verstehen und zu akzeptieren.'),
  ('R6-C40.9','Verstöße werden ignoriert oder uneinheitlich behandelt, wodurch wiederholtes unsicheres Verhalten oder ungerechte Behandlung ermöglicht wird.'),
  ('R6-C40.8','Ehemalige oder in andere Rollen versetzte Mitarbeitende legen Informationen offen oder missbrauchen sie, weil fortbestehende Pflichten unklar sind.'),
  ('R6-TRN-07','Rollenspezifische Sicherheitsaufgaben werden fehlerhaft ausgeführt, weil allgemeine Schulungen die tatsächlich verwendeten Werkzeuge, Berechtigungen oder Gefährdungen der Rolle nicht behandeln.'),
  ('R6-TRN-04','Mitarbeitende improvisieren unsichere Vorgehensweisen beim Umgang mit Informationen oder melden Bedenken verspätet, weil nutzbare Hinweise und Kontaktinformationen nicht auffindbar sind.'),
  ('R6-TRN-02','Neue Mitarbeitende legen Informationen offen oder befolgen betrügerische Anweisungen, bevor sie die wesentlichen Sicherheitspraktiken für ihre Arbeit erlernt haben.'),
  ('R6-TRN-03','Mitarbeitende wiederholen unsichere Praktiken oder können zugewiesene Sicherheitsaufgaben nicht ausführen, weil geplante Sensibilisierung und rollenbezogene Schulungen nicht durchgeführt oder aufgefrischt werden.'),
  ('R6-TRN-09','Versetzte Mitarbeitende machen bei der Ausführung ungewohnter Aufgaben sicherheitsrelevante Fehler und legen dadurch Informationen offen oder unterbrechen den betroffenen Betrieb.'),
  ('R6-TRN-05','Mitarbeitende bleiben außerstande, Bedrohungen zu erkennen oder zugewiesene Sicherheitsaufgaben auszuführen, weil Teilnahme mit wirksamem Lernen verwechselt wird und Defizite nicht behoben werden.'),
  ('R6-TRN-06','Mitarbeitende befolgen veraltete Hinweise zur Cyberhygiene und gehen mit aktuellen Bedrohungen oder veränderten Arbeitsweisen unsachgemäß um.'),
  ('R6-C40.2','Nutzende erhalten Zugriff über den berechtigten betrieblichen Bedarf hinaus; dadurch werden unbefugte Offenlegung, Änderung oder Löschung von Informationen sowie Störungen des betroffenen Dienstes ermöglicht.'),
  ('R6-C40.10','R1: Verwaiste Benutzer- oder Systemkonten werden für unbefugten Zugriff genutzt, und unklare Verantwortlichkeit verzögert die Eindämmung. R2: Ein Konto wird der falschen Person oder technischen Identität zugeordnet, wodurch die falsche Stelle Zugriff erhält und nachfolgende Aktionen falsch zugerechnet werden.'),
  ('R6-C40.3','R1: Nicht genehmigte oder veraltete Berechtigungen werden verwendet, um Informationen einzusehen oder zu verändern, nachdem der betriebliche Bedarf entfallen ist. R2: Fehlerhafte Zugriffsänderungen oder ein verfrühter Entzug verhindern, dass berechtigte Mitarbeitende oder Dienstkonten notwendige Aufgaben ausführen, und unterbrechen dadurch den legitimen Betrieb.'),
  ('R6-ACCESS-RECERT','R1: Durch frühere Rollen oder Projekte angesammelte Berechtigungen bleiben aktiv und ermöglichen unbefugten Zugriff auf Informationen oder deren Änderung. R2: Eine Überprüfung wird als abgeschlossen gekennzeichnet, obwohl die darin abgelehnten Berechtigungen weiterhin nutzbar sind.'),
  ('R6-C40.11','R1: Gemeinsam genutzte Zugänge verschleiern, wer eine Aktion ausgeführt hat, und erschweren die Untersuchung von Missbrauch. R2: Ehemalige oder in andere Rollen versetzte Nutzende behalten gemeinsam genutzte Zugangsdaten und greifen weiterhin auf Ressourcen zu, nachdem ihre individuelle Berechtigung erloschen ist.'),
  ('R6-C43.2','R1: Die Kompromittierung eines Kontos für die gewöhnliche Nutzung ermöglicht privilegierte Änderungen oder Zugriff auf geschützte Daten. R2: Administrative Aktionen können keiner Person zuverlässig zugerechnet werden, wodurch Untersuchung und Verantwortungszuordnung beeinträchtigt werden.'),
  ('R6-C43.3','Schadsoftware auf einem Administrationsarbeitsplatz fängt privilegierte Sitzungen oder Zugangsdaten ab und nutzt sie, um verwaltete Systeme zu kompromittieren.'),
  ('R6-C43.1','Veraltete oder übermäßige Administrationsrechte werden missbraucht, um auf sensible Informationen zuzugreifen oder Systeme über die aktuellen Zuständigkeiten der berechtigten Person hinaus zu verändern.'),
  ('R6-C40.5','R1: Fernzugriffsverkehr oder Zugangsdaten werden abgefangen, oder Befehle und Daten werden während der Übertragung verändert, wodurch die Vertraulichkeit oder Integrität der Fernzugriffsoperationen beeinträchtigt wird. R2: Nicht genehmigte oder zu weitreichende Fernverbindungen verschaffen Angreifenden Zugang zu internen Systemen.'),
  ('R6-SUP-ACCESS-WINDOW','R1: Eine Lieferantenverbindung bleibt nach dem genehmigten Unterstützungszeitraum nutzbar und eröffnet Angreifenden einen unnötigen Zugangsweg. R2: Dienstleisterzugriffe erstrecken sich auf Systeme oder Aktivitäten außerhalb des genehmigten Umfangs und ermöglichen unbefugte Offenlegung oder Änderungen.'),
  ('R6-C43.4','R1: Privilegierte Hilfsprogramme umgehen Anwendungsschutzmaßnahmen und legen geschützte Daten offen oder verändern sie. R2: Der Missbrauch privilegierter Hilfsprogramme lässt sich nicht rekonstruieren, wodurch Zuordnung und Eindämmung verzögert werden.'),
  ('R6-C41.1','Schwache Authentifizierung ermöglicht Angreifenden den Zugriff auf sensible Systeme mit gestohlenen Zugangsdaten.'),
  ('R6-C41.11','Angreifende erlangen Kontozugriff über schwache Registrierungs-, Erstausgabe- oder Wiederherstellungsprüfungen und umgehen damit einen ansonsten starken Anmeldeschutz.'),
  ('R6-C41.6','Offengelegte geheime Authentisierungsinformationen, einschließlich bei der Eingabe beobachteter Passwörter, ermöglichen unbefugten Zugriff.'),
  ('R6-C41.8','R1: Wiederholtes Raten oder automatisierte Anmeldeversuche ermitteln nutzbare Zugangsdaten und führen zur Kontoübernahme. R2: Angreifende lösen absichtlich kontoweite Sperrungen oder wiederholtes Zurücksetzen aus und verhindern dadurch den Zugriff berechtigter Nutzender auf Dienste oder überlasten den Wiederherstellungsprozess.'),
  ('R6-DEVICE-LOCK','Eine unbefugte Person nutzt ein unbeaufsichtigtes, ungesperrtes Gerät, um Informationen einzusehen oder im Konto der berechtigten Person Aktionen auszuführen.'),
  ('R6-C41.9','Eine andere Person verwendet eine inaktive authentifizierte Sitzung weiter, um Informationen zu lesen oder als berechtigte nutzende Person Aktionen auszuführen.'),
  ('R6-C41.7','Angreifende authentifizieren sich weiterhin mit einem offengelegten Passwort, Token oder anderen Zugangsdaten, nachdem die Einrichtung von der Kompromittierung erfahren hat.'),
  ('R6-C41.10','Schwächen der Authentifizierung werden bei veränderten Bedrohungen oder Zugriffsbedarfen ausnutzbar, während die Einrichtung weiterhin auf veraltete Verfahren vertraut.'),
  ('R6-C41.12','Eine nicht authentifizierte Person liest geschützte Informationen, indem sie den normalen Anmeldebildschirm umgeht.'),
  ('R6-C41.13','Eine Person, die initiale, temporäre oder vom Lieferanten voreingestellte geheime Informationen kennt, greift nach der Inbetriebnahme auf das Konto oder System zu.'),
  ('R6-C41.14','R1: Offengelegte oder wiederverwendete dienstliche Passwörter ermöglichen die Kompromittierung von Konten. R2: Schwacher Schutz oder eine schwache Wiederherstellung eines Passworttresors legt Zugangsdaten für mehrere dienstliche Konten zugleich offen. R3: Der Verlust des Zugriffs auf den Passworttresor ohne nutzbaren autorisierten Wiederherstellungsweg verhindert, dass Mitarbeitende die für kritische Arbeiten oder die Wiederherstellung benötigten Zugangsdaten abrufen.'),
  ('R6-AUTH-INTERVAL','Unbemerkt offengelegte Zugangsdaten bleiben über ihr festgelegtes Änderungsintervall hinaus nutzbar und ermöglichen dadurch fortgesetzten unbefugten Zugriff.'),
  ('R6-TRN-AUTH','Eine mitarbeitende Person gibt Zugangsdaten preis oder genehmigt die Anmeldung eines Angreifers und setzt dadurch einen ansonsten wirksamen technischen Schutz außer Kraft.'),
  ('R6-TRN-REMOTE','Mitarbeitende umgehen die geschützte Verbindung, vertrauen einer gefälschten Verbindung oder machen interne Ressourcen über einen nicht autorisierten Zugangsweg zugänglich.'),
  ('R6-C38.5','Mit der Reaktion betraute Personen oder Administrierende handeln anhand eines fehlerhaften Netzwerkplans und übersehen dadurch einen Angriffsweg oder beeinträchtigen bei einer Eindämmung oder Änderung eine Abhängigkeit.'),
  ('R6-C38.3','R1: Schleichende Konfigurationsabweichungen machen unnötige Dienste oder zu weitreichende Berechtigungen zugänglich, die Angreifer für den Systemzugriff nutzen. R2: Unkontrollierte Konfigurationsabweichungen verursachen Fehlfunktionen von Diensten oder einen inkompatiblen Betrieb.'),
  ('R6-C38.4','R1: Ein Angreifer gelangt aus einer Zone mit geringerem Vertrauen oder einer Zone Dritter in sensible Systeme und legt Informationen offen oder verändert sie. R2: Eine Infektion oder ein störendes Ereignis breitet sich über unzureichend getrennte Zonen aus und beeinträchtigt ansonsten nicht zusammenhängende Dienste.'),
  ('R6-C38.12','Die Kompromittierung eines von außen erreichbaren Dienstes eröffnet einen direkten Weg in interne Systeme und weitet den Sicherheitsvorfall über den exponierten Dienst hinaus aus.'),
  ('R6-C38.10','Ein Angreifer in einem operativen Netzwerk oder einem Netzwerk mit geringerem Vertrauen erreicht Managementschnittstellen und nimmt unbefugte administrative Änderungen vor.'),
  ('R6-C38.11','R1: Eine Kompromittierung oder unsichere Aktivität in Entwicklung oder Tests erreicht Produktionssysteme oder Wiederherstellungskopien und legt Produktionsinformationen offen. R2: Testaktivitäten beschädigen Produktionsdaten oder Sicherungskopien, unterbrechen produktive Dienste oder beeinträchtigen die Wiederherstellung.'),
  ('R6-C38.6','Ein nicht autorisiertes oder kompromittiertes Gerät verbindet sich mit dem Netzwerk und greift auf interne Ressourcen zu oder schleust schädlichen Verkehr ein.'),
  ('R6-C38.9','R1: Manipulierte Namensauflösung oder manipuliertes Routing leitet Nutzende und Systeme zu einem vom Angreifer kontrollierten Ziel und legt Zugangsdaten oder ausgetauschte Daten offen. R2: Routing- oder DNS-Ausfälle machen legitime Dienste unerreichbar oder leiten deren Verkehr um.'),
  ('R6-C38.7','Ein ungesteuerter Protokollübergang führt ungefilterte Verkehrswege oder inkompatible Verbindungen ein, macht Systeme angreifbar oder stört netzwerkabhängige Dienste.'),
  ('R6-C28.1','R1: Schädliche oder nicht autorisierte Software entwendet Informationen, erfasst Zugangsdaten oder ermöglicht Fernsteuerung. R2: Schadsoftware beschädigt oder verschlüsselt Daten und unterbricht betroffene Dienste.'),
  ('R6-NET-FILTER','R1: Unnötige eingehende Verbindungen setzen interne Dienste unbefugtem Zugriff aus. R2: Unbeschränkte ausgehende Wege ermöglichen Datenabfluss oder Command-and-Control-Verkehr von Angreifern.'),
  ('R6-WIFI-SEG','Ein Gastgerät oder ein kompromittiertes drahtloses Gerät mit geringer Vertrauensstufe erreicht Ressourcen der Einrichtung und greift auf Daten zu oder breitet einen Angriff aus.'),
  ('R6-WIFI-AUTH','R1: Nicht autorisierte Nutzende oder Geräte erhalten durch schwache Authentisierung internen WLAN-Zugang. R2: Ein Angreifer fängt unzureichend geschützten drahtlosen Verkehr ab oder manipuliert ihn und erlangt dadurch sensible Informationen oder bewirkt, dass Systeme veränderte Daten akzeptieren.'),
  ('R6-SYS-CAP','Der Bedarf übersteigt die Rechen-, Speicher- oder Netzwerkkapazität, beeinträchtigt oder stoppt Dienste und führt möglicherweise dazu, dass wartende Arbeitsaufträge oder Datensätze verworfen werden.'),
  ('R6-C38.13','R1: Durch Änderungen bleiben veraltete Netzwerkregeln oder unwirksame Zonengrenzen bestehen, sodass unbefugte Zugangswege unbemerkt fortbestehen. R2: Nach Netzwerkänderungen werden legitime Dienstabhängigkeiten durch veraltete Filter- oder Segmentierungsregeln blockiert; dies unterbricht den Betrieb bis zur Korrektur der Regeln.'),
  ('R6-C39.1','Uneinheitliche kryptografische Entscheidungen lassen sensible Informationen über Systeme und Austauschvorgänge hinweg ungeschützt oder erwecken fälschlich den Eindruck, diese seien geschützt.'),
  ('R6-CRYPTO-INV','R1: Nicht erfasste Zertifikate laufen ab, ohne dass eine Zuständigkeit für ihre Erneuerung feststeht, und unterbrechen abhängige Dienste. R2: Kompromittierte oder veraltete Schlüssel bleiben in Gebrauch, weil ihre Speicherorte und abhängigen Systeme für einen Austausch oder Widerruf nicht ermittelt werden können.'),
  ('R6-C39.2','R1: Eine unbefugte Partei liest sensible gespeicherte oder übertragene Informationen, wenn die erforderliche Verschlüsselung fehlt oder unwirksam ist. R2: Veränderte Kommunikation oder Daten werden als echt akzeptiert, wenn die erforderlichen Integritäts- und Authentizitätsschutzmaßnahmen nicht funktionieren.'),
  ('R6-C39.3','R1: Offengelegte, schwache oder nicht widerrufene Schlüssel ermöglichen es einem Angreifer, Informationen zu entschlüsseln oder sich als vertrauenswürdige Partei auszugeben. R2: Verlorene oder vorzeitig vernichtete Schlüssel, abgelaufene Zertifikate oder fehlerhafte Widerrufe machen geschützte Daten oder abhängige Dienste unverfügbar.'),
  ('R6-C39.4','Veraltete kryptografische Algorithmen oder Verfahren ermöglichen die Entschlüsselung geschützter Informationen oder die Fälschung vertrauenswürdiger Kommunikation.'),
  ('R6-C41.2','R1: Unbefugte Parteien hören oder lesen reguläre Sprach-, Video- oder Textkommunikation mit, die sensible Informationen enthält. R2: Einer gefälschten oder manipulierten Nachricht wird vertraut, wodurch eine fehlerhafte geschäftliche oder sicherheitsbezogene Handlung ausgelöst wird.'),
  ('R6-C41.5','R1: Ein System verbindet sich mit einem vorgetäuschten Endpunkt und legt Daten oder Zugangsdaten offen. R2: Nachrichten zwischen Systemen werden verändert oder erneut eingespielt und verursachen unbefugte Transaktionen oder fehlerhafte Verarbeitung.'),
  ('R6-C41.3','R1: Der Ausfall von Notfallkommunikationskanälen verzögert die Koordination und schützende Entscheidungen während eines Sicherheitsvorfalls. R2: Mit der Reaktion betraute Personen weichen auf nicht vertrauenswürdige Kanäle aus und legen sensible Vorfallsinformationen offen oder handeln aufgrund von Anweisungen mit vorgetäuschter Identität.'),
  ('R6-C38.8','R1: Eine uneinheitliche Einführung von E-Mail-Sicherheit führt dazu, dass gefälschten Nachrichten vertraut wird oder sensible E-Mails ohne den vorgesehenen Schutz übertragen werden. R2: Eine inkompatible Einführung von E-Mail-Sicherheit weist legitime Nachrichten zurück oder verzögert sie.'),
  ('R6-D04-01','Ein beschafftes System kann die für seinen vorgesehenen Daten- und Dienstkontext erforderlichen Schutzmaßnahmen nicht bereitstellen, legt Informationen offen oder erzwingt kostspielige Änderungen vor einer sicheren Nutzung.'),
  ('R6-D04-02','Ein Entwurf mit unsicheren Vertrauensgrenzen oder inkompatiblen Integrationen wird abgenommen und verankert dadurch eine Schwäche bei Zugriffssicherheit oder Resilienz, deren Behebung nach der Lieferung kostspielig ist.'),
  ('R6-D04-10','Eine verwundbare Komponente oder Abhängigkeit kann dem beschafften Produkt nicht zugeordnet werden, wodurch sich die Identifizierung und Behandlung betroffener Systeme verzögert.'),
  ('R6-D04-11','Für den Betrieb zuständige Personen setzen ein Produkt mit unsicheren Einstellungen ein oder betreiben es so, weil dessen Sicherheitsfunktionen und Konfigurationsanforderungen nicht verstanden werden.'),
  ('R6-D04-12','Die Sicherheitsunterstützung endet unbemerkt und lässt eingesetzte Produkte gegenüber Schwachstellen ungeschützt, für die keine Updates mehr verfügbar sind.'),
  ('R6-D04-03','Ein geliefertes System geht mit unwirksamen erforderlichen Schutzmaßnahmen in den Produktivbetrieb, weil die Abnahme auf Zusagen statt auf Funktionsnachweisen beruht, und gefährdet dadurch produktive Daten oder Dienste.'),
  ('R6-D04-13','R1: Nicht mehr unterstützte Systeme bleiben ohne wirksamen vorläufigen Schutz oder einen realisierbaren Migrationsweg in Betrieb und verlängern dadurch die Gefährdung durch ausnutzbare Schwachstellen. R2: Ein überstürzter Austausch nicht mehr unterstützter Technologie stört abhängige Dienste.'),
  ('R6-D04-04','Entwicklungsteams lassen Sicherheitsaktivitäten aus oder wenden uneinheitliche Verfahren an, sodass wiederkehrende Entwurfs- oder Umsetzungsschwächen in Releases gelangen.'),
  ('R6-D04-23','Ein externer Entwicklungsdienstleister lässt erforderliche Schutzmaßnahmen aus oder lässt Verantwortlichkeiten ungeklärt und liefert dadurch Software mit unbehandelten Schwächen oder legt anvertraute Informationen offen.'),
  ('R6-D04-14','Eine unsichere Systemarchitektur macht sensible Komponenten angreifbar oder erlaubt einem Angreifer, Vertrauensgrenzen zu überschreiten und weitere Funktionen zu kompromittieren.'),
  ('R6-D04-16','Unbefugte Änderungen an Quellcode oder Release-Branches gelangen in ein vertrauenswürdiges Release, führen schädliches Verhalten ein oder deaktivieren Schutzmaßnahmen.'),
  ('R6-D04-18','Offengelegte geheime Informationen für Entwicklung, Bereitstellung oder Signierung ermöglichen einem Angreifer, sich als vertrauenswürdige Automatisierung auszugeben, auf Systeme zuzugreifen oder scheinbar authentische schädliche Releases zu verbreiten.'),
  ('R6-D04-15','R1: Ein Angreifer nutzt Programmierfehler aus, um Daten unbefugt zu lesen oder zu verändern. R2: Softwarefehler verursachen auch ohne Angriff eine fehlerhafte Verarbeitung oder einen Dienstausfall.'),
  ('R6-D04-17','Ein Angreifer verändert Build-Eingaben, Pipeline-Konfigurationen oder Bereitstellungsaktionen, um ein kompromittiertes Release zu verbreiten oder die Produktionsumgebung unbefugt zu verändern.'),
  ('R6-D04-20','R1: Nicht benötigte sensible Echtdaten werden in Testumgebungen kopiert, wodurch bei unsachgemäßem Zugriff auf die Testumgebung oder deren unsachgemäßer Freigabe mehr Personen und Datensätze gefährdet sind. R2: Nicht repräsentative Testdaten lassen relevante Formate, Beziehungen oder Randbedingungen aus, sodass Fehler, die den tatsächlichen Betrieb beeinträchtigen, die Tests unentdeckt passieren.'),
  ('R6-D04-22','Als bereinigt oder anonymisiert bezeichnete Daten enthalten weiterhin identifizierbare oder wiederherstellbare sensible Werte, was zu einer Offenlegung führt, wenn sie als sichere Testdaten behandelt werden.'),
  ('R6-D04-21','Nicht autorisierte Testbeteiligte oder spätere Empfänger erhalten sensible Testdaten während der Speicherung oder Übertragung oder nachdem der Testbedarf entfallen ist.'),
  ('R6-D04-19','Sicherheitsmängel bleiben bis nach der Freigabe unentdeckt, weil Tests relevante Angriffswege nicht abdecken oder sich die Feststellungen auf eine andere Version beziehen.'),
  ('R6-D04-06','Eine Änderung schwächt unerwartet eine Sicherheitsgrenze oder beeinträchtigt einen abhängigen Dienst, weil ihre Auswirkungen nicht bewertet wurden.'),
  ('R6-CHG-ROLLBACK','Eine fehlgeschlagene Änderung kann weder rückgängig gemacht noch auf andere Weise sicher behoben werden, wodurch die Dienstunterbrechung verlängert wird oder beschädigte Daten und Konfigurationen weiterverwendet werden.'),
  ('R6-D04-07','Eine fehlerhafte oder inkompatible betriebliche Änderung gelangt in die Produktion und unterbricht Dienste oder setzt eine erforderliche Schutzmaßnahme außer Kraft.'),
  ('R6-CHG-AUTH','Eine nicht autorisierte Änderung umgeht nachvollziehbar verantwortete Risikoentscheidungen und führt zu einem unsicheren oder störenden Zustand der Produktionsumgebung.'),
  ('R6-D04-05','Untersuchende oder Betriebsverantwortliche können einen geänderten Systemzustand nicht rekonstruieren, wodurch Fehlerdiagnose, Ermittlung des Vorfallsumfangs oder Wiederherstellung verzögert werden.'),
  ('R6-D04-24','Eine Notfalländerung hinterlässt einen undokumentierten unsicheren Zustand, den spätere Betriebsverantwortliche nicht zuverlässig bewerten oder rückgängig machen können.'),
  ('R6-D04-08','R1: Handlungsrelevante Meldungen oder Sicherheitshinweise gelangen nicht zur Bewertung, sodass eine bekannte Schwachstelle vor ihrer Behandlung ausgenutzt werden kann. R2: Eine schlecht koordinierte Offenlegung gefährdet betroffene Nutzende, bevor Schutzmaßnahmen bereitstehen, oder verzögert Informationen, die sie zu ihrem Schutz benötigen.'),
  ('R6-D04-25','R1: Unentdeckte Schwachstellen bleiben auf Systemen ausnutzbar, die von Scans und Prüfungen ausgeschlossen oder unzureichend erfasst wurden. R2: Eine unsichere Tätigkeit zur Schwachstellenidentifikation stört ein sensibles betriebliches, klinisches oder OT-System.'),
  ('R6-D04-26','R1: Ein betroffenes System wird fälschlich als nicht betroffen eingestuft, sodass eine ausnutzbare Schwachstelle unbehandelt bleibt. R2: Ein nicht betroffenes System wird unnötigen, störenden Behebungsmaßnahmen unterzogen, weil Angaben zu Produkt, Version oder Exposition falsch interpretiert werden.'),
  ('R6-D04-27','Ressourcen werden auf weniger folgenreiche Schwachstellen gelenkt, während exponierte, betrieblich wichtige Schwachstellen für Angreifende weiterhin ausnutzbar bleiben.'),
  ('R6-D04-28','Angreifende nutzen eine bekannte Schwachstelle aus, während die erforderliche Behebung verzögert, aufgegeben oder lediglich als abgeschlossen dokumentiert wird, ohne tatsächlich umgesetzt worden zu sein.'),
  ('R6-D04-31','Angreifende erreichen eine nicht gepatchte verwundbare Funktion und nutzen sie aus, weil die angenommenen kompensierenden Schutzmaßnahmen den Angriffspfad tatsächlich nicht beschränken.'),
  ('R6-D04-30','Eine Schwachstelle bleibt aufgrund einer unzureichend informierten oder nicht autorisierten Ausnahme exponiert, und ihre Behandlung wird länger aufgeschoben, als es die rechenschaftspflichtigen Verantwortlichen beabsichtigt hatten.'),
  ('R6-D04-32','Eine Ausnahme bleibt bestehen, obwohl ihre Begründung durch veränderte Exposition, Patch-Verfügbarkeit oder Schutzmaßnahmen entfallen ist, sodass ein zunehmend ausnutzbares System unbehandelt bleibt.'),
  ('R6-D04-35','Ein gefälschtes Update aus einer nicht vertrauenswürdigen Quelle installiert Schadcode mit den Berechtigungen des Aktualisierungsprozesses.'),
  ('R6-D04-36','Ein verändertes oder beschädigtes Update-Paket wird als legitim installiert und führt schädliche Änderungen ein oder beeinträchtigt das Zielsystem.'),
  ('R6-D04-34','Ein inkompatibler oder fehlerhafter Sicherheitspatch unterbricht die Produktion oder beeinträchtigt eine erforderliche Sicherheitsfunktion.'),
  ('R6-MON-RISK','Die Überwachungsanforderungen übersehen ein relevantes System oder einen Angriffspfad, sodass eine Kompromittierung in einem nicht überwachten Bereich fortbestehen kann.'),
  ('R6-MON-BASE','R1: Erkennungskriterien stufen schädliche Abweichungen als normal ein und verzögern dadurch Untersuchungen. R2: Übermäßige oder irreführende Alarme binden die Aufmerksamkeit der Analysierenden und verdecken bedeutsame Ereignisse.'),
  ('R6-D02-01','Ein Angriff bleibt unentdeckt, weil die erforderliche Überwachungsabdeckung nicht in Betrieb ist oder keine nutzbaren Informationen liefert.'),
  ('R6-C44.6','R1: Inkonsistente oder manipulierte Zeitstempel ergeben einen falschen Vorfallsablauf und schwächen dadurch Korrelation, Zuordnung und Zuverlässigkeit der Nachweise. R2: Uhrabweichungen führen dazu, dass zeitabhängige Authentisierungs- oder Zertifikatsprüfungen gültige Zugriffe zurückweisen und damit Dienste unterbrechen, die von diesen Prüfungen abhängen.'),
  ('R6-LOG-RET-DEF','R1: Ein festgelegter Aufbewahrungszeitraum ist für den Untersuchungsbedarf zu kurz, sodass relevante Nachweise verschwinden, bevor ein Sicherheitsvorfall entdeckt wird. R2: Übermäßige Aufbewahrung setzt unnötige personenbezogene oder sensible Aufzeichnungen einer Gefährdung aus und schafft ungerechtfertigte Risiken bei der Datenverarbeitung.'),
  ('R6-C44.1','Fehlende oder unbrauchbare Ereignisaufzeichnungen verdecken relevante Aktivitäten und verhindern die Rekonstruktion eines Sicherheitsvorfalls auf den betroffenen Quellsystemen.'),
  ('R6-C44.2','R1: Angreifende verändern oder löschen Protokolle, um Aktivitäten zu verbergen und Untersuchende irrezuführen. R2: Unbefugter Zugriff auf Protokolle legt personenbezogene Daten, interne Infrastrukturdetails oder andere sensible betriebliche Informationen offen.'),
  ('R6-C44.3','R1: Rotation, Löschung oder Speicherfehler entfernen erforderliche Protokolle vor Ablauf des genehmigten Aufbewahrungszeitraums und verhindern dadurch Untersuchungen oder die Wiedergewinnung von Nachweisen. R2: Protokolle bleiben über ihren begründeten Aufbewahrungszeitraum hinaus zugänglich und setzen personenbezogene oder sensible Informationen unnötig einer Gefährdung aus.'),
  ('R6-C44.4','Untersuchende können relevante Aufzeichnungen nicht systemübergreifend abrufen oder miteinander verknüpfen, wodurch sich die Ermittlung des Vorfallsumfangs verzögert und betroffene Vermögenswerte oder Aktivitäten unerkannt bleiben.'),
  ('R6-LOG-PRIV','Der Missbrauch administrativer Berechtigungen bleibt unbemerkt und kann nicht zuverlässig zugeordnet werden, sodass unbefugte Änderungen oder Datenzugriffe fortgesetzt werden können.'),
  ('R6-C44.5','Bedeutsame Alarme oder ungewöhnliche Muster werden nicht zeitnah untersucht, sodass unbefugte Aktivitäten oder Schäden an Diensten fortbestehen können.'),
  ('R6-C44.7','Der Ausfall einer Überwachungs- oder Protokollierungskomponente erzeugt eine Sichtbarkeitslücke und führt zum Verlust von Ereignisaufzeichnungen, während die überwachten Dienste weiter genutzt werden.'),
  ('R6-C44.8','Der Ausfall des Überwachungs- oder Protokollierungsdienstes bleibt unbemerkt und führt zu einem längeren Zeitraum ohne Erkennung oder verlässliche Ereignisnachweise.'),
  ('R6-D02-02','Unbemerkte Erkennungslücken oder irreführende Regeln bleiben bestehen, weil Prüfungen anhand bekannter Ereignisse sie nicht aufdecken und die Korrekturen nicht verifizieren. Dadurch entsteht ein falsches Vertrauen in die Überwachung.'),
  ('R6-D02-12','Reaktionsverantwortliche treffen unter Druck widersprüchliche oder verspätete Entscheidungen, wodurch sich der Sicherheitsvorfall verschärft oder unnötige Betriebsunterbrechungen entstehen.'),
  ('R6-IR-TIME','Dringende Arbeiten an einem Sicherheitsvorfall warten zu lange auf Bewertung, Eskalation oder Eindämmung, wodurch vermeidbare Exposition oder Störungen zunehmen.'),
  ('R6-D02-05','Informationen über Sicherheitsvorfälle erreichen die Personen nicht, die handeln müssen, wodurch die Reaktion verzögert oder fehlgeleitet wird.'),
  ('R6-D02-13','Beobachtete verdächtige Aktivitäten erreichen das Reaktionsteam nicht, wodurch die Erkennung und Eindämmung eines tatsächlichen Sicherheitsvorfalls verzögert werden.'),
  ('R6-D02-14','R1: Mitarbeitende melden oder eskalieren einen tatsächlichen Sicherheitsvorfall nicht rechtzeitig. R2: Unvorbereitete Reaktionsverantwortliche ergreifen unsichere Maßnahmen, die Störungen verschärfen oder Nachweise vernichten.'),
  ('R6-D02-03','R1: Tatsächliche Sicherheitsvorfälle werden verworfen oder bleiben unerkannt, wodurch sich die Reaktion verzögert. R2: Unbedenkliche Aktivitäten werden fälschlich als Sicherheitsvorfall bestätigt und lösen unnötige Isolation oder Kontosperrungen aus, die den legitimen Betrieb stören.'),
  ('R6-D02-04','Ein Sicherheitsvorfall mit erheblichen Auswirkungen wird als nachrangig behandelt, wodurch sich seine Eindämmung verzögert, während Reaktionsressourcen für weniger dringende Ereignisse eingesetzt werden.'),
  ('R6-D02-15','Veraltete Bewertungen führen zu unangemessenen Reaktionen oder versäumten Meldepflichten.'),
  ('R6-D02-16','Maßnahmen lassen sich nicht rekonstruieren, und Reaktionsverantwortliche wiederholen frühere Entscheidungen oder widersprechen ihnen.'),
  ('R6-D02-17','R1: Nachweise werden verändert, gehen verloren oder lassen sich nicht auf ihre Quelle zurückführen, wodurch Untersuchungen und eine belastbare Nachweisführung beeinträchtigt werden. R2: Die unbefugte Offenlegung von Vorfallsnachweisen legt personenbezogene Informationen, Zugangsdaten oder sensible Einzelheiten der betroffenen Umgebung offen.'),
  ('R6-D02-07','R1: Ein Sicherheitsvorfall breitet sich auf weitere Systeme aus oder gefährdet weiterhin Informationen, bevor er eingedämmt wird. R2: Ungeeignete Eindämmungsmaßnahmen unterbrechen notwendige Dienste oder vernichten flüchtige Nachweise.'),
  ('R6-D02-08','Angreifende behalten ihren Zugang oder der Sicherheitsvorfall tritt trotz scheinbarer Eindämmung erneut auf.'),
  ('R6-D02-09','Dienste werden trotz einer nicht behobenen Kompromittierung wiederhergestellt und sind unmittelbar erneut betroffen.'),
  ('R6-D02-10','Unerkannte Grundursachen oder Schwächen der Reaktion treten bei späteren Sicherheitsvorfällen erneut auf und verursachen vermeidbare wiederholte Störungen oder Kompromittierungen.'),
  ('R6-D02-11','Erkannte Schwachstellen bleiben ungelöst, und dieselben Fehler treten erneut auf.'),
  ('R6-D02-18','Ungetestete Reaktionsverfahren versagen bei einem tatsächlichen Sicherheitsvorfall, und Übergaben funktionieren nicht.'),
  ('R6-D02-19','Die mit der Reaktion betrauten Personen befolgen veraltete Anweisungen oder kontaktieren die falschen Personen, wodurch die Behandlung des Sicherheitsvorfalls verzögert oder fehlgeleitet wird.'),
  ('R6-C54.1','Ein erheblicher Sicherheitsvorfall wird fälschlich als nicht meldepflichtig eingestuft. Dadurch werden die Kenntnisnahme und Koordination durch die Behörde verzögert, und die anwendbare Meldepflicht bleibt unerfüllt.'),
  ('R6-C54.2','Interne Unklarheiten oder Engpässe bei Freigaben verhindern eine fristgerechte gesetzliche Meldung.'),
  ('R6-C67.1','Ein erheblicher Sicherheitsvorfall kann bei Bedarf nicht über den offiziellen Meldeweg gemeldet werden. Dies verzögert die behördliche Koordination und setzt die Einrichtung dem Risiko eines Verstoßes gegen Meldepflichten aus.'),
  ('R6-C57.1','Wiederkehrende Sicherheitsvorfälle werden nur einzeln bewertet, sodass ihre gemeinsamen Auswirkungen nicht gemeldet werden, obwohl der anwendbare Meldeschwellenwert erreicht ist.'),
  ('R6-C58.1','Eine unterlassene, verspätete oder in wesentlichen Punkten unvollständige Frühwarnung verhindert eine rechtzeitige behördliche Bewertung und Koordination.'),
  ('R6-C60.1','Die auf die Frühwarnung folgende Meldung wird unterlassen oder verspätet übermittelt, oder es wird die falsche Frist angewendet. Dadurch wird eine rechtzeitige Koordination verhindert.'),
  ('R6-C60.4','Unvollständige oder unzuverlässige Meldeinhalte vermitteln der Behörde ein falsches Bild von Schweregrad, Ausbreitung oder technischem Kontext des Sicherheitsvorfalls und verzögern koordinierte Folgemaßnahmen oder lenken sie in die falsche Richtung.'),
  ('R6-C61.1','Eine angeforderte Statusaktualisierung wird nicht bereitgestellt, sodass die Behörde Folgemaßnahmen auf der Grundlage veralteter Informationen über den Sicherheitsvorfall koordinieren muss.'),
  ('R6-C62.1','Eine verspätete oder unterlassene Abschlussberichterstattung verhindert die rechtzeitige behördliche Prüfung des Ergebnisses der Vorfallsbehandlung und lässt den vorgeschriebenen Meldezyklus unvollständig.'),
  ('R6-C62.2','Eine unvollständige oder unbelegte abschließende Darstellung vermittelt der Behörde ein falsches Bild von Ursachen, Auswirkungen oder Abhilfemaßnahmen und beeinträchtigt Folgemaßnahmen sowie das gemeinsame Lernen.'),
  ('R6-C63.1','Ein andauernder Sicherheitsvorfall wird als abgeschlossen dargestellt oder es erfolgt keine Fortschrittsmeldung. Dadurch erhält die Behörde ein unzutreffendes Bild, und angemessene Folgemaßnahmen werden verhindert.'),
  ('R6-C64.1','Den Empfängern der Dienste fehlen rechtzeitige Informationen oder praktische Handlungshinweise, wodurch sie vermeidbare Störungen oder Schäden erleiden.'),
  ('R6-C64.4','R1: Erforderliche Informationen für die Öffentlichkeit werden zurückgehalten, sodass Menschen nicht angemessen auf den Sicherheitsvorfall reagieren können. R2: Eine öffentliche Vorfallsmitteilung legt unnötig personenbezogene Daten oder sensible Einzelheiten der Reaktion offen. Dies führt zu weiteren Offenlegungen oder hilft Angreifenden, ihr Vorgehen anzupassen.'),
  ('R6-C21.1','Die zuständige Behörde handelt auf der Grundlage eines unzutreffenden Bildes der Teilnahme der Einrichtung an einer Vereinbarung über den Informationsaustausch. Dies beeinträchtigt die erforderliche Aufsicht und Folgemaßnahmen.'),
  ('R6-C21.2','Durch den freiwilligen Austausch werden sensible Informationen offengelegt oder über den Kreis der berechtigten Teilnehmenden hinaus verbreitet.'),
  ('R6-BC-BIA','Kritische Abhängigkeiten und die Folgen länger andauernder Unterbrechungen werden falsch eingeschätzt, sodass Wiederherstellungsprioritäten und Vorkehrungen zur Betriebsfortführung die wichtigsten Dienste nicht schützen.'),
  ('R6-BC-RTO','Wiederherstellungsteams arbeiten auf willkürliche oder widersprüchliche Fristen hin, sodass Dienste länger ausfallen, als es die betrieblichen Toleranzen zulassen.'),
  ('R6-C32.1','Prioritäre Dienste fallen während einer Unterbrechung aus oder werden unterhalb eines akzeptablen Niveaus betrieben, weil die geplanten Vorkehrungen zur Betriebsfortführung nicht umsetzbar sind.'),
  ('R6-C32.3','Wiederherstellungsteams verfügen über keine ausführbaren Anweisungen oder stellen voneinander abhängige Komponenten in der falschen Reihenfolge wieder her. Dies verhindert die rechtzeitige und zuverlässige Wiederherstellung der Dienste.'),
  ('R6-C32.4','Bei einer Unterbrechung, die die Kapazität der routinemäßigen Vorfallsbehandlung übersteigt, trifft die Leitung widersprüchliche oder verspätete Entscheidungen. Dadurch verlängert sich die Dienstunterbrechung, und interessierte Parteien werden verunsichert.'),
  ('R6-C32.6','Dokumentierte Ersatzverfahren oder Wiederherstellungsschritte können nicht ausgeführt werden, weil Ersatzressourcen nicht verfügbar, nicht zugänglich oder zu knapp bemessen sind.'),
  ('R6-BC-RPO','Die Wiederherstellungsvorkehrungen stellen zu alte Daten wieder her und verursachen dadurch einen untragbaren Verlust von Transaktionen oder Datensätzen, selbst wenn der Dienst schnell wiederhergestellt wird.'),
  ('R6-C32.2','Das Datensicherungsverfahren lässt erforderliche Informationen unbemerkt aus oder erstellt keine aktuellen Wiederherstellungskopien. Dadurch verfügen Dienste über keine brauchbare Wiederherstellungsquelle.'),
  ('R6-C33.2','R1: Eine Kompromittierung oder ein gemeinsamer Ausfall zerstört oder beschädigt sowohl die Produktivdaten als auch die zu ihrer Wiederherstellung benötigten Kopien. R2: Ein Angreifer erlangt sensible Informationen aus Wiederherstellungskopien, die innerhalb derselben kompromittierten Vertrauensgrenze wie die Produktivsysteme liegen.'),
  ('R6-C32.7','R1: Ersatzverfahren für den Notbetrieb legen während des gestörten Betriebs Informationen offen oder ermöglichen unbefugten Zugriff. R2: Vorübergehende Notfallberechtigungen oder unsichere Konfigurationen bleiben nach der Wiederherstellung bestehen und werden später missbraucht.'),
  ('R6-TRN-BCDR','Mitarbeitende wissen nicht, wie prioritäre Dienste aufrechterhalten oder zugewiesene Wiederherstellungsaufgaben ausgeführt werden. Dadurch versagen ansonsten angemessene Pläne während einer Unterbrechung.'),
  ('R6-C32.5','Beschädigte oder unvollständige Sicherungsinhalte werden als nutzbar angesehen, können aber die zur Wiederherstellung benötigten Daten, Konfigurationen oder Metadaten nicht bereitstellen.'),
  ('R6-C33.1','Eine Wiederherstellung kann keine vollständigen, nutzbaren Daten zum erforderlichen Wiederherstellungspunkt rekonstruieren. Dadurch entstehen Datenverluste über das vereinbarte RPO hinaus.'),
  ('R6-C33.4','Bereitschaftsressourcen sind vorhanden, übernehmen jedoch nicht oder können den Dienst nicht tragen, wenn die primären Ressourcen nicht verfügbar sind.'),
  ('R6-C33.3','Die durchgängige Wiederherstellung überschreitet das RTO des Dienstes, weil Abhängigkeiten, Übergaben oder das Zusammenspiel der Wiederherstellungsschritte trotz Tests einzelner Komponenten nicht funktionieren.'),
  ('R6-C32.8','Die Leitung kann während einer schwerwiegenden Unterbrechung dringende Entscheidungen nicht koordinieren oder nicht wirksam kommunizieren, obwohl ein schriftlicher Krisenplan vorliegt.'),
  ('R6-REC-METRIC','Wiederkehrende Wiederherstellungsverzögerungen oder dienstspezifische RTO-Überschreitungen bleiben durch unvollständige Messungen oder irreführende Durchschnittswerte verborgen, sodass Verbesserungsmaßnahmen die tatsächlichen Engpässe verfehlen.'),
  ('R6-C51.5','Zwischen Beschaffung, Dienstverantwortlichen und Sicherheitsteams entstehen Zuständigkeitslücken bei der Lieferantensicherheit, sodass während der gesamten Beziehung erhebliche Risiken fortbestehen.'),
  ('R6-C51.1','Ein nicht erfasster Lieferant oder eine nicht erfasste Dienstabhängigkeit wird bei der Vorfallskoordination und Sicherheitsüberwachung übersehen. Dadurch verzögern sich Maßnahmen, wenn dieser Lieferant ausfällt oder kompromittiert wird.'),
  ('R6-SUP-RESP','R1: Jede Partei geht davon aus, dass die andere eine notwendige Sicherheitsaufgabe erfüllt. Dadurch bleiben Systeme ungepatcht, unüberwacht oder ohne nutzbare Sicherungskopien. R2: Unklare Übergaben verzögern die Eindämmung oder Wiederherstellung, während Einrichtung und Lieferant darüber streiten, wer handeln muss.'),
  ('R6-C51.2','Der Ausfall oder die Kompromittierung eines Lieferanten beeinträchtigt einen prioritären Dienst stärker als erwartet, weil seine betrieblichen Abhängigkeiten und Wiederherstellungsabhängigkeiten unterschätzt wurden.'),
  ('R6-C51.3','R1: Unbekannte oder übermäßige Lieferantenzugriffe werden genutzt, um Informationen der Einrichtung zu erlangen. R2: Ein kompromittiertes Lieferantenkonto oder eine kompromittierte Verbindung ermöglicht unbefugte Änderungen an internen Systemen.'),
  ('R6-C51.4','R1: Der Ausfall eines Lieferanten oder einer gemeinsam genutzten Plattform unterbricht mehrere abhängige Dienste gleichzeitig. R2: Anbieterbindung oder der Verlust internen Wissens verhindert einen rechtzeitigen Lieferantenwechsel und verlängert die Unterbrechung.'),
  ('R6-C49.4','Ein Lieferant wird ausgewählt, der begründete Cybersicherheits- oder Resilienzanforderungen nicht erfüllen kann. Dadurch ist die Einrichtung vermeidbaren Risiken ausgesetzt oder muss einen kostspieligen Lieferantenwechsel unter eingeschränkten Bedingungen vornehmen.'),
  ('R6-C50.1','Eine Lieferantenentscheidung beruht auf veralteten Annahmen und lässt ein erhebliches Lieferkettenrisiko unbehandelt, obwohl eine relevante koordinierte EU-Bewertung dieses aufgezeigt hat.'),
  ('R6-C49.2','R1: Ein Lieferantenprodukt oder eine Betriebspraxis setzt anvertraute Informationen unbefugtem Zugriff aus. R2: Ein ungeeigneter Lieferantendienst bietet nicht die von der Einrichtung benötigte Verfügbarkeit oder Wiederherstellbarkeit. R3: Schwache Entwicklungspraktiken des Lieferanten bringen ausnutzbare Fehler oder kompromittierte Komponenten in beschaffte oder gewartete Systeme ein.'),
  ('R6-SUP-LOC','R1: Eine regionale Strom-, Kommunikations- oder sonstige Störung beeinträchtigt sowohl den primären Dienst als auch seine Wiederherstellungsvorkehrungen, weil die gemeinsame Standortabhängigkeit nicht erkannt wurde. R2: Ein Lieferant verlagert die Diensterbringung oder Informationsverarbeitung ohne vorherige Bewertung. Dadurch werden Sicherheitsannahmen ungültig oder vereinbarte Wiederherstellungsvorkehrungen unwirksam.'),
  ('R6-C49.1','Eine festgestellte lieferantenspezifische Sicherheitsschwäche bleibt bei Akzeptanz- oder Korrekturentscheidungen unbehandelt und ermöglicht unbefugten Zugriff, Änderungen an den Systemen der Einrichtung oder eine Störung ihrer Dienstleistungen.'),
  ('R6-C52.1','R1: Ein Lieferant bestreitet oder unterlässt notwendige Sicherheitsarbeiten, weil verbindliche Verantwortlichkeiten und Leistungserwartungen unklar sind, sodass die Einrichtung Schutz oder Korrekturen nicht rechtzeitig erwirken kann. R2: Ein Lieferant verzögert relevante Vorfallinformationen oder hält sie zurück, wodurch sich die Reaktion der Einrichtung verzögert oder sie eine anwendbare gesetzliche Meldefrist versäumt. R3: Eine die Einrichtung betreffende Schwachstelle bleibt ausnutzbar, während Lieferant und Kunde über Zuständigkeiten, Benachrichtigungen oder Erwartungen an die Behebung streiten.'),
  ('R6-C52.3','Die Einrichtung kann keine für den Geltungsbereich relevanten Nachweise zur Sicherheitsbeurteilung erhalten, sodass wesentliche Schwächen des Lieferanten unentdeckt oder ungelöst bleiben.'),
  ('R6-C52.7','R1: Ein Unterauftragnehmer erhält oder verarbeitet Informationen der Einrichtung ohne die Schutzmaßnahmen, die vom direkten Lieferanten erwartet werden. R2: Eine nicht offengelegte oder unzureichend kontrollierte Abhängigkeit von einem Unterauftragnehmer unterbricht die vertraglich vereinbarte Dienstleistung. R3: Ein Unterauftragnehmer bringt schädliche oder kompromittierte Komponenten in das gelieferte Produkt oder die Dienstleistung ein und ermöglicht dadurch eine Kompromittierung der Systeme der Einrichtung.'),
  ('R6-C52.5','R1: Einer Person, bei der relevante und rechtmäßig feststellbare Bedenken hinsichtlich ihrer Vertrauenswürdigkeit bestehen, werden sensible Aufgaben beim Lieferanten übertragen, und sie missbraucht den dadurch gewährten Zugang. R2: Durch unverhältnismäßige Hintergrundüberprüfungen werden unnötige personenbezogene Informationen über das Lieferantenpersonal erhoben oder offengelegt.'),
  ('R6-C52.4','Das Lieferantenpersonal macht sicherheitsrelevante Fehler im Betrieb oder reagiert nicht angemessen, weil ihm die für seine zugewiesenen Aufgaben erforderlichen Kompetenzen fehlen.'),
  ('R6-SUP-AUTH','R1: Gefälschte, ausgetauschte oder böswillig veränderte Hardware oder Software wird in betrieblich genutzte Systeme übernommen und ermöglicht unbefugten Zugriff oder Manipulation. R2: Eine unzuverlässige gefälschte Komponente fällt im Betrieb aus und stört eine kritische Dienstleistung.'),
  ('R6-TRN-12','Mitarbeitende des Lieferanten missachten die Erwartungen der Einrichtung an Cyberhygiene oder Meldungen, wodurch gemeinsam genutzte Informationen gefährdet werden oder die Eskalation verdächtiger Aktivitäten verzögert wird.'),
  ('R6-C53.1','Ein Zertifikat oder Bericht, der sich auf die falsche Dienstleistung, den falschen Zeitraum oder den falschen Geltungsbereich bezieht, vermittelt falsche Sicherheit, sodass tatsächliche Schwächen des Lieferanten weiterhin akzeptiert und unbehandelt bleiben.'),
  ('R6-C53.2','Eine Verschlechterung der Schutzmaßnahmen des Lieferanten oder veränderte Leistungsabhängigkeiten bleiben unbemerkt, sodass die Gefährdung durch Kompromittierung oder Unterbrechung über die ursprünglich akzeptierten Bedingungen hinaus zunimmt.'),
  ('R6-SUP-EXIT-TEST','R1: Der Ausfall eines Lieferanten oder die Vertragsbeendigung führt dazu, dass die Einrichtung exportierte Informationen nicht nutzen oder die Dienstleistung nicht anderweitig wiederherstellen kann, weil die Übertragbarkeit nie nachgewiesen wurde. R2: Unerkannte Abhängigkeiten von Konfigurationen, Lizenzen, Fachkenntnissen oder Integrationen verlängern den Lieferantenwechsel über die für die Dienstleistung tolerierbare Unterbrechungsdauer hinaus.'),
  ('R6-C52.8','R1: Ein ehemaliger Lieferant behält nutzbare Zugänge oder Informationen und greift später unbefugt auf Daten der Einrichtung zu, verändert sie oder legt sie offen. R2: Eine unvollständige Dienstleistungsübergabe führt dazu, dass Informationen oder eine abhängige Dienstleistung während des Lieferantenausstiegs nicht verfügbar sind.'),
  ('R6-ENV-RISK','R1: Veränderungen der Hochwasser-, Hitze- oder Sturmgefährdung werden übersehen und bestehende Schutzmaßnahmen reichen nicht mehr aus, was zu ICT-Schäden, Informationsverlust oder Dienstleistungsunterbrechungen führt. R2: Physische und umgebungsbedingte Risiken für die unterstützende Stromversorgung, Kühlung oder Wiederherstellungsstandorte werden unterschätzt, sodass Primär- und Wiederherstellungsfähigkeit gleichzeitig ausfallen. R3: Gefährdungen durch physischen Zugang, Diebstahl oder Manipulation an einem ICT-Standort werden übersehen, sodass sensible Informationen und Geräte nicht angemessen vor unbefugten Eingriffen geschützt sind.'),
  ('R6-PHY-ZONE','R1: Eine eindringende Person umgeht die kontrollierte Tür über eine unzureichend geschützte Bereichsbegrenzung und erlangt Zugang zu Geräten oder Informationen. R2: Ein gemeinsam genutzter Bereich oder Anlieferungsbereich bietet einen unkontrollierten Zugang zu kritischen Gerätebereichen.'),
  ('R6-C46.1','R1: Eine unbefugte Person betritt einen geschützten Bereich und stiehlt, beobachtet oder kopiert sensible Informationen. R2: Physische Manipulationen an Systemen oder Geräten unterbrechen Dienstleistungen oder verändern deren Betrieb.'),
  ('R6-PHY-ENTRY-LOG','R1: Unbefugter oder unerklärter Zutritt lässt sich keiner Person oder Zeit zuordnen, weil Ein- und Austrittsaufzeichnungen für Serverräume fehlen, unvollständig sind oder nur auf gemeinsam genutzten Zutrittsmitteln beruhen. R2: Veränderte, vorzeitig gelöschte oder nicht zugängliche Zutrittsaufzeichnungen verhindern eine verlässliche Untersuchung physischer Eingriffe und die Rekonstruktion von Ereignissen. R3: Nicht erfasste Bereiche, Kameraausfälle oder unbrauchbare Bilder verhindern die Rekonstruktion unbefugten Zutritts oder physischer Eingriffe, wenn auf visuelle Nachweise vertraut wird. R4: Eine übermäßige Kameraerfassung oder unbefugter Zugriff auf Aufnahmen legt sensible Informationen oder identifizierbare Personen unnötig offen.'),
  ('R6-C46.4','Eine eindringende Person bleibt lange genug unentdeckt, um Informationen zu stehlen oder Systeme zu manipulieren, bevor das zuständige Personal reagieren kann.'),
  ('R6-PHY-WORK','R1: Eine autorisierte Arbeitskraft legt Informationen offen oder ermöglicht unbefugten Zutritt, indem sie Arbeitsregeln für geschützte Bereiche missachtet. R2: Unsichere Arbeiten oder im Raum zurückgelassene Materialien behindern die Kühlung oder beschädigen Geräte im laufenden Betrieb und unterbrechen Dienstleistungen.'),
  ('R6-TRN-PHY','R1: Personal meldet ein physisches oder umgebungsbedingtes Warnzeichen nicht unverzüglich, wodurch Schäden oder Unterbrechungen eskalieren können. R2: Ungeschultes Personal handelt außerhalb seiner Kompetenz oder umgeht Schutzmaßnahmen des Raums und verursacht dadurch vermeidbare Gefährdungen oder Ausfälle.'),
  ('R6-PHY-ACCESS-TEST','R1: Fehlerhafte Zutrittskontrollen ermöglichen einer unbefugten Person den Zugang zu geschützten Systemen, obwohl die Zutrittsberechtigungen scheinbar korrekt sind. R2: Ungeprüfte Änderungen lassen Umgehungswege unentdeckt, wodurch Geräte oder Informationen Diebstahl oder Eingriffen ausgesetzt sind.'),
  ('R6-PHY-SITING','R1: Eine ungünstige Geräteaufstellung oder ein behinderter Luftstrom verursacht Überhitzung, Schäden oder einen Dienstleistungsausfall. R2: Frei zugängliche Konsolen, Komponenten oder ungesicherte Geräte ermöglichen unbefugte Einsichtnahme, Entnahme oder Manipulation.'),
  ('R6-PHY-TAMPER-CHECK','R1: Eine unbefugte physische Veränderung bleibt unbemerkt und ermöglicht Informationsdiebstahl oder Änderungen am Systembetrieb. R2: Unerklärte Änderungen an Komponenten oder Verbindungen bleiben unentdeckt, bis sie eine kritische Dienstleistung stören.'),
  ('R6-C46.2','R1: Feuer, Wasser, Hitze oder eine andere wesentliche standortspezifische Gefahr beschädigt Geräte oder Datenträger und unterbricht die unterstützten Dienstleistungen. R2: Eine standortspezifische Gefahr zerstört gespeicherte Informationen oder beschädigt sie unwiederbringlich, sodass erforderliche Aufzeichnungen auch nach der Wiederherstellung von Systemen und Räumlichkeiten nicht verfügbar sind. R3: Feuer oder extreme Umgebungsbedingungen verletzen Personal oder machen den Aufenthalt in den Räumlichkeiten unsicher, sodass ein sicherer Betrieb oder eine sichere Vorfallreaktion nicht möglich ist.'),
  ('R6-C46.3','R1: Der Ausfall von Stromversorgung, Kühlung oder Kommunikation setzt abhängige Systeme oder Räumlichkeiten länger außer Betrieb, als die Dienstleistung tolerieren kann. R2: Ein abrupter Stromausfall beschädigt laufende Schreibvorgänge oder führt zum Verlust noch nicht festgeschriebener Daten, sodass auch bei schneller Wiederaufnahme der Dienstleistung eine Datenrekonstruktion erforderlich wird.'),
  ('R6-PHY-CLIMATE','R1: Unzureichende Kühlung oder Luftströmung führt zu Überhitzung, Leistungsdrosselung von Geräten, Schäden oder zur Abschaltung der Dienstleistung. R2: Ungeeignete Luftfeuchtigkeit ermöglicht Kondensation oder elektrostatische Effekte, die Geräte beschädigen und den zuverlässigen Betrieb beeinträchtigen.'),
  ('R6-C46.7','R1: Beschädigungen oder Manipulationen der Stromversorgungs- oder Telekommunikationsinfrastruktur unterbrechen abhängige Dienstleistungen. R2: Durch Abhören ungeschützter Telekommunikationsinfrastruktur werden sensible Kommunikationsinhalte offengelegt.'),
  ('R6-C46.6','Eine beeinträchtigte Schutzvorkehrung der Versorgungseinrichtungen oder eine Notversorgung versagt im Bedarfsfall und verursacht trotz nominell vorhandener Reservekapazität einen vermeidbaren Ausfall.'),
  ('R6-PHY-MAINT','R1: Nicht gewartete Hardware verschlechtert sich oder fällt aus und unterbricht die unterstützte Dienstleistung. R2: Nicht autorisierte oder unkontrollierte Wartungsarbeiten legen Informationen offen oder verändern kritische Geräte.'),
  ('R6-PHY-RETURN','R1: Geräte werden mit veränderten Sicherheitseinstellungen oder verbliebenen Wartungszugängen wieder in Betrieb genommen und ermöglichen dadurch unbefugte Nutzung. R2: Ein unentdeckter Reparaturmangel verursacht nach der Freigabe einen erneuten Ausfall oder unzuverlässigen Betrieb.'),
  ('R6-C46.5','Eine Abweichung bei Umgebungsbedingungen oder Versorgungseinrichtungen bleibt unbemerkt oder erreicht keine handlungsfähige zuständige Person und eskaliert zu Geräteschäden oder einer Dienstleistungsunterbrechung.'),
  ('R6-C37.1','Bewertungen messen Tätigkeiten statt Schutzwirkungen oder verwenden uneinheitliche Kriterien, wodurch falsche Sicherheit entsteht und Verbesserungsprioritäten fehlgeleitet werden.'),
  ('R6-C37.5','R1: Nicht getestete Angriffspfade im laufenden Betrieb bleiben ausnutzbar und werden fälschlich als abgesichert angesehen. R2: Unzureichend kontrollierte Sicherheitstests stören betriebliche Dienstleistungen oder beschädigen Daten.'),
  ('R6-C37.2','Auf unwirksame Schutzmaßnahmen wird weiterhin vertraut, weil ihre Funktionsweise und Ergebnisse nicht geprüft werden, sodass bekannte Arten von Vorfällen erneut auftreten können.'),
  ('R6-C37.3','Regelmäßige Abweichungen von Sicherheitsregeln bleiben bestehen, ohne dass die Leitung davon Kenntnis erhält, sodass unsichere Praktiken nicht korrigiert werden.'),
  ('R6-C37.4','Eine voreingenommene oder unqualifizierte Überprüfung übersieht Schwächen oder berichtet einen unzutreffenden Sicherheitszustand, was zu unangemessenen Korrekturentscheidungen führt.'),
  ('R6-C47.1','Eine festgestellte Schutzschwäche bleibt bestehen, während sich die Korrektur verzögert, sodass derselbe Fehler oder Angriffspfad erneut wirksam werden kann.'),
  ('R6-C47.2','Eine Korrekturmaßnahme wird abgeschlossen, obwohl sie die zugrunde liegende Schwäche nicht beseitigt hat, wodurch falsche Sicherheit entsteht und eine Wiederholung möglich bleibt.'),
  ('R6-C28.2','Auf ein Produkt, eine Dienstleistung, einen Prozess oder eine Einrichtung wird vertraut, ohne dass eine wirksame Zertifizierungsanforderung erfüllt ist, was zur Beanstandung der Regelkonformität und zu einem möglicherweise betriebsbeeinträchtigenden Austausch oder einer eingeschränkten Nutzung führt.'),
  ('R6-C69.1','Unvollständige oder unzutreffende Nachweise verhindern eine verlässliche Bewertung der Umsetzung durch die Behörde und führen zu zusätzlichen Nachfragen oder korrigierenden Aufsichtsmaßnahmen.'),
  ('R6-C69.2','Die Behinderung eines rechtmäßigen aufsichtsrechtlichen Zugangs verzögert die Feststellung oder Überprüfung von Schwächen und setzt die Einrichtung einer Verschärfung der Durchsetzungsmaßnahmen aus.'),
  ('R6-C69.3','Die Behörde kann die Feststellungen gezielter Audits nicht bewerten oder festgestellte Schwächen nicht nachverfolgen, weil ihr die Auditergebnisse nicht wie vorgeschrieben zur Verfügung gestellt werden.'),
  ('R6-C72.1','Eine verbindliche aufsichtsrechtliche Anweisung wird nicht im geforderten Umfang oder nicht fristgerecht erfüllt, wodurch der festgestellte Verstoß fortbesteht und weitere Durchsetzungsmaßnahmen in Betracht gezogen werden.'),
  ('R6-C72.2','Eine vorgeschriebene öffentliche Bekanntmachung eines Verstoßes ist unvollständig oder verspätet, sodass betroffene Parteien uninformiert bleiben und weitere aufsichtsrechtliche Folgemaßnahmen ausgelöst werden.'),
  ('R6-ISO-ACCESS-COORDINATION','R1: Eine sicherheitsrelevante Zugangsänderung wird an einer abhängigen Schnittstelle nicht mitgeteilt oder nicht umgesetzt, sodass ein unbeabsichtigter Weg zu geschützten Informationen oder Werten (Assets) offen bleibt. R2: Widersprüchliche Zugangsentscheidungen zwischen den relevanten Regelungen lassen nicht begründeten Zugang zu oder verhindern zu Unrecht autorisierte Arbeit.'),
  ('R6-ISO-ANNEX-COMPARISON','Eine erforderliche Schutzmaßnahme fehlt, weil die Auswahl nie gegen den vollständigen Referenzsatz geprüft wurde.'),
  ('R6-ISO-ASSET-CHANGE','Eine auf eine andere Aufgabe versetzte Person oder ein gewechselter Dienstleister behält Informationen oder Ausstattung, die nicht mehr benötigt werden, und kann sie außerhalb der neuen berechtigten Rolle nutzen oder offenlegen.'),
  ('R6-ISO-AUDIT-EXECUTION','Das Auditprogramm besteht nur auf dem Papier, während wesentliche Mängel des ISMS nie untersucht werden.'),
  ('R6-ISO-AUDIT-PLAN','Wichtige ISMS-Prozesse oder ISMS-Anforderungen werden systematisch nicht von der internen Auditabdeckung erfasst.'),
  ('R6-ISO-AUDIT-REPORTING','Die Leitung kann auf Auditfeststellungen nicht reagieren und nicht belegen, was tatsächlich auditiert wurde.'),
  ('R6-ISO-AUDITOR-SELECTION','Auditfeststellungen sind unzuverlässig, weil den Auditoren die Kompetenz fehlt oder weil sie Arbeitsergebnisse ohne ausreichende Unparteilichkeit bewerten.'),
  ('R6-ISO-AUTHORITY-CONTACTS','Die Organisation kann im Bedarfsfall keine behördliche Unterstützung erhalten oder den zuständigen Empfänger nicht erreichen.'),
  ('R6-ISO-CLIMATE','Klimabedingte Veränderungen setzen die Annahmen zur Sicherheit oder zur Betriebsfortführung außer Kraft, und relevante Anforderungen werden übersehen.'),
  ('R6-ISO-CLOUD-LIFECYCLE','Der Kunde nimmt an, dass der Anbieter eine nicht zugewiesene Verantwortung abdeckt, oder er verliert den sicheren Zugang und die Datenübertragbarkeit, wenn sich der Cloud-Dienst ändert oder endet.'),
  ('R6-ISO-COMMUNICATION','Sicherheitsbezogene Entscheidungen, Pflichten oder Änderungen erreichen die Personen nicht, die handeln müssen.'),
  ('R6-ISO-COMPETENCE-ACTIONS','Eine Kompetenzlücke besteht nach Mentoring, Umsetzung oder Neueinstellung fort, weil der Abschluss der Maßnahme mit der nachgewiesenen Fähigkeit verwechselt wird.'),
  ('R6-ISO-CONTEXT','Wesentliche geschäftliche oder externe Rahmenbedingungen werden übersehen, sodass das ISMS die falschen Prioritäten schützt.'),
  ('R6-ISO-CONTINUAL-IMPROVEMENT','Das ISMS bleibt statisch und verliert seine Wirksamkeit, während sich Betrieb und Bedrohungen verändern.'),
  ('R6-ISO-DISPLAY-CLEARING','Sensible Besprechungs- oder Betriebsinformationen bleiben für Besucher oder spätere Raumnutzer sichtbar, nachdem die berechtigte Tätigkeit beendet ist.'),
  ('R6-ISO-DOCUMENT-NEEDS','Wesentliche Vorgaben oder Nachweise fehlen, weil der Dokumentationsbedarf nie bestimmt wurde.'),
  ('R6-ISO-DOCUMENT-RELEASE','Ungeeignete oder nicht genehmigte Dokumente werden als verbindliche Vorgaben herausgegeben.'),
  ('R6-ISO-EMERGENCY-AUTHORISATION','Notfallberechtigungen werden zu einem unbeschränkten Zugang zu sensiblen Systemen.'),
  ('R6-ISO-EMERGENCY-REVIEW','Missbrauch während eines Ausnahmezugriffs bleibt unentdeckt, weil die Genehmigung mit einer Gewähr für die ordnungsgemäße Nutzung verwechselt wird.'),
  ('R6-ISO-EMPLOYER-DUTIES','Den Beschäftigten werden Sicherheitsanforderungen auferlegt, ohne dass die Organisation ihre eigene Verantwortung festlegt. Dadurch entstehen Unklarheiten bei beschäftigungsbezogenen Sicherheitsentscheidungen.'),
  ('R6-ISO-EXTERNAL-DOCUMENTS','Überholte externe Anforderungen oder Vorgaben führen zu falschen Sicherheits- oder Konformitätsentscheidungen.'),
  ('R6-ISO-INFORMATION-IA','R1: Informationen sind gegen Offenlegung geschützt, können jedoch ohne ausreichende Sicherungen verändert werden. R2: Eine für eine kritische Entscheidung benötigte Information ist nicht verfügbar, weil ihr Verfügbarkeitsbedarf nie klassifiziert wurde.'),
  ('R6-ISO-INFORMATION-INVENTORY','Geschäftsinformationen oder Assets außerhalb der IKT bleiben von Schutzentscheidungen ausgenommen, weil das Verzeichnis nur Dienste, Systeme und Geräte aufführt.'),
  ('R6-ISO-IP-DISPOSAL','Geräte verlassen die berechtigte Nutzung mit weiterhin installierter lizenzierter Software, was eine unbefugte Nutzung oder Weitergabe ermöglicht.'),
  ('R6-ISO-IP-ENTITLEMENTS','Die Organisation setzt Software oder Material ein, ohne über ein gültiges Nutzungsrecht zu verfügen.'),
  ('R6-ISO-IP-USAGE','Die tatsächliche Nutzung überschreitet die Lizenzrechte und führt zu rechtlichen Risiken oder zum Verlust des Zugriffs auf kritische Software.'),
  ('R6-ISO-ISMS-ACTION-EFFECTIVENESS','Abgeschlossene Planungsmaßnahmen gelten als wirksam, während die ursprüngliche Schwäche des Managementsystems fortbesteht.'),
  ('R6-ISO-ISMS-ACTIONS','Bekannte Schwächen des ISMS bleiben unbearbeitet, weil Planungsentscheidungen nie in die operative Arbeit gelangen.'),
  ('R6-ISO-ISMS-AWARENESS','Mitarbeitende kennen einzelne technische Regeln, missachten aber die übergreifenden Sicherheitsverantwortlichkeiten oder Konsequenzen, die das Managementsystem erst wirksam machen.'),
  ('R6-ISO-ISMS-CHANGE-PLAN','Eine Änderung der Governance oder des Anwendungsbereichs führt zu nicht zugewiesenen Verantwortlichkeiten oder zu uneinheitlichen ISMS-Prozessen.'),
  ('R6-ISO-ISMS-MEASUREMENT-DESIGN','Die Organisation beurteilt ihr ISMS anhand technischer Testergebnisse, während ungemessene Fehler in der Governance oder in den Betriebsprozessen die beabsichtigten Ergebnisse verhindern.'),
  ('R6-ISO-ISMS-PERFORMANCE','Einzelne Schutzmaßnahmen erscheinen wirksam, während Fehler des Managementsystems die Organisation daran hindern, ihre Sicherheitsziele zu erreichen.'),
  ('R6-ISO-ISMS-RISKS-OPPORTUNITIES','Schwächen des Managementsystems oder Chancen zur Verbesserung werden trotz technischer Risikobeurteilungen übersehen.'),
  ('R6-ISO-ISMS-UNINTENDED-CHANGE','Unerwartete organisatorische Änderungen beeinträchtigen das ISMS, ohne dass ihre Folgen behandelt werden.'),
  ('R6-ISO-LEADERSHIP-ALIGNMENT','Sicherheitsziele stehen im Widerspruch zur Geschäftsstrategie und werden bei wesentlichen Entscheidungen übergangen.'),
  ('R6-ISO-LEADERSHIP-SUPPORT','Formale Rollen sind vorhanden, doch ohne aktive Unterstützung der Leitung können die Beschäftigten das ISMS nicht umsetzen.'),
  ('R6-ISO-LEGAL-COMPLIANCE','Ein vollständiges Rechtsregister erzeugt eine trügerische Sicherheit, obwohl die darin aufgeführten Pflichten nicht umgesetzt sind.'),
  ('R6-ISO-LEGAL-REQUIREMENTS','Eine verbindliche oder vertragliche Pflicht wird übersehen, ist veraltet oder wird auf den falschen Anwendungsbereich bezogen.'),
  ('R6-ISO-LOGIN-ATTEMPTS','R1: Ein Angreifer errät wiederholt Anmeldedaten oder verwendet abgeflossene Anmeldedaten erneut, ohne dass eine wirksame Beschränkung greift, und erlangt so unberechtigten Zugriff. R2: Ein schlecht gewähltes Sperrverhalten ermöglicht es einem Angreifer, berechtigten Nutzenden den Zugang zu entziehen, indem er Sperrungen gezielt auslöst.'),
  ('R6-ISO-MALWARE-COVERAGE','R1: Schadcode gelangt über eine ungeschützte Dateifreigabe, einen ungeschützten Übertragungsweg oder einen Wechseldatenträger herein, obwohl der Schutz an anderer Stelle wirkt. R2: Verschlüsselte oder archivierte Inhalte umgehen die gewählten Schutzmaßnahmen, weil weder eine geeignete Inspektion noch eine wirksame Alternative umgesetzt wurde.'),
  ('R6-ISO-MR-CONDUCT','Die oberste Leitung prüft nicht regelmäßig, ob das Managementsystem seinen Zweck weiterhin erfüllt.'),
  ('R6-ISO-MR-DECISIONS','Die Managementbewertung führt zu Diskussionen, aber zu keiner festgehaltenen Vorgabe für Verbesserungen oder notwendige Änderungen.'),
  ('R6-ISO-MR-FOLLOW-UP','Entscheidungen bleiben im Protokoll stehen und bekannte Schwächen des ISMS bestehen trotz Zustimmung der Leitung fort.'),
  ('R6-ISO-MR-INPUTS','Die Leitung gelangt zu einer scheinbar fundierten Schlussfolgerung, lässt dabei aber wesentliche Änderungen, Leistungsmängel oder ungelöste Risiken außer Acht.'),
  ('R6-ISO-NC-CAUSE','Der sichtbare Mangel wird behoben, ohne dass festgestellt wird, warum er aufgetreten ist, sodass derselbe Fehler erneut auftritt.'),
  ('R6-ISO-NC-CORRECTION','Ein Fehler des Managementsystems besteht fort oder seine Folgen wirken weiter, während die Organisation lediglich die Absicht einer künftigen Korrekturmaßnahme festhält.'),
  ('R6-ISO-NC-EFFECTIVENESS','Eine Korrekturmaßnahme des Managementsystems wird für erfolgreich erklärt, ohne ihre Wirkung zu prüfen, sodass derselbe Prozessfehler erneut auftreten kann.'),
  ('R6-ISO-NC-EXTENT','Ein Mangel wird lokal behoben, während derselbe zugrunde liegende Fehler in anderen Teilen der Organisation fortbesteht.'),
  ('R6-ISO-NC-RECURRENCE','Die Ursache ist dokumentiert, doch es wird nur der unmittelbare Mangel korrigiert, sodass derselbe Fehler im ISMS erneut auftreten kann.'),
  ('R6-ISO-NDA-COVERAGE','Geeignete Vertraulichkeitsklauseln bestehen, doch eine Partei, die geschützte Informationen erhält, ist nicht an sie gebunden.'),
  ('R6-ISO-NDA-TERMS','Unterzeichnete Vereinbarungen schützen die tatsächlich betroffenen Informationen nicht oder gelten mit unpassenden Klauseln fort.'),
  ('R6-ISO-NETWORK-SERVICE-ASSURANCE','Für einen Netzdienst sind Schutzmaßnahmen auf dem Papier vereinbart, im Betrieb werden sie jedoch nicht erbracht.'),
  ('R6-ISO-NETWORK-SERVICE-REQUIREMENTS','Abhängige Systeme verlassen sich auf Schutzmaßnahmen oder Unterstützungsleistungen von Netzdiensten, die nie vereinbart wurden.'),
  ('R6-ISO-OBJECTIVE-PLANS','Die Sicherheitsziele bleiben bloße Absichtserklärungen, weil niemand über einen umsetzbaren Plan zu ihrer Erreichung verfügt.'),
  ('R6-ISO-OBJECTIVE-REVIEW','Verfehlte oder überholte Ziele bestimmen weiterhin die Entscheidungen, ohne dass die Leitung die Lücke erkennt.'),
  ('R6-ISO-OBJECTIVES-DEFINED','Der Organisation fehlt eine klare und gemeinsam getragene Festlegung der Sicherheitsergebnisse, die sie erreichen will.'),
  ('R6-ISO-OPERATING-PROCEDURES','Der Routinebetrieb hängt vom Gedächtnis Einzelner ab, und eine uneinheitliche Ausführung schädigt Informationen oder unterbricht Dienste.'),
  ('R6-ISO-OTHER-AREA-PERIMETERS','Personen gelangen über eine ungeschützte Büro- oder Archivgrenze an sensible Informationen, obwohl der Serverraum wirksam geschützt ist.'),
  ('R6-ISO-OTHER-EQUIPMENT-PROTECTION','Betriebsmittel außerhalb des Installationsbereichs der IKT werden beschädigt oder geben Informationen preis, weil ihre Aufstellung und ihr Schutz nicht bewertet wurden.'),
  ('R6-ISO-OTHER-FACILITY-EXPOSURE','Vertrauliche Informationen werden mitgehört oder eingesehen, ohne dass jemand den geschützten Raum betritt.'),
  ('R6-ISO-OTHER-FACILITY-HAZARDS','Informationen in Büros oder Archiven werden beschädigt, weil sich der Schutz ausschließlich auf Technikräume konzentriert.'),
  ('R6-ISO-OTHER-SECURE-AREA-WORK','Ein berechtigter Zutritt wird als Erlaubnis missverstanden, geschützte Informationen während der Arbeit im Sicherheitsbereich aufzuzeichnen, offenzulegen oder zu beeinträchtigen.'),
  ('R6-ISO-PARTIES-ID','Eine relevante Partei wird übersehen, sodass ihre Erwartungen an die Informationssicherheit nie in die ISMS-Planung einfließen.'),
  ('R6-ISO-PARTIES-REQUIREMENTS','Die ermittelten interessierten Parteien bleiben eine bloße Namensliste, während verbindliche oder wichtige Anforderungen im ISMS unberücksichtigt bleiben.'),
  ('R6-ISO-POLICY-COMMITMENTS','Der Leitlinie fehlen die Verpflichtungen, die Rechtskonformität und Verbesserung steuern, sodass Sicherheitsentscheidungen ohne klaren Auftrag der Leitung getroffen werden.'),
  ('R6-ISO-PRIVACY-IMPLEMENTATION','Personenbezogene Daten außerhalb der sicherheitsbezogenen Verarbeitung nach NIS2 werden entgegen den anwendbaren Datenschutzanforderungen verarbeitet.'),
  ('R6-ISO-PRIVACY-RESPONSIBILITIES','Datenschutzmaßnahmen sind festgelegt, aber die Parteien, welche die Verarbeitung durchführen, kennen ihre Verantwortlichkeiten nicht.'),
  ('R6-ISO-PROCESS-DESIGN','Für die ISMS-Tätigkeiten fehlen vereinbarte Durchführungskriterien, und die Verantwortlichkeiten brechen an den Prozessschnittstellen ab.'),
  ('R6-ISO-PROCESS-OPERATION','Das ISMS verfügt über dokumentierte Verfahren, die im tatsächlichen Geschäftsbetrieb jedoch umgangen werden.'),
  ('R6-ISO-PROJECT-REQUIREMENTS','Projektrisiken werden bewertet, die erforderlichen Schutzmaßnahmen sind jedoch nicht umgesetzt, bevor die geschäftliche Veränderung wirksam wird.'),
  ('R6-ISO-PROJECT-RISKS','Ein Geschäftsprojekt führt zu einer nicht bewerteten Offenlegung von Informationen, weil sich die Sicherheitsprüfungen ausschließlich auf die IT-Entwicklung konzentrieren.'),
  ('R6-ISO-RECORD-READABILITY','Aufbewahrte Aufzeichnungen werden unbrauchbar, weil die zum Lesen erforderliche Software oder das erforderliche Format nicht mehr verfügbar ist.'),
  ('R6-ISO-RECORD-RETENTION','Erforderliche Geschäftsaufzeichnungen werden zu früh vernichtet oder ohne begründeten Bedarf weiter aufbewahrt.'),
  ('R6-ISO-RECORD-SAFEGUARDS','Aufzeichnungen sind über den erforderlichen Zeitraum zwar vorhanden, werden aber verändert, gehen verloren oder werden offengelegt und können ihren vorgesehenen Zweck nicht mehr erfüllen.'),
  ('R6-ISO-RESIDUAL-ACCEPTANCE','Die verbleibende Gefährdung wird von einer Person akzeptiert, die nicht Eigentümer des Risikos ist oder über die Höhe des Restrisikos nicht informiert ist.'),
  ('R6-ISO-REVIEW-CHANGE','Eine wesentliche Änderung setzt die bestehenden Sicherheitsregelungen außer Kraft, während die unabhängige Überprüfung weiterhin das frühere Betriebsmodell bewertet.'),
  ('R6-ISO-RISK-OWNER','Niemand mit entsprechender Verantwortung entscheidet darüber, wie ein wesentliches Risiko behandelt oder akzeptiert wird.'),
  ('R6-ISO-RISK-PRIORITY','Risiken mit hoher Auswirkung werden zurückgestellt, während Maßnahmen geringerer Priorität Ressourcen binden, weil aus den Risikobewertungen keine einheitlichen Behandlungsprioritäten abgeleitet wurden.'),
  ('R6-ISO-ROLES','Anforderungen an das ISMS und Lücken in seiner Leistung bleiben ohne verantwortliche Person oder werden nicht eskaliert.'),
  ('R6-ISO-SCOPE','Relevante Informationen oder Schnittstellen liegen außerhalb des Sicherheitsmanagements, während nach außen eine umfassendere Zertifizierung behauptet wird.'),
  ('R6-ISO-SCREENING-ENTRY','Relevantes Personal nimmt Tätigkeiten in einer Vertrauensstellung auf, ohne dass die für die Rolle gerechtfertigte Überprüfung des Hintergrunds erfolgt ist.'),
  ('R6-ISO-SCREENING-ONGOING','Änderungen, die die Vertrauenswürdigkeit betreffen, bleiben nach der Erstüberprüfung unbetrachtet.'),
  ('R6-ISO-SECURITY-FORUMS','Einschlägiges Fachwissen und sicherheitsrelevante Entwicklungen werden nicht wahrgenommen, wodurch sich fundierte Sicherheitsentscheidungen verzögern.'),
  ('R6-ISO-SOA-EXCLUSIONS','Notwendige Maßnahmen bleiben hinter nicht belegten Entscheidungen zur Nichtanwendbarkeit verborgen.'),
  ('R6-ISO-SOA-INCLUSIONS','Die Organisation kann ihre ausgewählten Schutzmaßnahmen nicht begründen und nicht nachweisen, dass erforderliche Maßnahmen außerhalb von Annex A berücksichtigt wurden.'),
  ('R6-ISO-SOA-STATUS','Die Leitung oder die Auditoren verlassen sich auf eine SoA, die eine Umsetzung ausweist, welche die zugrunde liegenden Nachweise nicht belegen.'),
  ('R6-ISO-SOURCE-READ','Unbefugte Leserinnen und Leser erlangen vertraulichen Code oder Entwicklungswissen, obwohl sie diesen nicht verändern können.'),
  ('R6-ISO-TEST-PROTECTION','Unbefugte erlangen sensible Testinformationen durch übermäßige Zugriffsrechte, durch eine unwirksame Bereinigung oder durch Kopien, die nach dem Ende eines betrieblichen Tests aufbewahrt bleiben.'),
  ('R6-ISO-TEST-SELECTION','R1: Sensible Produktivinformationen werden im betrieblichen Test unnötig offengelegt. R2: Ungeeignete Testinformationen bilden wichtige Betriebsbedingungen nicht ab, sodass eine fehlerhafte Änderung oder ein fehlerhaftes Wiederherstellungsverfahren als erfolgreich erscheint.'),
  ('R6-ISO-THREAT-ANALYSIS','Relevante Bedrohungsinformationen werden zwar erhoben, fließen aber nie in Schutz- oder Reaktionsentscheidungen ein.'),
  ('R6-ISO-THREAT-SOURCES','Die Bedrohungsanalyse stützt sich auf unpassende oder unzuverlässige Quellen und übersieht die Bedrohungen, von denen die Organisation betroffen ist.'),
  ('R6-ISO-TREATMENT-PLAN-APPROVAL','Die Behandlung wird umgesetzt, ohne dass der verantwortliche Risikoeigentümer der geplanten Reaktion zugestimmt hat.'),
  ('R6-ISO-WEB-ENFORCEMENT','Nutzende gelangen trotz dokumentierter Einschränkungen des Webzugriffs an schädliche Inhalte.'),
  ('R6-ISO-WEB-RULES','Die Regeln zum Schutz des Webzugriffs sind willkürlich oder lassen die Exposition außer Acht, welche die Organisation verringern muss.')
) AS v(rid,txt)
WHERE r.risk_id = v.rid;

-- ----------------------------------------------------------------------------
-- 3) B1: <br> aus den englischen Risikotexten.
--
--    89 der 362 Risiken sind zweiteilig ("R1: … <br>R2: …"). Die Oberfläche
--    gibt Risikotext als Text aus, nicht als HTML — kein
--    dangerouslySetInnerHTML, kein whitespace-pre (geprüft in ScenarioList.tsx,
--    RiskPicker.tsx, AuditWorkbench.tsx). Der Nutzer sieht das Tag also wörtlich
--    mitten im Satz. Die deutschen Texte oben sind bereits bereinigt; hier wird
--    dasselbe für die englische Spalte und den englischen meta-Text getan.
--    Die Zweiteilung bleibt erhalten, die Marker R1:/R2: auch — nur das Tag
--    weicht einem Leerzeichen.
-- ----------------------------------------------------------------------------
UPDATE public.risks
SET text_en = btrim(regexp_replace(regexp_replace(text_en, '\s*<br\s*/?>\s*', ' ', 'gi'), '\s{2,}', ' ', 'g'))
WHERE text_en LIKE '%<br%';

UPDATE public.controls c
SET meta = COALESCE(c.meta,'{}'::jsonb) || jsonb_build_object(
  'risk_text', btrim(regexp_replace(regexp_replace(c.meta->>'risk_text', '\s*<br\s*/?>\s*', ' ', 'gi'), '\s{2,}', ' ', 'g')))
WHERE c.meta->>'risk_text' LIKE '%<br%';

-- ----------------------------------------------------------------------------
-- 4) B3: ISO-IP-USAGE nennt eine Malware-Freigabe in einer Lizenzkontrolle.
--
--    Die Kontrolle hängt an ISO/IEC 27001:2022 A.5.32 (geistiges Eigentum) und
--    fragt, ob die tatsächliche Nutzung von den erworbenen Rechten gedeckt ist.
--    Der Erläuterungssatz lautete: "Malware approval and an entitlement record
--    do not prove that actual usage is licensed." Eine Malware-Freigabe hat
--    darin nichts zu suchen — gemeint ist erkennbar die Freigabe der Software
--    zur Installation, die eben kein Lizenznachweis ist. Nur dieses eine Wort
--    wird gestellt; der Rest des Satzes bleibt, wie er ist. Über replace(),
--    damit ein zweiter Lauf nichts mehr findet.
-- ----------------------------------------------------------------------------
UPDATE public.controls c
SET meta = COALESCE(c.meta,'{}'::jsonb) || jsonb_build_object(
  'description', replace(c.meta->>'description', 'Malware approval and an entitlement record do not prove that actual usage is licensed.', 'Software approval and an entitlement record do not prove that actual usage is licensed.'))
WHERE c.framework = 'ISO27001' AND c.id = 'ISO-IP-USAGE';

COMMIT;
